"use strict";

// Google Analytics 4 (Jeff, 2026-10-21): the same property as the
// marketing site (G-0V1YPFCTSD), loaded by this single shared entry
// so every app view is measured, signed in or not.
var GA_ID = "G-0V1YPFCTSD";
if (GA_ID) {
  var gaScript = document.createElement("script");
  gaScript.async = true;
  gaScript.src = "https://www.googletagmanager.com/gtag/js?id=" + GA_ID;
  document.head.appendChild(gaScript);
  window.dataLayer = window.dataLayer || [];
  window.gtag = function () { window.dataLayer.push(arguments); };
  gtag("js", new Date());
  gtag("config", GA_ID);
}
function trackEvent(name, params) { if (window.gtag) gtag("event", name, params || {}); }

const state = {
  user: null,
  boot: null, // markets, tiers, categories, plans
  joinMode: "quick", // two-step claim: "quick" (default) or "full"
  view: "home",
  tab: null,
  prefill: null, // claim-link prefill: sanitized ?handle=&market=&tier=
  claimStep: 1, // Build -85 claim flow: 1 welcome, 2 facts, 3 account, 4 done
  claimDraft: null, // Build -85: the in-progress claim (memory only until Finish)
  claimDone: null, // Build -85: the done-state readout ({firstName, total, complete, under})
  bizPrefill: null, // business-wave prefill: sanitized ?biz=&market=&category=
  publicHandle: null, // set when the URL is /c/<handle>
  resetToken: "", // password reset token from a /?reset= email link
  preview: null, // admin Business Preview session (see enterPreview)
  partnerData: null, // partner dashboard: the /partner/summary payload, fetched once per session
  agentQueue: null, // overhaul Stage 1: Ready-for-you queue the current home computed ({count, title, rows:[{text, sub, btn, act}], empty})
  sigQueue: null, // V4.1: the V3 queue items the current Home computed ([{text, short, btn, act}]) — shared by Home and the Sig tab (one queue, two doors)
  sigQueueLinks: [], // V4.1: the caught-up links that ride the current Home's queue card
  sigQueueCount: 0, // V4.1: pending queue count, carried as the Sig tab badge
  sigThread: [], // V4.1: the Sig conversation on the Sig tab ([{who, text, flow}]) — session-only, like every other Sig surface
  sigFocusAsk: false, // V4.1: set by the Home ask box so the Sig tab lands with its chat input focused
  sigFlow: null, // Sig Operator: the active in-chat action flow ({id, step, data}) — memory only until the user confirms; exiting writes nothing
  igDrafts: null, // Handle onboarding: per-surface fetched drafts ({side, draft}) — session memory only until the summary's confirm copies values into a form; never persisted
  sigOpData: null, // Sig Operator: scratch data for the active flow (search results, readout, gaps) — session-only, never persisted
  discover: [],
  discoverCats: [], // Discover category filter: the chip row owns it, multi-select, OR semantics
  discoverSpanish: false, // Discover filter: the "Spanish-speaking creators only" toggle
  discoverMusician: "", // Discover filter (Sig activation): "" = off, "1" = musician attribute (the toggle), "perform"/"create" = the openness modes Sig's prompts deep-link
  discoverUniversity: "", // Discover filter (U1): canonical university name, "" = all; options come from the server facet
  lang: "", // Spanish claim path (S1): "es" when the creator arrived with ?lang=es (persisted) or their record carries lang=es
  threads: [],
  activeThread: null, // other user id
  counterCode: "",
  badges: null, // tab badge counts from GET /notifications (UX redesign section 2)
  offerDraft: {}, // offer composer form state: survives re-renders, cleared on a successful submit
  staff: null, // live staff session info (GET /staff/session) while in staff mode
  staffCode: "", // business staff code from a /redeem/<code> register link
  staffBizName: "", // business name resolved for the PIN screen
};

const app = document.getElementById("app");
const topnav = document.getElementById("topnav");
const bottomnav = document.getElementById("bottomnav");
const PAID_COMP = "Paid cash campaigns";

// Realtor layer (Jeff, 2026-10-22; switch form, 2026-10-28): the
// stored profession value "Real estate agent" remains the carrier
// the server reads (creatorIsRealtor, the public payload gate),
// but creators no longer pick it from a "what do you do" list:
// the profile form carries one switch, "I am a licensed real
// estate agent", whose state derives from the stored value. Any
// other stored profession value (the retired everyday list) is
// never asked about again and rides through saves untouched; the
// server stays authoritative (cleanProfession still accepts the
// legacy values so old records keep loading and re-saving).
const REALTOR_PROFESSION = "Real estate agent";
function isRealtorProfile(c) {
  return !!c && c.profession === REALTOR_PROFESSION;
}
function syncRealtorFields() {
  const block = document.getElementById("p-realtor-block");
  const sw = document.getElementById("p-realtor");
  if (block && sw) block.style.display = sw.checked ? "" : "none";
  return false;
}
// What the profile save sends for profession: only a deliberate
// flip of the realtor switch writes (on = the realtor value, off
// = blank). An untouched switch sends nothing, so a stored legacy
// value is never erased by a save that was not about this.
function realtorSwitchProfession() {
  const sw = document.getElementById("p-realtor");
  if (!sw) return undefined;
  const was = isRealtorProfile(state.user && state.user.creator);
  if (sw.checked === was) return undefined;
  return sw.checked ? REALTOR_PROFESSION : "";
}

function esc(s) {
  return String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

// GET cache (perf, 2026-10-28): moving between sections re-renders
// views that refetch the same endpoints seconds apart, and every
// fetch used to pay a full function round trip. A short in-memory
// cache plus in-flight dedupe makes repeat renders instant. Any
// mutation clears the whole cache, so an action never reads state
// it just changed; entries also expire on their own after 15s.
// Callers receive a deep copy, never the cached object itself, so
// view code mutating a result cannot poison the next render.
const getCache = new Map();
const getInflight = new Map();
const GET_CACHE_TTL_MS = 15000;
function cloneJson(x) {
  return x === undefined ? x : JSON.parse(JSON.stringify(x));
}

// Stale-build self-heal (2026-10-28): the shell stamps the build
// it loaded with (window.__SIGNL_BUILD__ in index.html) and the
// server stamps every API response with its build (x-signl-build,
// lib/build.js). A tab that outlives a deploy is running old code
// against a new server, the mixed state behind the stuck-nav
// report; on the first response that proves it, reload once into
// the fresh asset set. Two guards keep it tame: it only heals
// toward a NEWER build (a stale browser-cached bootstrap response
// still carries the old build's stamp and must not drag a fresh
// client backwards; rollback deploys bump the id like any other
// deploy, per lib/build.js), and a sessionStorage record of the
// build already healed toward caps it at one automatic reload
// per new server build per tab session, so a permanently
// mismatched deploy can never become a reload loop.
const RUNNING_BUILD = window.__SIGNL_BUILD__ || null;
function buildOrder(id) {
  const m = /^(\d{4}\.\d{2}\.\d{2})-(\d+)$/.exec(String(id || ""));
  return m ? { day: m[1], n: parseInt(m[2], 10) } : null;
}
function isNewerBuild(serverBuild, runningBuild) {
  const s = buildOrder(serverBuild), r = buildOrder(runningBuild);
  if (!s || !r) return serverBuild !== runningBuild; // unparseable: any mismatch heals
  if (s.day !== r.day) return s.day > r.day;
  return s.n > r.n;
}
function noteServerBuild(serverBuild) {
  try {
    if (!serverBuild || !RUNNING_BUILD) return;
    if (!isNewerBuild(serverBuild, RUNNING_BUILD)) return;
    const KEY = "signlBuildReloadFor";
    if (sessionStorage.getItem(KEY) === serverBuild) return;
    sessionStorage.setItem(KEY, serverBuild);
    location.reload();
  } catch (e) { /* healing is best-effort; never break a request */ }
}
// Views that render from already-loaded state make no request, so
// a returning user might click through local views for a while
// before any response can report a deploy. When the tab or window
// comes back to the foreground, probe the bootstrap header
// directly (no-store, so the 60s bootstrap cache cannot answer
// with a stale stamp), at most once a minute.
let lastBuildProbeAt = 0;
function probeServerBuild() {
  const now = Date.now();
  if (now - lastBuildProbeAt < 60000) return;
  lastBuildProbeAt = now;
  fetch("/api/bootstrap", { cache: "no-store", credentials: "same-origin" })
    .then((res) => noteServerBuild(res.headers && res.headers.get ? res.headers.get("x-signl-build") : null))
    .catch(() => {});
}
document.addEventListener("visibilitychange", () => { if (!document.hidden) probeServerBuild(); });
window.addEventListener("focus", probeServerBuild);

async function api(method, path, body) {
  const isGet = method === "GET";
  if (!isGet) getCache.clear();
  if (isGet) {
    const hit = getCache.get(path);
    if (hit && Date.now() - hit.at < GET_CACHE_TTL_MS) return cloneJson(hit.data);
    if (getInflight.has(path)) return cloneJson(await getInflight.get(path));
  }
  const run = (async () => {
    let res;
    try {
      res = await fetch("/api" + path, {
        method,
        headers: body ? { "Content-Type": "application/json" } : {},
        body: body ? JSON.stringify(body) : undefined,
        credentials: "same-origin",
      });
    } catch (e) {
      // A network failure says so in plain words, never as a raw
      // status or a browser exception string.
      throw new Error("We could not reach SIGNL. Check your connection and try again.");
    }
    noteServerBuild(res.headers && res.headers.get ? res.headers.get("x-signl-build") : null);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      // Server messages are plain language and pass through. A bare
      // failure with no message becomes a friendly one: nobody should
      // ever see "Request failed (502)" (UX audit fix, 2026-10-22).
      // The parsed body rides along on the error so callers that need
      // structured fields (the offer dedupe's existingOfferId) can
      // read them without a second request.
      const e = new Error(data.error || "Something went wrong on our side. Try again in a moment.");
      e.data = data;
      e.status = res.status;
      throw e;
    }
    return data;
  })();
  if (!isGet) return run;
  getInflight.set(path, run);
  try {
    const data = await run;
    getCache.set(path, { at: Date.now(), data });
    return cloneJson(data);
  } finally {
    getInflight.delete(path);
  }
}

// Skeleton loading state (visual experience pass, 2026-10-24):
// shimmer cards while a surface loads, with the old loading text
// kept for screen readers. Purely presentational.
function skelHtml(label, n) {
  return `<div class="skel-wrap" role="status"><span class="sr-only">${esc(label)}</span>${'<div class="skel skel-card"><div class="skel-line med" style="margin-top:22px"></div><div class="skel-line"></div><div class="skel-line short"></div></div>'.repeat(n || 2)}</div>`;
}

// Business initial chip (visual experience pass): offer feeds have
// no business photography in the data model, so cards lead with a
// compact gradient monogram chip built from the business name
// (existing data) instead of a bare text header.
function bizChipHtml(name) {
  const initial = (String(name || "?").trim().charAt(0) || "?").toUpperCase();
  return `<span class="avatar-initial" style="width:42px;height:42px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:1.02rem;flex:none" aria-hidden="true">${esc(initial)}</span>`;
}

// Success check SVG (visual experience pass): drawn once by CSS
// animation inside .success-check-wrap. Shared by the redemption
// and proof-submission success moments.
function successCheckHtml() {
  return `<div class="success-check-wrap"><svg class="success-check" viewBox="0 0 52 52" aria-hidden="true"><circle cx="26" cy="26" r="24"></circle><path d="M15 27l7.5 7.5L37 19"></path></svg></div>`;
}

// Submit state (UX audit fix, 2026-10-22): one shared helper so a
// slow connection never invites a double-tap. The first call
// disables the form's submit button and swaps its label to
// "Working..."; the second restores both. Returns false when the
// form is already busy, so handlers can bail on re-entry.
function submitBusy(form, busy) {
  if (!form || !form.querySelector) return true;
  const btn = form.querySelector('button[type="submit"]');
  if (!btn) return true;
  if (busy) {
    if (btn.dataset.busy) return false;
    btn.dataset.busy = "1";
    btn.dataset.label = btn.textContent;
    btn.disabled = true;
    btn.textContent = "Working...";
    return true;
  }
  delete btn.dataset.busy;
  btn.disabled = false;
  if (btn.dataset.label) btn.textContent = btn.dataset.label;
  return true;
}

// Creator referral (Jeff, 2026-10-18): a visitor who arrived through
// a creator's invite link (?ref=<handle>) carries that credit through
// to their registration, so the inviting creator is credited.
function storedRef() {
  try { return localStorage.getItem("signl_ref") || ""; } catch (e) { return ""; }
}

// Signup source (Jeff, 2026-10-21): segment and channel pages tag
// their claim links with ?src= (moms, students, linkedin, learn).
// It is persisted exactly like the referral credit and sent at
// registration, so each applicant's origin page is on the record.
function storedSrc() {
  try { return localStorage.getItem("signl_src") || ""; } catch (e) { return ""; }
}
// Golden Ticket (Build -33): a claim link carrying ?ticket=
// persists the ticket id like the referral and the source, so
// registration can claim the held seat server-side.
function storedTicket() {
  try { return localStorage.getItem("signl_ticket") || ""; } catch (e) { return ""; }
}

// Spanish claim path (S1, Jeff, 2026-10-28): T(en, es) returns
// the Spanish string when this session is a Spanish one
// (state.lang === "es", set at init from the ?lang=es arrival
// signal or the signed-in record) and the English otherwise.
// ONLY the claim flow and the profile-completion essentials
// read T(); the rest of the app is English for now, by design,
// and the Spanish site pages say so. A missing Spanish string
// falls back to the English, never to a blank.
function T(en, es) {
  return state.lang === "es" && es ? es : en;
}
// Sig Operator language (Jeff, 2026-10-28): the operator speaks
// the user's stored language end to end. Creators ride state.lang
// (the S1 claim path / record lang); businesses ride their S3
// preferredLanguage. ST() is T() keyed to that combined answer,
// used by the operator engine, the brief builder, and the
// performance readout — surfaces the plain T() never reached.
function sigLang() {
  const u = state.user;
  if (u && u.role === "business" && u.business && u.business.preferredLanguage === "es") return "es";
  return state.lang === "es" ? "es" : "en";
}
function ST(en, es) {
  return sigLang() === "es" && es ? es : en;
}
function storedLang() {
  try { return localStorage.getItem("signl_lang") === "es" ? "es" : ""; } catch (e) { return ""; }
}

// Claim-link prefill (Jeff, 2026-10-19): per-target links from email
// and partner channels arrive as ?handle=<ig>&market=<name>&tier=<band>
// and pre-fill the creator sign-up form, so a creator we already know
// lands on a half-completed application instead of a cold form. The
// params only ever FILL fields: they never submit the form, never skip
// the human review, and anything that does not exactly match the
// published market and tier lists is silently ignored. (DM copy is
// unchanged by design: DMs still carry the generic link.)
function sanitizeClaimHandle(v) {
  return String(v || "").trim().replace(/^@/, "").replace(/[^A-Za-z0-9._]/g, "").slice(0, 30);
}

// Mirror of the server's normalizeHandle (Jeff, 2026-10-26): a
// handle typed as @name or pasted as a full profile link becomes
// the same clean handle before anything is sent, and the form
// writes the clean value back so the creator sees what was
// understood. The server normalizes again on arrival; the two
// must stay in step.
function normalizeHandleClient(raw) {
  let h = String(raw == null ? "" : raw).trim();
  if (!h) return "";
  if (h.includes("/")) {
    h = h.replace(/^https?:\/\//i, "").replace(/^www\./i, "");
    const parts = h.split(/[/?#]/).map((x) => x.trim()).filter(Boolean);
    h = parts.length ? parts[parts.length - 1] : "";
  }
  return h.replace(/^@/, "").trim();
}

function parseClaimParams(params) {
  const out = {};
  const handle = sanitizeClaimHandle(params.get("handle"));
  if (handle) out.handle = handle;
  // Claim links may carry &platform=<slug> (Jeff, 2026-10-22): the
  // claim opens with that platform preselected in the picker.
  // Absent or unknown values prefill nothing, and the forms default
  // to Instagram, exactly as every link already sent behaves.
  const platformRaw = String(params.get("platform") || "").trim().toLowerCase();
  if (PRIMARY_PLATFORMS_CLIENT.some((p) => p.id === platformRaw)) out.platform = platformRaw;
  let marketRaw = String(params.get("market") || "").trim().slice(0, 60);
  if (marketRaw === "Hampton Roads") marketRaw = "Virginia Beach";
  if (marketRaw && state.boot) {
    const m = state.boot.markets.find((x) => x.name === marketRaw || x.id === marketRaw);
    if (m) out.market = m.name;
    else if (marketRaw === unlistedLabel()) out.market = marketRaw;
  }
  const tierRaw = String(params.get("tier") || "").trim().slice(0, 20);
  if (tierRaw && state.boot && state.boot.tiers.some((t) => t.id === tierRaw)) out.tier = tierRaw;
  return out;
}

// Business-wave prefill (Jeff, 2026-10-23): the founding
// business wave email carries a prebuilt link per business,
// ?biz=<name>&market=<name>&category=<app category>&src=business-wave.
// Same discipline as the claim prefill: values only FILL the
// founding registration form, anything that does not exactly
// match the published market and category lists is silently
// ignored, and nothing ever auto-submits. The src is persisted
// by the generic ?src= handling in init, so the created record
// carries signupSource "business-wave" with no extra plumbing.
function parseBizParams(params) {
  const out = {};
  const biz = String(params.get("biz") || "").trim().slice(0, 120);
  if (biz) out.businessName = biz;
  let marketRaw = String(params.get("market") || "").trim().slice(0, 60);
  if (marketRaw === "Hampton Roads") marketRaw = "Virginia Beach";
  if (marketRaw && state.boot) {
    const m = state.boot.markets.find((x) => x.name === marketRaw || x.id === marketRaw);
    if (m) out.market = m.name;
  }
  const catRaw = String(params.get("category") || "").trim().slice(0, 60);
  if (catRaw && state.boot && state.boot.businessCategories.includes(catRaw)) out.category = catRaw;
  return out;
}

// Public creator profile (Jeff, 2026-10-19): an approved creator's
// shareable page, app.joinsignl.com/c/<handle>. The server answers a
// whitelist payload for approved creators only; everyone else reads
// as "not public". The roster itself stays private: this is one
// creator's own link, never a listing.
function publicProfileUrl(u) {
  const handle = u && u.creator && u.creator.handle;
  return handle ? `https://app.joinsignl.com/c/${encodeURIComponent(handle)}` : "";
}

async function copyPublicProfile() {
  const el = document.getElementById("pp-copied");
  try {
    await navigator.clipboard.writeText(publicProfileUrl(state.user));
    if (el) el.textContent = "Copied.";
  } catch (e) {
    if (el) el.textContent = "Copy the link from the box above.";
  }
  return false;
}

// Share shell for /c/ profiles (UX audit fix, 2026-10-22): the
// profile page sets its own document title and Open Graph /
// Twitter meta from the loaded profile, so a link the creator
// pastes into Messages, WhatsApp, or their bio unfurls as their
// name, photo, and market instead of a generic SIGNL card. Since
// Jeff's 2026-10-23 ruling, approved + profile-complete profiles
// ALSO get this meta server-rendered with index,follow (the
// cpage route in the router); this client shell remains the
// in-app fallback and keeps SPA navigation consistent.
const DEFAULT_PAGE_TITLE = "SIGNL - Local Creator Marketing Platform";
function setShareMeta(key, attr, content) {
  if (!content) return;
  let el = document.head.querySelector(`meta[${attr}="${key}"][data-signl-meta]`);
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, key);
    el.setAttribute("data-signl-meta", "1");
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}
function setShareCanonical(href) {
  // The server-rendered /c/ page already carries a canonical; the
  // in-app shell just keeps it pointing at the profile on screen
  // (and adds one, marked for cleanup, on shells served without).
  let el = document.head.querySelector('link[rel="canonical"]');
  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    el.setAttribute("data-signl-meta", "1");
    document.head.appendChild(el);
  }
  el.setAttribute("href", href);
}
function applyProfileShareShell(p, place) {
  document.title = `${p.name} (@${p.handle}) on SIGNL${place ? ` | ${place}` : ""}`;
  // Mirrors profilePageMeta in lib/profile-meta.js exactly,
  // including the multi-market line (2026-11-01), so the
  // in-app head and the server-rendered head never disagree.
  const alsoList = (p.listedMarkets || []).filter((m) => !m.home && typeof m.pct === "number").slice(0, 2);
  const also = alsoList.length ? ` Also ranked in ${alsoList.map((m) => `${m.market} (${m.pct}% of their audience)`).join(" and ")}.` : "";
  const desc = `${p.name} is a founding creator on SIGNL in ${place || "their market"}${p.tierBand ? ` (${p.tierBand} tier)` : ""}.${typeof p.localAudiencePct === "number" ? ` ${p.localAudiencePct}% of their audience is local.` : ""}${also} Local businesses comp creators for honest posts.`;
  setShareCanonical(`https://app.joinsignl.com/c/${p.handle}`);
  setShareMeta("og:title", "property", document.title);
  setShareMeta("og:description", "property", desc);
  setShareMeta("og:type", "property", "profile");
  if (p.photoUrl) setShareMeta("og:image", "property", p.photoUrl.startsWith("http") ? p.photoUrl : `https://app.joinsignl.com${p.photoUrl}`);
  setShareMeta("twitter:card", "name", p.photoUrl ? "summary_large_image" : "summary");
  setShareMeta("twitter:title", "name", document.title);
  setShareMeta("twitter:description", "name", desc);
  if (p.photoUrl) setShareMeta("twitter:image", "name", p.photoUrl.startsWith("http") ? p.photoUrl : `https://app.joinsignl.com${p.photoUrl}`);
}
function clearShareShell() {
  document.title = DEFAULT_PAGE_TITLE;
  document.head.querySelectorAll("meta[data-signl-meta], link[data-signl-meta]").forEach((el) => el.remove());
}

// Book-me page (Build -31 + Amendments 1 and 2, Jeff,
// 2026-10-29): the creator's public page at /c/<handle>, shown
// only when the creator turned it on. The server tiers the
// payload by viewer, and this render follows the tier exactly:
//   Tier 0 (logged out / creators / anyone else): showcase
//     plus the public rate card (2026-11-01: listed offerings
//     show at every tier). No follower counts, no social
//     links, no contact path. The handle is text, never a
//     link out.
//   Tier 1 (signed-in business, not paid/active): the rate
//     card + the Book on SIGNL action, plus the locked
//     socials panel.
//   Tier 2 (paid, active business): rate, Book, the creator's
//     social channel rows, and an in-platform Message box.
// The ONLY booking action routes inside SIGNL. Nothing on this
// page links to the creator's off-platform profiles except the
// Tier 2 channel rows, which are the paid unlock itself.
const BOOKME_GUARANTEE_LINE = "Bookings through SIGNL carry the Visit Guarantee and payment protection: payment is held until the post is live. Deals arranged outside SIGNL carry neither.";
const BOOKME_STAYS_LINE = "Bookings that start on SIGNL stay on SIGNL.";
const BOOKME_LOCKED_LINE = "Paying businesses can message this creator right here on SIGNL.";
const BOOKING_STARTED_LINE = "This booking started on SIGNL, so it runs through SIGNL, where the Visit Guarantee and payment protection apply.";

function bookMeBook() {
  const u = state.user;
  if (!u) return go("signin");
  if (u.role === "business" && businessAccessState(u) === "active" && state.bookMeCreatorId) {
    startOffer(state.bookMeCreatorId);
    return false;
  }
  return go("dashboard");
}

async function bookMeSendMessage(handle) {
  const ta = document.getElementById("bm-msg");
  const note = document.getElementById("bm-msg-note");
  const body = ta ? ta.value.trim() : "";
  if (!body) { if (note) note.textContent = "Write a short first message first."; return; }
  try {
    const data = await api("POST", "/c/" + encodeURIComponent(handle) + "/message", { body });
    if (data && data.message) openThread(data.message.toId);
  } catch (e) {
    if (note) note.textContent = (e && e.message) || "That message did not send. Try again.";
  }
}

// Shared video embed parser (Build -79): a mirror of
// netlify/functions/lib/video-embed.js, kept line-for-line in
// behavior. The server stamps the same descriptor onto every
// best-work card it serves (w.embed); this mirror covers any
// URL a renderer meets without one. Returns null for anything
// that is not a known video URL, and every renderer falls back
// to the plain link card for those.
function videoEmbedFor(url) {
  let u;
  try {
    u = new URL(String(url || ""));
  } catch (e) {
    return null;
  }
  if (u.protocol !== "http:" && u.protocol !== "https:") return null;
  const host = u.hostname.toLowerCase().replace(/^www\./, "").replace(/^m\./, "");
  const seg = u.pathname.split("/").filter(Boolean);
  if (host === "instagram.com") {
    const type = String(seg[0] || "").toLowerCase();
    const id = seg[1] || "";
    if (!["p", "reel", "reels", "tv"].includes(type) || !/^[A-Za-z0-9_-]{5,40}$/.test(id)) return null;
    const normType = type === "reels" ? "reel" : type;
    return { platform: "Instagram", kind: normType === "p" ? "post" : "reel", embedUrl: `https://www.instagram.com/${normType}/${id}/embed`, aspect: "portrait" };
  }
  if (host === "tiktok.com") {
    const id = seg[2] || "";
    if (String(seg[0] || "").charAt(0) !== "@" || String(seg[1] || "").toLowerCase() !== "video" || !/^\d{3,}$/.test(id)) return null;
    return { platform: "TikTok", kind: "video", embedUrl: `https://www.tiktok.com/embed/v2/${id}`, aspect: "portrait" };
  }
  if (host === "youtube.com" || host === "youtu.be") {
    let id = "";
    let kind = "video";
    if (host === "youtu.be") {
      id = seg[0] || "";
    } else if (String(seg[0] || "").toLowerCase() === "watch") {
      id = u.searchParams.get("v") || "";
    } else if (String(seg[0] || "").toLowerCase() === "shorts") {
      id = seg[1] || "";
      kind = "short";
    } else if (String(seg[0] || "").toLowerCase() === "embed" || String(seg[0] || "").toLowerCase() === "live") {
      id = seg[1] || "";
    }
    if (!/^[A-Za-z0-9_-]{6,20}$/.test(id)) return null;
    return { platform: "YouTube", kind, embedUrl: `https://www.youtube-nocookie.com/embed/${id}`, aspect: kind === "short" ? "portrait" : "wide" };
  }
  return null;
}

// One merged Work grid (Build -64): the portfolio sample, the
// featured posts, and the creator's best-work links were three
// near-identical sections on the public page. They are one grid
// now: embed cells carry a designed placeholder behind the
// iframe (a slow or blocked embed shows the placeholder, never
// a void), and link-only posts ride as designed tiles in the
// same grid. Deduped by URL. Mirrors profileWorkItems in
// lib/profile-meta.js, which renders the same grid into the
// served HTML.
// Build -79: best-work links that parse as videos join the
// embeds (the video itself, click to play in place); the rest
// stay tiles.
function workItemsOf(p) {
  const items = [];
  const seen = new Set();
  const norm = (u) => String(u || "").replace(/\/+$/, "").toLowerCase();
  if (p.portfolioSample && p.portfolioSample.url) {
    const emb = videoEmbedFor(p.portfolioSample.url);
    items.push({ kind: "embed", url: p.portfolioSample.url, embedUrl: (emb && emb.embedUrl) || p.portfolioSample.embedUrl, embedAspect: (emb && emb.aspect) || "portrait", platform: (emb && emb.platform) || p.primaryPlatformLabel || "Instagram", tag: "Portfolio sample" });
    seen.add(norm(p.portfolioSample.url));
  }
  for (const f of p.featuredPosts || []) {
    if (!f || !f.url || seen.has(norm(f.url))) continue;
    const emb = videoEmbedFor(f.url);
    items.push({ kind: "embed", url: f.url, embedUrl: (emb && emb.embedUrl) || f.embedUrl, embedAspect: (emb && emb.aspect) || "portrait", platform: (emb && emb.platform) || p.primaryPlatformLabel || "Instagram", tag: "Featured post" });
    seen.add(norm(f.url));
  }
  for (const w of p.pastWork || []) {
    if (!w || !w.url || seen.has(norm(w.url))) continue;
    const emb = w.embed || videoEmbedFor(w.url);
    if (emb && emb.embedUrl) {
      items.push({ kind: "embed", url: w.url, embedUrl: emb.embedUrl, embedAspect: emb.aspect || "portrait", platform: emb.platform || w.platform || "", tag: emb.platform || w.platform || "Video" });
    } else {
      items.push({ kind: "tile", url: w.url, label: w.label || "Watch", platform: w.platform || "" });
    }
    seen.add(norm(w.url));
  }
  return items;
}
function workGridHtml(p) {
  const items = workItemsOf(p);
  if (!items.length) return "";
  const cells = items.map((it) => it.kind === "embed"
    ? `<div class="work-cell${it.embedAspect === "wide" ? " wide" : ""}"><div class="work-ph"><span class="work-ph-mark">${esc(it.platform || "Video")}</span><span class="work-ph-note">Post loading</span></div><iframe src="${esc(it.embedUrl || "")}" loading="lazy" frameborder="0" scrolling="no" allowtransparency="true" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen title="${esc(it.tag)} by @${esc(p.handle)}" onload="this.parentNode.classList.add('on')"></iframe><span class="work-tag">${esc(it.tag)}</span></div>`
    : `<a class="work-cell tile" href="${esc(it.url)}" target="_blank" rel="noopener"><span class="work-ph-mark">${esc(it.platform || "Post")}</span><span class="work-tile-label">${esc(it.label)}</span><span class="work-go">View post</span></a>`).join("");
  return `
      <h3 class="bookme-h">Work</h3>
      <div class="work-grid">${cells}</div>
      <p class="small muted">Posts ${esc(p.name)} picked to show their work. They are the creator's own posts, not SIGNL visits.</p>`;
}

// ---------- profile header facts (Build -66) ----------
// Mirror of the server render in profile-meta.js (the two
// renders must never tell two different stories): quick links
// to the creator's socials and a stats cluster ride the top
// bar next to the name and photo. Links come from the
// payload's socialLinks, built server-side from stored handles
// only; a platform with nothing on the record never appears.
function fmtFollowers(n) {
  const v = Math.floor(Number(n) || 0);
  if (v >= 1000000) return (v / 1000000).toFixed(1).replace(/\.0$/, "") + "M";
  if (v >= 1000) return (v / 1000).toFixed(1).replace(/\.0$/, "") + "K";
  return String(v);
}

function profileHeaderSocialsHtml(p) {
  const links = (Array.isArray(p.socialLinks) ? p.socialLinks : []).filter((s) => s && s.url && s.label);
  if (!links.length) return "";
  return `<div class="bookme-socials-row">${links.map((s) => `<a class="bm-soc" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a>`).join("")}</div>`;
}

// The viewed market (Build -68): the headline local number
// is keyed to the market the viewer is looking in. Resolution
// order: the logged-in business's own market, then a ?market=
// on the URL, then the creator's home market. A candidate
// counts only when the creator is listed there (a
// listedMarkets entry at or above the listing floor); a
// viewed market with no share falls back to home, never to a
// zero headline.
function profileViewMarket(p) {
  const listed = (Array.isArray(p.listedMarkets) ? p.listedMarkets : []).filter((m) => m && typeof m.pct === "number");
  const homeEntry = listed.find((m) => m.home) || null;
  const home = { market: homeEntry ? homeEntry.market : (p.market || ""), pct: (p.localAudiencePct === null || p.localAudiencePct === undefined) ? (homeEntry ? homeEntry.pct : null) : p.localAudiencePct, home: true };
  const candidates = [];
  const u = state.user;
  if (u && u.role === "business" && u.market) candidates.push(u.market);
  try { const q = new URLSearchParams(window.location.search).get("market"); if (q) candidates.push(q); } catch (e) { /* no URL context */ }
  for (const cand of candidates) {
    const hit = listed.find((m) => String(m.market).toLowerCase() === String(cand).trim().toLowerCase());
    if (hit) return { market: hit.market, pct: hit.pct, home: !!hit.home };
  }
  return home;
}
// Follower count for a share of the creator's total (Build
// -68): arithmetic on the creator's own reported numbers,
// compact format, null when there is no total to count from.
function followersForPct(pct, total) {
  if (pct === null || pct === undefined || !Number.isFinite(Number(pct)) || !(Number(total) > 0)) return null;
  return fmtFollowers(Math.round((Number(pct) / 100) * Number(total)));
}
// The public name line (Build -68): first name only, pronouns
// beside it when set; a record with no real first name renders
// exactly as it did.
function profileDisplayName(p) {
  if (p.firstName) return p.pronouns ? `${p.firstName} \u00B7 ${p.pronouns}` : String(p.firstName);
  return p.name || "";
}

function profileHeaderStatsHtml(p) {
  // Local first and bold, total second (Build -66 order,
  // kept). The local number is the viewed market's share
  // (profileViewMarket), with its follower count under it
  // when the creator has a total on record; no total means
  // the local stat stands alone, never a zero.
  const view = profileViewMarket(p);
  const total = totalAudienceOf(p);
  const stats = [];
  if (view.pct !== null && view.pct !== undefined && Number.isFinite(Number(view.pct))) {
    const cnt = followersForPct(view.pct, total);
    stats.push(`<div class="bm-stat bm-stat-local"><span class="bm-num">${view.pct}%</span><span class="bm-lbl">${view.home ? "local" : `local \u00B7 ${esc(view.market)}`}</span>${cnt ? `<span class="bm-sub">${cnt} followers</span>` : ""}</div>`);
  }
  if (total > 0) {
    stats.push(`<div class="bm-stat bm-stat-fol"><span class="bm-num">${fmtFollowers(total)}</span><span class="bm-lbl">followers</span></div>`);
  }
  if (!stats.length) return "";
  return `<div class="bookme-stats">${stats.join("")}</div>`;
}

async function renderPublicProfile() {
  const handle = state.publicHandle || "";
  // Hydration (Build -92): when the server already rendered the
  // profile body into the page (profile-meta.js stamps it
  // data-server-rendered), enhance over it — never blank it out
  // behind a loading line, and if the payload fetch fails, the
  // server-rendered profile stays up instead of becoming a dead
  // end. Only a page that arrived as the bare shell shows the
  // loading state, exactly as before.
  const serverRendered = !!(app.querySelector && app.querySelector('.public-profile[data-server-rendered="1"]'));
  if (!serverRendered) {
    app.innerHTML = `<section class="panel center" style="max-width:560px;margin:40px auto"><p class="muted">Loading @${esc(handle)}...</p></section>`;
  }
  let p = null;
  try {
    const data = await api("GET", "/c/" + encodeURIComponent(handle));
    p = data.profile;
  } catch (e) { p = null; }
  if (!p) {
    if (serverRendered) return; // the served profile is the page; keep it
    document.title = "Profile not public | SIGNL";
    app.innerHTML = `
    <section class="panel center" style="max-width:560px;margin:40px auto">
      <h2>Profile not public</h2>
      <p class="muted">There is no public SIGNL page at this link. The creator may not have turned their page on, may still be in review, or the link may be wrong.</p>
      <div class="cta-row" style="justify-content:center">
        ${state.user ? `<a class="btn" href="#" onclick="return go('dashboard')">Back to my dashboard</a>` : `<a class="btn" href="#" onclick="return go('join-creator')">Become a Founding Creator</a>`}
      </div>
    </section>`;
    return;
  }
  if (p.pageState === "claimed") return renderClaimedProfile(p);
  state.bookMeCreatorId = p.creatorUserId || null;
  const view = profileViewMarket(p);
  const total = totalAudienceOf(p);
  const place = p.unlisted ? esc(p.city) : esc(marketDisplayName(p.market));
  applyProfileShareShell(p, p.unlisted ? (p.city || "") : (p.market || ""));
  const initial = esc((p.name || "?").trim().charAt(0).toUpperCase() || "?");
  const tier = typeof p.viewerTier === "number" ? p.viewerTier : 0;
  // Market chips, deduped (Build -64, audit F4): the place chip
  // and the city chip named the same market twice in two cases.
  // The city rides only when it adds information the place does
  // not already carry.
  const placeNorm = String(p.unlisted ? (p.city || "") : marketDisplayName(p.market)).toLowerCase();
  const cityNorm = String(p.city || "").toLowerCase();
  const cityChip = p.city && !p.unlisted && cityNorm && !placeNorm.includes(cityNorm) && !cityNorm.includes(placeNorm.replace(/,.*$/, ""))
    ? `<span class="cc-chip">${esc(p.city)}</span>` : "";
  // Rate card as listed offerings (2026-11-01): the offerings
  // are public on the finished profile at every tier (Jeff's
  // CreatorMarket-standard ruling); only the Book action and
  // the booking target stay behind sign-in. Rows come from the
  // server's rateCard list, so the page, the share meta, and
  // the structured data can never quote different numbers.
  const rateRows = (p.rateCard || []).map((r) => `
      <div style="display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid #DFE7DF">
        <span><strong>${esc(r.label)}</strong><br><span class="small muted">${esc(r.detail || "")}</span></span>
        <span style="white-space:nowrap"><strong>${r.price ? "$" + fmtPrice(r.price) : "Open"}</strong></span>
      </div>`).join("");
  const rateBlock = `
    <h3 class="bookme-h">Rate card</h3>
    <div class="tint-block" style="margin-top:0">
      ${rateRows || `<p class="small muted" style="margin:0">This creator takes bookings through SIGNL; rates are set on their dashboard.</p>`}
      ${p.canBook ? `<div class="cta-row" style="justify-content:flex-start;margin-top:10px"><button class="btn" onclick="return bookMeBook()">Book on SIGNL</button></div>` : tier === 0 ? `<p class="small" style="margin:10px 0 0"><strong>Businesses:</strong> ${state.user ? "booking opens from your dashboard." : `<a class="tlink" href="#" onclick="return go('signin')">sign in</a> to book on SIGNL.`}</p>` : ""}
      <p class="small muted">${BOOKME_GUARANTEE_LINE}</p>
      <p class="small muted">${BOOKME_STAYS_LINE}</p>
    </div>`;
  // Audience visual (2026-11-01): the creator's listed markets
  // as one bar: home market first (deep green), other listed
  // markets in the SIGNL gradient hues, and the pale remainder
  // is everywhere else. Every number is the creator's own
  // reported share, labeled as such.
  const bdSegColors = ["#006AFC", "#03C9AB", "#2FE07E", "#019BFC", "#5F7265", "#006AFC"];
  const bd = p.audienceBreakdown;
  const breakdownHtml = bd && bd.segments && bd.segments.length ? `
    <div style="margin:14px 0 0">
      <div style="display:flex;height:14px;border-radius:999px;overflow:hidden;background:#E3F5EA" role="img" aria-label="Where this creator's audience lives">
        ${[...bd.segments].sort((a, b) => (a.market === view.market ? -1 : b.market === view.market ? 1 : b.pct - a.pct)).map((s, i) => `<span style="display:block;width:${s.pct}%;background:${bdSegColors[i] || "#5F7265"}"></span>`).join("")}
      </div>
      <p class="small muted" style="margin:6px 0 0">Where their audience lives: ${[...bd.segments].sort((a, b) => (a.market === view.market ? -1 : b.market === view.market ? 1 : b.pct - a.pct)).map((s) => { const cnt = followersForPct(s.pct, total); return `${esc(s.market)} ${s.pct}%${cnt ? ` &middot; ${cnt} followers` : ""}`; }).join(" &middot; ")}${bd.elsewherePct > 0 ? ` &middot; everywhere else ${bd.elsewherePct}%` : ""}. Self-reported by the creator.</p>
    </div>` : "";
  const socialsBlock = tier >= 2 ? `
    ${p.socialsHiddenByCreator ? "" : (p.socialLinks && p.socialLinks.length ? `
    <div class="bookme-socials">
      <h3 class="bookme-h">Their channels</h3>
      ${p.socialLinks.map((s) => `<a class="bookme-channel" href="${esc(s.url)}" target="_blank" rel="noopener"><span class="bookme-channel-name">${esc(s.label)}</span><span class="bookme-channel-go">View channel</span></a>`).join("")}
    </div>` : "")}
    ${p.canMessage ? `
    <div class="bookme-message">
      <h3 class="bookme-h">Message ${esc(p.name.split(" ")[0] || "them")} on SIGNL</h3>
      <textarea id="bm-msg" rows="3" maxlength="2000" placeholder="Say hello and what you have in mind. Booking talk stays here, in SIGNL."></textarea>
      <div class="cta-row" style="justify-content:flex-start"><button class="btn" onclick="bookMeSendMessage('${esc(p.handle)}')">Message</button></div>
      <p class="small muted" id="bm-msg-note"></p>
    </div>` : ""}` : `
    <div class="bookme-locked">
      <p style="margin:0">${BOOKME_LOCKED_LINE}</p>
    </div>`;
  app.innerHTML = `
  <div class="public-profile bookme theme-${esc(p.pageTheme || "ink")}" style="max-width:720px;margin:20px auto">
    <div class="bookme-cover${p.photoUrl ? " has-photo" : " no-photo"}">
      ${p.photoUrl ? `<img class="bookme-banner" src="${esc(p.photoUrl)}" alt="">` : `<div class="cc-mono bookme-mono"><span>${initial}</span></div>`}
      <div class="bookme-cover-id">
        <div class="bookme-id-row">
          <div class="bookme-id-main">
            <div class="cc-name bookme-name">${esc(profileDisplayName(p))}</div>
            <div class="bookme-handle">@${esc(p.handle)} &middot; ${esc(p.primaryPlatformLabel || "Instagram")}</div>
            ${profileHeaderSocialsHtml(p)}
            ${p.charter ? `<span class="charter-seal sm">Charter Creator</span>` : ""}
          </div>
          ${profileHeaderStatsHtml(p)}
        </div>
      </div>
    </div>
    ${p.realPeopleChecked ? `<p class="small" style="margin:10px 0 0"><span class="badge ok">Checked by a person</span> Real posts, real local life.</p>` : ""}
    ${galleryRowHtml(p.photos)}
    <section class="panel bookme-body">
      <div class="cc-chips">
        <span class="cc-chip market">${place}</span>
        ${cityChip}
        ${p.neighborhood ? `<span class="cc-chip">${esc(p.neighborhood)}</span>` : ""}
        ${p.campusBadge ? `<span class="cc-chip">${esc(p.campusBadge)}</span>` : ""}
        ${p.tierBand ? `<span class="cc-chip">${esc(p.tierBand)}</span>` : ""}
        ${p.isRealtor ? `<span class="cc-chip">Realtor</span>` : ""}
        ${p.charter ? "" : `<span class="cc-chip">Founding Creator</span>`}
        ${(p.listedMarkets || []).filter((m) => m.market !== view.market).map((m) => { const cnt = followersForPct(m.pct, total); return `<span class="cc-chip">Also ranked in ${esc(m.market)} &middot; ${m.pct}%${cnt ? ` &middot; ${cnt} followers` : " of followers"}</span>`; }).join("")}
      </div>
      ${p.pitchLine ? `<p class="bookme-pitch" style="font-size:1.05rem;margin:10px 0 0"><em>${esc(p.pitchLine)}</em></p>` : ""}
      ${p.bio ? `<p class="bookme-bio">${esc(p.bio)}</p>` : ""}
      <div class="cc-local">
        ${view.pct === null || view.pct === undefined
          ? `<div class="lbl">Local audience not reported yet</div>`
          : `<div class="big">${view.pct}%</div><div class="lbl">of their audience is local to ${esc(view.market)}</div>${followersForPct(view.pct, total) ? `<div style="font-weight:800;margin-top:2px">${followersForPct(view.pct, total)} followers</div>` : ""}<div class="src">${(p.localAudienceSource || "Self-reported") === "Self-reported" ? "Self-reported: the creator's own number" : esc(p.localAudienceSource)}</div>`}
      </div>
      ${breakdownHtml}
      ${p.proof && p.proof.visitsCompleted > 0 ? `<div class="wcard" style="margin:14px 0 0"><p style="margin:0"><span class="badge ok">Verified on SIGNL</span></p><p style="margin:8px 0 0"><strong>${p.proof.visitsCompleted} visit${p.proof.visitsCompleted === 1 ? "" : "s"} completed</strong> &middot; ${p.proof.onTimePosts} on time</p><p class="small muted" style="margin:6px 0 0">From this creator's real SIGNL visits, counted by SIGNL, not claimed by the creator.</p></div>` : ""}
      ${p.engagement && p.engagement.postsWithMetrics >= 3 ? `<div class="wcard" style="margin:14px 0 0"><p style="margin:0"><span class="badge ok">Post engagement</span></p><p style="margin:8px 0 0"><strong>${Number(p.engagement.totals.views || 0).toLocaleString("en-US")} views &middot; ${Number(p.engagement.totals.likes || 0).toLocaleString("en-US")} likes &middot; ${Number(p.engagement.totals.shares || 0).toLocaleString("en-US")} shares &middot; ${Number(p.engagement.totals.saves || 0).toLocaleString("en-US")} saves</strong></p><p class="small muted" style="margin:4px 0 0">Per post on average: ${Number(p.engagement.averages.views || 0).toLocaleString("en-US")} views, ${Number(p.engagement.averages.likes || 0).toLocaleString("en-US")} likes, ${Number(p.engagement.averages.shares || 0).toLocaleString("en-US")} shares, ${Number(p.engagement.averages.saves || 0).toLocaleString("en-US")} saves. From ${p.engagement.postsWithMetrics} SIGNL posts with reported numbers. Recorded: the creator's own reported figures.</p></div>` : ""}
      ${p.categories && p.categories.length ? `<p class="small">${p.categories.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
      ${p.isRealtor && p.farmAreas && p.farmAreas.length ? `<p class="small">Neighborhoods: ${p.farmAreas.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
      ${p.streets && p.streets.length ? `<p class="small">My streets: ${p.streets.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
      ${p.compCategories && p.compCategories.length ? `<p class="small muted">Open to comps: ${p.compCategories.map(esc).join(", ")}</p>` : ""}
      ${workGridHtml(p)}
      ${rateBlock}
      ${socialsBlock}
      ${visitIncludesHtml(p.visitIncludes)}
      ${p.isRealtor && p.brokerage ? `<p class="small muted">Brokered by ${esc(p.brokerage)}</p>` : ""}
      ${p.viewerIsOwner ? `<p class="small muted">This is your book-me page, exactly as visitors see it. Edit it any time under Profile.</p><p class="small">${shareBlockHtml(p.handle, p.market || "", "Share your invite")}</p>` : ""}
    </section>
    ${!state.user ? `<div class="bookme-sticky"><span class="bs-name">Book ${esc(p.firstName || p.name)} on SIGNL</span><a class="btn bs-btn" href="#" onclick="return go('signin')">Book on SIGNL</a></div>` : ""}
  </div>`;
}

// Claim-tier page (Build -61, Jeff, 2026-10-31): the page a
// creator holds from the moment they claim their founding spot.
// It shows what the claim actually captured (handle, market, any
// categories on the record) plus the rate card, and says plainly
// that booking opens when the market launches. No audience
// numbers, no local reach, no proof: none of that exists yet.
// When the profile is finished and approved, the full book-me
// page above takes over this same URL.
function renderClaimedProfile(p) {
  const placeLabel = p.unlisted ? esc(p.city || "") : esc(marketDisplayName(p.market));
  const place = p.unlisted ? (p.city || "") : (p.market || "");
  document.title = `@${p.handle} on SIGNL${place ? ` | ${place}` : ""}`;
  setShareCanonical(`https://app.joinsignl.com/c/${p.handle}`);
  setShareMeta("og:title", "property", document.title);
  setShareMeta("og:description", "property", `@${p.handle} is a founding creator on SIGNL in ${place || "their market"}. Their booking page is live: local businesses book local creators for honest posts, and founding creators get the first look when businesses start booking.`);
  setShareMeta("og:type", "property", "profile");
  setShareMeta("twitter:card", "name", "summary");
  setShareMeta("twitter:title", "name", document.title);
  const initial = esc((p.name || "?").trim().charAt(0).toUpperCase() || "?");
  app.innerHTML = `
  <div class="public-profile bookme" style="max-width:720px;margin:20px auto">
    <div class="bookme-cover">
      <div class="cc-mono bookme-mono"><span>${initial}</span></div>
      <div class="bookme-cover-id">
        <div class="cc-name bookme-name">${esc(p.name)}</div>
        <div class="bookme-handle">@${esc(p.handle)} &middot; ${esc(p.primaryPlatformLabel || "Instagram")}</div>
      </div>
    </div>
    <section class="panel bookme-body">
      <div class="cc-chips">
        <span class="cc-chip market">${placeLabel}</span>
        <span class="cc-chip">Founding Creator</span>
        ${(p.categories || []).map((x) => `<span class="cc-chip">${esc(x)}</span>`).join("")}
      </div>
      <p style="margin:12px 0 0"><strong>This booking page is live.</strong> It went live the moment @${esc(p.handle)} claimed their founding spot. Their full profile lands here once it is finished and approved.</p>
      <div class="tint-block" style="margin-top:14px">
        <p class="small" style="margin-top:0">${p.compOpen === false ? `<span class="badge warn">Paid visits only</span>` : `<span class="badge info">Open to comp visits</span>`}${p.paidRate ? ` <span class="badge tier">Paid bookings: ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)}</span>` : ""}</p>
        <p class="small muted" style="margin:6px 0 0">${p.compOpen === false ? "Paid bookings only." : "Comped visits: a meal, a service, or an experience, for an honest post."}</p>
        ${p.paidRate ? `<p class="small muted">Paid bookings at ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)} &middot; creator keeps 97% &middot; payment held until the post is live.</p>` : ""}
        ${p.licensingFee ? `<p class="small muted">Run my post as an ad for 90 days: ${currencySymbolForMarket(p.market)}${fmtPrice(p.licensingFee)} &middot; I approve each use &middot; I keep 97%.</p>` : ""}
      </div>
      <p class="small muted">Booking opens when ${placeLabel} launches on SIGNL. Founding creators get the first look at offers.</p>
      ${p.viewerIsOwner ? `<p class="small muted">This is your page, exactly as visitors see it. The copyable link is on your status screen and your profile. Finish your profile from your dashboard and your photo, your audience, and your local reach appear here.</p>` : state.user ? "" : `<div class="cta-row" style="justify-content:flex-start"><a class="btn" href="#" onclick="return go('join-business')">Join as a founding business</a> <a class="btn ghost" href="#" onclick="return go('join-creator')">Become a Founding Creator</a></div>`}
    </section>
  </div>`;
}

// Listing presentation proof (Jeff, 2026-10-22, realtor layer):
// a print-optimized one-pager at /c/<handle>/proof, rendered from
// the SAME public payload as /c/<handle>, so it can only ever show
// public facts: no email, no account data, nothing private. The
// owner reaches it from the "Listing proof sheet" action on their
// own Profile tab; anyone with the link sees the same public
// facts. Honesty rule (playbook Part 3): every number here is a
// real stored value from the creator's record. A metric that is
// null or gated (rating below 3 businesses) is OMITTED, never
// estimated, projected, or zero-filled into a claim.
async function renderPublicProof() {
  const handle = state.publicHandle || "";
  app.innerHTML = `<section class="panel center" style="max-width:560px;margin:40px auto"><p class="muted">Loading the proof sheet for @${esc(handle)}...</p></section>`;
  let p = null;
  try {
    const data = await api("GET", "/c/" + encodeURIComponent(handle));
    p = data.profile;
  } catch (e) { p = null; }
  if (!p) {
    document.title = "Proof sheet not public | SIGNL";
    app.innerHTML = `
    <section class="panel center" style="max-width:560px;margin:40px auto">
      <h2>Proof sheet not public</h2>
      <p class="muted">There is no public SIGNL profile at this link yet, so there is no proof sheet to show. Proof sheets exist once a creator is approved and public.</p>
      <div class="cta-row" style="justify-content:center">
        ${state.user ? `<a class="btn" href="#" onclick="return go('dashboard')">Back to my dashboard</a>` : `<a class="btn" href="#" onclick="return go('join-creator')">Become a Founding Creator</a>`}
      </div>
    </section>`;
    return;
  }
  const place = p.unlisted ? (p.city || "") : (p.market || "");
  document.title = `Listing proof: ${p.name} (@${p.handle}) | SIGNL`;
  const initial = esc((p.name || "?").trim().charAt(0).toUpperCase() || "?");
  const tr = p.trackRecord || {};
  const generated = new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
  const statCells = [];
  if (totalAudienceOf(p) > 0) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${fmtNum(totalAudienceOf(p))}</div><div class="stat-lbl">Stacked audience, all platforms</div></div>`);
  }
  if (p.localAudiencePct !== null && p.localAudiencePct !== undefined) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${p.localAudiencePct}%</div><div class="stat-lbl">Local reach (${(p.localAudienceSource || "Self-reported") === "Self-reported" ? "self-reported: their own number" : esc(p.localAudienceSource)})</div></div>`);
  }
  if (p.spanishAudiencePct !== null && p.spanishAudiencePct !== undefined) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${p.spanishAudiencePct}%</div><div class="stat-lbl">Spanish-speaking audience (self-reported)</div></div>`);
  }
  if (typeof p.momentumPoints === "number") {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${p.momentumPoints}</div><div class="stat-lbl">Momentum points · part of the order businesses see</div></div>`);
  }
  if (p.ratingCount >= 3 && p.ratingAvg !== null && p.ratingAvg !== undefined) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${esc(String(p.ratingAvg))} / 5</div><div class="stat-lbl">Rating from ${p.ratingCount} businesses</div></div>`);
  }
  if (tr.postsDelivered > 0) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${tr.postsDelivered}</div><div class="stat-lbl">Posts delivered on SIGNL</div></div>`);
  }
  if (tr.visitsCompleted > 0) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${tr.visitsCompleted}</div><div class="stat-lbl">Visits completed</div></div>`);
  }
  if (tr.postsDelivered > 0 && tr.onTimePct !== null && tr.onTimePct !== undefined) {
    statCells.push(`<div class="stat-cell"><div class="stat-num">${tr.onTimePct}%</div><div class="stat-lbl">Posts on time</div></div>`);
  }
  app.innerHTML = `
  <div class="proof-sheet">
    <div class="proof-head">
      ${p.photoUrl ? `<img class="proof-photo" src="${esc(p.photoUrl)}" alt="">` : `<div class="proof-mono"><span>${initial}</span></div>`}
      <div class="proof-id">
        <div class="proof-name">${esc(p.name)}</div>
        <div class="proof-handle">@${esc(p.handle)} &middot; ${esc(p.primaryPlatformLabel || "Instagram")}</div>
        <div class="proof-place">${esc(place)}${p.city && !p.unlisted ? ` &middot; ${esc(p.city)}` : ""}${p.neighborhood ? ` &middot; ${esc(p.neighborhood)}` : ""}</div>
        <div class="cc-chips" style="margin-top:8px">
          ${p.tierBand ? `<span class="cc-chip">${esc(p.tierBand)}</span>` : ""}
          ${p.isRealtor ? `<span class="cc-chip">Realtor</span>` : ""}
          <span class="cc-chip">Founding Creator</span>
        </div>
      </div>
      <div class="proof-brand">SIGNL</div>
    </div>
    ${p.isRealtor && p.farmAreas && p.farmAreas.length ? `<p class="proof-hoods">Neighborhoods: ${p.farmAreas.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
    ${p.streets && p.streets.length ? `<p class="proof-hoods">My streets: ${p.streets.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
    <div class="stat-band proof-stats">${statCells.join("")}</div>
    ${tr.businessesWorkedWith && tr.businessesWorkedWith.length ? `<p class="proof-biz">Businesses posted for: ${tr.businessesWorkedWith.map(esc).join(", ")}</p>` : ""}
    ${p.isRealtor && p.brokerage ? `<p class="proof-brokerage">Brokered by ${esc(p.brokerage)}</p>` : ""}
    <div class="proof-foot">
      <p>Activity verified by SIGNL &middot; Generated ${esc(generated)}</p>
      <p class="muted">Every figure on this sheet comes from this creator's real SIGNL record: delivered posts, tracked visits, and business ratings. Local audience share is reported by the creator and labeled with its source above. Nothing here is estimated or projected.</p>
    </div>
    <div class="cta-row no-print" style="justify-content:flex-start;margin-top:16px">
      <button class="btn" onclick="window.print()">Print or save as PDF</button>
      <a class="btn ghost" href="/c/${encodeURIComponent(p.handle)}">Back to profile</a>
    </div>
  </div>`;
}

function inviteUrlFor(u) {
  const handle = u && u.creator && u.creator.handle;
  return handle ? `https://app.joinsignl.com/?ref=${encodeURIComponent(handle)}` : "";
}

// One-tap referral sharing (Jeff, 2026-10-21, narrow scope): the
// creator's referral link with a pre-written founding-status line
// naming their market. navigator.share where the platform offers
// it (the mobile share sheet: Instagram, Facebook, messages);
// otherwise a small fallback menu: copy link, Facebook, X,
// WhatsApp. Placed ONLY in the dashboard roster block, the
// founding status (approval) surface, the profile-completion
// moment, and the public /c/ profile (with the profile owner's
// own referral link, so the creator is credited whoever shares).
function displayMarketName(place) {
  return place === "Hampton Roads" ? "Virginia Beach" : place;
}

function sharePayloadFor(place, handle, subjectName) {
  place = displayMarketName(place);
  const url = `https://app.joinsignl.com/?ref=${encodeURIComponent(handle || "")}`;
  const text = subjectName
    ? `${subjectName} is a founding creator on SIGNL in ${place}. Local businesses comp creators for honest posts, and it is free for creators. Claim your spot:`
    : `I just became a founding creator on SIGNL in ${place}. Local businesses comp creators for honest posts, and it is free for creators. Claim your spot:`;
  return { title: "SIGNL", text, url };
}

function shareBlockHtml(handle, place, label, subjectName) {
  if (!handle) return "";
  const payload = sharePayloadFor(place, handle, subjectName);
  const full = `${payload.text} ${payload.url}`;
  return `<span class="share-wrap"><button type="button" class="btn small-btn ghost" data-share-handle="${esc(handle)}" data-share-place="${esc(displayMarketName(place) || "")}"${subjectName ? ` data-share-name="${esc(subjectName)}"` : ""} onclick="return shareInvite(this)">${esc(label || "Share your invite")}</button><span class="share-menu" style="display:none"> <a href="#" onclick="return copyShareLink(this)">Copy link</a> &middot; <a href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(payload.url)}" target="_blank" rel="noopener">Facebook</a> &middot; <a href="https://twitter.com/intent/tweet?text=${encodeURIComponent(payload.text)}&url=${encodeURIComponent(payload.url)}" target="_blank" rel="noopener">X</a> &middot; <a href="https://wa.me/?text=${encodeURIComponent(full)}" target="_blank" rel="noopener">WhatsApp</a></span></span>`;
}

function shareInvite(btn) {
  const payload = sharePayloadFor(btn.getAttribute("data-share-place") || "", btn.getAttribute("data-share-handle") || "", btn.getAttribute("data-share-name") || "");
  if (navigator.share) {
    navigator.share(payload).catch(() => {});
    return false;
  }
  const menu = btn.parentElement ? btn.parentElement.querySelector(".share-menu") : null;
  if (menu) menu.style.display = menu.style.display === "block" ? "none" : "block";
  return false;
}

function copyShareLink(a) {
  const wrap = a.closest ? a.closest(".share-wrap") : null;
  const btn = wrap ? wrap.querySelector("[data-share-handle]") : null;
  const url = btn ? sharePayloadFor("", btn.getAttribute("data-share-handle") || "").url : "";
  if (url && navigator.clipboard) navigator.clipboard.writeText(url).catch(() => {});
  a.textContent = "Copied";
  return false;
}

// University autocomplete (Jeff, 2026-10-21): the bundled IPEDS
// institution dataset (public/data/us-colleges.json, US Dept of
// Education) lazy-loads the first time a form renders the field.
// Typing 2+ characters matches names and aliases; picking a
// result fills the canonical dataset name, and the server
// resolves it (plus city/state) at save. Text with no pick is
// sent as typed and lands as a flagged free entry.
let collegesClientCache = null;
let collegesClientLoading = null;
function loadCollegesClient() {
  if (collegesClientCache) return Promise.resolve(collegesClientCache);
  if (!collegesClientLoading) {
    collegesClientLoading = fetch("/data/us-colleges.json")
      .then((r) => (r.ok ? r.json() : []))
      .then((list) => {
        collegesClientCache = (Array.isArray(list) ? list : []).map((rec) => ({ n: rec.n, a: rec.a || [], c: rec.c, s: rec.s, q: (rec.n + " " + (rec.a || []).join(" ")).toLowerCase() }));
        return collegesClientCache;
      })
      .catch(() => { collegesClientCache = []; return collegesClientCache; });
  }
  return collegesClientLoading;
}

function universityMatches(q) {
  const query = (q || "").trim().toLowerCase();
  if (query.length < 2 || !collegesClientCache) return [];
  const starts = [];
  const subs = [];
  for (const rec of collegesClientCache) {
    if (rec.n.toLowerCase().startsWith(query) || rec.a.some((a) => a.toLowerCase().startsWith(query))) starts.push(rec);
    else if (rec.q.includes(query)) subs.push(rec);
    if (starts.length >= 8) break;
  }
  return starts.concat(subs).slice(0, 8);
}

function setupUniversityAutocomplete(inputId, resultsId) {
  const input = document.getElementById(inputId);
  const box = document.getElementById(resultsId);
  if (!input || !box || input.dataset.uniWired) return;
  input.dataset.uniWired = "1";
  input.setAttribute("autocomplete", "off");
  loadCollegesClient();
  input.addEventListener("input", () => {
    const q = input.value;
    if ((q || "").trim().length < 2) { box.innerHTML = ""; return; }
    loadCollegesClient().then(() => {
      const ms = universityMatches(q);
      box.innerHTML = ms.map((rec, i) => `<button type="button" class="uni-opt" data-uni-i="${i}"><strong>${esc(rec.n)}</strong> <span class="muted">${esc(rec.c)}, ${esc(rec.s)}</span></button>`).join("");
      box.querySelectorAll(".uni-opt").forEach((btn, i) => {
        btn.addEventListener("click", () => {
          input.value = ms[i].n;
          box.innerHTML = "";
        });
      });
    });
  });
  input.addEventListener("blur", () => { setTimeout(() => { box.innerHTML = ""; }, 200); });
}

function universityStatusSuffix(u) {
  // Admin detail helper: " (Current student)" / " (Alumni)" /
  // " (Not a student)" beside the university, empty when unset.
  const s = (u && u.universityStatus) || (u && u.creator && u.creator.universityStatus) || "";
  const label = { current_student: "Current student", alumni: "Alumni", not_student: "Not a student" }[s] || "";
  return label ? ` (${label})` : "";
}

function campusBadgeHtml(source) {
  if (!source) return "";
  let badge = "";
  if (typeof source === "string") badge = source;
  // The server computes the badge under the student-status gate
  // (current students only): when the field is present, even as
  // null, it is the whole answer. Never re-derive it from the
  // university alone, or alumni would get their badge back.
  else if ("campusBadge" in source) badge = source.campusBadge || "";
  else if (source.profile && "campusBadge" in source.profile) badge = source.profile.campusBadge || "";
  else if (source.creator && "campusBadge" in source.creator) badge = source.creator.campusBadge || "";
  return badge ? ` <span class="badge info">${esc(badge)}</span>` : "";
}

function growRosterHtml(u) {
  const link = inviteUrlFor(u);
  if (!link) return "";
  const place = u.market === unlistedLabel() ? (u.city || "your city") : u.market;
  const m = u.momentum || { signups: 0, approved: 0, points: 0 };
  return `
    <div class="panel mt" id="grow-roster" style="text-align:left">
      <h3 style="margin-top:0">Grow your roster</h3>
      <p class="small">Share your invite link — creators who join through it are credited to you.</p>
      <div class="field"><label>Your invite link</label><input type="text" readonly value="${esc(link)}" onclick="this.select()"></div>
      <p class="small">${shareBlockHtml(u.creator && u.creator.handle, place, "Share your invite")}</p>
      ${m.signups > 0 ? `<p class="small"><strong>Your roster:</strong> ${m.signups} ${m.signups === 1 ? "creator" : "creators"} joined through your link &middot; ${m.approved} approved &middot; <strong>${m.points} Momentum points</strong></p>` : ""}
      ${m.campusCrew ? `<p class="small"><strong>Your campus crew: ${m.campusCrew.count} creator${m.campusCrew.count === 1 ? "" : "s"} from ${esc(m.campusCrew.university)}</strong></p>` : ""}
      ${m.campusLead && m.campusLead.qualified ? `<p class="small"><strong>Campus Lead · ${esc(m.campusLead.university)}</strong> — ${m.campusLead.count} classmates you recruited are approved. The badge is on your profile.</p>` : m.campusLead && m.campusLead.count > 0 ? `<p class="small"><strong>Campus Lead at ${esc(m.campusLead.university)}:</strong> ${m.campusLead.count} of ${m.campusLead.threshold} classmates recruited and approved — ${m.campusLead.needed} more earns the badge.</p>` : ""}
      <p class="small">Points: +3 per sign-up &middot; +10 per approval. Roster builders get seen first. ${POINTS_WHY_SHORT}</p>
      ${ladderHtml(u)}
      <p class="small muted">Tap the link to copy it.</p>
    </div>`;
}

// Earn-row deep links (Jeff, 2026-10-27): a checklist row is a
// link only when its action can be completed right now, and the
// tap lands on the exact surface (and field) that completes it.
// Checkmarked rows stay plain. Outcome rows (an on-time post, a
// streak, a business running a post as an ad) can never be
// completed on demand, so they stay plain forever. The two
// state-dependent rows (review a business, report post numbers)
// link only while the server payload names a due visit for them
// (item.dueBookingId); otherwise they are plain too.
const EARN_STACK_IDS = ["p-followers", "p-stack-tiktok", "p-stack-facebook", "p-stack-x", "p-stack-linkedin", "p-stack-youtube", "p-stack-snapchat"];
const EARN_WORK_IDS = ["p-work-0", "p-work-1", "p-work-2"];

function earnActionFor(item, u) {
  if (!item) return null;
  if (item.id === "reviews" || item.id === "performance") {
    return item.dueBookingId ? { visit: item.dueBookingId } : null;
  }
  if (item.done) return null;
  switch (item.id) {
    case "photo": return { tab: "Profile", scroll: "p-gallery" };
    case "bio": return { tab: "Profile", focus: ["p-bio"] };
    case "neighborhood": return { tab: "Profile", focus: ["p-neighborhood"] };
    case "local": return { tab: "Profile", focus: ["p-localpct"] };
    case "stack":
    case "audience": return { tab: "Profile", focusFirstEmpty: EARN_STACK_IDS };
    case "bestwork": return { tab: "Profile", focusFirstEmpty: EARN_WORK_IDS };
    case "city": return { tab: "Profile", focus: ["p-city", "p-city-text"] };
    case "categories": return { tab: "Profile", focusSelector: "input[name='p-cat']" };
    case "firstoffer": return (!u || !u.founding || u.founding.marketLive) ? { tab: "Offers" } : null;
    case "referrals": return { tab: "Momentum", scroll: "grow-roster" };
    default: return null;
  }
}

// The leading icon follows the same rule as the link itself
// (Jeff, 2026-10-27): done earns the mint check; a row you can
// complete right now wears the filled mint "+"; a row you cannot
// act on gets NO icon at all — an empty slot of the same width
// keeps the labels aligned, the points still print, and the
// check appears the moment the thing actually happens.
function earnStateHtml(item, u) {
  if (item.done) return `<span class="earn-state">&#10003;</span>`;
  if (earnActionFor(item, u)) return `<span class="earn-state">+</span>`;
  return `<span class="earn-state earn-slot" aria-hidden="true"></span>`;
}

function earnRowWrap(item, u, inner) {
  const cls = `earn-row ${item.done ? "done" : ""}`;
  const stateHtml = earnStateHtml(item, u);
  if (!earnActionFor(item, u)) return `<div class="${cls}">${stateHtml}${inner}</div>`;
  return `<button type="button" class="${cls} earn-link" onclick="return earnGo('${item.id}')">${stateHtml}${inner}<span class="earn-chev">&#8250;</span></button>`;
}

function earnFindEl(ids, selector, firstEmpty) {
  if (selector) return document.querySelector(selector);
  if (!ids) return null;
  let first = null;
  for (const id of ids) {
    const el = document.getElementById(id);
    if (!el) continue;
    if (!firstEmpty) return el;
    if (!first) first = el;
    const v = String(el.value || "").trim();
    if (v === "" || v === "0") return el;
  }
  return first;
}

function earnFocusWhenReady(ids, selector, firstEmpty) {
  let tries = 0;
  const step = () => {
    const el = earnFindEl(ids, selector, firstEmpty);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "center" });
      setTimeout(() => { try { el.focus({ preventScroll: true }); } catch (e) { /* focus is an enhancement; the scroll already landed */ } }, 260);
      return;
    }
    if (++tries < 24) setTimeout(step, 75);
  };
  setTimeout(step, 60);
}

function earnScrollWhenReady(id) {
  let tries = 0;
  const step = () => {
    const el = document.getElementById(id);
    if (el) { el.scrollIntoView({ behavior: "smooth", block: "start" }); return; }
    if (++tries < 24) setTimeout(step, 75);
  };
  setTimeout(step, 60);
}

function earnGo(id) {
  const u = state.user;
  if (!u) return false;
  const pools = [...(((u.momentum || {}).checklist) || []), ...(((u.profileCompletion || {}).items) || [])];
  const item = pools.find((i) => i.id === id);
  const act = earnActionFor(item, u);
  if (!act) return false;
  if (act.visit) {
    state.visitsSeg = "done";
    state.visitFocus = act.visit;
    go("dashboard", "My Visits");
    if (id === "performance") earnFocusWhenReady([`perf-views-${act.visit}`], null, false);
    return false;
  }
  go("dashboard", act.tab);
  if (act.focusFirstEmpty) earnFocusWhenReady(act.focusFirstEmpty, null, true);
  else if (act.focus) earnFocusWhenReady(act.focus, null, false);
  else if (act.focusSelector) earnFocusWhenReady(null, act.focusSelector, false);
  else if (act.scroll) earnScrollWhenReady(act.scroll);
  return false;
}

// Two-step claim, step two (Jeff, 2026-10-20): the finish-your-
// profile card. It rides on an approved creator's dashboard until
// the profile is complete: progress over the gate items, every
// item with its Momentum value, and the button into the Profile
// tab where the work happens. Data is the server-computed
// user.profileCompletion payload; nothing here is client math.
function profileCompletionHtml(u) {
  const pc = u && u.profileCompletion;
  if (!pc || pc.complete || u.role !== "creator" || u.status !== "approved") return "";
  const rows = pc.items.map((item) => earnRowWrap(item, u, `
      <span class="earn-label">${esc(item.label)}${item.required && !item.done ? ` <span class="badge info">Needed</span>` : ""}${item.detail ? ` <span class="muted">(${esc(item.detail)})</span>` : ""}</span>
      <span class="earn-points">${item.points ? "+" + item.points + " pts" : ""}</span>`)).join("");
  return `
  <div class="panel mt tint" style="text-align:left">
    <div class="flex-between"><h3 style="margin:0">${T("Finish your profile to be launch-ready", "Termina tu perfil para estar listo al lanzar")}</h3><span class="badge info">${pc.requiredDone} ${T("of", "de")} ${pc.requiredTotal} ${T("essentials done", "esenciales listos")}</span></div>
    <p class="small">${T("Businesses can't see you until the essentials are done.", "Los negocios no pueden verte hasta que termines lo esencial.")}</p>
    ${rows}
    <div class="mt"><button class="btn" onclick="return goFinishProfile()">${T("Finish my profile", "Terminar mi perfil")}</button></div>
  </div>`;
}

// Momentum (expanded, Jeff 2026-10-19): one computed currency. The
// dashboard shows the total, the ways-to-earn checklist with live
