// The matcher: phrase hits are strongest, then word-group hits,
// then solo tokens. Longer words tolerate a one-letter typo.
// Scores are compared across the whole bank; a clear winner
// answers, anything murky falls back honestly with suggestions.
function sigNorm(text) {
  return " " + String(text || "").toLowerCase().replace(/can't/g, "cant").replace(/don't/g, "dont").replace(/won't/g, "wont").replace(/[^a-z0-9% ]+/g, " ").replace(/\s+/g, " ").trim() + " ";
}
function sigLev(a, b) {
  if (Math.abs(a.length - b.length) > 1) return 2;
  let d = 0;
  const m = Math.min(a.length, b.length);
  for (let i = 0; i < m; i++) if (a[i] !== b[i]) d++;
  d += Math.abs(a.length - b.length);
  return d;
}
function sigTokenHit(t, toks, variant) {
  if (variant.includes(" ")) return t.includes(" " + variant + " ") ? 3 : 0;
  if (t.includes(" " + variant + " ") || t.includes(" " + variant)) return 3;
  if (variant.length >= 5) for (const tok of toks) if (tok.length >= 4 && sigLev(tok, variant) <= 1) return 2;
  return 0;
}
function sigScoreTopic(topic, t, toks) {
  let score = 0;
  for (const p of topic.ph || []) { const np = p.replace(/can't/g, "cant").replace(/don't/g, "dont").replace(/won't/g, "wont"); if (t.includes(np)) score += 10; }
  for (const group of topic.g || []) {
    let best = 0;
    for (const v of group) best = Math.max(best, sigTokenHit(t, toks, v));
    score += best === 3 ? 4 : best === 2 ? 3 : 0;
  }
  for (const s of topic.s || []) if (sigTokenHit(t, toks, s)) score += 6;
  return score;
}
function sigMatch(text, biz) {
  const bank = sigBankFor(biz);
  const t = sigNorm(text);
  const toks = t.split(" ").filter(Boolean);
  const scored = bank.map((topic, i) => ({ topic, i, score: sigScoreTopic(topic, t, toks) })).sort((a, b) => b.score - a.score || a.i - b.i);
  const top = scored[0];
  const second = scored[1];
  if (top && top.score >= 8 && (!second || top.score > second.score || top.score >= 14)) return { topic: top.topic, score: top.score, scored };
  return { topic: null, score: top ? top.score : 0, scored };
}
// SIGBANK-END (verify-sig extracts the bank + matcher between
// the sigBankFor definition and this marker)

// The straight answers accordion (Sig tab + Ask Sig sheet) reads
// the same bank, so what Sig says in chat and what is listed can
// never drift apart.
function sigQaFor() {
  const u = state.user;
  if (!u) return [];
  const ctx = sigCtx();
  return sigBankFor(ctx.biz).map((topic) => ({ q: topic.q, keys: topic.ph || [], a: typeof topic.a === "function" ? topic.a(ctx) : topic.a }));
}

function sigFlowIndex(label) {
  if (!label) return null;
  const flows = sigFlowsFor();
  const i = flows.findIndex((f) => f.label === label);
  return i > -1 ? i : null;
}
function sigTopicReply(topic, ctx) {
  const text = typeof topic.a === "function" ? topic.a(ctx) : topic.a;
  const label = typeof topic.flow === "function" ? topic.flow(ctx) : topic.flow;
  return { text, flow: sigFlowIndex(label) };
}
function sigFallbackReply(match) {
  const near = (match.scored || []).filter((s) => s.score >= 4).slice(0, 3).map((s) => s.topic);
  const reply = { text: "I don't have that one yet.", suggest: [] };
  if (near.length) {
    reply.text += " The closest things I can answer are right here; tap one and I will tell you straight. For anything else, hello@joinsignl.com reaches a person.";
    reply.suggest = near.map((topic) => topic.q);
  } else {
    reply.text += " Try me on how SIGNL works, what things cost, or how visits and points run. For anything else, hello@joinsignl.com reaches a person.";
  }
  return reply;
}
// The bank route: Sig's offline brain. Also used to pick the
// walk-to button under an AI answer.
function sigRouteAsk(text) {
  const ctx = sigCtx();
  const match = sigMatch(text, ctx.biz);
  if (match.topic) return sigTopicReply(match.topic, ctx);
  const t = sigNorm(text);
  const flows = sigFlowsFor();
  for (let i = 0; i < flows.length; i++) if (flows[i].keys.some((k) => t.includes(k))) return { text: `That lives under "${flows[i].label}". One tap takes you there.`, flow: i };
  return sigFallbackReply(match);
}
// Ask Sig: the server first (Build -69: its live-data brain
// answers factual questions straight from the records with
// source "data"; the real AI, canon-grounded and fed the same
// live fact sheet, takes the rest with source "ai"), the bank
// when the server cannot answer.
// Build -81 (Jeff, 2026-11-02): anything Sig SHOWS carries its
// walk. sigdata's linked answers name a destination key; this
// map is the one place keys become real navigation, per role.
// Admin keys point only at the console's own record tabs, so
// the console stays read-only: the walk never edits a record
// and never lands on someone else's surface.
function sigLinkGo(dest) {
  // Build -102: a same-origin path dest (a public roster page)
  // opens as a page, in a new tab so the dashboard stays put.
  if (typeof dest === "string" && dest.startsWith("/roster/")) { window.open(dest, "_blank", "noopener"); return false; }
  switch (dest) {
    case "biz-home": return go("dashboard", "Home");
    case "biz-results": return go("dashboard", "Analytics");
    case "biz-applicants": state.offersSeg = "applicants"; return go("dashboard", "My Offers");
    case "biz-offers": return go("dashboard", "My Offers");
    case "biz-setup": return go("dashboard", "Campaign Setup");
    case "biz-drafts": state.offersSeg = "drafts"; return go("dashboard", "My Offers");
    case "biz-discover": return go("dashboard", "Discover");
    case "biz-visits": return go("dashboard", "Visits & Posts");
    case "biz-regulars": return go("dashboard", "Regulars");
    case "biz-profile": return go("dashboard", "Profile");
    case "biz-content": return go("dashboard", "Content");
    case "cr-numbers": return go("dashboard", "Numbers");
    case "cr-momentum": return go("dashboard", "Momentum");
    case "cr-offers": return go("dashboard", "Offers");
    case "cr-offers-applied": state.crOffersSeg = "applied"; return go("dashboard", "Offers");
    case "cr-offers-invited": state.crOffersSeg = "invited"; return go("dashboard", "Offers");
    case "cr-visits": state.visitsSeg = "needs"; return go("dashboard", "My Visits");
    case "cr-earnings": return go("dashboard", "Earnings");
    case "cr-terms": window.open("https://joinsignl.com/creator-terms.html", "_blank", "noopener"); return false;
    case "cr-profile": return go("dashboard", "Profile");
    case "admin-applications": return go("dashboard", "Applications");
    case "admin-businesses": ccTab = "businesses"; return go("dashboard", "Stats");
    case "admin-partners": return go("dashboard", "Partners");
    case "admin-compliance": return go("dashboard", "Compliance");
    case "admin-markets": ccTab = "markets"; return go("dashboard", "Stats");
    // Partner Sig walks (Build -106): the partner shell's own
    // tabs, and the Impact Portal's Report.
    case "partner-earnings": return go("dashboard", "Earnings");
    case "partner-links": return go("dashboard", "Links");
    case "partner-markets": return go("dashboard", "Markets");
    case "partner-team": return go("dashboard", "Team");
    case "pilot-report": return go("dashboard", "Report");
    default: return false;
  }
}

// The Sig home chips are built server-side from fixed label
// templates (sigdata buildHomeState), so a chip's walk is
// matched here from its label. Entity chips (a queue, a record
// set, a view of your own numbers) navigate; pure status chips
// (founding list, market live) and the bare visits-left count
// stay plain text.
function sigChipDest(label) {
  const t = " " + String(label || "").toLowerCase() + " ";
  if (t.includes("pack is final")) return "partner-earnings";
  if (t.includes("end-of-pilot pack")) return "pilot-report";
  if (t.includes("through your links")) return "partner-markets";
  if (t.includes("accrued and owed")) return "partner-earnings";
  if (t.includes("london race")) return "partner-markets";
  if (t.includes("hasn't accepted their invite")) return "partner-team";
  if (t.includes("square register")) return "biz-home";
  if (t.includes("left to set up")) return "biz-home";
  if (t.includes("first campaign")) return "biz-setup";
  if (t.includes("visits unused")) return "biz-setup";
  if (t.includes("applicants waiting")) return "biz-applicants";
  if (t.includes("draft")) return "biz-drafts";
  if (t.includes("offers live")) return "biz-offers";
  if (t.includes("posts live")) return "biz-content";
  if (t.includes("ending soon")) return "biz-content";
  if (t.includes("book again")) return "biz-regulars";
  if (t.includes("standing hours")) return "biz-profile";
  if (t.includes("receipt is ready")) return "biz-results";
  if (t.includes("roster")) return "biz-discover";
  if (t.includes("set up payouts")) return "cr-profile";
  if (t.includes("rate card")) return "cr-profile";
  if (t.includes("invite")) return "cr-offers-invited";
  if (t.includes("offers waiting")) return "cr-offers";
  if (t.includes("posts owed")) return "cr-visits";
  if (t.includes("applications waiting")) return "cr-offers-applied";
  if (t.includes("license")) return "cr-earnings";
  if (t.includes("momentum")) return "cr-momentum";
  if (t.includes("profile")) return "cr-profile";
  return null;
}

async function sigAsk(text) {
  const ctx = sigCtx();
  const isAdmin = !!state.user && state.user.role === "admin";
  const history = (state.sigThread || []).filter((turn) => !turn.pending && (turn.who === "user" || turn.who === "sig")).map((turn) => ({ who: turn.who, text: turn.text }));
  if (history.length && history[history.length - 1].who === "user" && history[history.length - 1].text === text) history.pop();
  try {
    const data = await Promise.race([
      api("POST", "/sig/ask", { q: text, history }),
      new Promise((_, reject) => setTimeout(() => reject(new Error("sig timeout")), 10000)),
    ]);
    if (data && (data.source === "ai" || data.source === "data") && data.text) {
      // Admin: the business/creator walk-to flow picker below
      // never applies to the console: no button into someone
      // else's surface. Build -81: a data answer may carry its
      // own link, and admin links point only at the console's
      // own record tabs (Applications, Partners, Compliance),
      // so the console Sig stays read-only: the walk opens the
      // queue, it never edits it. The admin fallback bank
      // answers instead of the creator bank when the AI cannot.
      if (isAdmin) return { text: data.text, flow: null, link: data.link || null };
      // Partner + funder Sig (Build -106) is scoped answers
      // only: no business/creator flow matching ever attaches
      // to a partner answer; the answer's own link is the walk.
      if (state.user && (state.user.role === "partner" || state.user.role === "pilot_partner")) return { text: data.text, flow: null, link: data.link || null, action: data.action || null };
      const match = sigMatch(text, ctx.biz);
      let flow = null;
      if (match.topic) {
        const label = typeof match.topic.flow === "function" ? match.topic.flow(ctx) : match.topic.flow;
        flow = sigFlowIndex(label);
      }
      return { text: data.text, flow, link: data.link || null };
    }
  } catch (e) { /* the bank answers instead */ }
  if (state.user && state.user.role === "partner") return { text: "I cannot reach your numbers right now. Everything is still on your tabs: Earnings for money and packs, Markets for the funnel, Links for your claim links.", flow: null, link: null };
  if (state.user && state.user.role === "pilot_partner") return { text: "I cannot reach your pilot's numbers right now. The Overview and Report tabs still hold everything, including the downloadable pack.", flow: null, link: null };
  return isAdmin ? sigAdminRouteAsk(text) : sigRouteAsk(text);
}
function sigThreadHtml() {
  const flows = sigFlowsFor();
  // Operator chips render ONLY on the newest turn that carries
  // them: an old step's buttons staying live would let a stray
  // tap rewind or corrupt the active flow. One live step at a
  // time, like every other chat surface.
  const turns = state.sigThread || [];
  let lastActionTurn = -1;
  turns.forEach((t, i) => { if (t.who !== "user" && (t.actions || []).length) lastActionTurn = i; });
  return turns.map((turn, ti) => turn.who === "user"
    ? `<div class="sig-turn user"><div class="sig-bub">${esc(turn.text)}</div></div>`
    : `<div class="sig-turn sig"><span class="sig-turn-ava">${turn.pending ? sigAvatarHtml("think") : turn.talk ? sigAvatarHtml("talk") : SIG_AVATAR_HTML}</span><div class="sig-bub">${esc(turn.text)}${turn.pending ? `<span class="sig-typing" aria-hidden="true"><i></i><i></i><i></i></span>` : ""}${turn.cardKind ? sigCardsHtmlFor(turn, ti) : ""}${turn.flow != null && flows[turn.flow] ? `<button type="button" class="btn small-btn sig-turn-act" data-sigflow="${turn.flow}">${esc(flows[turn.flow].label)}</button>` : ""}${(turn.suggest || []).map((q) => `<button type="button" class="btn small-btn sig-turn-act" data-sigask="${esc(q)}">${esc(q)}</button>`).join("")}${ti === lastActionTurn ? (turn.actions || []).map((a, ai) => `<button type="button" class="btn small-btn sig-turn-act${a.primary ? "" : " ghost"}" data-opact="${ti}:${ai}">${esc(a.label)}</button>`).join("") : ""}</div></div>`).join("");
}
async function sigAskSubmit(ev) {
  if (ev) ev.preventDefault();
  const input = document.getElementById("sig-ask-input");
  const text = input ? input.value.trim() : "";
  if (!text) return false;
  // Sig Operator routing (Jeff, 2026-10-28): an active flow
  // consumes the message first; then action intents; only then
  // does the question path (AI, then the canon bank) run. The
  // operator never writes anything before a plain summary and
  // an explicit yes.
  if (typeof sigOpTry === "function" && (await sigOpTry(text))) {
    if (input) input.value = "";
    return false;
  }
  state.sigThread = state.sigThread || [];
  state.sigThread.push({ who: "user", text });
  const pending = { who: "sig", text: "One sec.", flow: null, pending: true };
  state.sigThread.push(pending);
  if (input) input.value = "";
  const paint = () => {
    const host = document.getElementById("sig-thread");
    if (host) { host.innerHTML = sigThreadHtml(); wireSigThread(host); host.scrollTop = host.scrollHeight; }
    const anyPending = state.sigThread.some((t) => t.pending);
    const anyTalk = state.sigThread.some((t) => t.talk);
    const presText = document.querySelector("[data-sig-presence-text]");
    const presSub = document.querySelector("[data-sig-presence-sub]");
    const heroAva = document.querySelector("[data-sig-hero-media]");
    const dot = document.querySelector("[data-sig-presence-dot]");
    if (presText) presText.textContent = anyPending ? "Thinking" : anyTalk ? "Talking" : "Ready";
    if (presSub) presSub.textContent = anyPending ? "Lining up a straight answer." : anyTalk ? "Answering now." : "Listening. Your queue is in order.";
    if (dot) dot.classList.toggle("thinking", anyPending);
    if (heroAva) sigHeroSet(anyPending ? "think" : anyTalk ? "talk" : "idle");
  };
  paint();
  const reply = await sigAsk(text);
  pending.text = reply.text;
  pending.flow = reply.flow != null ? reply.flow : null;
  // Build -81: a data answer that shows records carries its
  // walk as this turn's action (rendered like an operator
  // action while the turn is the newest action-bearing one).
  if (reply.link && reply.link.dest && reply.link.label) {
    const dest = reply.link.dest;
    pending.actions = [{ label: reply.link.label, primary: true, run: async () => sigLinkGo(dest) }];
  }
  // Team seats (Build -107): a confirm-first action rides a
  // scoped partner/funder answer. Nothing has happened yet;
  // the button is the confirmation, and the team endpoint
  // re-checks every fence when it is tapped.
  if (reply.action && reply.action.type) {
    const act = reply.action;
    pending.actions = [{
      label: act.label || "Confirm",
      primary: true,
      run: async () => {
        try {
          if (act.type === "team_invite") {
            const r = await api("POST", "/partner/team/invite", act.payload || {});
            sigOpSay(r && r.emailSent === false ? "Done, the seat is created, but the invite email did not go out. Resend it from the Team view." : `Done. The invite is on its way to ${(act.payload || {}).email || "them"}; the seat shows on your Team view right away.`);
          } else if (act.type === "team_revoke") {
            await api("POST", "/partner/team/revoke", act.payload || {});
            sigOpSay("Done. That seat is revoked: their access ends on their next request, and everything they brought in stays credited.");
          }
        } catch (e) {
          sigOpSay(`That did not go through: ${e.message}`);
        }
        sigOpPaint();
      },
    }];
  }
  pending.suggest = reply.suggest || [];
  delete pending.pending;
  pending.talk = true;
  paint();
  setTimeout(() => { pending.talk = false; paint(); }, 2000);
  const inp2 = document.getElementById("sig-ask-input");
  if (inp2) inp2.focus();
  return false;
}
function wireSigThread(root) {
  if (!root) return;
  root.querySelectorAll("[data-sigflow]").forEach((btn) => {
    btn.onclick = () => { const f = sigFlowsFor()[Number(btn.getAttribute("data-sigflow"))]; if (f && f.act) f.act(); };
  });
  root.querySelectorAll("[data-sigask]").forEach((btn) => {
    btn.onclick = () => { const input = document.getElementById("sig-ask-input"); if (input) input.value = btn.getAttribute("data-sigask"); sigAskSubmit(); };
  });
  // Sig result cards (Build -78): a results turn carries card
  // descriptors plus per-card action closures (Invite / Save,
  // Apply / Pass). Unlike flow chips, card buttons stay live on
  // their own turn: they act on real records, not on a flow
  // step, so an older result card can still be used after the
  // conversation moves on. The handlers repaint the thread.
  root.querySelectorAll("[data-sigcard]").forEach((btn) => {
    btn.onclick = async () => {
      const parts = btn.getAttribute("data-sigcard").split(":");
      const turn = (state.sigThread || [])[Number(parts[0])];
      const acts = turn && turn.cardActs && turn.cardActs[Number(parts[1])];
      const fn = acts && acts[parts[2]];
      if (typeof fn !== "function") return;
      btn.disabled = true;
      try { await fn(); } catch (e) { /* card handlers surface their own errors as turns */ }
      if (typeof sigOpPaint === "function") sigOpPaint();
    };
  });
  // Build -81: a creator card's body (photo, name, stats) is
  // the walk to that creator's full profile, the same
  // destination a Discover tap opens. Invite and Save are
  // buttons inside the card and keep their own tap: a click
  // that lands on one never navigates. Demo cards ride the
  // same path: openCreatorProfile is the Discover door, with
  // its fencing, exactly as tapped there.
  root.querySelectorAll("[data-sigprofile]").forEach((el) => {
    el.onclick = (ev) => {
      if (ev.target.closest("[data-sigcard]")) return;
      const uid = el.getAttribute("data-sigprofile");
      if (uid) openCreatorProfile(uid);
    };
  });
  // Build -81: an offer card's body opens the offer's home:
  // the creator Offers tab, on the Invited segment for a
  // direct invite. Apply/Accept and Pass keep their own tap.
  root.querySelectorAll("[data-sigoffer]").forEach((el) => {
    el.onclick = (ev) => {
      if (ev.target.closest("[data-sigcard]")) return;
      if (el.getAttribute("data-sigoffer") === "accept") state.crOffersSeg = "invited";
      go("dashboard", "Offers");
    };
  });
  // Sig Operator action chips: a turn's actions are closures
  // held in memory with the thread (session-only, like the
  // thread itself). A tap runs the step; the flow repaints.
  root.querySelectorAll("[data-opact]").forEach((btn) => {
    btn.onclick = async () => {
      const parts = btn.getAttribute("data-opact").split(":");
      const turn = (state.sigThread || [])[Number(parts[0])];
      const act = turn && turn.actions && turn.actions[Number(parts[1])];
      if (!act || typeof act.run !== "function") return;
      btn.disabled = true;
      try { await act.run(); } catch (e) { /* flows surface their own errors as turns */ }
      if (typeof sigOpPaint === "function") sigOpPaint();
    };
  });
}

// The Sig tab (V4.1): Sig's whole surface as a destination —
// the same queue Home shows (same items, same actions), the
// conversation with its chat input, the guided flows and the
// straight answers. One Sig, one queue, one thread; Home's
// field and this tab are two doors into it.
function renderSigTab() {
  const el = document.getElementById("tab-body");
  if (!el) return;
  const items = state.sigQueue || [];
  const links = state.sigQueueLinks || [];
  const flows = sigFlowsFor();
  const qa = (item) => `<details class="help-qa"><summary>${esc(item.q)}</summary><p class="small">${esc(item.a)}</p></details>`;
  const anyPending = (state.sigThread || []).some((t) => t.pending);
  const anyTalk = (state.sigThread || []).some((t) => t.talk);
  const presence = anyPending ? "Thinking" : anyTalk ? "Talking" : "Ready";
  const presenceSub = anyPending ? "Lining up a straight answer." : anyTalk ? "Answering now." : "Listening. Your queue is in order.";
  const queueHtml = sigQueueHtml(items, { links, speaker: true });
  el.innerHTML = `
  <section class="sig-hero" aria-label="Sig">
    <div class="sig-hero-ava">${sigHeroMediaHtml()}</div>
    <div class="sig-hero-copy">
      <div class="sig-hero-kicker">Your guide</div>
      <h2>Sig</h2>
      <div class="sig-presence"><span class="sig-live-dot${anyPending ? " thinking" : ""}" data-sig-presence-dot></span><strong data-sig-presence-text>${presence}</strong><span data-sig-presence-sub>${presenceSub}</span></div>
      <p>Ask in plain words, or tell me to do it: campaigns, people, numbers, right here. I keep the queue in order, and I confirm before anything is saved.</p>
    </div>
  </section>
  ${state.user && state.user.role !== "admin" ? `<div class="sig-home" id="sig-home">
    <div class="sig-home-greet" id="sig-home-greet"></div>
    <div class="sig-home-chips" id="sig-home-chips"><span class="sig-chip is-quiet">${ST("Loading your numbers…", "Cargando tus números…")}</span></div>
  </div>` : ""}
  <div id="sig-queue-host">${queueHtml}</div>
  ${state.user && state.user.role === "business" ? sigBizStartersHtml(state.user) : ""}
  ${state.user && state.user.role === "creator" ? sigCreatorStartersHtml() : ""}
  <div class="sig-chat">
    <div class="sig-chat-head"><div><div class="sig-chat-title">Conversation</div><div class="muted small">Straight answers and real actions, with the next step attached. Nothing posts, sends, or saves until you confirm a plain summary.</div></div>${anyPending ? `<span class="sig-typing" aria-hidden="true"><i></i><i></i><i></i></span>` : ""}</div>
    <div id="sig-thread" class="sig-thread">${sigThreadHtml() || `<div class="sig-turn sig"><span class="sig-turn-ava">${SIG_AVATAR_HTML}</span><div class="sig-bub">${state.user && state.user.role === "business" ? "Ask me anything about how SIGNL works for your business: what your plan includes, how campaigns run, how your results get counted. Or tell me to do something: draft a campaign, find creators, set your staff PIN. I confirm before anything is saved." : "Ask me anything about how SIGNL works: how you make money, what things cost, how visits and points run. Or tell me to do something: set up a campaign, find creators, show your numbers. I confirm before anything is saved."}</div></div>`}</div>
    <form class="sig-ask-form" onsubmit="return sigAskSubmit(event)">
      <input id="sig-ask-input" type="text" placeholder="Ask Sig anything" autocomplete="off" aria-label="Ask Sig anything">
      <button class="btn" type="submit">Ask</button>
    </form>
  </div>
  <h3 style="margin:22px 0 6px">${esc(ST("What Sig can do", "Lo que Sig puede hacer"))}</h3>
  <div class="sig-panel">
    ${sigOpCapabilities().map((c) => `<div class="sheet-row" style="cursor:default"><span>${esc(c)}</span></div>`).join("")}
    <div style="padding:10px 2px 2px;display:flex;gap:8px;flex-wrap:wrap">${sigOpHomeActions().map((a, i) => `<button type="button" class="btn small-btn" data-opstart="${i}">${esc(a.label)}</button>`).join("")}</div>
  </div>
  <h3 style="margin:22px 0 6px">Things Sig can walk you to</h3>
  <div class="sig-panel">
    ${flows.map((f, i) => `<button type="button" class="sheet-row ask-flow" data-flow="${i}"><span>${esc(f.label)}</span><span class="ask-chev">›</span></button>`).join("")}
  </div>
  <h3 style="margin:22px 0 2px">Straight answers</h3>
  ${sigQaFor().map(qa).join("")}`;
  wireSigQueue(el, items, links);
  wireSigThread(el);
  if (state.user && state.user.role !== "admin") loadSigHome();
  if (!anyPending && !anyTalk && sigQueueBeat) { const beat = sigQueueBeat; sigQueueBeat = ""; sigHeroSet(beat); }
  else sigHeroSet(anyPending ? "think" : anyTalk ? "talk" : "idle");
  el.querySelectorAll("[data-flow]").forEach((btn) => {
    btn.onclick = () => { const f = flows[Number(btn.getAttribute("data-flow"))]; if (f && f.act) f.act(); };
  });
  el.querySelectorAll("[data-opstart]").forEach((btn) => {
    btn.onclick = async () => { const a = sigOpHomeActions()[Number(btn.getAttribute("data-opstart"))]; if (a && a.run) { btn.disabled = true; try { await a.run(); } catch (e) { /* flows surface errors as turns */ } } };
  });
  if (state.sigFocusAsk) {
    state.sigFocusAsk = false;
    setTimeout(() => { const i = document.getElementById("sig-ask-input"); if (i) i.focus(); }, 60);
  }
}

// Business starters (Build -68, Jeff: Sig front and center,
// focused on what a business would want and need): the five
// business jobs as tappable chips at the top of the Sig tab.
// Questions route through the same ask path a typed question
// takes; the campaign chip starts the same B1 flow the home
// action starts.
function sigBizStartersHtml(u) {
  const place = foundingBizPlace(u);
  return `<div class="sig-starters" style="display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 0">
    <button type="button" class="rchip" onclick="return sigBizStarterCampaign()">Draft my first campaign</button>
    <button type="button" class="rchip" onclick="return sigBizStarterFind()">Find creators near me</button>
    <button type="button" class="rchip" onclick="return sigBizStarterAsk('What does my plan include?')">What does my plan include?</button>
    <button type="button" class="rchip" onclick="return sigBizStarterAsk('How will my results be counted?')">How will my results be counted?</button>
    <button type="button" class="rchip" onclick="return sigBizStarterAsk('What happens when ${esc(place)} opens?')">What happens when ${esc(place)} opens?</button>
  </div>`;
}
function sigBizStarterCampaign() {
  sigB1Start();
  sigOpPaint();
  return false;
}
// Sig home state (Build -78): the tab opens the way the
// benchmark does — a greeting, the asker's real live state as
// chips, and "where should we pick up?" The numbers come from
// GET /sig/home, which the server builds from the same sigdata
// fact sheet the answers come from; the client never counts
// anything itself here.
async function loadSigHome() {
  const host = document.getElementById("sig-home");
  if (!host) return;
  let d = null;
  try { d = await api("GET", "/sig/home"); } catch (e) { d = null; }
  const greetEl = document.getElementById("sig-home-greet");
  const chipsEl = document.getElementById("sig-home-chips");
  if (!greetEl || !chipsEl) return;
  if (!d) { chipsEl.innerHTML = ""; return; }
  state.sigHome = d;
  const hour = new Date().getHours();
  const day = hour < 12 ? ST("Good morning", "Buenos días") : hour < 18 ? ST("Good afternoon", "Buenas tardes") : ST("Good evening", "Buenas noches");
  const name = d.displayName || "";
  greetEl.innerHTML = `<div class="sig-home-h">${esc(day)}${name ? `, ${esc(name)}` : ""}.</div><div class="sig-home-sub">${ST("Where should we pick up?", "¿Por dónde seguimos?")}</div>`;
  chipsEl.innerHTML = (d.chips && d.chips.length)
    ? d.chips.map((c) => { const dest = sigChipDest(c); return dest ? `<button type="button" class="sig-chip sig-chip-link" data-sigchip="${dest}">${esc(c)}</button>` : `<span class="sig-chip">${esc(c)}</span>`; }).join("")
    : `<span class="sig-chip is-quiet">${ST("All quiet right now", "Todo tranquilo por ahora")}</span>`;
  chipsEl.querySelectorAll("[data-sigchip]").forEach((el) => el.addEventListener("click", () => sigLinkGo(el.getAttribute("data-sigchip"))));
}
// "Find creators near me" runs the search right here in Sig
// (Build -78): same ranked cards a typed request gets, no
// detour through Discover.
function sigBizStarterFind() {
  (async () => { sigB2FlowStart(); await sigB2Run({}); sigOpPaint(); })();
  return false;
}
// Creator pick-up starters (Build -78): the creator mirror of
// the business chips — the four jobs a creator opens Sig for,
// each running its real flow in the thread.
function sigCreatorStartersHtml() {
  return `<div class="sig-starters" style="display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 0">
    <button type="button" class="rchip" onclick="return sigCreatorStarter('offers')">${ST("Find offers for me", "Buscar ofertas para mí")}</button>
    <button type="button" class="rchip" onclick="return sigCreatorStarter('finish')">${ST("Finish my profile", "Terminar mi perfil")}</button>
    <button type="button" class="rchip" onclick="return sigCreatorStarter('earn')">${ST("How do I earn more?", "¿Cómo gano más?")}</button>
    <button type="button" class="rchip" onclick="return sigCreatorStarter('numbers')">${ST("How am I doing?", "¿Cómo voy?")}</button>
  </div>`;
}
function sigCreatorStarter(kind) {
  (async () => {
    if (kind === "offers") await sigC1Start();
    else if (kind === "finish") await sigC2Start();
    else if (kind === "earn") await sigC5Run();
    else await sigC3Run();
    sigOpPaint();
  })();
  return false;
}
function sigBizStarterAsk(text) {
  const input = document.getElementById("sig-ask-input");
  if (input) input.value = text;
  return sigAskSubmit({ preventDefault: () => {} });
}

function openAgentSheet() {
  // Ask Sig (V3, spec §4.1): guided flows that walk you to the
  // exact screen, plus straight answers from SIGNL's locked
  // facts. This sheet stays a walk-to surface; the operator
  // (Sig doing the doing, confirm-first) lives on the Sig tab.
  // The content is shared with the Sig tab (sigFlowsFor/sigQaFor).
  closeAgentSheet();
  const u = state.user;
  if (!u) return false;
  const flows = sigFlowsFor();
  const qa = (item) => `<details class="help-qa"><summary>${esc(item.q)}</summary><p class="small">${esc(item.a)}</p></details>`;
  const el = document.createElement("div");
  el.id = "agent-sheet";
  el.className = "sheet-overlay";
  el.innerHTML = `
  <div class="sheet" role="dialog" aria-label="Ask Sig">
    <div class="flex-between"><span class="sig-top" style="gap:10px">${SIG_AVATAR_HTML}<strong>Ask Sig</strong></span><button class="linklike" onclick="closeAgentSheet()">Close</button></div>
    <p class="small muted" style="margin:8px 0 4px">Tell Sig what you want to do. Sig walks you to the exact screen.</p>
    ${flows.map((f, i) => `<button type="button" class="sheet-row ask-flow" data-flow="${i}"><span>${esc(f.label)}</span><span class="ask-chev">›</span></button>`).join("")}
    <h4 style="margin:16px 0 4px">Straight answers</h4>
    ${sigQaFor().map(qa).join("")}
  </div>`;
  el.addEventListener("click", (e) => { if (e.target === el) closeAgentSheet(); });
  document.body.appendChild(el);
  el.querySelectorAll("[data-flow]").forEach((btn) => {
    btn.onclick = () => { const f = flows[Number(btn.getAttribute("data-flow"))]; closeAgentSheet(); if (f && f.act) f.act(); };
  });
  return false;
}
function closeAgentSheet() {
  const el = document.getElementById("agent-sheet");
  if (el) el.remove();
  return false;
}

// Generic home segments (same grammar as the business dashSegs):
// buttons switch [data-seg] panels inside the [data-dash] root.
function homeSegsHtml(segs) {
  return `<div class="view-toggle dash-segs"><div class="vt-group">${segs.map(([id, label, badge], i) => `<button type="button" class="rchip${i === 0 ? " on" : ""}" data-segbtn="${id}" onclick="dashSeg('${id}', this)">${label}${badge ? ` <span class="seg-badge">${badge}</span>` : ""}</button>`).join("")}</div></div>`;
}
// Segmented panel switch for the analytics toggles (funnel
// window, content library) — same show/hide grammar as dashSeg.
function segPanels(btn, panelAttr, val, btnAttr) {
  const root = btn && btn.closest ? btn.closest("[data-dash]") : null;
  if (!root) return false;
  root.querySelectorAll(`[${panelAttr}]`).forEach((p) => { p.hidden = p.getAttribute(panelAttr) !== String(val); });
  root.querySelectorAll(`[${btnAttr}]`).forEach((b) => b.classList.toggle("on", b.getAttribute(btnAttr) === String(val)));
  return false;
}
function bizFnWin(days, btn) { return segPanels(btn, "data-fnp", days, "data-fnbtn"); }
function bizLibTab(which, btn) { return segPanels(btn, "data-libp", which, "data-libbtn"); }
// Feed filter chips: hide cards whose data-fk does not match.
function feedChip(btn, kind) {
  const root = btn && btn.closest ? btn.closest("[data-dash]") : null;
  if (!root) return false;
  root.querySelectorAll("[data-fcbtn]").forEach((b) => b.classList.toggle("on", b === btn));
  root.querySelectorAll("[data-fk]").forEach((c) => { c.hidden = kind !== "all" && c.getAttribute("data-fk") !== kind; });
  return false;
}
// Offer template cards (Offers segment): land in the composer
// with the lane preset. A draft the business already started is
// never overwritten — the same rule as the two-tap prefill.
function startOfferTemplate(kind) {
  state.offerTarget = null;
  state.composerLane = "open";
  if (offerDraftIsEmpty()) {
    state.offerDraft.kind = kind === "paid" ? "paid" : kind === "coupon" ? "coupon" : "comp";
    // Build -84: a fresh template starts on its kind's
    // recommended deliverables.
    const std = deliverableStandardClient(state.offerDraft.kind);
    state.offerDraft.dposts = String(std.posts);
    state.offerDraft.dstory = std.story;
    state.offerDraft.dwindow = String(std.windowHours);
    state.offerDraft.deliverablesTouched = false;
  }
  state.tab = "Campaign Setup";
  render();
  return false;
}

// License state pill for a delivered post (content library):
// derived server-side from the visit's own terms.
function licPillHtml(lic) {
  if (!lic || lic.type === "native") return `<span class="lic-pill">Native share only</span>`;
  const label = lic.type === "licensed" ? "Licensed" : "Standard license";
  if (lic.daysLeft === null || lic.daysLeft === undefined) return `<span class="lic-pill live">${label}</span>`;
  if (lic.daysLeft < 0) return `<span class="lic-pill over">${label} ended</span>`;
  return `<span class="lic-pill live">${label} · ${lic.daysLeft}d left</span>`;
}
// License window in plain words (Build -76, Jeff's license
// clarity ruling): every license record stores its end date
// (windowEndsAt) and the server ships it, but rows used to show
// only the pill's day count. A window is exactly 90 days, so the
// start is the end minus 90: the post date on a paid booking,
// the creator's approval day on a licensed post.
function licWindowLine(lic) {
  if (!lic || lic.type === "native" || !lic.windowEndsAt) return "";
  const end = Date.parse(lic.windowEndsAt);
  if (!Number.isFinite(end)) return "";
  const start = new Date(end - 90 * 86400000).toISOString();
  if (lic.daysLeft !== null && lic.daysLeft !== undefined && lic.daysLeft < 0) return `<div class="lib-meta">Repost + ad use ended ${fmtDay(lic.windowEndsAt)}</div>`;
  return `<div class="lib-meta">Repost + ad use: ${fmtDay(start)} to ${fmtDay(lic.windowEndsAt)}</div>`;
}
// Business funnel with the 7/30-day segmented toggle. Falls back
// to the cumulative pipeline when windowed counts are absent.
function bizFunnelHtml(h) {
  const stage = (n, l, s) => `<div class="pv-stage"><div class="pv-stage-num">${n}</div><div class="pv-stage-lbl">${l}</div><div class="pv-stage-sub">${s}</div></div>`;
  const fun = (f) => `<div class="pv-funnel">${stage(f.invited, "Invited", "Bookings created")}${stage(f.claimed, "Claimed", "Codes issued")}${stage(f.visited, "Visited", "Redeemed in store")}${stage(f.posted, "Posted", "Posts reported live")}</div>`;
  if (h.funnel7 && h.funnel30) {
    return `<div class="view-toggle lib-toggle"><div class="vt-group"><button type="button" class="rchip" data-fnbtn="7" onclick="return bizFnWin(7, this)">7 days</button><button type="button" class="rchip on" data-fnbtn="30" onclick="return bizFnWin(30, this)">30 days</button></div></div><div data-fnp="7" hidden>${fun(h.funnel7)}</div><div data-fnp="30">${fun(h.funnel30)}</div>`;
  }
  const p = h.pipeline || { invited: 0, claimed: 0, clockRunning: 0, live: 0 };
  return `<div class="pv-funnel">${stage(p.invited, "Invited", "Bookings created")}${stage(p.claimed, "Claimed", "Codes issued")}${stage(p.clockRunning, "Visited", "Visits redeemed")}${stage(p.live, "Posted", "Posts delivered")}</div><p class="ana-note">All-time pipeline. Windowed counts arrive with your first full week of visits.</p>`;
}
// Content library: every delivered post with its license state,
// split into the creator's posts and the ones the business can
// actually use. Rights follow the visit, never the plan.
function bizLibraryHtml(h) {
  const lib = h.contentLibrary || [];
  if (!lib.length) return `<div class="feed-empty"><strong>No posts yet</strong>Delivered posts land here with their license state.</div>`;
  const row = (r) => `<div class="lib-row"><div class="lib-main"><div class="lib-title">${esc(r.title)}</div><div class="lib-meta">@${esc(r.creatorHandle)} · ${r.postedAt ? fmtDay(r.postedAt) : ""} · ${fmtNum(r.views)} views · ${r.onTime ? "on time" : "late"}${r.kind === "coupon" ? " · Coupon post" : r.kind === "paid" ? " · Paid post" : ""}${r.redemptions ? ` · ${r.redemptions.count} code uses · $${fmtMoney(r.redemptions.basketTotal)} rung up` : ""}</div>${licWindowLine(r.license)}</div>${licPillHtml(r.license)}${r.postUrl ? `<a class="btn small-btn ghost" href="${esc(r.postUrl)}" target="_blank" rel="noopener">View post</a>` : ""}</div>`;
  const yours = lib.filter((r) => r.license && r.license.type !== "native");
  return `<div class="view-toggle lib-toggle"><div class="vt-group"><button type="button" class="rchip on" data-libbtn="creator" onclick="return bizLibTab('creator', this)">Creator posts</button><button type="button" class="rchip" data-libbtn="yours" onclick="return bizLibTab('yours', this)">Yours to use</button></div></div>
  <div data-libp="creator"><p class="small muted">Seeing a post here is not the right to reuse it. Comped and coupon posts are native share only, with credit, unless you license them from the creator.</p>${lib.map(row).join("")}</div>
  <div data-libp="yours" hidden><p class="small muted">Posts you can repost and run as ads inside the window shown. Every license runs 90 days: from the post date on a paid booking, from the day the creator said yes on a licensed post. The end date is on each post, and a license never runs longer than 90 days.</p>${yours.length ? yours.map(row).join("") : `<div class="feed-empty"><strong>Nothing licensed yet</strong>Paid bookings carry a 90-day standard license. A comped or coupon post can be licensed at the creator's listed fee.</div>`}</div>`;
}
// Offers-segment template cards, in SIGNL's own terms.
function bizTemplatesHtml() {
  const card = (kind, icon, name, desc) => `<div class="tmpl-card"><div class="tmpl-tile">${bnIcon(icon)}</div><div class="tmpl-name">${name}</div><div class="tmpl-desc">${desc}</div><button type="button" class="btn small-btn" onclick="return startOfferTemplate('${kind}')">Start</button></div>`;
  return `<div class="tmpl-grid">${card("comp", "offers", "Comped visit", "You cover the meal or service. The creator posts honestly within 48 hours.")}${card("paid", "visits", "Paid booking", "Book at the creator's listed rate. They keep 97%, and a 90-day license is included.")}${card("coupon", "offers", "Coupon post", "Pay with a coupon: money off, a percent off, or store credit. One post, no story, unless you change it.")}${card("open", "join", "Open call", "Post it to your market and let matching creators apply. You pick from the stack.")}</div>`;
}
// Activity feed cards from delivered posts + their licenses.
function bizActivityFeedHtml(h) {
  const lib = h.contentLibrary || [];
  if (!lib.length) return `<div class="feed-empty"><strong>Nothing here yet</strong>Posts and licenses land here as visits complete.</div>`;
  const cards = [];
  for (const r of lib) {
    cards.push(`<div class="feed-card" data-fk="posts"><div class="feed-dot">${bnIcon("visits")}</div><div class="feed-main"><div class="feed-title">Post live: ${esc(r.title)}</div><div class="feed-meta">@${esc(r.creatorHandle)} · ${r.postedAt ? fmtDay(r.postedAt) : ""} · ${fmtNum(r.views)} views · ${r.onTime ? "on time" : "late"}</div></div>${r.postUrl ? `<span class="feed-act"><a class="btn small-btn ghost" href="${esc(r.postUrl)}" target="_blank" rel="noopener">View post</a></span>` : ""}</div>`);
    if (r.license && r.license.type !== "native") {
      cards.push(`<div class="feed-card" data-fk="licenses"><div class="feed-dot acc">${bnIcon("offers")}</div><div class="feed-main"><div class="feed-title">${r.license.type === "licensed" ? "Licensed post" : "Standard license"}: ${esc(r.title)}</div><div class="feed-meta">${r.license.daysLeft === null || r.license.daysLeft === undefined ? "90-day license window" : r.license.daysLeft < 0 ? `The reuse window ended ${r.license.windowEndsAt ? fmtDay(r.license.windowEndsAt) : ""}` : `${r.license.daysLeft} days left to repost and run ads${r.license.windowEndsAt ? ` · ends ${fmtDay(r.license.windowEndsAt)}` : ""}`}</div></div><span class="feed-act"><button type="button" class="btn small-btn ghost" onclick="return go('dashboard','Visits &amp; Posts')">Open</button></span></div>`);
    }
  }
  return `<div class="feed-chips"><button type="button" class="chip on" data-fcbtn onclick="return feedChip(this,'all')">All</button><button type="button" class="chip" data-fcbtn onclick="return feedChip(this,'posts')">Posts</button><button type="button" class="chip" data-fcbtn onclick="return feedChip(this,'licenses')">Licenses</button></div>${cards.join("")}`;
}

function go(view, tab) {
  // Any navigation leaves Business Preview: the mode is a single
  // deliberate walk, and the admin lands back on the normal console.
  if (state.preview) { stopPreviewCountdown(); state.preview = null; }
  stopHomeCountdown();
  // Flush the deferred notification read (see loadNotificationsInto):
  // leaving the dashboard marks its Updates read and clears the badges.
  if (state.notesReadPending) {
    state.notesReadPending = false;
    api("POST", "/notifications/read", {}).then(() => refreshBadges()).catch(() => {});
  }
  state.view = view;
  // A direct invite (startOffer) latches the Offers composer for
  // the render that follows it. Deliberate navigation anywhere
  // else releases the latch: without this, one Invite tap in
  // Discover pinned EVERY later tab to My Offers until a refresh
  // reset the in-memory state (Jeff's stuck-nav report,
  // 2026-10-28, reproduced in the seed world). The draft itself
  // is kept (state.offerDraft survives re-renders); only the
  // direct targeting ends when the business walks away from it.
  if (tab && tab !== "My Offers" && tab !== "Campaign Setup") state.offerTarget = null;
  // Multi-scope exit (Build -106): the Impact Portal's
  // "Partner view" row leaves the pilot scope and lands back
  // on the license partner's Home.
  if (tab === "__partner_scope_exit") {
    state.pilotScopeId = null;
    pilotState.me = null;
    state.tab = "Home";
    render();
    return false;
  }
  if (tab) state.tab = tab;
  render();
  return false;
}

async function render() {
  // The Ready-for-you queue belongs to the home that computed it;
  // every navigation clears it and the new home re-registers.
  state.agentQueue = null;
  renderAgentFab();
  renderNav();
  // Build -68: while a public profile is on screen, the
  // profile-view CSS centers the content column in the page
  // (the admin rail otherwise left-anchors it, stranding the
  // profile against the left with a void on the right).
  document.body.classList.toggle("profile-view", state.view === "public-profile");
  if (state.view === "public-profile") return renderPublicProfile();
  if (state.view === "public-proof") return renderPublicProof();
  clearShareShell();
  if (state.view === "staff") return renderStaff();
  const u = state.user;
  if (!u) {
    if (state.view === "join-creator") return renderJoinCreator();
    if (state.view === "for-businesses" || state.view === "join-business") return renderForBusinesses();
    if (state.view === "signin") return renderSignin();
    if (state.view === "forgot") return renderForgot();
    if (state.view === "reset") return renderReset();
    return renderHome();
  }
  // Build -85: the claim flow's done state replaces the pending
  // wall for the claim session itself ("You're on the roster").
  // It is one screen, shown once: the exits below clear the step,
  // and a returning pending creator gets the normal pending home.
  if (state.claimStep === 4 && state.claimDone) return renderClaimDone();
  if (u.status === "pending") return u.role === "business" ? renderBusinessFoundingStatus() : renderPending();
  if (u.status === "rejected") return renderRejected();
  // Build -68: approved founding businesses route into the
  // real dashboard like everyone else; the founding wall that
  // used to sit here is gone. renderBusinessFoundingStatus
  // remains only for the pending-review business above.
  return renderDashboard();
}

