function unlistedLabel() {
  return (state.boot && state.boot.unlistedMarket) || "Not listed yet";
}

// Listed label for a market (Jeff, 2026-10-23): the record keeps
// the canonical name ("Virginia Beach"); labels read
// "Virginia Beach (Hampton Roads)" from the bootstrap label. The
// value submitted and stored never changes.
function marketDisplayName(name) {
  const m = state.boot && state.boot.markets ? state.boot.markets.find((x) => x.name === name) : null;
  return (m && m.label) || name;
}

// Market naming rule (Build -47, audit C15): identity and meta
// lines use the display label ("Virginia Beach (Hampton
// Roads)"); prose uses the talk name ("Hampton Roads"). One
// form per context, held everywhere. An identity line never
// repeats the market's own lead city after the label.
function marketPlaceLine(market, city) {
  const label = marketDisplayName(market);
  const leadCity = String(market || "").split(" (")[0];
  if (!city || city === leadCity) return label;
  return `${label} · ${city}`;
}

// Conversational name for the Virginia Beach market in creator
// and business prose (Jeff, 2026-10-23): talk says Hampton Roads.
function marketTalkNameClient(name) {
  return name === "Virginia Beach" ? "Hampton Roads" : name;
}

// "City, Country" for an unlisted creator. Records from before the
// country field fall back to their stored state, so nobody's place
// loses its second half.
function unlistedPlace(rec) {
  const region = rec.country || rec.state || "";
  return `${rec.city || ""}${region ? ", " + region : ""}`;
}

// Typed-city resolution (Jeff, 2026-10-23): when intake resolved
// the typed city into a market, the pending screen says so in one
// line, so a creator who typed Portsmouth learns they are filed
// under the Virginia Beach market instead of parked as
// "not listed". Conversation about that market says Hampton
// Roads (Jeff, 2026-10-23), so its towns read that way here.
function marketResolvedNote(u) {
  if (!u || u.marketResolvedFrom !== "typed_city" || !u.market || u.market === unlistedLabel()) return "";
  const city = u.marketResolvedCity || u.city || "";
  if (!city) return "";
  if (u.market === "Virginia Beach") return `<p><span class="badge info">${esc(city)} is part of Hampton Roads, so you're filed there.</span></p>`;
  return `<p><span class="badge info">${esc(city)} is part of our ${esc(u.market)} market, so you're filed there.</span></p>`;
}

// Display spelling of a typed city for the candidate prompt: the
// record keeps the typed value verbatim ("Portsmouth, United
// States"); the prompt reads better without the country suffix.
function typedCityDisplay(rec) {
  return String((rec && rec.city) || "").replace(/,\s*(united states|usa)$/i, "");
}

// One tap on an ambiguous intake's candidate metro: files the
// record under it through the pending market endpoint, which
// keeps the typed city as the home city.
async function pickCandidateMarket(e, market) {
  if (e) e.preventDefault();
  try {
    const data = await api("POST", "/me/market", { market });
    state.user = data.user;
    render();
  } catch (err) { alert(err.message); }
  return false;
}

// Market options are grouped by country (United States first, then the
// rest alphabetically), cities alphabetical inside each country, so the
// picker stays scannable as SIGNL goes universal (38 markets: universal
// 2026-10-18, roster reset 2026-10-23, Miami restored 2026-10-30).
function marketOptions(selected, forJoin) {
  const byCountry = {};
  for (const m of state.boot.markets) {
    const country = m.country || "United States";
    (byCountry[country] = byCountry[country] || []).push(m);
  }
  const countries = Object.keys(byCountry).sort((a, b) => (a === "United States" ? -1 : b === "United States" ? 1 : a.localeCompare(b)));
  const groups = countries.map((country) => {
    const opts = [...byCountry[country]]
      .sort((a, b) => a.name.localeCompare(b.name))
      .map((m) => `<option value="${esc(m.name)}" ${m.name === selected ? "selected" : ""}>${esc(m.label)}</option>`)
      .join("");
    return `<optgroup label="${esc(country)}">${opts}</optgroup>`;
  }).join("");
  return forJoin ? groups + `<option value="${esc(unlistedLabel())}">My city is not listed yet</option>` : groups;
}

// Options for the per-market audience share rows on the creator
// Profile (multi-market listing, 2026-11-01): every SIGNL market
// except the creator's home market (the home share is the local
// % field, never a row here), with a blank "pick a market" head.
// Build -90: grouped by country exactly like the claim form's
// market picker (marketOptions), so the profile rows and the
// claim facts screen offer the same search-then-pick control.
function audienceMarketOptions(selected, homeMarket) {
  const markets = ((state.boot && state.boot.markets) || []).filter((m) => m.name !== homeMarket);
  const byCountry = {};
  for (const m of markets) {
    const country = m.country || "United States";
    (byCountry[country] = byCountry[country] || []).push(m);
  }
  const countries = Object.keys(byCountry).sort((a, b) => (a === "United States" ? -1 : b === "United States" ? 1 : a.localeCompare(b)));
  const groups = countries.map((country) => {
    const opts = [...byCountry[country]]
      .sort((a, b) => a.name.localeCompare(b.name))
      // Short market names, not the "Name, State" label: this
      // select shares its row with the % input, and at phone
      // width the long label truncates into ambiguity.
      .map((m) => `<option value="${esc(m.name)}" ${m.name === selected ? "selected" : ""}>${esc(m.name)}</option>`)
      .join("");
    return `<optgroup label="${esc(country)}">${opts}</optgroup>`;
  }).join("");
  return `<option value="">Pick a market</option>` + groups;
}

// Multi-market audience rows (Build -64, audit F2): the profile
// form used to render five always-open dropdown rows before any
// explanation. Now the help leads, the form starts with the
// rows the creator actually has (one blank row when they have
// none), rows are added and removed one at a time up to five,
// and each row carries the claim form's search-then-pick
// pattern instead of a bare full-list select.
function amRowHtml(market, pct) {
  const u = state.user || {};
  return `<div class="p-am-row"><input class="p-am-search" placeholder="${T("Search markets, for example: Dubai", "Busca mercados, por ejemplo: Dubái")}" oninput="filterAmOptions(this)" style="margin-bottom:6px"><select class="p-am-market" style="width:100%">${audienceMarketOptions(market || "", u.market)}</select><div style="display:flex;align-items:center;gap:8px;margin-top:6px"><input class="p-am-pct" type="number" min="0" max="100" style="width:96px" placeholder="%" value="${esc(pct === undefined || pct === null ? "" : String(pct))}"><span class="small muted">${T("% of my audience", "% de mi audiencia")}</span><button type="button" class="btn small-btn ghost" onclick="return amRemoveRow(this)">${T("Remove", "Quitar")}</button></div></div>`;
}
function amRowCount() {
  return document.querySelectorAll("#p-am-rows .p-am-row").length;
}
function amSyncAddBtn() {
  const b = document.getElementById("p-am-add");
  if (b) b.style.display = amRowCount() >= 5 ? "none" : "";
}
function amAddRow() {
  const host = document.getElementById("p-am-rows");
  if (!host || amRowCount() >= 5) return false;
  const tmp = document.createElement("div");
  tmp.innerHTML = amRowHtml("", "");
  host.appendChild(tmp.firstElementChild);
  amSyncAddBtn();
  return false;
}
function amRemoveRow(btn) {
  const host = document.getElementById("p-am-rows");
  const row = btn && btn.closest ? btn.closest(".p-am-row") : null;
  if (row) row.remove();
  if (host && !host.querySelector(".p-am-row")) {
    const tmp = document.createElement("div");
    tmp.innerHTML = amRowHtml("", "");
    host.appendChild(tmp.firstElementChild);
  }
  amSyncAddBtn();
  return false;
}
function filterAmOptions(input) {
  const row = input && input.closest ? input.closest(".p-am-row") : null;
  const sel = row ? row.querySelector(".p-am-market") : null;
  if (!sel) return;
  const q = input.value.trim().toLowerCase();
  for (const opt of sel.querySelectorAll("option")) {
    if (!opt.value) continue;
    opt.hidden = !!q && !opt.textContent.toLowerCase().includes(q) && !opt.value.toLowerCase().includes(q);
  }
  // Claim-picker pattern: a country group with no visible match
  // hides too, so search never leaves an empty heading behind.
  for (const grp of sel.querySelectorAll("optgroup")) {
    grp.hidden = ![...grp.querySelectorAll("option")].some((o) => !o.hidden);
  }
}

// The search box above the market picker filters the grouped options
// live; if the current selection gets filtered out, the first match
// takes over so the city list below never disagrees with the market.
function filterMarketOptions() {
  const input = document.getElementById("jc-market-search");
  const sel = document.getElementById("jc-market");
  if (!input || !sel) return;
  const q = input.value.trim().toLowerCase();
  let firstMatch = null;
  for (const opt of sel.querySelectorAll("option")) {
    if (opt.value === unlistedLabel()) continue;
    const hit = !q || opt.textContent.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q);
    opt.hidden = !hit;
    if (hit && !firstMatch) firstMatch = opt;
  }
  for (const grp of sel.querySelectorAll("optgroup")) {
    grp.hidden = ![...grp.querySelectorAll("option")].some((o) => !o.hidden);
  }
  const current = sel.selectedOptions && sel.selectedOptions[0];
  if (q && firstMatch && current && current.hidden) {
    sel.value = firstMatch.value;
    syncMarketChoice();
  }
}

// When a joiner picks "My city is not listed yet", the market city
// dropdown swaps for their own typed city + country: nobody is turned
// away, and their sign-up counts toward opening their city.
function syncMarketChoice() {
  const m = document.getElementById("jc-market");
  if (!m) return;
  const unlisted = m.value === unlistedLabel();
  const cityWrap = document.getElementById("jc-city-wrap");
  const customWrap = document.getElementById("jc-custom-wrap");
  if (cityWrap) cityWrap.style.display = unlisted ? "none" : "";
  if (customWrap) { customWrap.style.display = unlisted ? "" : "none"; customWrap.style.gridColumn = unlisted ? "1 / -1" : ""; }
  if (!unlisted) document.getElementById("jc-city").innerHTML = m.value === "London" ? `<option value="London" selected>London</option>` : cityOptions(m.value);
  // Build -88: for London the free-text neighborhood field is
  // replaced by the area picker (home city stays London).
  const jcAreaWrap = document.getElementById("jc-area-wrap");
  if (jcAreaWrap) {
    jcAreaWrap.style.display = m.value === "London" ? "" : "none";
    if (m.value === "London") {
      const areaSel = document.getElementById("jc-area");
      if (areaSel) areaSel.innerHTML = areaOptions("London", areaSel.value || undefined);
    }
  }
  const jcNbWrap = document.getElementById("jc-neighborhood-wrap");
  if (jcNbWrap) jcNbWrap.style.display = m.value === "London" ? "none" : "";
  // Dubai Advertiser Permit note (Build -70): shown only when
  // Dubai is the picked market. It never blocks the signup.
  const dubaiNote = document.getElementById("jc-dubai-note");
  if (dubaiNote) dubaiNote.style.display = m.value === "Dubai" ? "" : "none";
  // London note (Build -86): same shape as the Dubai note
  // above, for UK ad-labelling norms. Never blocks the signup.
  const londonNote = document.getElementById("jc-london-note");
  if (londonNote) londonNote.style.display = m.value === "London" ? "" : "none";
}

function cityOptions(marketName, selected) {
  const m = state.boot.markets.find((x) => x.name === marketName) || state.boot.markets[0];
  return m.cities.map((c) => `<option value="${esc(c)}" ${c === selected ? "selected" : ""}>${esc(c)}</option>`).join("");
}

// Build -88: the area picker options for a market, fed by the
// market's own typed city list (for London, its full
// neighbourhood + surrounding-towns list). The area search box
// filters the options live, mirroring the market picker.
function areaOptions(marketName, selected) {
  const m = (state.boot.markets || []).find((x) => x.name === marketName);
  const list = m ? m.cities : [];
  return list.map((c) => `<option value="${esc(c)}" ${c === selected ? "selected" : ""}>${esc(c)}</option>`).join("");
}
// Build -89: currency by market, client side. The bootstrap
// market entries carry currencySymbol + paidFloor (London: £,
// 40); every other market defaults to $ and 50. Creator money
// surfaces render with the CREATOR's home-market symbol — the
// viewer's own market when the surface is the creator's own.
function currencySymbolForMarket(name) {
  const m = (state.boot.markets || []).find((x) => x.name === name);
  return (m && m.currencySymbol) || "$";
}
function paidFloorForMarketClient(name) {
  const m = (state.boot.markets || []).find((x) => x.name === name);
  return m && typeof m.paidFloor === "number" ? m.paidFloor : 50;
}
function ownCurrencySymbol() {
  return state.user ? currencySymbolForMarket(state.user.market) : "$";
}
function ownPaidFloor() {
  return state.user ? paidFloorForMarketClient(state.user.market) : 50;
}
function filterAreaOptions(searchId, selectId) {
  const input = document.getElementById(searchId);
  const sel = document.getElementById(selectId);
  if (!input || !sel) return;
  const q = input.value.trim().toLowerCase();
  let firstMatch = null;
  for (const opt of sel.querySelectorAll("option")) {
    const hit = !q || opt.textContent.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q);
    opt.hidden = !hit;
    if (hit && !firstMatch) firstMatch = opt;
  }
  const current = sel.selectedOptions && sel.selectedOptions[0];
  if (q && firstMatch && current && current.hidden) sel.value = firstMatch.value;
}

function renderSignin() {
  app.innerHTML = `
  <section class="panel form-panel" style="max-width:460px;margin:30px auto">
    <div class="form-head">
    <h2>Sign in</h2>
    </div>
    <div class="form-body">
    <div id="form-error"></div>
    <form novalidate onsubmit="return doSignin(event)">
      <div class="field"><label>Email</label><input type="email" id="si-email" required autocomplete="email"></div>
      <div class="field"><label>Password</label><input type="password" id="si-password" required autocomplete="current-password"></div>
      <button class="btn" type="submit" style="width:100%">Sign in</button>
    </form>
    <p class="small muted mt">You will stay signed in on this device for 30 days. <a class="tlink" href="#" onclick="return go('forgot')">Forgot password?</a></p>
    <button class="btn ghost mt" style="width:100%" onclick="return goStaff()">Redeem a creator visit</button>
    <p class="small muted">Staff at a SIGNL business: the button above takes you straight to the register screen. PIN in, creator code in, redeemed.</p>
    <p class="small muted mt">New to SIGNL? <a class="tlink" href="#" onclick="return go('join-creator')">Join as a founding creator</a>. Businesses: <a class="tlink" href="#" onclick="return go('for-businesses')">join the founding business list</a>.</p>
    </div>
  </section>`;
}

async function doSignin(e) {
  e.preventDefault();
  const form = e.target;
  // Empty submit speaks (Build -47, audit L1): the form is
  // novalidate so this check, not a browser bubble, answers.
  const siEmail = (document.getElementById("si-email").value || "").trim();
  const siPw = document.getElementById("si-password").value || "";
  if (!siEmail || !siPw) {
    document.getElementById("form-error").innerHTML = `<div class="error-box">${!siEmail && !siPw ? "Enter your email and password to sign in." : !siEmail ? "Enter your email to sign in." : "Enter your password to sign in."}</div>`;
    return false;
  }
  if (!submitBusy(form, true)) return false;
  try {
    const data = await api("POST", "/auth/login", {
      email: document.getElementById("si-email").value,
      password: document.getElementById("si-password").value,
    });
    state.user = data.user;
    state.view = "dashboard";
    render();
    refreshBadges();
  } catch (err) {
    submitBusy(form, false);
    document.getElementById("form-error").innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

// Forgot password (UX audit fix, 2026-10-22): the request screen
// always lands on the same neutral confirmation, whether or not
// the email belongs to an account, so the form never confirms
// that an account exists.
function renderForgot() {
  app.innerHTML = `
  <section class="panel form-panel" style="max-width:460px;margin:30px auto">
    <div class="form-head">
    <h2>Forgot password</h2>
    </div>
    <div class="form-body">
    <p class="muted">Enter the email on your SIGNL account and we will email you a link to set a new password. The link works once and expires in one hour.</p>
    <div id="form-error"></div>
    <form onsubmit="return doForgot(event)">
      <div class="field"><label>Email</label><input type="email" id="fp-email" required autocomplete="email"></div>
      <button class="btn" type="submit" style="width:100%">Email me a reset link</button>
    </form>
    <p class="small muted mt">Remembered it after all? <a href="#" onclick="return go('signin')">Back to sign in</a>.</p>
    </div>
  </section>`;
}

async function doForgot(e) {
  e.preventDefault();
  const form = e.target;
  if (!submitBusy(form, true)) return false;
  try {
    const data = await api("POST", "/auth/forgot", { email: document.getElementById("fp-email").value });
    // Transport honesty (Build -46): when the server says email
    // itself is down, no link can go out to anyone, so the screen
    // says that instead of promising one — with a human way
    // forward, never a loop of fresh requests that cannot send.
    if (data && data.emailDown) {
      app.innerHTML = `
    <section class="panel center" style="max-width:460px;margin:30px auto">
      <h2>Email is down on our side</h2>
      <p>We cannot send a reset link right now, so none went out. This is a problem on our end, not with your account.</p>
      <p class="muted">Try again in a little while, or email hello@joinsignl.com and we will help you set a new password by hand.</p>
      <div class="cta-row" style="justify-content:center">
        <a class="btn ghost" href="#" onclick="return go('signin')">Back to sign in</a>
      </div>
    </section>`;
      return false;
    }
    app.innerHTML = `
    <section class="panel center" style="max-width:460px;margin:30px auto">
      <h2>Check your email</h2>
      <p>If an account exists for that email, a reset link is on its way. The link works once and expires in one hour.</p>
      <p class="muted">Nothing arrived after a few minutes? Check spam, then request a fresh link. If it keeps not arriving, email hello@joinsignl.com and we will sort it out with you.</p>
      <div class="cta-row" style="justify-content:center">
        <a class="btn" href="#" onclick="return go('forgot')">Request another link</a>
        <a class="btn ghost" href="#" onclick="return go('signin')">Back to sign in</a>
      </div>
    </section>`;
  } catch (err) {
    submitBusy(form, false);
    document.getElementById("form-error").innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

// The reset screen the email link lands on (/?reset=<token>).
function renderReset() {
  app.innerHTML = `
  <section class="panel form-panel" style="max-width:460px;margin:30px auto">
    <div class="form-head">
    <h2>Set a new password</h2>
    </div>
    <div class="form-body">
    <p class="muted">Pick a new password for your SIGNL account. Setting it signs out every other device on the account.</p>
    <div id="form-error"></div>
    <form onsubmit="return doReset(event)">
      <div class="field"><label>New password (10+ characters)</label><input type="password" id="rs-password" required minlength="10" autocomplete="new-password"></div>
      <div class="field"><label>New password again</label><input type="password" id="rs-password2" required minlength="10" autocomplete="new-password"></div>
      <button class="btn" type="submit" style="width:100%">Set my new password</button>
    </form>
    <p class="small muted mt">Link expired or already used? <a href="#" onclick="return go('forgot')">Request a new one</a>.</p>
    </div>
  </section>`;
}

async function doReset(e) {
  e.preventDefault();
  const form = e.target;
  const errBox = (msg) => { document.getElementById("form-error").innerHTML = `<div class="error-box">${esc(msg)}</div>`; };
  const pw = document.getElementById("rs-password").value;
  if (pw !== document.getElementById("rs-password2").value) { errBox("The two passwords do not match. Type the same new password in both boxes."); return false; }
  if (!submitBusy(form, true)) return false;
  try {
    await api("POST", "/auth/reset", { token: state.resetToken || "", password: pw });
    state.resetToken = "";
    app.innerHTML = `
    <section class="panel center" style="max-width:460px;margin:30px auto">
      <h2>Your password is set</h2>
      <p>Sign in with your new password to pick up right where you left off.</p>
      <div class="cta-row" style="justify-content:center"><a class="btn" href="#" onclick="return go('signin')">Sign in</a></div>
    </section>`;
  } catch (err) {
    submitBusy(form, false);
    errBox(err.message);
  }
  return false;
}

async function signOut() {
  // In a view-as session (Build -67), signing out exits the view
  // back to Admin; the admin is never signed out from under the
  // view. The server routes logout the same way, belt and braces.
  if (state.user && state.user.viewAs) { await exitViewAs(); return; }
  try { await api("POST", "/auth/logout", {}); } catch (e) { /* ignore */ }
  state.user = null;
  state.view = "home";
  // V4.1: Sig's queue + conversation belong to the signed-out
  // account; the next person on this device starts clean.
  state.sigQueue = null;
  state.sigQueueLinks = [];
  state.sigQueueCount = 0;
  state.sigThread = [];
  render();
}

// Account basics (UX audit fix, 2026-10-22): every signed-in
// account surface shows who you are signed in as and offers a
// password change (current password required; every other device
// signs out, this one stays). Before this there was no settings
// surface at all: no email display, no password change, and a
// forgotten password was a permanent lockout.
function accountHtml(u) {
  return `
  <div class="panel mt">
    <h3>Your account</h3>
    <p class="small muted">Signed in as <strong>${esc(u.email)}</strong>. This is the email SIGNL uses for your account and launch messages.</p>
    <div id="acct-error"></div>
    <form onsubmit="return doChangePassword(event)">
      <div class="form-2col">
        <div class="field"><label>Current password</label><input type="password" id="acct-current" required autocomplete="current-password"></div>
        <div class="field"><label>New password (10+ characters)</label><input type="password" id="acct-new" required minlength="10" autocomplete="new-password"></div>
      </div>
      <button class="btn" type="submit">Change password</button> <span id="acct-ok" class="saved"></span>
      <p class="small muted mt">Changing your password signs out every other device on this account. This device stays signed in.</p>
    </form>
    <p class="small muted">Cannot get in at all? Sign out, then use Forgot password on the sign-in screen and we will email you a reset link.</p>
  </div>`;
}

async function doChangePassword(e) {
  e.preventDefault();
  const form = e.target;
  if (!submitBusy(form, true)) return false;
  const errEl = document.getElementById("acct-error");
  try {
    await api("POST", "/auth/change-password", {
      currentPassword: document.getElementById("acct-current").value,
      newPassword: document.getElementById("acct-new").value,
    });
    submitBusy(form, false);
    form.reset();
    if (errEl) errEl.innerHTML = "";
    const ok = document.getElementById("acct-ok");
    if (ok) ok.textContent = "Password changed.";
  } catch (err) {
    submitBusy(form, false);
    if (errEl) errEl.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

function suggestedTierId(followers) {
  const n = Number(followers) || 0;
  if (n >= 15000) return "Headliners";
  if (n >= 2000) return "Locals";
  return "Neighbors";
}

const JC_STACK_ROWS = [["jc-stack-tiktok", "tiktok"], ["jc-stack-facebook", "facebook"], ["jc-stack-x", "x"], ["jc-stack-linkedin", "linkedin"], ["jc-stack-youtube", "youtube"], ["jc-stack-snapchat", "snapchat"]];
function jcPrimary() {
  const sel = document.getElementById("jc-platform");
  return sel ? sel.value : "instagram";
}
function signupStackTotal() {
  // The main followers field IS the primary platform's count; a
  // stack row for that same platform would double it, so its row
  // is hidden by syncJcPlatform and skipped here.
  let total = parseInt((document.getElementById("jc-followers") || {}).value, 10) || 0;
  const primary = jcPrimary();
  for (const [id, platform] of JC_STACK_ROWS) {
    if (platform === primary) continue;
    const el = document.getElementById(id);
    if (el) total += parseInt(el.value, 10) || 0;
  }
  return total;
}
function syncJcPlatform() {
  syncProofDisclosure("jc-platform", "jc-proof-note");
  const meta = primaryMetaClient(jcPrimary());
  const handleLabel = document.getElementById("jc-handle-label");
  if (handleLabel) handleLabel.textContent = `${meta.label} ${T("handle (required)", "usuario (obligatorio)")}`;
  const followersLabel = document.getElementById("jc-followers-label");
  if (followersLabel) followersLabel.textContent = `${meta.label} ${T("followers (required)", "seguidores (obligatorio)")}`;
  const input = document.getElementById("jc-handle");
  const link = document.getElementById("jc-ig-link");
  if (link) link.textContent = input && input.value ? meta.host + input.value.replace(/^@/, "") : "";
  for (const [, platform] of JC_STACK_ROWS) {
    const row = document.getElementById("jc-stackrow-" + platform);
    if (row) row.style.display = platform === meta.id ? "none" : "";
  }
  syncSuggestedTier();
}

// Tier bands are fully automatic (Jeff, 2026-10-19): the band is
// derived from the total audience across platforms, at sign-up and
// on every profile save. Nobody picks or confirms their own band,
// so the form shows it as a read-only line that follows the counts.
function syncSuggestedTier() {
  const total = signupStackTotal();
  const line = document.getElementById("jc-tier-line");
  if (line) line.textContent = total >= 500
    ? `Your band: ${suggestedTierId(total)}, set automatically from your total audience across platforms (${total.toLocaleString()} total).`
    : total > 0
      ? `SIGNL starts at 500 total followers across your platforms. You have ${total.toLocaleString()} counted so far; add every platform you post on and the counts add up.`
      : "Your band is set automatically from your total audience across platforms. SIGNL starts at 500 total followers across your platforms.";
  syncPaidOption();
}

// Paid cash campaigns are a Headliners-tier option: the checkbox block
// only appears while the automatic band is Headliners.
function syncPaidOption() {
  const wrap = document.getElementById("jc-paid-wrap");
  if (wrap) wrap.style.display = suggestedTierId(signupStackTotal()) === "Headliners" ? "" : "none";
}

function profileStackTotal() {
  const ids = ["p-followers", "p-stack-tiktok", "p-stack-facebook", "p-stack-x", "p-stack-linkedin", "p-stack-youtube", "p-stack-snapchat"];
  return ids.reduce((s, id) => s + (parseInt((document.getElementById(id) || {}).value, 10) || 0), 0);
}

function syncPaidOptionProfile() {
  const wrap = document.getElementById("p-paid-wrap");
  if (wrap) wrap.style.display = suggestedTierId(profileStackTotal()) === "Headliners" ? "" : "none";
}

// ================= Sig Operator (Jeff, 2026-10-28) =================
// Sig does the doing in this chat: set up campaigns, find
// people, track data, prompt the next move, on both sides.
// The contract, from the actions catalog:
//  - routing: active flow first, then operator intents, then
//    the existing question path (AI, then the canon bank).
//  - confirm-before-commit on every write; reads need none.
//  - commits are the exact api() calls the screens make, so a
//    server refusal surfaces with the server's own reason, and
//    Sig offers the compliant fix in the same turn.
//  - flow state lives in memory only until confirmation;
//    "never mind" exits any flow with nothing written.
//  - English/Spanish end to end via ST(), keyed to the stored
//    language (creator record lang from S1, business
//    preferredLanguage from S3). Server error strings surface
//    as written; that is the named S1 limit.
// Operator text matching folds accents first (sigOpNorm), so
// Spanish phrasing matches with or without them.
function sigOpNorm(text) {
  return sigNorm(String(text || "").normalize("NFD").replace(/[\u0300-\u036f]/g, ""));
}
function sigOpSay(text, actions) {
  state.sigThread = state.sigThread || [];
  state.sigThread.push({ who: "sig", text, actions: actions && actions.length ? actions : undefined });
}
function sigOpUserTurn(text) {
  state.sigThread = state.sigThread || [];
  state.sigThread.push({ who: "user", text });
}
function sigOpPaint() {
  const host = document.getElementById("sig-thread");
  if (host) { host.innerHTML = sigThreadHtml(); wireSigThread(host); host.scrollTop = host.scrollHeight; }
  const inp = document.getElementById("sig-ask-input");
  if (inp) inp.focus();
}
async function sigOpPick(label, fn) {
  sigOpUserTurn(label);
  await fn();
  sigOpPaint();
}
function sigOpCancelAction() {
  const label = ST("Never mind", "Cancelar");
  return { label, run: () => sigOpPick(label, async () => {
    state.sigFlow = null;
    state.sigOpData = null;
    sigOpSay(ST("Stopped. Nothing was saved, sent, or posted.", "Listo. No se guardó, envió ni publicó nada."), sigOpHomeActions());
  }) };
}
function sigOpAsk(text, actions) {
  sigOpSay(text, [...(actions || []), sigOpCancelAction()]);
}
function sigOpIsCancel(norm) {
  return [" never mind ", " cancel ", " cancelar ", " olvida ", " olvidalo ", " forget it ", " stop here ", " detente "].some((p) => norm.includes(p));
}
function sigOpNum(text) {
  const m = String(text || "").replace(/[$,]/g, "").match(/(\d+(?:\.\d+)?)/);
  return m ? Number(m[1]) : null;
}
