function sigOpIntent(norm) {
  const u = state.user;
  if (!u) return null;
  const has = (...ps) => ps.some((p) => norm.includes(p));
  if (u.role === "business") {
    if (has("monthly receipt", "receipt export", "forward my receipt", "export my receipt", "receipt for my bookkeeper")) return async () => sigB96Receipt();
    if (has("standing hours", "standing availability", "set my hours", "my opening hours", "when are we open", "when am i open")) return async () => sigB96AvailabilityStart();
    if (has("my regulars", "regulars", "book again", "rebook")) return async () => sigB95Regulars();
    if (has("licence expiring", "license expiring", "licences ending", "licenses ending", "licence ending", "license ending", "renew licence", "renew license", "renew my licence", "renew my license")) return async () => sigB95Licences();
    if (has("asset packet", "paquete de recursos", "paquete", "brand assets", "mis enlaces")) return async () => sigPacketStart();
    if (has("how am i doing", "como voy", "my numbers", "mis numeros", "my results", "mis resultados", "rendimiento", "track my data", "performance")) return async () => sigB3Run();
    if (has("who should i invite", "who do i invite", "who should we invite", "invite first", "quien invito primero")) return async () => { sigB2FlowStart(); await sigB2Run({}); };
    if (has("find creator", "find me creator", "buscar creador", "encuentra creador", "show me creator", "ver creadores", "buscar creadores") || (has("creator", "creators", "creador", "creadores") && has("find", "show me", "near me", "nearby", "looking for", "search", "buscar", "muestra"))) return async () => {
      // A request that already says what it wants ("find me
      // food creators near me") runs the search right away and
      // answers with cards; a bare "find creators" still opens
      // the criteria prompt first.
      const crit = sigB2ParseCrit(norm);
      if (Object.keys(crit).length || norm.includes(" near me ") || norm.includes(" nearby ")) { sigB2FlowStart(); await sigB2Run(crit); }
      else sigB2Start();
    };
    if (has("set up a campaign", "create an offer", "post an offer", "new offer", "make an offer", "start a campaign", "draft a campaign", "draft my campaign", "draft my first", "draft an offer", "make a campaign", "make me a campaign", "campaign for my", "campaign for our", "crear una oferta", "publicar una oferta", "nueva oferta", "crear campana", "una campana", "quiero una oferta", "lanzar una oferta")) return async () => sigB1Start();
    if (has("set me up", "set up my business", "setup my business", "set up from instagram", "use my instagram", "from my instagram", "configura mi negocio", "configurar mi negocio")) return async () => sigSetupStart("business");
    return null;
  }
  if (u.role === "creator") {
    if (has("payout setup", "set up payouts", "what will stripe ask", "1099", "payout paperwork")) return async () => sigC98Payout();
    if (has("starting point", "starting rate", "starting default")) return async () => sigC98Rates();
    if (has("creator terms", "terms in plain words")) return async () => sigC98Terms();
    if (has("licence request", "license request", "licence requests", "license requests", "renewal request", "licence renewal", "license renewal")) return async () => sigC95Licences();
    if (has("invite a creator", "invite link", "invitar a un creador", "mi enlace de invitacion", "referral link", "invite creators")) return async () => sigC4Run();
    if (has("set me up", "set up from instagram", "use my instagram", "from my instagram", "set up my profile from", "configura mi perfil")) return async () => sigSetupStart("creator");
    if (has("finish my profile", "complete my profile", "build my profile", "what do i still need", "still need to finish", "need to finish", "left to finish", "what is missing", "whats missing", "what am i missing", "terminar mi perfil", "completar mi perfil", "completar perfil", "que me falta")) return async () => sigC2Start();
    if (has("how do i earn more", "earn more", "make more money", "how do i make money", "earn more money", "ganar mas", "como gano mas")) return async () => sigC5Run();
    if (has("how am i doing", "como voy", "my numbers", "mis numeros", "my momentum", "track my data", "mis resultados")) return async () => sigC3Run();
    if (has("find offers", "offers for me", "find work", "find gigs", "buscar ofertas", "ofertas para mi", "see offers", "show me offers", "ver ofertas")) return async () => sigC1Start();
    return null;
  }
  return null;
}
// ---------- Build -95: Sig Operator for Regulars + licences ----------
// Business Sig DOES the item-10 work in-thread, confirm-first
// like every other operator flow: show the business's real
// Regulars with a Book again draft per row, and the licences
// inside their 14-day window with an Ask to renew per row.
// Creator Sig shows the real pending licence and renewal
// requests waiting on them, with Approve / Decline that write
// through the same endpoints the Earnings tab uses.
async function sigB95Regulars() {
  let rows = [];
  try { const d = await api("GET", "/me/regulars"); rows = d.regulars || []; } catch (e) { sigOpSay("I could not load your Regulars just now. Try again, or open Regulars in the rail.", sigOpHomeActions()); return; }
  if (!rows.length) {
    sigOpSay("No Regulars yet. A creator becomes one of your Regulars the day a visit with them is completed and their post is live. Then they sit in your Regulars view with the deal that ran and a Book again button.", [{ label: "Open Regulars", run: async () => go("dashboard", "Regulars") }, ...sigOpHomeActions()]);
    return;
  }
  const head = rows.length === 1 ? "You have 1 Regular:" : `You have ${rows.length} Regulars:`;
  const list = rows.slice(0, 5).map((r) => `${r.creatorName} (@${r.creatorHandle}), ${r.visits} ${r.visits === 1 ? "visit" : "visits"}, last one ${r.lastVisitAt ? fmtDay(r.lastVisitAt) : "on record"}${r.rebookedSince ? ", already rebooked since" : ""}`).join(". ") + ".";
  sigOpSay(`${head} ${list} Tap one to draft a repeat visit with the same deal.`, [
    ...rows.slice(0, 5).map((r) => ({
      label: `Book again: @${r.creatorHandle}`,
      run: async () => sigOpPick(`Book again: @${r.creatorHandle}`, async () => {
        sigOpAsk(`Book ${r.creatorName} again? I will copy the last visit's deal ("${r.lastTitle || "your last visit"}", ${r.deal.line}) into a new draft in Your campaigns. Nothing sends until you publish the draft.`, [
          { label: "Yes, draft it", primary: true, run: async () => sigOpPick("Yes, draft it", async () => {
            try {
              const d = await api("POST", `/me/regulars/${r.creatorId}/book-again`, {});
              sigOpSay(`Draft created: "${d.offer.title}" is saved in Your campaigns as a draft with the same terms as the last visit. Nothing was sent.`, [
                { label: "Open the draft", primary: true, run: async () => { state.offersSeg = "drafts"; go("dashboard", "My Offers"); } },
                { label: "Back to Regulars", run: async () => sigB95Regulars() },
              ]);
            } catch (e) { sigOpSay(`That draft did not save: ${e.message}`, sigOpHomeActions()); }
          }) },
        ]);
      }),
    })),
    { label: "Open Regulars", run: async () => go("dashboard", "Regulars") },
  ]);
}
async function sigB95Licences() {
  let rows = [];
  try { const d = await api("GET", "/me/licences-expiring"); rows = d.licences || []; } catch (e) { sigOpSay("I could not load your licences just now. Try again, or open Posts and licenses in the rail.", sigOpHomeActions()); return; }
  if (!rows.length) {
    sigOpSay("No licences are ending in the next 14 days. Every licence you hold shows its end date in Posts and licenses, and you get an alert 14 days and again 1 day before one ends.", [{ label: "Open Posts and licenses", run: async () => go("dashboard", "Content") }, ...sigOpHomeActions()]);
    return;
  }
  const list = rows.map((l) => `${l.creatorName}'s post "${l.title}" ends ${fmtDay(l.windowEndsAt)}${l.ended ? " (already ended)" : ""}`).join(". ") + ".";
  sigOpSay(`Ending soon: ${list} Tap one to ask to renew. The request goes to the creator at their listed fee, and a fresh 90 days starts only if they approve.`, [
    ...rows.map((l) => ({
      label: `Ask to renew: @${l.creatorHandle}`,
      run: async () => sigOpPick(`Ask to renew: @${l.creatorHandle}`, async () => {
        if (!l.fee) { sigOpSay("This creator has not listed a licensing fee, so this post cannot be renewed through SIGNL. It stays shareable inside Instagram with credit.", sigOpHomeActions()); return; }
        sigOpAsk(`Ask to renew the licence on ${l.creatorName}'s post "${l.title}"? It ends ${fmtDay(l.windowEndsAt)}. The request goes to the creator at their $${fmtPrice(l.fee)} fee: you pay $${fmtMoney(Math.round(l.fee * 1.03 * 100) / 100)} only if they approve, the creator keeps $${fmtMoney(Math.round(l.fee * 0.97 * 100) / 100)} (97%), and a fresh 90 days starts the day they approve. Nothing renews unless they say yes.`, [
          { label: "Yes, ask to renew", primary: true, run: async () => sigOpPick("Yes, ask to renew", async () => {
            try {
              await api("POST", `/posts/${l.postId}/license-request`, {});
              sigOpSay("Renewal request sent. It is waiting on the creator's yes or no, and the licence only continues if they approve.", [
                { label: "Open Posts and licenses", run: async () => go("dashboard", "Content") },
                { label: "Check again", run: async () => sigB95Licences() },
              ]);
            } catch (e) { sigOpSay(`That request did not send: ${e.message}`, sigOpHomeActions()); }
          }) },
        ]);
      }),
    })),
    { label: "Open Posts and licenses", run: async () => go("dashboard", "Content") },
  ]);
}
// ---- Build -96: Business Sig serves the monthly receipt export ----
// One fetch of the real export record; the answer states the
// three honesty classes separately (never summed), then the
// actions carry the actual CSV download link and the print
// view. The Results view stays one tap away.
async function sigB96Receipt() {
  try {
    const data = await api("GET", "/me/receipt-export");
    const exp = data.export;
    const c = exp.counted || {}, r = exp.recorded || {}, it = exp.intent || {}, v = exp.visits || {};
    const lines = ST(
      `Your ${exp.monthLabel} receipt, ready to forward. Counted at the register: ${fmtNum(c.customers)} customers, $${fmtMoney(c.registerDollars)}. Recorded from posts: ${fmtNum(r.views)} views across ${fmtNum(r.reportedPosts)} reported posts. Intent recorded: ${fmtNum(it.total)} shares and saves. Three separate kinds of numbers, never added together. Visits used: ${fmtNum(v.used)} of ${fmtNum(v.allowance)} (${fmtNum(v.carriedIn)} rolled over). ${(exp.credit || {}).line || ""}${(exp.licences || []).length ? ` Licences held: ${exp.licences.map((l) => `${l.creatorName}'s post ends ${String(l.windowEndsAt).slice(0, 10)}`).join("; ")}.` : " No licences held right now."}`,
      `Tu recibo de ${exp.monthLabel}, listo para reenviar. Contado en caja: ${fmtNum(c.customers)} clientes, $${fmtMoney(c.registerDollars)}. Registrado de publicaciones: ${fmtNum(r.views)} vistas en ${fmtNum(r.reportedPosts)} publicaciones. Intención registrada: ${fmtNum(it.total)} compartidos y guardados. Tres tipos de cifras, nunca sumadas. Visitas usadas: ${fmtNum(v.used)} de ${fmtNum(v.allowance)} (${fmtNum(v.carriedIn)} trasladadas).`);
    sigOpSay(lines, [
      { label: ST("Download CSV", "Descargar CSV"), run: async () => sigOpPick(ST("Download CSV", "Descargar CSV"), async () => { window.location.href = `/api/me/receipt-export/csv?month=${encodeURIComponent(exp.month)}`; sigOpSay(ST("Your CSV download has started. Any month can be picked from Results.", "La descarga de tu CSV empezó. Puedes elegir cualquier mes en Resultados.")); }) },
      { label: ST("Print view", "Vista de impresión"), run: async () => sigOpPick(ST("Print view", "Vista de impresión"), async () => { state._receiptExport = exp; receiptExportPrint(); sigOpSay(ST("The print view is open in a new tab: print it, or save it as a PDF from there.", "La vista de impresión está abierta en una pestaña nueva.")); }) },
      { label: ST("Open Results", "Abrir Resultados"), run: async () => sigOpPick(ST("Open Results", "Abrir Resultados"), async () => go("dashboard", "Analytics")) },
    ]);
  } catch (e) { sigOpSay(ST("I could not load your receipt just now. It lives in Results, and the export card sits at the foot of it.", "No pude cargar tu recibo ahora. Vive en Resultados, y la tarjeta de exportación está al pie.")); }
}
// ---- Build -96: Business Sig reads and sets standing availability ----
// Read is instant from the account record. Set is confirm-
// first: Sig parses the plain words, reads the line back, and
// saves only on Yes, through the same business-page PATCH.
async function sigB96AvailabilityStart() {
  const cur = state.user.business ? availabilitySummaryClient(state.user.business.standingAvailability) : null;
  if (cur) sigOpSay(ST(`Your standing availability reads: "${cur}". Creators see that line on your offers, and new offers pre-fill their timing from it. Tell me the new version in plain words, like "Fri to Sun, 12 to 4 · Tue to Thu by appointment", or say clear to take it off.`,
    `Tu horario habitual dice: "${cur}". Los creadores ven esa línea en tus ofertas. Dime la nueva versión en palabras simples, o di borrar para quitarlo.`));
  else sigOpSay(ST("You have not set standing availability yet. Tell me your usual open days and hours in plain words, like \"Fri to Sun, 12 to 4 · Tue to Thu by appointment\", and I will read it back before saving. Creators see it on your offers, and new offers pre-fill their timing from it.",
    "Aún no fijaste tu horario habitual. Dime tus días y horas habituales en palabras simples, y te lo leo antes de guardar."));
  state.sigFlow = { id: "b96avail", step: "collect", data: {} };
  sigOpPaint();
}
// The collect step of the availability flow: parse the plain
// words, then confirm with a button (the codebase's confirm
// pattern) before anything saves. "Clear" clears, on confirm.
async function sigB96AvailStep(f, text) {
  const t = String(text || "").trim();
  const tl = t.toLowerCase();
  if (tl === "clear" || tl === "remove" || tl === "borrar" || tl === "quitar") {
    state.sigFlow = null;
    sigOpAsk(ST("Take your standing availability off entirely? Creators stop seeing the line, and new offers stop pre-filling from it.", "¿Quitar tu horario habitual por completo?"), [
      { label: ST("Yes, take it off", "Sí, quitarlo"), primary: true, run: async () => sigOpPick(ST("Yes, take it off", "Sí, quitarlo"), async () => {
        try {
          const data = await api("PATCH", "/me/profile", { standingAvailability: null });
          state.user = data.user;
          sigOpSay(ST("Cleared. Your standing availability is off; creators no longer see a standing line, and offers carry their own timing notes.", "Borrado. Tu horario habitual está desactivado."), [{ label: ST("Open your business page", "Abrir tu página"), run: async () => go("dashboard", "Profile") }]);
        } catch (e) { sigOpSay(ST("I could not save that just now. Your business page holds the same setting, under When creators can come.", "No pude guardarlo ahora."), sigOpHomeActions()); }
      }) },
    ]);
    return;
  }
  const parsed = parseAvailabilityText(t);
  if (!parsed) { sigOpAsk(ST("I could not pick days or hours out of that. Try the plain shape: \"Fri to Sun, 12 to 4\" and, if you take them, \"Tue to Thu by appointment\".", "No pude leer días ni horas ahí. Prueba la forma simple: \"Vie a Dom, 12 a 4\".")); return; }
  state.sigFlow = null;
  const summary = availabilitySummaryClient(parsed);
  sigOpAsk(ST(`Save this as your standing availability? It will read: "${summary}". Creators see it on your offers, and new offers pre-fill their timing from it.`, `¿Guardar esto como tu horario habitual? Dirá: "${summary}".`), [
    { label: ST("Yes, save it", "Sí, guardarlo"), primary: true, run: async () => sigOpPick(ST("Yes, save it", "Sí, guardarlo"), async () => {
      try {
        const data = await api("PATCH", "/me/profile", { standingAvailability: parsed });
        state.user = data.user;
        sigOpSay(ST(`Saved. Your standing availability now reads: "${summary}".`, `Guardado. Tu horario habitual ahora dice: "${summary}".`), [{ label: ST("Open your business page", "Abrir tu página"), run: async () => go("dashboard", "Profile") }]);
      } catch (e) { sigOpSay(ST("I could not save that just now. Your business page holds the same setting, under When creators can come.", "No pude guardarlo ahora."), sigOpHomeActions()); }
    }) },
  ]);
}
