// Business-wave prefill application (Jeff, 2026-10-23): when
// the visitor arrived on a prebuilt link, the founding
// registration opens with the business name, market and
// category already filled in, under a note that says so. Every
// field stays editable, per the form's existing conventions;
// the business still adds its own name, email and password.
function applyBizPrefill() {
  const pre = state.bizPrefill;
  if (!pre) return;
  const note = document.getElementById("jb-prefill");
  if (note && pre.businessName) {
    note.innerHTML = `<div class="notice blue">We pre-built this founding registration for ${esc(pre.businessName)}. Check the details, add your name, email and password, and claim your spot.</div>`;
  }
  const bizEl = document.getElementById("jb-business");
  if (bizEl && pre.businessName) bizEl.value = pre.businessName;
  const catEl = document.getElementById("jb-category");
  if (catEl && pre.category) {
    catEl.value = pre.category;
    // V4: the category is a chip group over this hidden input —
    // keep the highlighted chip in step with the prefilled value.
    const catRow = document.querySelector('.chiprow[data-chipfor="jb-category"]');
    if (catRow) catRow.querySelectorAll(".rchip").forEach((b) => b.classList.toggle("on", (b.getAttribute("data-val") || "") === pre.category));
  }
  const mktEl = document.getElementById("jb-market");
  if (mktEl && pre.market) {
    mktEl.value = pre.market;
    syncBizMarketChoice();
  }
}

function bizCityOptions() {
  const mkt = state.boot.markets.find((m) => m.name === document.getElementById("jb-market").value);
  const sel = document.getElementById("jb-city");
  if (!sel) return;
  sel.innerHTML = (mkt ? mkt.cities : []).map((c) => `<option>${esc(c)}</option>`).join("");
}

// The business market picker gets the same search + not-listed
// treatment the creator forms have (UX audit fix, 2026-10-22):
// search filters the grouped options, and "My city is not listed
// yet" swaps the city dropdown for the founding-list interest
// fields instead of dead-ending the registration.
function filterBizMarketOptions() {
  const input = document.getElementById("jb-market-search");
  const sel = document.getElementById("jb-market");
  if (!input || !sel) return;
  const q = input.value.trim().toLowerCase();
  let firstMatch = null;
  for (const opt of sel.querySelectorAll("option")) {
    if (opt.value === unlistedLabel()) continue;
    const hit = !q || opt.textContent.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q);
    opt.hidden = !hit;
    if (hit && !firstMatch) firstMatch = opt;
  }
  for (const grp of sel.querySelectorAll("optgroup")) {
    grp.hidden = ![...grp.querySelectorAll("option")].some((o) => !o.hidden);
  }
  const current = sel.selectedOptions && sel.selectedOptions[0];
  if (q && firstMatch && current && current.hidden) {
    sel.value = firstMatch.value;
    syncBizMarketChoice();
  }
}

function syncBizMarketChoice() {
  const m = document.getElementById("jb-market");
  if (!m) return;
  const unlisted = m.value === unlistedLabel();
  const customWrap = document.getElementById("jb-custom-wrap");
  const cityRow = document.getElementById("jb-city-row");
  if (customWrap) customWrap.style.display = unlisted ? "" : "none";
  if (cityRow) cityRow.style.display = unlisted ? "none" : "";
  if (!unlisted) bizCityOptions();
}


// Apply by Conversation (Build -32): a Sig-guided version of the
// founding business application. One question at a time; the
// answers file through the SAME /auth/register call the form
// makes, with applicationSource "conversation" stamped on the
// record server-side. There is one application record; this is
// a second way to answer it, never a fork of it.
let jbConvoState = null;
function jbConvoSteps(a) {
  const steps = [
    { key: "businessName", q: "What is your business called?", type: "text", ph: "Your business as customers know it" },
    { key: "name", q: "And your name, the person running this account?", type: "text", ph: "Your name" },
    { key: "email", q: "What email should the account use?", type: "email", ph: "you@yourbusiness.com" },
    { key: "password", q: "Set a password, 10 characters or more.", type: "password", ph: "Password" },
    { key: "category", q: "What kind of business is it?", type: "chips", options: () => (state.boot.businessCategories || []).map((c) => ({ value: c, label: c })) },
    { key: "market", q: "Which market are you in?", type: "chips", options: () => (state.boot.markets || []).map((m) => ({ value: m.name, label: m.label || m.name })).concat([{ value: unlistedLabel(), label: "My city is not listed yet" }]) },
  ];
  if (a.market === unlistedLabel()) {
    steps.push({ key: "customCity", q: "What city are you in? Your sign-up counts toward opening SIGNL there.", type: "text", ph: "For example: Tulsa" });
    steps.push({ key: "customCountry", q: "And the country?", type: "text", ph: "For example: United States" });
    steps.push({ key: "customState", q: "State or province? Optional, say skip by leaving it empty.", type: "text", optional: true, ph: "Optional" });
  } else if (a.market) {
    const mkt = (state.boot.markets || []).find((m) => m.name === a.market);
    steps.push({ key: "city", q: "Which city?", type: "chips", options: () => ((mkt && mkt.cities) || []).map((c) => ({ value: c, label: c })) });
  }
  steps.push({ key: "neighborhood", q: "Neighborhood or area? Optional, leave it empty to skip.", type: "text", optional: true, ph: "For example: Oceanfront, Ghent" });
  steps.push({ key: "planId", q: "Which founding plan fits? No card is taken, and billing starts at activation.", type: "chips", options: () => (state.boot.plans || []).map((pl) => ({ value: pl.id, label: `${pl.name}: $${pl.priceMonthly}/mo for ${pl.visitsPerMonth} creators a month` })) });
  steps.push({ key: "moment", q: "Last question: what is your first month about? The moment names the play your first month runs.", type: "chips", options: () => momentsClient().map((m) => ({ value: m.id, label: m.label })).concat([{ value: "", label: "Not sure yet" }]) });
  steps.push({ key: "terms", q: "That is everything. Agree to the terms and Sig files your founding application.", type: "terms" });
  return steps;
}
function jbConvoStart() {
  const host = document.getElementById("jb-convo");
  const startBtn = document.getElementById("jb-convo-start");
  if (startBtn) startBtn.style.display = "none";
  jbConvoState = { answers: {}, idx: 0, log: [] };
  jbConvoRender();
  if (host) host.scrollIntoView({ behavior: "smooth", block: "center" });
}
function jbConvoRender() {
  const host = document.getElementById("jb-convo");
  if (!host || !jbConvoState) return;
  const st = jbConvoState;
  const steps = jbConvoSteps(st.answers);
  const step = steps[st.idx];
  const logHtml = st.log.map((m) => m.who === "sig"
    ? `<p class="small" style="margin:6px 0"><strong>Sig:</strong> ${esc(m.text)}</p>`
    : `<p class="small muted" style="margin:6px 0 6px 18px"><strong>You:</strong> ${esc(m.text)}</p>`).join("");
  if (!step) { host.innerHTML = logHtml; return; }
  let inputHtml = "";
  if (step.type === "chips") {
    inputHtml = `<div class="chip-row">${step.options().map((o) => `<button type="button" class="chip" onclick="jbConvoAnswer('${esc(step.key)}', '${esc(o.value)}', '${esc(o.label)}')">${esc(o.label)}</button>`).join("")}</div>`;
  } else if (step.type === "terms") {
    inputHtml = `<label class="ckrow" style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" class="ckbox" id="jb-convo-terms"><span>I agree to the Terms of Service and Privacy Policy, including keeping bookings that start on SIGNL on SIGNL, and to account and marketing emails from SIGNL.</span></label>
      <div id="jb-convo-error"></div>
      <button class="btn mt" type="button" onclick="jbConvoFile()">File my founding application</button>`;
  } else {
    inputHtml = `<div style="display:flex;gap:8px;flex-wrap:wrap"><input id="jb-convo-input" type="${step.type}" placeholder="${esc(step.ph || "")}" style="flex:1;min-width:200px" onkeydown="if(event.key==='Enter'){event.preventDefault();jbConvoAnswerText('${esc(step.key)}');}"><button class="btn small-btn" type="button" onclick="jbConvoAnswerText('${esc(step.key)}')">${step.optional ? "Continue" : "Next"}</button></div>`;
  }
  host.innerHTML = `${logHtml}<p class="small" style="margin:10px 0 6px"><strong>Sig:</strong> ${esc(step.q)}</p>${inputHtml}`;
  const inp = document.getElementById("jb-convo-input");
  if (inp) inp.focus();
}
function jbConvoAnswer(key, value, label) {
  const st = jbConvoState;
  if (!st) return;
  const steps = jbConvoSteps(st.answers);
  const step = steps[st.idx];
  st.log.push({ who: "sig", text: step.q });
  st.log.push({ who: "you", text: label || value || "(skipped)" });
  st.answers[key] = value;
  st.idx += 1;
  jbConvoRender();
}
function jbConvoAnswerText(key) {
  const inp = document.getElementById("jb-convo-input");
  const val = inp ? inp.value.trim() : "";
  const st = jbConvoState;
  if (!st) return;
  const steps = jbConvoSteps(st.answers);
  const step = steps[st.idx];
  if (!step.optional && !val) { if (inp) inp.focus(); return; }
  if (key === "password" && val.length < 10) { st.log.push({ who: "sig", text: "That password is short. Set one with 10 characters or more." }); jbConvoRender(); return; }
  st.log.push({ who: "sig", text: step.q });
  st.log.push({ who: "you", text: key === "password" ? "(password set)" : (val || "(skipped)") });
  st.answers[key] = val;
  st.idx += 1;
  jbConvoRender();
}
async function jbConvoFile() {
  const st = jbConvoState;
  const errHost = document.getElementById("jb-convo-error");
  const terms = document.getElementById("jb-convo-terms");
  if (!terms || !terms.checked) { if (errHost) errHost.innerHTML = `<div class="error-box">Agree to the terms and Sig can file it.</div>`; return; }
  const a = st.answers;
  const isUnlisted = a.market === unlistedLabel();
  try {
    const data = await api("POST", "/auth/register", {
      role: "business",
      name: a.name,
      businessName: a.businessName,
      email: a.email,
      password: a.password,
      market: a.market,
      customCity: isUnlisted ? a.customCity : undefined,
      customCountry: isUnlisted ? a.customCountry : undefined,
      customState: isUnlisted ? (a.customState || undefined) : undefined,
      city: isUnlisted ? undefined : a.city,
      category: a.category,
      neighborhood: a.neighborhood || "",
      planId: a.planId,
      moment: a.moment || undefined,
      applicationSource: "conversation",
      agreedTerms: true,
      signupSource: storedSrc() || undefined,
    });
    state.user = data.user;
    state.view = "dashboard";
    state.tab = null;
    render();
  } catch (err) {
    if (errHost) errHost.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
  return false;
}

async function registerBusiness(e) {
  e.preventDefault();
  const form = e.target;
  const errBox = (msg) => { document.getElementById("jb-error").innerHTML = `<div class="error-box">${esc(msg)}</div>`; };
  const marketVal = document.getElementById("jb-market").value;
  const isUnlisted = marketVal === unlistedLabel();
  const customCity = isUnlisted ? document.getElementById("jb-city-text").value.trim() : "";
  const customCountry = isUnlisted ? document.getElementById("jb-country-text").value.trim() : "";
  const customState = isUnlisted ? document.getElementById("jb-state-text").value.trim() : "";
  if (isUnlisted && !customCity) { errBox(T("Tell us your city, so your sign-up counts toward opening SIGNL there.", "Dinos tu ciudad, para que tu registro cuente para abrir SIGNL ahí.")); return false; }
  if (isUnlisted && !customCountry) { errBox(T("Tell us your country, so your sign-up counts toward opening SIGNL there.", "Dinos tu país, para que tu registro cuente para abrir SIGNL ahí.")); return false; }
  if (!submitBusy(form, true)) return false;
  try {
    const data = await api("POST", "/auth/register", {
      role: "business",
      name: document.getElementById("jb-name").value,
      businessName: document.getElementById("jb-business").value,
      email: document.getElementById("jb-email").value,
      password: document.getElementById("jb-password").value,
      market: marketVal,
      customCity: isUnlisted ? customCity : undefined,
      customCountry: isUnlisted ? customCountry : undefined,
      customState: isUnlisted ? customState : undefined,
      city: isUnlisted ? undefined : document.getElementById("jb-city").value,
      category: document.getElementById("jb-category").value,
      posProvider: (document.getElementById("jb-pos") || {}).value || undefined,
      posOther: (document.getElementById("jb-pos-other") || {}).value || undefined,
      neighborhood: document.getElementById("jb-neighborhood").value,
      zip: document.getElementById("jb-zip").value,
      about: document.getElementById("jb-about").value,
      planId: document.getElementById("jb-plan").value,
      moment: (document.getElementById("jb-moment") || {}).value || undefined,
      baselineDay: (document.getElementById("jb-baseline-day") || {}).value || undefined,
      baselineCount: (document.getElementById("jb-baseline-count") || {}).value || undefined,
      applicationSource: window.__jbAppSource || undefined,
      agreedTerms: document.getElementById("jb-terms").checked,
      signupSource: storedSrc() || undefined,
    });
    state.user = data.user;
    state.view = "dashboard";
    state.tab = null;
    render();
  } catch (err) {
    submitBusy(form, false);
    errBox(err.message);
  }
  return false;
}

// Founding price hierarchy (Jeff, 2026-10-26): wherever a
// business sees a plan price, the standard rate is the hero
// figure and the founding first-month price rides directly
// under it as a bold mint badge, never the other way around.
// The small print under the card carries the 3-month minimum
// and the founding-rate-held line only: the first-month price
// is stated once, in the badge.
function foundingBadgeHtml(p) {
  return `<span class="founding-badge">FOUNDING: $100 CREDIT — FIRST MONTH $${fmtPrice(p.firstMonthPriceMonthly)}</span>`;
}

function selectPlan(id) {
  document.getElementById("jb-plan").value = id;
  document.querySelectorAll(".plan-card").forEach((el) => el.classList.remove("selected"));
  const el = document.getElementById("plan-" + id);
  if (el) el.classList.add("selected");
  const hidden = document.getElementById("me-plan");
  if (hidden) hidden.value = id;
}

// The founding business status page (Build -68): now ONLY
// the pending-review screen. An approved founding business
