function renderBusinessFoundingStatus() {
  const u = state.user;
  const bz = u.business || {};
  const bizPlace = u.market === unlistedLabel() ? (u.city || "your city") : marketTalkNameClient(u.market);
  app.innerHTML = `<div class="wrap" style="max-width:680px">
  ${wsHead("Status", { sub: "Where your founding enrollment stands." })}
  <section class="wcard" style="margin-top:14px">
    <p><span class="badge info">Application in review</span></p>
    <h2 style="margin-top:8px">${esc(bz.businessName || "Your business")} is on the founding list</h2>
    <p>You joined the <strong>Founding business list, ${esc(bizPlace)}</strong>. Your application is in review, and every founding application gets a decision or a clear status within 2 business days.</p>
    ${marketResolvedNote(u)}
    <div class="panel" style="margin-top:16px">
      <div class="ui-row"><span class="k">Plan interest</span><span class="v">${esc(bz.planName || "")}</span></div>
      <div class="ui-row"><span class="k">Category spot</span><span class="v">Your ${esc(bz.category || "business")} spot is held in application order</span></div>
      <div class="ui-row"><span class="k">Founding pricing</span><span class="v">Locked while you stay subscribed</span></div>
      <div class="ui-row"><span class="k">Payment</span><span class="v">Nothing is due now. Payment stays concierge: Jeff, SIGNL's founder, sends the payment step by hand at activation</span></div>
    </div>
    <h3 class="mt">What happens next</h3>
    <ol style="padding-left:20px">
      <li>SIGNL reviews your application. You will get a decision or a clear status within 2 business days.</li>
      <li>When your application is approved, this page opens into the full app: your plan, the creator roster in ${esc(bizPlace)}, and your first campaign, which you can save as a draft for opening day.</li>
      <li>When your market opens, SIGNL activates founding businesses by hand, in application order.</li>
    </ol>
    <p class="muted small">Sign back in any time to check your status. Questions: hello@joinsignl.com</p>
    <div class="mt"><button class="btn ghost" onclick="signOut()">Sign out</button></div>
  </section>
  <div id="fbz-account">${accountHtml(u)}</div></div>`;
}

// ---------- founding business preview (first 60 seconds, Jeff, 2026-10-29) ----------
// The value reveal under the founding status card. BUILD -30
// (Jeff, 2026-10-29): no roster counts, no creator cards, no
// thin-market framing anywhere on this page. What carries it
// instead: category presence from GET /me/roster-preview (the
// categories with at least one finished creator in this
// business's market, presence only), the local-reach explainer
// with one clearly labeled example, the first offer drafted by
// the same play machinery Sig's B1 flow and the composer use
// (SIG_PLAYS + briefFromParts, nothing new), and the benefit
// lines, which state the product exactly as it works. Nothing
// here is saved, sent, or booked: it is a preview, labeled one.
async function loadFoundingBusinessPreview() {
  if (!document.getElementById("fbz-preview")) return;
  let data = null;
  try { data = await api("GET", "/me/roster-preview"); } catch (e) { data = null; }
  const host = document.getElementById("fbz-preview");
  if (!host) return;
  host.innerHTML = foundingPreviewHtml(data);
  loadReceipt();
}

function foundingPreviewHtml(data) {
  const u = state.user;
  const bizPlace = u.market === unlistedLabel() ? (u.city || "your city") : marketTalkNameClient(u.market);
  return [
    foundingAnchorHtml(data),
    foundingCategoriesHtml(data, bizPlace),
    foundingNearYouHtml(data, bizPlace),
    foundingLocalReachHtml(),
    foundingFirstOfferHtml(u),
    foundingFirstMonthHtml(u, data),
    foundingLastAdHtml(),
    receiptFoundingHtml(),
    foundingBenefitsHtml(u),
    foundingPlansHtml(u),
  ].join("");
}

// Near your door (Build -31): the founding roster grouped by
// distance BANDS from the business's own ZIP. Bands and the
// categories inside them only: no creator names, no counts per
// band, no exact distance, no pin. Without a ZIP on file the
// section is the prompt to add one (profile PATCH, same record
// the business profile edits).
function foundingNearYouHtml(data, bizPlace) {
  if (!data) return "";
  const prox = data.proximity || { hasZip: false, bands: [] };
  if (!prox.hasZip) {
    return `<section class="wcard">
    <p class="ui-kicker">Preview &middot; near your door</p>
    <h3>Creators close to your door</h3>
    <p class="wc-sub">Add your business ZIP and this preview groups the founding roster by how close creators are to you: same neighborhood, under 2 miles, under 5 miles. Bands only. You never see a creator's exact location, and they never see yours.</p>
    <div class="field" style="max-width:260px"><label>Your business ZIP</label><input id="fbz-zip" inputmode="numeric" maxlength="5" placeholder="For example: 23452"></div>
    <button class="btn small-btn" onclick="foundingSaveZip()">Save ZIP</button> <span id="fbz-zip-note" class="small muted"></span>
  </section>`;
  }
  const bands = Array.isArray(prox.bands) ? prox.bands : [];
  return `<section class="wcard">
    <p class="ui-kicker">Preview &middot; near your door</p>
    <h3>Creators close to your door</h3>
    <p class="wc-sub">Grouped by distance from your business ZIP. Bands only: no exact distances, no pins, and a creator can opt out of near-you grouping without leaving the roster.</p>
    ${bands.length ? bands.map((b) => `<div style="margin-top:12px"><p style="margin:0"><span class="badge info">${esc(b.band)}</span></p>${b.categories && b.categories.length ? `<div class="dcard-chips" style="margin-top:8px">${b.categories.map((x) => `<span class="cc-chip">${esc(x)}</span>`).join("")}</div>` : ""}</div>`).join("") : `<p class="small muted" style="margin:10px 0 0">No finished creators fall inside the near bands yet. The full roster opens at activation, and recruiting continues across every category.</p>`}
  </section>`;
}

async function foundingSaveZip() {
  const el = document.getElementById("fbz-zip");
  const note = document.getElementById("fbz-zip-note");
  const zip = el ? el.value.trim() : "";
  if (!/^\d{5}$/.test(zip)) { if (note) note.textContent = "Enter the 5 digit ZIP for your business address."; return; }
  try {
    const data = await api("PATCH", "/me/profile", { zip });
    if (data && data.user) state.user = data.user;
    renderBusinessFoundingStatus();
  } catch (e) {
    if (note) note.textContent = (e && e.message) || "That ZIP did not save. Try again.";
  }
}

// Menu of Moments (Build -32): the moment list the server
// ships in the bootstrap, with a local fallback copy so the
// founding page never depends on one payload field. Each moment
// names the play the First Month Plan frames itself as.
const MOMENTS_CLIENT = [
  { id: "slow_weeknight", label: "A slow weeknight", play: "The Slow Tuesday Fix" },
  { id: "new_menu_drop", label: "A new menu or launch drop", play: "The First Taste" },
  { id: "reopening", label: "A reopening", play: "The Grand Reopening" },
  { id: "game_day", label: "Game day", play: "The Game Day Play" },
  { id: "tourist_weekend", label: "A tourist weekend", play: "The Tourist Weekend" },
  { id: "other", label: "Something else", play: "The First Month Play" },
];
function momentsClient() {
  const boot = (state.boot && state.boot.moments) || [];
  return boot.length ? boot : MOMENTS_CLIENT;
}
function momentOf(id) {
  return momentsClient().find((m) => m.id === id) || null;
}
async function foundingSetMoment(id) {
  try {
    const data = await api("PATCH", "/me/profile", { moment: id || null });
    if (data && data.user) state.user = data.user;
    renderBusinessFoundingStatus();
  } catch (e) { /* the picker simply stays as it was */ }
}

// Your first month, planned (Build -31): the first-offer
// preview extended into a one-month plan. Five visit slots on a
// Week 1 to Week 4 grid, labeled by creator category and visit
// type only: no creator names, no counts, no calendar dates.
// The whole panel is a plan preview and says so, with the Visit
// Guarantee line attached.
// Neighborhood Anchor (Build -32): the badge renders from the
// roster-preview payload (viewerAnchor), which the server stamps
// on the first founding business in a category + neighborhood.
// The copy states the one thing it must never hide: the badge
// blocks nobody and changes nobody else's terms.
function foundingAnchorHtml(data) {
  const a = data && data.viewerAnchor;
  if (!a || !a.label) return "";
  return `<section class="wcard">
    <p class="ui-kicker">Founding Anchor</p>
    <p style="margin:6px 0 0"><span class="badge info">${esc(a.label)}</span></p>
    <p class="wc-sub" style="margin-top:10px">Your business was the first founding business in its category and neighborhood, so the badge is yours and it is permanent. It never blocks anyone: every business joins on the same terms, and the badge changes nothing about anyone else's spot.</p>
  </section>`;
}

// Your Last Ad, Graded (Build -32): the owner enters their last
// promo and Sig hands back their own receipt, restated, plus the
// honest arithmetic of the same dollars at founding rates. The
// panel prices what the money buys: visits, the guarantee, the
// tracking. It never projects an outcome and never quotes a
// SIGNL statistic, because there is nothing honest to project
// from yet.
function foundingLastAdHtml() {
  return `<section class="wcard">
    <p class="ui-kicker">Your last ad, graded</p>
    <h3>What did your last ad actually buy?</h3>
    <p class="wc-sub">Tell Sig about the last promo you paid for. You get your own receipt back, restated plainly, and the same dollars priced at founding rates.</p>
    <div class="form-2col" style="margin-top:12px">
      <div class="field"><label>What was it?</label><select id="la-type">
        <option>An influencer post</option>
        <option>A boosted social post</option>
        <option>Radio</option>
        <option>Print or a magazine ad</option>
        <option>A coupon mailer</option>
        <option>A discount deal site</option>
        <option>Something else</option>
      </select></div>
      <div class="field"><label>What did it cost? ($)</label><input id="la-cost" type="number" min="1" placeholder="For example: 400"></div>
    </div>
    <div class="field"><label>What can you point to from it?</label><select id="la-point">
      <option>Nothing I can point to</option>
      <option>A busy spell, maybe</option>
      <option>Some new regulars</option>
      <option>Sales I can track</option>
    </select></div>
    <button class="btn small-btn" type="button" onclick="gradeLastAd()">Grade it</button>
    <div id="la-result" style="margin-top:12px"></div>
  </section>`;
}

function gradeLastAd() {
  const out = document.getElementById("la-result");
  if (!out) return;
  const type = (document.getElementById("la-type") || {}).value || "Something else";
  const point = (document.getElementById("la-point") || {}).value || "Nothing I can point to";
  const cost = Math.round(Number((document.getElementById("la-cost") || {}).value) || 0);
  if (!(cost > 0)) { out.innerHTML = `<p class="small muted">Enter what it cost and Sig will grade it.</p>`; return; }
  const plan = (state.boot.plans || []).find((x) => x.id === "self-service") || { priceMonthly: 199, visitsPerMonth: 5, firstMonthPriceMonthly: 99 };
  const verdicts = {
    "Nothing I can point to": "Grade: unproven. Not because the ad was bad, because nothing about it could be counted.",
    "A busy spell, maybe": "Grade: a feeling. Busy is good, but a feeling is not a number you can renew on.",
    "Some new regulars": "Grade: promising, still uncounted. Regulars are the prize. The open questions are how many, and whether they came back.",
    "Sales I can track": "Grade: counted. That puts you ahead of most local ads. SIGNL counts it per creator, per visit, automatically.",
  };
  const months = Math.floor(cost / plan.priceMonthly);
  const sameDollars = months >= 1
    ? `The same $${fmtMoney(cost)} covers ${months} month${months === 1 ? "" : "s"} of the founding ${plan.name || "Self-Service"} plan: ${months * plan.visitsPerMonth} creator visits, and your first month is $${plan.firstMonthPriceMonthly} with the founding credit.`
    : `The founding ${plan.name || "Self-Service"} plan is $${plan.priceMonthly} a month for ${plan.visitsPerMonth} creator visits, and the first month is $${plan.firstMonthPriceMonthly} with the founding credit. Your $${fmtMoney(cost)} is most of a first month of tracked visits.`;
  out.innerHTML = `<div class="panel" style="margin:0">
    <p style="margin:0"><strong>Your last ad, restated:</strong> $${fmtMoney(cost)} on ${esc(type.toLowerCase())}. What you can point to from it: ${esc(point.toLowerCase())}.</p>
    <p style="margin:8px 0 0"><strong>${esc(verdicts[point] || verdicts["Nothing I can point to"])}</strong></p>
    <p style="margin:8px 0 0">${esc(sameDollars)}</p>
    <p class="small muted" style="margin:8px 0 0">What the money buys on SIGNL: creator visits from your market's roster, the Visit Guarantee on every visit (a creator who does not post does not burn the visit), and a receipt for every visit: a check-in, a verified post, and code redemptions counted at your register. This is what the money buys, priced. It is not a projection of results, and SIGNL does not quote its own stats at you.</p>
    <p style="margin:10px 0 0"><strong>Your founding plan is priced below, and your spot is held in application order.</strong></p>
  </div>`;
}

function foundingFirstMonthHtml(u, data) {
  const bz = u.business || {};
  const moment = momentOf(bz.moment);
  const playName = moment ? moment.play : null;
  const covered = data && Array.isArray(data.categories) && data.categories.length ? data.categories : [];
  const all = (state.boot && state.boot.creatorCategories) || [];
  const planCats = covered.length ? covered : all;
  if (!planCats.length) return "";
  const slots = [
    { week: "Week 1", cat: planCats[0], type: "Comped visit" },
    { week: "Week 1", cat: planCats[1 % planCats.length], type: "Comped visit" },
    { week: "Week 2", cat: planCats[2 % planCats.length], type: "Paid booking" },
    { week: "Week 3", cat: planCats[3 % planCats.length], type: "Comped visit" },
    { week: "Week 4", cat: planCats[4 % planCats.length], type: "Paid booking" },
  ];
  const weeks = ["Week 1", "Week 2", "Week 3", "Week 4"];
  return `<section class="wcard">
    <p class="ui-kicker">Plan preview &middot; ${playName ? esc(playName) : "your first month"}</p>
    <h3>${playName ? `Your first month: ${esc(playName)}` : "Your first month, planned"}</h3>
    <p class="wc-sub">Five visits across your first month on your founding plan, spread over the categories lining up in ${esc(u.market === unlistedLabel() ? (u.city || "your city") : marketTalkNameClient(u.market))}. Paid slots book at each creator's listed rate, and the creator keeps 97%.${moment ? ` The moment you picked: ${esc(moment.label.toLowerCase())}. The plan runs it as ${esc(playName)}.` : ""}</p>
    <div class="fm-grid">
      ${weeks.map((w) => `<div class="fm-week"><div class="fm-week-h">${w}</div>${slots.filter((s) => s.week === w).map((s) => `<div class="fm-slot"><div class="fm-slot-cat">${esc(s.cat)}</div><div class="fm-slot-type">${esc(s.type)}</div></div>`).join("")}</div>`).join("")}
    </div>
    <p class="small muted" style="margin:12px 0 0">Your first month, planned. Nothing is saved, nothing is booked.</p>
    <p class="small" style="margin:6px 0 0"><strong>Visit Guarantee:</strong> if a booked creator does not show up or does not post, that visit does not count against your plan and is replaced.</p>
    <div class="field" style="margin-top:14px"><label>What is this first month about?</label>
      <div class="chip-row">${momentsClient().map((m) => `<button type="button" class="chip ${bz.moment === m.id ? "on" : ""}" onclick="foundingSetMoment('${m.id}')">${esc(m.label)}</button>`).join("")}</div>
      <p class="small muted" style="margin-top:6px">Pick the moment and the plan names its play. Change it any time; it is packaging for the same five visits, never a different product.</p>
    </div>
  </section>`;
}

// Category presence, never counts: tiles name the kinds of
// creators a business will book in this market. When the market
// already has finished creators, the tiles are the categories
// they cover; when it has none yet, the full category set rides
// as what is being recruited, stated as recruiting, which is
// true either way the roster stands.
function foundingCategoriesHtml(data, bizPlace) {
  if (!data) {
    return `<section class="wcard">
    <p class="ui-kicker">Preview &middot; who you will book</p>
    <h3>The creators being lined up in ${esc(bizPlace)}</h3>
    <p class="wc-sub">We could not load your preview just now. Your founding spot is unaffected; sign back in to see it.</p>
  </section>`;
  }
  const present = Array.isArray(data.categories) ? data.categories : [];
  const all = (state.boot && state.boot.creatorCategories) || [];
  const recruiting = !present.length;
  const tiles = recruiting ? all : present;
  return `<section class="wcard">
    <p class="ui-kicker">Preview &middot; who you will book</p>
    <h3>${recruiting ? `Creators are being recruited in ${esc(bizPlace)} now` : `The creators already lining up in ${esc(bizPlace)}`}</h3>
    <p class="wc-sub">${recruiting
      ? `Founding creators across every category below are being recruited in ${esc(bizPlace)} right now, and each one is ranked by local reach, not follower count.`
      : `Finished founding creators in ${esc(bizPlace)} already cover the ground below, and recruiting continues across every category. Each creator is ranked by local reach, not follower count.`}</p>
    ${tiles.length ? `<div class="dcard-chips" style="margin-top:10px">${tiles.map((x) => `<span class="cc-chip">${esc(x)}</span>`).join("")}</div>` : ""}
    ${recruiting ? `<p class="small muted" style="margin:10px 0 0">Categories recruiting now in ${esc(bizPlace)}.</p>` : ""}
    <p style="margin:12px 0 0"><strong>Founding businesses get first access to the roster when ${esc(bizPlace)} activates.</strong> Your spot is held in application order, ahead of every business that joins after you.</p>
  </section>`;
}

// The local-reach explainer: how the ranking actually works,
// taught with ONE illustrative comparison. The example is
// labeled an example in the copy itself, uses no real creator,
// no handle, and no roster figure, so it can never be mistaken
// for market data.
function foundingLocalReachHtml() {
  return `<section class="wcard">
    <p class="ui-kicker">How ranking works</p>
    <h3>Ranked by local reach, not followers</h3>
    <p class="wc-sub">Every creator on SIGNL is ranked by the share of their audience that actually lives in your market, ranked over follower count. What matters is how many of a creator's people are your neighbors, not how big the account is.</p>
    <div class="panel" style="margin-top:12px">
      <p style="margin:0"><span class="badge info">Example</span></p>
      <p style="margin:8px 0 0">Example: a 2,000-follower creator whose audience is 90% local outranks a 50,000-follower account at 12% local, because the smaller creator's crowd is the one that can walk through your door.</p>
    </div>
  </section>`;
}

// The Sig-drafted first offer: the category's recommended play
// (SIG_PLAY_BY_CATEGORY, the same recommendation B1 makes), with
// the brief drafted through briefFromParts exactly as B1 drafts
// it after its questions. The one input a preview cannot know is
// what the business comps, so the hook carries the play's
// placeholder for it and the card says so.
function foundingFirstOfferHtml(u) {
  const bz = u.business || {};
  const bizName = bz.businessName || "your business";
  const recId = SIG_PLAY_BY_CATEGORY[bz.category || ""] || "weekend_fill";
  const play = sigPlay(recId) || sigPlay("weekend_fill");
  if (!play) return "";
  const hookFilled = playFill(play.hook, bizName, "a visit on us");
  const brief = briefFromParts({
    goal: play.goal,
    hook: hookFilled.charAt(0).toUpperCase() + hookFilled.slice(1),
    mustMention: [bizName, ...play.mustExtra].filter(Boolean),
    timing: play.timing,
    callToAction: play.cta,
  });
  const visit = (state.boot && state.boot.standardVisit) || {};
  const deliverable = `${(visit.deliverables || ["1 post or reel", "1 story that shares the post"]).join(" + ")}, within 48 hours of the visit`;
  return `<section class="wcard">
    <div style="display:flex;gap:12px;align-items:center">
      ${sigAvatarHtml("greet")}
      <div>
        <p class="ui-kicker" style="margin:0">Preview &middot; drafted by Sig</p>
        <h3 style="margin:2px 0 0">Your first offer is already drafted</h3>
      </div>
    </div>
    <p class="wc-sub" style="margin-top:10px">Sig picked the <strong>${esc(play.name)}</strong> play${bz.category && bz.category !== "Other" ? ` for a ${esc(String(bz.category).toLowerCase())} business` : " for your business"}. A play is a ready-made offer pattern: the goal, the brief and the timing are preset, and you can edit every word. ${esc(play.mix)} You never start from a blank screen here.</p>
    <div class="panel" style="margin-top:12px">
      <div class="ui-row"><span class="k">Play</span><span class="v">${esc(play.name)}</span></div>
      <div class="ui-row"><span class="k">Spots</span><span class="v">${play.spots} creators, picked by you</span></div>
      <div class="ui-row"><span class="k">Visit window</span><span class="v">${play.windowDays} days</span></div>
      <div class="ui-row"><span class="k">Lane</span><span class="v">Open offer. Creators apply, you pick. Comped, or paid at a creator's listed rate.</span></div>
    </div>
    ${briefBlockHtml({ brief: { ...brief, deliverable } })}
    <p class="small muted" style="margin:10px 0 0">This is a preview of a draft. Nothing is saved, nothing is sent, and no creator has been contacted. At activation, Sig rebuilds this as a real draft in your account, with what you comp filled in, and you approve it before anything goes out. Sig confirms with you before anything posts, always.</p>
  </section>`;
}

// The benefit layer: each line states a mechanic the product
// actually has, in the order a business feels them (see the
// roster, book, get proof, see results, run it again, keep the
// content). No numbers are promised anywhere in it.
function foundingBenefitsHtml(u) {
  const bizName = (u.business && u.business.businessName) || "your business";
  const items = [
    ["Ranked by local reach", "Every creator is ranked by the share of their audience that actually lives here, ranked over follower count. A smaller creator whose crowd is your neighbors beats a big account whose crowd is somewhere else."],
    ["Booked in two taps, both lanes", "Comp a creator a meal, a service, or an experience, or book them paid at their own listed rate. On paid bookings, SIGNL holds the payment until the post is live, and the creator keeps 97%."],
    ["Proof at your register", "Every visit carries a redemption code your staff scans or keys in at the register. Your point of sale is never touched. Each redemption is a sale your staff rang up, and your dashboard adds up exactly those counted dollars."],
    ["Results on day 7, 14, and 30", "Reach, engagement, and redemptions land on one page on a set rhythm after every visit, so you can see what a visit did instead of guessing."],
    ["The Visit Guarantee", "If a creator no-shows or never posts, the visit does not count against your plan and is replaced. No-shows are tracked with strikes."],
    ["One tap to run it again", "When a visit works, one tap clones it, brief and content packet attached, into a fresh offer. No starting over, no re-briefing."],
    ["A content packet from every visit", "Finished visits assemble into a packet of the post and its license terms, ready to reuse. A comped post is yours to share inside Instagram, with the creator tagged. A paid booking includes one standard license: 90 days of repost and paid ad use."],
  ];
  return `<section class="wcard">
    <p class="ui-kicker">Why businesses join</p>
    <h3>What SIGNL does for ${esc(bizName)}</h3>
    ${items.map(([lead, text]) => `<p style="margin:10px 0 0"><strong>${esc(lead)}.</strong> ${esc(text)}</p>`).join("")}
  </section>`;
}

// Founding pricing, from bootstrap plans only: the same plan
// objects the join form and the rest of the app price from,
// with the business's own pick marked. No charge language: the
// section states plainly that nothing is due now and that
// businesses activate at market launch.
function foundingPlansHtml(u) {
  const plans = (state.boot && state.boot.plans) || [];
  if (!plans.length) return "";
  const chosen = (u.business && u.business.plan) || "";
  return `<section class="wcard">
    <p class="ui-kicker">Founding pricing</p>
    <h3>Locked founding rates</h3>
    <p class="wc-sub">Nothing is due now. Businesses activate at market launch, founding rates are held while a plan stays active, and unused visits roll into the next month, then expire. 3 month minimum. No per-location charge.</p>
    <p style="margin:10px 0 0"><strong>The founding business class is limited in every market. Founding businesses get first access when their market activates.</strong></p>
    <div class="rp-plans">${plans.map((p) => `<div class="rp-plan${p.id === chosen ? " on" : ""}">
      <div class="rp-plan-name">${esc(p.name)}${p.id === chosen ? ` <span class="badge ok">Your pick</span>` : ""}</div>
      <div class="rp-plan-price">$${fmtPrice(p.priceMonthly)}<span class="muted"> / month</span></div>
      <div class="small">${p.visitsPerMonth} creators a month</div>
      <div style="margin-top:8px">${foundingBadgeHtml(p)}</div>
    </div>`).join("")}</div>
  </section>`;
}

// Instant payoff at claim (Build -61, Jeff, 2026-10-31): the
// claim success screen hands the creator the thing they now
// hold: a live booking page. The URL sits big and copyable, the
// bio line and the one next-step sentence are plain, and one
// optional control sets a paid rate through the existing
// PATCH /me/profile write path. The claim form itself gains no
// fields; nothing here is required.
function claimPayoffHtml(u) {
  const url = publicProfileUrl(u);
  if (!url) return "";
  const c = u.creator || {};
  const isUnl = u.market === unlistedLabel();
  const place = isUnl ? esc(u.city || "") : esc(marketTalkNameClient(u.market));
  const rateSet = typeof c.paidRate === "number" && c.paidRate > 0;
  const curSym = currencySymbolForMarket(u.market);
  const curFloor = paidFloorForMarketClient(u.market);
  return `
    <div class="tint-block" style="text-align:left;margin-top:16px">
      <p style="margin:0"><strong>${T("Your booking page is live.", "Tu página de reservas ya está activa.")}</strong></p>
      <div style="display:flex;gap:8px;margin-top:8px;align-items:center">
        <code style="flex:1;overflow-x:auto;white-space:nowrap;padding:8px;background:#fff;border:1px solid #dfe7df;border-radius:8px">${esc(url)}</code>
        <button class="btn small-btn" onclick="return copyClaimPage()">${T("Copy", "Copiar")}</button>
      </div>
      <p class="small" id="claim-copy-ok" style="margin:6px 0 0"></p>
      <p class="small" style="margin:8px 0 0">${T("Put it in your bio. Anyone who taps it sees your page and your rate card.", "Ponlo en tu bio. Quien lo toque ve tu página y tus tarifas.")}</p>
      <p class="small muted" style="margin:6px 0 0">${isUnl
        ? T(`When SIGNL opens in ${place}, founding creators get the first look at offers.`, `Cuando SIGNL abra en ${place}, los creadores fundadores ven las ofertas primero.`)
        : T(`When ${place} businesses start booking, founding creators get the first look at offers.`, `Cuando los negocios de ${place} empiecen a reservar, los creadores fundadores ven las ofertas primero.`)}</p>
      ${rateSet
        ? `<p class="small" style="margin:10px 0 0">${T(`Your paid rate is ${curSym}${fmtPrice(c.paidRate)}, and it is on your page. Change it any time on your profile.`, `Tu tarifa pagada es ${curSym}${fmtPrice(c.paidRate)}, y ya está en tu página. Cámbiala cuando quieras en tu perfil.`)}</p>`
        : `<div style="margin-top:12px">
            <p class="small" style="margin:0"><strong>${T("Set your paid rate (optional, 20 seconds)", "Pon tu tarifa pagada (opcional, 20 segundos)")}</strong></p>
            <p class="small muted" style="margin:4px 0 0">${T(`It shows on your page. Businesses book at your rate, you keep 97%, and payment is held until your post is live. Minimum ${curSym}${curFloor}. Comped visits work without it.`, `Aparece en tu página. Los negocios reservan a tu tarifa, te quedas con el 97%, y el pago se retiene hasta que tu publicación esté en vivo. Mínimo ${curSym}${curFloor}. Las visitas de cortesía funcionan sin esto.`)}</p>
            <div style="display:flex;gap:8px;margin-top:8px;align-items:center">
              <span>${curSym}</span><input id="claim-rate" type="number" min="${curFloor}" step="1" inputmode="numeric" placeholder="150" style="width:110px">
              <button class="btn small-btn" onclick="return saveClaimRate()">${T("Put it on my page", "Ponla en mi página")}</button>
            </div>
            <p class="small" id="claim-rate-msg" style="margin:6px 0 0"></p>
          </div>`}
    </div>`;
}

async function copyClaimPage() {
  const el = document.getElementById("claim-copy-ok");
  try {
    await navigator.clipboard.writeText(publicProfileUrl(state.user));
    if (el) el.textContent = T("Copied.", "Copiado.");
  } catch (e) {
    if (el) el.textContent = T("Copy the link from the box above.", "Copia el enlace del cuadro de arriba.");
  }
  return false;
}

async function saveClaimRate() {
  const input = document.getElementById("claim-rate");
  const msg = document.getElementById("claim-rate-msg");
  const rate = Math.round(Number(input && input.value));
  const floor = ownPaidFloor(); const sym = ownCurrencySymbol();
  if (!Number.isFinite(rate) || rate < floor) { if (msg) msg.textContent = T(`Rates start at ${sym}${floor}.`, `Las tarifas empiezan en ${sym}${floor}.`); return false; }
  try {
    const data = await api("PATCH", "/me/profile", { paidRate: rate });
    if (data && data.user) state.user = data.user;
    else if (state.user && state.user.creator) state.user.creator.paidRate = rate;
    render();
  } catch (e) {
    if (msg) msg.textContent = (e && e.message) || T("That did not save. You can set it later on your profile.", "No se guardó. Puedes ponerla luego en tu perfil.");
  }
  return false;
}

function renderPending() {
  const u = state.user;
  if (u.role === "business") return renderBusinessFoundingStatus();
  const f = u.founding || {};
  const isCreator = u.role === "creator";
  const isUnlisted = isCreator && u.market === unlistedLabel();
  const place = isUnlisted ? esc(unlistedPlace(u)) : esc(marketTalkNameClient(u.market));
  // Two-step claim (Jeff, 2026-10-20): a quick claim is a claimed
  // spot, not a built profile, and the screen says so plainly.
  const claimedOnly = isCreator && u.creator && u.creator.signupPath === "quick_claim" && u.creator.profileComplete === false;
  // The one celebration (animated Sig, 2026-10-28): the render
  // right after a successful quick claim gets Sig celebrating
  // at the head of this confirmation, once. The flag is set only
  // by doQuickClaim and cleared here, so later visits to this
  // screen render exactly as before. (A claim that lands already
  // approved never reaches this screen; the queue card on the
  // founding home consumes the same flag there instead.)
  const celebAva = state.sigCelebrate ? `<div style="display:flex;justify-content:center;margin-bottom:12px">${sigCelebMediaHtml()}</div>` : "";
  if (state.sigCelebrate) { state.sigCelebrate = false; setTimeout(sigCelebKick, 30); }
  app.innerHTML = `
  <section class="panel center" style="max-width:560px;margin:40px auto">
    ${celebAva}
    <h2>${claimedOnly ? T("Your spot is claimed", "Tu lugar está reclamado") : T("Founding profile received", "Perfil fundador recibido")}</h2>
    ${claimedOnly
      ? `<p>${T("Thanks,", "Gracias,")} ${esc(u.name)}. ${T("Your founding spot in", "Tu lugar de fundador en")} <strong>${place}</strong> ${T("is claimed and your application is in the review queue. Every founding application gets a decision or a clear status within 2 business days.", "está reclamado y tu solicitud está en la fila de revisión. Cada solicitud fundadora recibe una decisión o un estado claro en 2 días laborables.")}</p>
    <p class="muted" style="text-align:left">${T("Your profile is not finished yet, and that is by design: when you are approved, we email you, and you finish your profile from the checklist on your dashboard (your home city, your audience counts, what share of it is local, your photo). A finished profile is what businesses see, so that step is what makes you bookable.", "Tu perfil aún no está terminado, y es así a propósito: cuando te aprobemos, te escribimos por correo, y terminas tu perfil desde la lista de tu panel (tu ciudad, tus conteos de audiencia, qué parte es local, tu foto). Un perfil terminado es lo que ven los negocios, así que ese paso es lo que te hace contratable.")}</p>`
      : `<p>${T("Thanks,", "Gracias,")} ${esc(u.name)}. ${T("Your founding creator profile for", "Tu perfil de creador fundador para")} <strong>${place}</strong> ${T("is built and in the review queue. Every founding application gets a decision or a clear status within 2 business days.", "está creado y en la fila de revisión. Cada solicitud fundadora recibe una decisión o un estado claro en 2 días laborables.")}</p>`}
    ${isCreator && u.underMinimum ? `<div class="notice blue" style="text-align:left"><strong>${T("Your application is in line, and one thing is holding it:", "Tu solicitud está en la fila, y una cosa la está deteniendo:")}</strong> ${T("SIGNL starts at 500 total followers across your platforms, and your counted total right now is", "SIGNL empieza con 500 seguidores en total, sumando todas tus plataformas, y tu total contado ahora mismo es")} ${esc(fmtNum(u.underMinimum.total || 0))}. ${T("Nothing else is wrong, and your spot in line is kept. When your audience reaches 500 total, email hello@joinsignl.com and we will move your application forward from the same spot.", "Nada más está mal, y tu lugar en la fila se mantiene. Cuando tu audiencia llegue a 500 en total, escribe a hello@joinsignl.com y moveremos tu solicitud desde el mismo lugar.")}</div>` : ""}
    ${isCreator ? `<p><strong>${T(CREATOR_FREE_LINE, "Unirte a SIGNL es gratis para los creadores. Siempre.")}</strong></p>` : ""}
    ${isCreator && !u.underMinimum ? `<p class="small">${T("One founding standard: SIGNL starts at 500 total followers across your platforms.", "Un estándar fundador: SIGNL empieza con 500 seguidores en total, sumando todas tus plataformas.")}</p>` : ""}
    ${isCreator ? marketResolvedNote(u) : ""}
    ${isCreator && isUnlisted && Array.isArray(u.marketCandidates) && u.marketCandidates.length ? `
    <div style="text-align:left;margin-top:16px">
      <p class="small" style="margin:0"><strong>${T("One quick thing:", "Una cosa rápida:")}</strong> ${esc(typedCityDisplay(u))} ${T("is in more than one SIGNL market. Which one is yours?", "está en más de un mercado de SIGNL. ¿Cuál es el tuyo?")}</p>
      <div style="margin-top:8px">${u.marketCandidates.map((m) => `<button class="btn small-btn" style="margin:0 8px 8px 0" onclick="return pickCandidateMarket(event, '${esc(m)}')">${esc(marketDisplayName(m))}</button>`).join("")}</div>
      <p class="small muted" style="margin:0">${T("Your typed city stays as your home city either way.", "Tu ciudad escrita se queda como tu ciudad de todos modos.")}</p>
    </div>` : ""}
    ${claimedOnly ? claimPayoffHtml(u) : ""}
    ${isCreator && f.queueBand ? `<p><span class="badge info">${isUnlisted ? `You are in the first ${f.queueBand} to sign up in ${esc(u.city)}` : `You are in the first ${f.queueBand} to sign up in ${esc(marketTalkNameClient(u.market))}`}</span></p><p class="small muted">Applications are reviewed in sign-up order. Founding status starts at approval, not at sign-up.</p>` : ""}
    <p class="muted">${isUnlisted
      ? `${T("SIGNL is not open in", "SIGNL aún no abrió en")} ${esc(u.city)} ${T("yet, and your sign-up counts toward opening it: we open new markets where creator sign-ups pile up, and founding sign-ups there go first. Every application is reviewed by a person. The moment you are approved, your founding status page opens here, and we will email you at", "y tu registro cuenta para abrirlo: abrimos mercados nuevos donde se juntan registros de creadores, y los registros fundadores de ahí van primero. Cada solicitud la revisa una persona. En cuanto te aprobemos, tu página de estado fundador se abre aquí, y te escribimos a")} ${esc(u.email)} ${T("the moment", "en cuanto")} ${esc(u.city)} ${T("opens. Sign back in any time to check your status.", "abra. Entra cuando quieras para ver tu estado.")}${state.boot && state.boot.email && state.boot.email.enabled ? ` ${T("A confirmation email is on its way to", "Un correo de confirmación va en camino a")} ${esc(u.email)}.` : ""}`
      : `${T("Every application is reviewed by a person. The moment you are approved, your founding status page opens here, and we will email you at", "Cada solicitud la revisa una persona. En cuanto te aprobemos, tu página de estado fundador se abre aquí, y te escribimos a")} ${esc(u.email)} ${T("when", "cuando")} ${esc(marketTalkNameClient(u.market))} ${T("opens to businesses. Sign back in any time to check your status.", "abra para los negocios. Entra cuando quieras para ver tu estado.")}${state.boot && state.boot.email && state.boot.email.enabled ? ` ${T("A confirmation email is on its way to", "Un correo de confirmación va en camino a")} ${esc(u.email)}.` : ""}`}</p>
    ${isCreator && !(u.creator && u.creator.hasPhoto) ? `
    <div style="text-align:left">
      <div class="field"><label>${T("Add your profile photo now (optional)", "Agrega tu foto de perfil ahora (opcional)")}</label><input type="file" id="pending-photo" accept="image/png,image/jpeg,image/webp"></div>
      <button class="btn small-btn" onclick="return uploadPendingPhoto(event)">${T("Upload photo", "Subir foto")}</button> <span id="pending-photo-ok" class="saved"></span>
    </div>` : ""}
    ${isCreator ? `
    <div style="text-align:left;margin-top:16px">
      <p class="small" style="margin:0"><a href="#" onclick="return togglePendingMarket(event)"><strong>Wrong market?</strong></a> <span class="muted">If ${place} is not where your audience is, move your application now, while it is still in review. Once a decision lands, your market is set.</span></p>
      <div id="pm-wrap" style="display:none;margin-top:10px">
        <div id="pm-error"></div>
        <div class="field"><label>Your market</label><input id="pm-market-search" placeholder="Search markets, for example: Raleigh" oninput="filterPendingMarketOptions()" style="margin-bottom:6px"><select id="pm-market" onchange="syncPendingMarketChoice()">${marketOptions(u.market === unlistedLabel() ? "" : u.market, true)}</select></div>
        <div class="field" id="pm-city-wrap"><label>Your home city</label><select id="pm-city">${cityOptions(u.market, u.city || "")}</select></div>
        <div id="pm-custom-wrap" style="display:none">
          <div class="field"><label>Your city</label><input id="pm-city-text" value="${esc(u.city || "")}" placeholder="For example: Tulsa"></div>
          <div class="field"><label>Your country</label><input id="pm-country-text" value="${esc(u.country || "")}" placeholder="For example: United States"></div>
          <div class="field"><label>Your state or province (optional)</label><input id="pm-state-text" value="${esc(u.state || "")}" placeholder="Optional, for example: OK"></div>
          <p class="small muted">${T("Not open there yet — your sign-up counts toward opening it. Founding sign-ups go first.", "Todavía no abrimos ahí. Tu registro cuenta para abrirlo. Los registros fundadores van primero.")}</p>
        </div>
        <button class="btn small-btn" onclick="return savePendingMarket(event)">Move my application</button>
        <p class="small muted" style="margin-top:8px">Your sign-up time moves with you, so your place in line is kept.</p>
      </div>
    </div>` : ""}
    ${isCreator ? growRosterHtml(u) : ""}
    <div class="mt"><button class="btn ghost" onclick="signOut()">Sign out</button></div>
  </section>`;
  if (isCreator) initPendingMarket();
}

async function uploadPendingPhoto(e) {
  e.preventDefault();
  const ok = await uploadPhotoInput("pending-photo");
  const el = document.getElementById("pending-photo-ok");
  if (el) el.textContent = ok ? "Photo added to your profile." : "That photo did not upload. You can add it later from your profile.";
  if (ok && state.user && state.user.creator) state.user.creator.hasPhoto = true;
  return false;
}

// Wrong-market rescue (audit F2): while the application is in
// review, the market can still be fixed from the pending screen.
// The form mirrors signup (canonical market + a city inside it, or
// the typed not-listed path); the server accepts the change only
// while the application is pending, and stamps it on the record.
function togglePendingMarket(e) {
  if (e) e.preventDefault();
  const wrap = document.getElementById("pm-wrap");
  if (wrap) wrap.style.display = wrap.style.display === "none" ? "" : "none";
  return false;
}

function initPendingMarket() {
  const sel = document.getElementById("pm-market");
  if (!sel || !state.user) return;
  if (state.user.market === unlistedLabel()) sel.value = unlistedLabel();
  syncPendingMarketChoice();
}

function filterPendingMarketOptions() {
  const input = document.getElementById("pm-market-search");
  const sel = document.getElementById("pm-market");
  if (!input || !sel) return;
  const q = input.value.trim().toLowerCase();
  let firstMatch = null;
  for (const opt of sel.querySelectorAll("option")) {
    if (opt.value === unlistedLabel()) continue;
    const hit = !q || opt.textContent.toLowerCase().includes(q) || opt.value.toLowerCase().includes(q);
    opt.hidden = !hit;
    if (hit && !firstMatch) firstMatch = opt;
  }
  for (const grp of sel.querySelectorAll("optgroup")) {
    grp.hidden = ![...grp.querySelectorAll("option")].some((o) => !o.hidden);
  }
  const current = sel.selectedOptions && sel.selectedOptions[0];
  if (q && firstMatch && current && current.hidden) {
    sel.value = firstMatch.value;
    syncPendingMarketChoice();
  }
}

function syncPendingMarketChoice() {
  const m = document.getElementById("pm-market");
  if (!m) return;
  const unlisted = m.value === unlistedLabel();
  const customWrap = document.getElementById("pm-custom-wrap");
  const cityWrap = document.getElementById("pm-city-wrap");
  if (customWrap) customWrap.style.display = unlisted ? "" : "none";
  if (cityWrap) cityWrap.style.display = unlisted ? "none" : "";
  if (!unlisted) {
    const citySel = document.getElementById("pm-city");
    if (citySel) citySel.innerHTML = cityOptions(m.value, citySel.value);
  }
}

async function savePendingMarket(e) {
  if (e) e.preventDefault();
  const errBox = (msg) => {
    const el = document.getElementById("pm-error");
    if (el) el.innerHTML = `<div class="error-box">${esc(msg)}</div>`;
  };
  const marketVal = document.getElementById("pm-market").value;
  const isUnlisted = marketVal === unlistedLabel();
  const body = { market: marketVal };
  if (isUnlisted) {
    body.customCity = document.getElementById("pm-city-text").value.trim();
    body.customCountry = document.getElementById("pm-country-text").value.trim();
    body.customState = document.getElementById("pm-state-text").value.trim();
    if (!body.customCity) { errBox(T("Tell us your city, so your sign-up counts toward opening SIGNL there.", "Dinos tu ciudad, para que tu registro cuente para abrir SIGNL ahí.")); return false; }
    if (!body.customCountry) { errBox(T("Tell us your country, so your sign-up counts toward opening SIGNL there.", "Dinos tu país, para que tu registro cuente para abrir SIGNL ahí.")); return false; }
  } else {
    body.city = document.getElementById("pm-city").value;
  }
  try {
    const data = await api("POST", "/me/market", body);
    state.user = data.user;
    render();
  } catch (err) {
    errBox(err.message);
  }
  return false;
}

function renderRejected() {
  app.innerHTML = `
  <section class="panel center" style="max-width:560px;margin:40px auto">
    <h2>Not a fit right now</h2>
    <p>Your application was not approved for this round. Markets open in waves, and you are welcome to apply again when your market expands.</p>
    <p class="muted">Questions: hello@joinsignl.com</p>
    <button class="btn ghost" onclick="signOut()">Sign out</button>
  </section>`;
}

// ---------------- dashboards ----------------

function renderDashboard() {
  const u = state.user;
  if (u.role === "admin" && state.preview) return renderPreview();
  if (u.role === "admin") return renderAdmin();
  if (u.role === "creator") return renderCreatorDash();
  // Build -106: a partner inside one of their pilot scopes
  // gets the Impact Portal shell, not the license shell.
  if (u.role === "partner" && state.pilotScopeId) return renderPilotDash();
  if (u.role === "partner") return renderPartnerDash();
  if (u.role === "recruiter") return renderRecruiterDash();
  if (u.role === "pilot_partner") return renderPilotDash();
  return renderBusinessDash();
}

function tabsHtml(tabs, active) {
  return `<div class="tabs">${tabs.map((t) => `<button class="${t === active ? "active" : ""}" onclick="go('dashboard','${esc(t)}')">${esc(t)}</button>`).join("")}</div>`;
}

function scoreBadge(score) {
  if (score === null || score === undefined) return `<span class="badge info">Impact score pending</span>`;
  return `<span class="badge ok">Local Impact Score ${score}</span>`;
}

// Every social link a creator provided, rendered the same way wherever
// a profile is displayed (founding page, business discovery).
function socialLinksHtml(p) {
  const links = [];
  if (p.instagramUrl) links.push(`<a href="${esc(p.instagramUrl)}" target="_blank" rel="noopener">Instagram</a>`);
  if (p.tiktokUrl) links.push(`<a href="${esc(p.tiktokUrl)}" target="_blank" rel="noopener">TikTok</a>`);
  if (p.youtubeChannel) links.push(/^https?:\/\//i.test(p.youtubeChannel) ? `<a href="${esc(p.youtubeChannel)}" target="_blank" rel="noopener">YouTube</a>` : `YouTube: ${esc(p.youtubeChannel)}`);
  if (p.facebookUrl) links.push(`<a href="${esc(p.facebookUrl)}" target="_blank" rel="noopener">Facebook</a>`);
  if (p.xUrl) links.push(`<a href="${esc(p.xUrl)}" target="_blank" rel="noopener">X</a>`);
  if (p.linkedinUrl) links.push(`<a href="${esc(p.linkedinUrl)}" target="_blank" rel="noopener">LinkedIn</a>`);
  return links.join(" &middot; ");
}

// ---------- creator showcase: photo, best work, track record, reviews ----------
// One set of renderers for every surface that shows a creator (public
// profile page, discovery card, full profile view, the creator's own
// profile, and the admin Business Preview), so what a business sees
// is identical everywhere. All data comes from the server payloads,
// which compute everything from stored records only.

function starsHtml(n) {
  const full = Math.max(0, Math.min(5, Math.round(Number(n) || 0)));
  return `<span class="stars" title="${full} out of 5 stars">${"★".repeat(full)}${"☆".repeat(5 - full)}</span>`;
}

// ---------- paid lane + review links (Jeff, 2026-10-19) ----------
// Two lanes, one roster. These renderers read only the normalized
// payload fields (profile.paidRate: number or null; profile.compOpen:
// boolean) so every surface states the creator's booking terms the
// same way: her listed rate with a "Paid bookings" marker when she
// charges, and her comp-open state either way.
// Creator standing badges (ladder v2 + SIGNL Elite, Jeff,
// 2026-10-21): the server computes them (user.badges on the public
// payload, card.badges in discovery, creator.badges in the
// applicant stack); this only renders them.
function badgesHtml(badges) {
  if (!badges || !badges.length) return "";
  return badges.map((b) => b.kind === "elite"
    ? ' <span class="badge elite">SIGNL Elite</span>'
    : ` <span class="badge tier">${esc(b.name)}</span>`).join("");
}

// The ladder block inside Grow your roster: badges earned, the
// pending unlock, the distance to the next badge, and Elite. Copy
// is plain on purpose (Jeff): badges and points, no guarantees,
// and points are priority because points set the order businesses
// see.
function ladderHtml(u) {
  const l = u && u.ladder;
  if (!l) return "";
  const earned = (l.badges || []).filter((b) => b.kind === "milestone" || b.kind === "campus");
  let out = `<p class="small" style="margin-top:10px"><strong>Referral badges:</strong> approved referrals earn badges and bonus Momentum points. 1 approved referral: Connector badge, +25 points. 3: Super Connector, +50. 5: Roster Builder, +75. 10: City Lead, +150.</p>`;
  if (earned.length) out += `<p class="small">Your badges: ${earned.map((b) => esc(b.name)).join(" &middot; ")}</p>`;
  const pending = (l.milestones || []).find((m) => m.state === "pending_unlock");
  if (pending) {
    out += `<p class="small">Your ${esc(pending.name)} badge unlocks when @${esc(pending.trippingHandle || "your referral")} delivers their first post.</p>`;
  } else if (l.next) {
    out += `<p class="small">${l.next.needed} more approved ${l.next.needed === 1 ? "referral" : "referrals"} to your next badge: ${esc(l.next.name)}.</p>`;
  }
  if (l.elite && l.elite.qualified) out += `<p class="small"><span class="badge elite">SIGNL Elite</span> You hold SIGNL Elite: 10 or more on-time posts and a 4.5+ rating from 5 or more businesses.</p>`;
  return out;
}

function paidLaneBadgesHtml(p) {
  if (!p) return "";
  let out = "";
  if (p.paidRate) out += ` <span class="badge tier">Paid bookings: ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)}</span>`;
  if (p.licensingFee) out += ` <span class="badge tier">Licenses posts: ${currencySymbolForMarket(p.market)}${fmtPrice(p.licensingFee)}</span>`;
  out += p.compOpen === false
    ? ` <span class="badge warn">Paid visits only</span>`
    : ` <span class="badge info">Open to comp visits</span>`;
  return out;
}

// The business's public review pages, as a courtesy block. The
// server sends [{key,label,url}] only when links exist, so this
// renders nothing at all for businesses without them. No points
// attach to external reviews, anywhere, ever.
function reviewLinksBlockHtml(links) {
  if (!links || !links.length) return "";
  return `<div class="showcase-block"><h4>Their review pages</h4><p class="small" style="margin:0">${links.map((l) => `<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a>`).join(" &middot; ")}</p><p class="small muted" style="margin:4px 0 0">If you want to leave them a public review too, these are their pages. Entirely your call, and never part of the deal.</p></div>`;
}

// The business's own referral program, tied in (Jeff,
// 2026-10-25). The server sends {url, code, note} only when
// the business has set a link or a code, so this renders
// nothing at all for businesses without one. Any rewards are
// the business's program under its own terms; SIGNL never
// runs or guarantees them.
// Musician openness, as creators see it (Jeff, 2026-10-28):
// the business-side mirror of the creator's musician signals.
// The payload view is null unless the business switched "Open
// to booking musicians" on, so nothing renders for anyone
// else. The pill names the openness; the line under it says
// which kinds the business switched on.
function musicOpenBlockHtml(view) {
  if (!view) return "";
  const kinds = [view.live ? "live performances" : "", view.created ? "created music" : ""].filter(Boolean);
  return `<p class="small"><span class="badge ok">Open to musicians</span>${kinds.length ? ` <span class="muted">This business is open to booking musicians for ${kinds.join(" and ")}.</span>` : ""}</p>`;
}

// Student openness, as creators see it (university layers U3,
// Jeff, 2026-10-28): the campus mirror of the musician block.
// The payload view is null unless the business switched "Open
// to student creators" on, so nothing renders for anyone else.
function studentOpenBlockHtml(view) {
  if (!view) return "";
  return `<p class="small"><span class="badge ok">Open to student creators</span></p>`;
}

function referralProgramBlockHtml(prog) {
  if (!prog || (!prog.url && !prog.code)) return "";
  return `<div class="showcase-block"><h4>This business runs its own referral program</h4>
    ${prog.note ? `<p class="small" style="margin:0 0 4px"><strong>From the business:</strong> ${esc(prog.note)}</p>` : ""}
    ${prog.url ? `<p class="small" style="margin:0">Referral link: <a href="${esc(prog.url)}" target="_blank" rel="noopener">${esc(prog.url)}</a></p>` : ""}
    ${prog.code ? `<p class="small" style="margin:0">Referral code: <strong>${esc(prog.code)}</strong></p>` : ""}
    <p class="small muted" style="margin:4px 0 0">Include the link in your caption or bio, or the code in your caption, so the business can track the bookings your post sends them. Any rewards come from the business's own program, under its terms, on top of your SIGNL comp or pay. SIGNL does not run or guarantee their program.</p></div>`;
}

// Book a paid visit at the creator's listed rate (real surface).
// Paid booking confirm sheet (UX redesign section 9): the old
// flow chained a native confirm() and a native prompt(), the same
// silent-gate pattern that killed the tester and close buttons
// (a suppressed dialog books nothing and says nothing). The sheet
// shows the full math and the honest payment state before anything
// is booked; Cancel books nothing and sends nothing.
function bookPaidVisit(creatorId) {
  const c = (state.discover || []).find((x) => x.userId === creatorId);
  const p = c && c.profile ? c.profile : {};
  const rate = p.paidRate;
  if (!rate) { alert("That creator has not listed a paid rate."); return; }
  const total = Math.round(rate * 1.03 * 100) / 100;
  const net = Math.round(rate * 0.97 * 100) / 100;
  closePaidSheet();
  const el = document.createElement("div");
  el.id = "paid-sheet";
  el.className = "sheet-overlay";
  el.innerHTML = `
  <div class="sheet" role="dialog" aria-label="Book a paid visit">
    <strong>Book a paid visit with ${esc(c ? c.name : "this creator")}</strong>
    <p class="small" style="margin:10px 0 2px">Listed rate: <strong>$${fmtPrice(rate)}</strong></p>
    <p class="small" style="margin:2px 0">You pay <strong>$${fmtMoney(total)}</strong> (rate + 3%)</p>
    <p class="small" style="margin:2px 0">They keep <strong>$${fmtMoney(net)}</strong> (97%)</p>
    <p class="small" style="margin:2px 0">Includes the standard license: repost + ad use for 90 days from the post date, never longer. The exact end date shows in Posts &amp; licenses once the post is live.</p>
    ${paymentsLive()
      ? (cardOnFileView()
        ? `<p class="small muted">Your ${esc(brandName(cardOnFileView().brand))} &middot;&middot;&middot;&middot;${esc(cardOnFileView().last4)} is charged $${fmtMoney(total)} when you book. SIGNL holds it and releases the creator's share after the post is live and the 48 hour hold passes.</p>`
        : `<p class="small muted">Paid bookings charge a card on file, held by SIGNL until the post is live. Add yours once and every paid booking confirms in one tap.</p>`)
      : `<p class="small muted">No card is charged in the app yet. This records the booking and holds the amount in the app ledger. It is released after the post is live and the 48 hour hold passes.</p>`}
    ${growthNudgeHtml()}
    <div class="field"><label>Key points for the creator (optional)</label><textarea id="paid-brief" rows="3" maxlength="500" placeholder="What to feature, names, dates"></textarea><p class="small muted">${PAID_BRIEF_GUIDANCE}</p></div>
    <button class="btn" style="width:100%" id="paid-sheet-book">${paymentsLive() && !cardOnFileView() ? "Add a card to book" : "Book paid visit"}</button>
    <button class="btn ghost" style="width:100%;margin-top:8px" id="paid-sheet-cancel">Cancel</button>
  </div>`;
  document.body.appendChild(el);
  document.getElementById("paid-sheet-cancel").onclick = () => closePaidSheet();
  el.addEventListener("click", (e) => { if (e.target === el) closePaidSheet(); });
  document.getElementById("paid-sheet-book").onclick = async () => {
    if (paymentsLive() && !cardOnFileView()) { closePaidSheet(); addBusinessCard(); return; }
    const briefEl = document.getElementById("paid-brief");
    const paidBrief = briefEl ? briefEl.value.trim().slice(0, 500) : "";
    closePaidSheet();
    try {
      const data = await api("POST", "/bookings/paid", { creatorId, ...(paidBrief ? { paidBrief } : {}) });
      state.tab = "Visits & Posts";
      render();
      showBookingCard(data.booking, "Paid visit booked", data.booking.paidLane ? data.booking.paidLane.paymentNote : "");
    } catch (err) { alert(err.message); }
  };
}

function closePaidSheet() {
  const el = document.getElementById("paid-sheet");
  if (el) el.remove();
  return false;
}

// Preview twin of the paid booking: a simulation with the real fee
// math, zero writes (the server route enforces it).
async function previewPaidBooking(creatorId) {
  try {
    const data = await api("POST", "/admin/preview/paid-booking", { creatorId });
    const bk = data.booking;
    // The result renders as a sheet in the booking-card family,
    // not a native alert: the preview is a presenter surface and
    // every other preview action answers in the app's own UI
    // (perfection pass, 2026-10-26).
    dismissBookingCard();
    const el = document.createElement("div");
    el.id = "booking-card";
    el.className = "booking-card";
    el.setAttribute("role", "dialog");
    el.setAttribute("aria-label", "Preview paid booking");
    el.innerHTML = `
    <div class="flex-between">
      <strong>Paid booking preview</strong>
      <button type="button" class="linklike" onclick="dismissBookingCard()">Dismiss</button>
    </div>
    <p class="small muted" style="margin:6px 0 0">Simulation: nothing is booked, charged or sent.</p>
    <div class="mt">
      <div class="flex-between"><span class="small">Creator rate</span><strong>$${fmtMoney(bk.rate)}</strong></div>
      <div class="flex-between"><span class="small">You pay (rate + 3%)</span><strong>$${fmtMoney(bk.businessTotal)}</strong></div>
      <div class="flex-between"><span class="small">Creator keeps (97% of their rate)</span><strong>$${fmtMoney(bk.creatorNet)}</strong></div>
      <div class="flex-between"><span class="small">SIGNL fee, split evenly</span><strong>$${fmtMoney(bk.platformFee)}</strong></div>
    </div>
    <p class="small" style="margin:10px 0 0">Held by SIGNL until the post is live.</p>
    <p class="small" style="margin:2px 0 0">Includes the standard license: repost + ad use for 90 days from the post date, never longer. The exact end date shows in Posts &amp; licenses once the post is live.</p>
    ${state.preview && state.preview.planId === "self-service" ? `<p class="small muted">Growth is built for paid work and reuse: every license and renewal tracked in one library, and priority access to the creators you license.</p>` : ""}
    ${bk.paymentNote ? `<p class="small muted">${esc(bk.paymentNote)}</p>` : ""}
    ${bk.note ? `<p class="small muted">${esc(bk.note)}</p>` : ""}`;
    document.body.appendChild(el);
  } catch (err) { alert(err.message); }
}

// Business rates the creator after a completed visit (the post
// proof is in). One rating per booking, not editable; it feeds
// the creator's star rating shown next to their Momentum points.
// Ratings never move anyone's Momentum points.
async function submitCreatorReview(e, bookingId) {
  e.preventDefault();
  const stars = document.getElementById("crev-stars-" + bookingId).value;
  const comment = document.getElementById("crev-comment-" + bookingId).value;
  try {
    await api("POST", `/bookings/${bookingId}/review`, { stars: Number(stars), comment });
    loadMyVisits("business");
  } catch (err) { alert(err.message); }
  return false;
}

// Visit close-out packet (Build -39): the comp cost at close
// (pre-filled from the business's usual cost, one tap to
// confirm), the counted-events trail with its correction
// controls, and the counter script card.
function closeoutPacketHtml(b) {
  const paid = !!(b.paidLane && typeof b.paidLane.rate === "number" && b.paidLane.rate > 0);
  let comp = "";
  if (b.status === "completed" && !paid) {
    const entry = b.compCostEntry || null;
    const dflt = compCostDefaultClient(b.category);
    const prefill = entry ? entry.amount : dflt;
    comp = `<div style="margin-top:12px;border-top:1px solid var(--hairline,#DFE7DF);padding-top:10px">
      <h4 style="margin:0 0 4px">Close out this visit: what did the comp cost you?</h4>
      <p class="small muted" style="margin:0 0 8px">${entry ? `On record: $${fmtMoney(entry.amount)} at your cost${entry.confirmedZero ? " (you confirmed it cost you nothing)" : ""}. Adjust it here while this month's books stay open.` : "One number, at your cost, not the menu price. It completes this visit's score, and it never touches the creator's side of anything."}</p>
      <div class="form-2col">
        <div class="field"><label>What the comp cost you ($)</label><input type="number" id="co-cost-${b.id}" min="0" step="0.01" placeholder="At your cost" value="${prefill !== null && prefill !== undefined ? prefill : ""}"></div>
        <div class="field"><label>&nbsp;</label><button class="btn small-btn" type="button" onclick="saveCloseoutCompCost('${b.id}')">${!entry && dflt !== null ? `Confirm $${fmtMoney(dflt)}` : "Save the cost"}</button></div>
      </div>
      <label class="ckrow small"><input type="checkbox" class="ckbox" id="co-zero-${b.id}" ${entry && entry.confirmedZero ? "checked" : ""}><span>It genuinely cost us nothing</span></label> <span class="small" id="co-note-${b.id}"></span>
    </div>`;
  }
  return `${comp}
    <details style="margin-top:12px">
      <summary class="small" onclick="loadBookingEvents('${b.id}')"><strong>Counted events for this visit</strong></summary>
      <div id="evlist-${b.id}"><p class="small muted">Loading the register trail...</p></div>
    </details>
    <div class="panel" style="margin-top:12px">
      <h4 style="margin:0 0 4px">For the counter: the one question</h4>
      <p class="small" style="margin:0">Ask it at the natural moment, ringing up or seating: <strong>"First time in? How'd you hear about us?"</strong> When a creator or a post comes up, tap "Someone mentioned the post" above. Those answers count on their own line of your receipt, separate from register money: they are how the customers nobody handed a code still get counted.</p>
    </div>`;
}
async function saveCloseoutCompCost(bookingId) {
  const amtEl = document.getElementById(`co-cost-${bookingId}`);
  const zeroEl = document.getElementById(`co-zero-${bookingId}`);
  const note = document.getElementById(`co-note-${bookingId}`);
  const body = zeroEl && zeroEl.checked ? { confirmedZero: true } : { amount: amtEl && amtEl.value !== "" ? Number(amtEl.value) : null };
  if ((!zeroEl || !zeroEl.checked) && (body.amount === null || !Number.isFinite(body.amount))) { if (note) note.textContent = "Enter the cost, or check the box if it genuinely cost you nothing."; return; }
  try { await api("POST", `/bookings/${bookingId}/comp-cost`, body); loadMyVisits("business"); }
  catch (e) { if (note) note.textContent = e.message; }
}
async function loadBookingEvents(bookingId) {
  const host = document.getElementById(`evlist-${bookingId}`);
  if (!host || host.dataset.loaded) return;
  host.dataset.loaded = "1";
  try {
    const data = await api("GET", `/bookings/${bookingId}/events`);
    const evs = data.events || [];
    if (!evs.length) { host.innerHTML = `<p class="small muted">No counted events yet for this visit. A check total logged at the counter becomes one.</p>`; return; }
    host.innerHTML = evs.map((e) => `<div class="lrow" style="margin-top:6px"><div style="flex:1"><span>${e.kind === "return" ? "Came back" : e.kind === "audience" ? "Audience code" : "First visit"} · $${fmtMoney(e.amount)}${e.voided ? ` · <strong>voided</strong>` : ""}</span><div class="small muted">${fmtDate(e.at)}${e.channel ? ` · ${e.channel === "in_store" ? "in store" : e.channel}` : ""}${(e.corrections || []).length ? ` · corrected ${e.corrections.length} time${e.corrections.length === 1 ? "" : "s"}, trail on the event` : ""}</div></div>
      ${e.correctable ? `<span><input type="number" id="ev-amt-${e.id}" min="0" step="0.01" style="width:90px" value="${e.voided ? "" : e.amount}"> <button class="btn small-btn ghost" type="button" onclick="correctEventUi('${e.id}','${bookingId}',false)">Fix</button>${e.voided ? "" : ` <button class="btn small-btn ghost" type="button" onclick="correctEventUi('${e.id}','${bookingId}',true)">Void</button>`}</span>` : `<span class="small muted">Books closed for its month</span>`}
    </div>`).join("") + `<p class="small muted" style="margin-top:6px">A mistyped total is fixable while its month's books stay open. Corrections ride the event, and your receipt recomputes from the trail.</p>`;
  } catch (err) { host.innerHTML = `<p class="small muted">${esc(err.message)}</p>`; }
}
async function correctEventUi(eventId, bookingId, voidIt) {
  try {
    const body = voidIt ? { void: true } : { amount: Number((document.getElementById(`ev-amt-${eventId}`) || {}).value) };
    await api("POST", `/me/redeem-events/${eventId}/correct`, body);
    const host = document.getElementById(`evlist-${bookingId}`);
    if (host) { delete host.dataset.loaded; loadBookingEvents(bookingId); }
  } catch (err) { alert(err.message); }
}

// Creator reviews the business after a completed visit: +10
// Momentum at ANY star rating (honest reviews, never paid praise).
async function submitBusinessReview(e, bookingId) {
  e.preventDefault();
  const stars = document.getElementById("bizrev-stars-" + bookingId).value;
  const text = document.getElementById("bizrev-text-" + bookingId).value;
  try {
    await api("POST", `/bookings/${bookingId}/review-business`, { stars: Number(stars), text });
    loadMyVisits("creator");
  } catch (err) { alert(err.message); }
  return false;
}

// The creator's uploaded photo, or a brand-styled initial tile when
// they have not added one yet.
function avatarHtml(card, cls) {
  if (card.photoUrl) return `<img class="${cls}" src="${esc(card.photoUrl)}" alt="">`;
  const initial = esc((card.name || "?").trim().charAt(0).toUpperCase() || "?");
  return `<span class="${cls} avatar-initial" aria-hidden="true">${initial}</span>`;
}

// Best work (Build -79, Jeff): on a profile, a best-work link
// that is a video shows the video itself, click to play, inside
// SIGNL: the platform embed renders the post's own visual with
// its own play control. The embed descriptor rides the card
// from the server (w.embed, lib/video-embed.js) with the client
// mirror as fallback. A link that is not a parseable video
// (a photo post, another platform, a bad URL) keeps the labeled
// outbound link card it has always had ("Watch: Instagram
// reel"). The compact rendering
// (discovery cards) keeps link cards: a results grid is a
// scanning surface, and the full profile is one tap away.
function bestWorkEmbedCardHtml(w, emb) {
  return `<figure class="work-embed-card ${emb.aspect === "wide" ? "wide" : "portrait"}">
    <div class="work-embed-frame"><iframe src="${esc(emb.embedUrl)}" loading="lazy" frameborder="0" scrolling="no" allowtransparency="true" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen title="${esc(w.label || "Best work video")}"></iframe></div>
    <figcaption><span class="work-embed-plat">${esc(emb.platform)}</span><a href="${esc(w.url)}" target="_blank" rel="noopener noreferrer">Open post</a></figcaption>
  </figure>`;
}
function bestWorkHtml(list, compact) {
  if (!list || !list.length) return "";
  const pill = (w) => `<a class="work-card" href="${esc(w.url)}" target="_blank" rel="noopener noreferrer"><span class="work-play">&#9654;</span><span>${esc(w.label)}</span><span class="work-host">${esc(w.platform)}</span></a>`;
  if (compact) return `<div class="work-row">${list.map(pill).join("")}</div>`;
  const embeds = [];
  const pills = [];
  for (const w of list) {
    const emb = w.embed || videoEmbedFor(w.url);
    if (emb && emb.embedUrl) embeds.push(bestWorkEmbedCardHtml(w, emb));
    else pills.push(pill(w));
  }
  return `<div class="showcase-block"><h4>Best work</h4>${embeds.length ? `<div class="work-embed-row">${embeds.join("")}</div>` : ""}${pills.length ? `<div class="work-row">${pills.join("")}</div>` : ""}</div>`;
}

// The SIGNL track record: real visits, posts, and on-time record from
// completed platform bookings only. Before any activity the honest
// zero state shows instead of numbers.
function trackRecordHtml(card) {
  const tr = card.trackRecord;
  if (!tr) return "";
  if (tr.isNew) {
    return `<div class="showcase-block"><h4>SIGNL track record</h4><p class="muted">New to SIGNL — no visits yet.${card.foundingBand ? ` Founding creator, first ${card.foundingBand} in ${esc(card.market || "")}.` : ""}</p></div>`;
  }
  const names = (tr.businessesWorkedWith || []).map(esc).join(", ");
  return `<div class="showcase-block"><h4>SIGNL track record</h4>
    <div class="stat-row">
      <div class="stat"><div class="num">${tr.visitsCompleted}</div><div class="lbl">Visits completed</div></div>
      <div class="stat"><div class="num">${tr.postsDelivered}</div><div class="lbl">Posts delivered</div></div>
      <div class="stat"><div class="num">${tr.onTimePct === null || tr.onTimePct === undefined ? "—" : tr.onTimePct + "%"}</div><div class="lbl">On time</div></div>
      ${typeof tr.contentViews === "number" ? `<div class="stat"><div class="num">${fmtNum(tr.contentViews)}</div><div class="lbl">Content views (creator-reported)</div></div>` : ""}
    </div>
    ${engagementStripHtml(tr)}
    ${names ? `<p class="small muted">Worked with: ${names}</p>` : ""}</div>`;
}

// Engagement strip (Build -83): totals and per-post averages
// across the creator's posts with reported metrics, labeled
// recorded, with the post count it rests on. Absent when no
// post has reported metrics. The Return score is business
// facing: a creator viewing their own profile sees the numbers,
// not the score.
function engagementStripHtml(tr) {
  const eng = tr && tr.engagement;
  if (!eng) return "";
  const score = tr.returnScore && state.user && state.user.role !== "creator"
    ? `<p class="small" style="margin:8px 0 0"><strong>Return score: ${tr.returnScore.score} of 100.</strong> Built from saves and shares first, likes second, views as the base, and counted customers when we have them.</p>` : "";
  return `<div style="margin-top:12px">
    <div class="stat-row">
      <div class="stat"><div class="num">${fmtNum(eng.totals.views)}</div><div class="lbl">Views (recorded)</div></div>
      <div class="stat"><div class="num">${fmtNum(eng.totals.likes)}</div><div class="lbl">Likes (recorded)</div></div>
      <div class="stat"><div class="num">${fmtNum(eng.totals.shares)}</div><div class="lbl">Shares (recorded)</div></div>
      <div class="stat"><div class="num">${fmtNum(eng.totals.saves)}</div><div class="lbl">Saves (recorded)</div></div>
    </div>
    <p class="small muted" style="margin:6px 0 0">From ${eng.postsWithMetrics} post${eng.postsWithMetrics === 1 ? "" : "s"} with reported numbers: on average ${fmtNum(eng.averages.views)} views, ${fmtNum(eng.averages.likes)} likes, ${fmtNum(eng.averages.shares)} shares and ${fmtNum(eng.averages.saves)} saves a post. Saves and shares mean people planning to come. Recorded means the creator reported these numbers.</p>
    ${score}</div>`;
}

// Business ratings appear only when a real rating exists (a
// business rated a completed visit). The headline reads the
// server-computed ratingAvg / ratingCount; an unrated creator
// renders nothing here at all, never a zero. Nothing is ever
// seeded or averaged in.
function reviewsHtml(card) {
  const sum = card.reviewSummary || { count: 0, average: null };
  const avg = card.ratingAvg !== undefined && card.ratingAvg !== null ? card.ratingAvg : sum.average;
  const count = card.ratingCount !== undefined ? card.ratingCount : sum.count;
  if (!count || avg === null || avg === undefined) return "";
  const items = (card.reviews || []).map((r) => `
    <div class="review-item">
      <div>${starsHtml(r.stars)} <strong>${esc(r.businessName)}</strong> <span class="muted small">${esc(fmtDate(r.createdAt))}</span></div>
      ${r.comment ? `<p style="margin:6px 0 0">${esc(r.comment)}</p>` : ""}
    </div>`).join("");
  return `<div class="showcase-block"><h4>Business reviews</h4>
    <p>${starsHtml(avg)} <strong>${esc(String(avg))}</strong> average rating from ${count} business rating${count === 1 ? "" : "s"} after completed visits.</p>
    ${items}</div>`;
}

function creatorShowcaseHtml(card) {
  return bestWorkHtml(card.bestWork) + trackRecordHtml(card) + reviewsHtml(card);
}

// The full creator profile view: what a business opens from a
// discovery card (and what the admin preview opens). Built entirely
// from the same card payload discovery returns, so the detail view
// can never disagree with the card.
function creatorProfileDetailHtml(c, preview, opts) {
  // Admin review mode (Jeff, 2026-10-26): the same profile a
  // business sees, rendered from the Admin Applications queue. The
  // business actions (offers, Later, Not a fit) are replaced by
  // the way back to the queue; everything else is byte-identical.
  const adminView = !!(opts && opts.admin);
  const p = c.profile || {};
  const localTxt = p.localAudiencePct === null || p.localAudiencePct === undefined
    ? "Local audience not reported yet"
    : `${p.localAudiencePct}% local audience <span class="badge info">${esc(p.localAudienceSource || "Self-reported")}</span>`;
  const initial = esc((c.name || "?").trim().charAt(0).toUpperCase() || "?");
  return `
  <div class="panel">
    <p><button class="btn small-btn ghost" onclick="${adminView ? "adminBackToRequests()" : preview ? "previewBackToResults()" : "backToDiscover()"}">&larr; Back to ${adminView ? "Applications" : "results"}</button></p>
    <div class="creator-card full">
      <div class="cc-photo${c.photoUrl ? "" : " no-photo"}">
        ${c.photoUrl ? `<img src="${esc(c.photoUrl)}" alt="">` : `<div class="cc-mono"><span>${initial}</span></div>`}
        ${p.tierBand ? `<span class="cc-tier">${esc(p.tierBand)}</span>` : ""}
        ${p.paidRate ? `<span class="cc-paid">Paid bookings: ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)}</span>` : ""}${p.licensingFee ? ` <span class="cc-paid">Licenses posts: ${currencySymbolForMarket(p.market)}${fmtPrice(p.licensingFee)}</span>` : ""}
      </div>
      ${galleryRowHtml(c.photos)}
      <div class="cc-body">
        <div class="cc-id">
          <div class="cc-name">${esc(c.name)}</div>
          ${ccHandleHtml(p)}
          <div class="cc-chips">
            <span class="cc-chip market">${esc(marketDisplayName(c.market))}</span>
            ${c.city ? `<span class="cc-chip">${esc(c.city)}</span>` : ""}
            ${c.neighborhood ? `<span class="cc-chip">${esc(c.neighborhood)}</span>` : ""}
            ${campusBadgeHtml(c) ? `<span class="cc-chip">${esc(c.campusBadge || (c.profile && c.profile.campusBadge) || "")}</span>` : ""}
            ${c.foundingBand ? `<span class="cc-chip">First ${c.foundingBand} founding</span>` : ""}
          </div>
        </div>
        <p>${scoreBadge(c.localImpactScore)}${p.openToPaidCampaigns ? ` <span class="badge tier">Open to paid campaigns</span>` : ""}${p.spanishContent ? ` <span class="badge">Spanish content</span>` : ""}${p.musician ? ` <span class="badge">Musician</span>` : ""}${paidLaneBadgesHtml(p)}${c.momentum && c.momentum.points ? ` <span class="badge info">Momentum ${c.momentum.points} pts</span>` : ""}${badgesHtml(c.badges)}</p>
        <div class="cc-local">
          ${p.localAudiencePct === null || p.localAudiencePct === undefined
            ? `<div class="lbl">Local audience not reported yet</div>`
            : `<div class="big">${p.localAudiencePct}%</div><div class="lbl">of their followers are local</div><div class="src">${esc(p.localAudienceSource || "Self-reported")}</div>`}
        </div>
        <div class="cc-meta">
          <div><div class="k">Total audience (all platforms)</div><div class="v">${fmtNum(totalAudienceOf(c))}</div></div>
          <div><div class="k">Typical views</div><div class="v">${fmtNum(p.avgViews)}</div></div>
        </div>
        ${stackList(c).length ? `<div class="cc-platforms">${stackList(c).map((x) => `<span class="cc-plat">${esc(x.label)} ${fmtNum(x.count)}${x.synced ? " &middot; Synced" : ""}</span>`).join("")}</div>` : ""}
      </div>
    </div>
    ${c.standing === "paused" ? `<p><span class="badge warn">Paused: a late post is outstanding</span> <span class="small muted">Greyed out in search and unable to take new offers until the post is delivered.</span></p>` : ""}
    ${c.bookedUp ? `<p><span class="badge info">Booked up this week</span> <span class="small muted">At their weekly visit max. Offers can still be sent; accepting reopens next week.</span></p>` : ""}
    ${visitIncludesHtml(c.visitIncludes)}
    ${c.marketContext ? `<p class="small">You are browsing <strong>${esc(c.marketContext.market)}</strong>: ${c.marketContext.pct}% of their audience is there, and that is the local number on this card. They are based in ${esc(marketDisplayName(c.marketContext.homeMarket))} and listed in ${esc(c.marketContext.market)} on that audience.</p>` : ""}
    ${(c.listedMarkets || []).filter((m) => !m.home).length ? `<p class="small muted">Also listed in: ${(c.listedMarkets || []).filter((m) => !m.home).map((m) => `${esc(m.market)} ${m.pct}%`).join(" &middot; ")}</p>` : ""}
    ${c.scoreComponents ? `<p class="small muted">Local Impact Score, in the open: local audience ${c.scoreComponents.localAudiencePct}% &middot; reliability ${c.scoreComponents.reliability} (${esc(c.scoreComponents.reliabilityBasis)}) &middot; engagement ${c.scoreComponents.engagement}.</p>` : ""}
    ${p.categories && p.categories.length ? `<p class="small">${p.categories.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
    ${p.compCategories && p.compCategories.filter((x) => x !== PAID_COMP).length ? `<p class="small muted">Open to comps: ${p.compCategories.filter((x) => x !== PAID_COMP).map(esc).join(", ")}</p>` : ""}
    ${p.musician && (p.musicPerform || p.musicCreate) ? `<p class="small muted">${[p.musicPerform ? "Open to live performances" : "", p.musicCreate ? "Open to creating music for businesses" : ""].filter(Boolean).join(" &middot; ")}</p>` : ""}
    ${p.spanishAudiencePct !== null && p.spanishAudiencePct !== undefined ? `<p class="small muted">${p.spanishAudiencePct}% Spanish-speaking audience</p>` : ""}
    ${p.topAudienceCities && p.topAudienceCities.length ? `<p class="small muted">Top audience cities: ${p.topAudienceCities.map(esc).join(", ")}</p>` : ""}
    ${p.bio ? `<p>${esc(p.bio)}</p>` : ""}
    <p class="small">${socialLinksHtml(p)}</p>
    ${creatorShowcaseHtml(c)}
    ${adminView ? `<div class="cta-row" style="justify-content:flex-start"><button class="btn ghost" onclick="adminBackToRequests()">Back to Applications</button></div>` : `<div class="cta-row" style="justify-content:flex-start">
      ${preview
        ? `<button class="btn" onclick="previewStartOffer('${c.userId}')">Send offer</button>${p.paidRate ? ` <button class="btn ghost" onclick="previewPaidBooking('${c.userId}')">Preview paid booking (${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)})</button>` : ""}`
        : `<button class="btn" onclick="startOffer('${c.userId}')">Send offer</button>${p.paidRate ? ` <button class="btn" onclick="bookPaidVisit('${c.userId}')">Book paid visit (${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)})</button>` : ""} <button class="btn ghost" onclick="openThread('${c.userId}')">Message</button>`}
      <button class="btn small-btn ghost" onclick="profileLater('${c.userId}', ${preview ? "true" : "false"})">Later</button>
      <button class="btn small-btn ghost" onclick="profileNotFit('${c.userId}', ${preview ? "true" : "false"})">Not a fit</button>
    </div>`}
    ${p.paidRate ? `<p class="small muted">Paid bookings: ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)} &middot; you pay rate + 3% &middot; they keep 97% &middot; held until the post is live.</p>` : ""}
    ${preview ? `<p class="small muted">Preview: an offer sent from here is a simulation. It never reaches ${esc(c.name)} and nothing is saved.</p>` : ""}
    ${preview && c.trackRecord && c.trackRecord.postsDelivered > 0 ? `
    <div class="showcase-block"><h4>Ad use (preview)</h4>
      <p class="small muted">Ad use comes with the standard license: on a paid visit, a business can repost the post and run it as an ad for 90 days from the post date, and a comped post can be licensed the same way at the creator's listed fee with their approval. In the real app that logs the use, notifies the creator, and awards +25 Momentum. Here it is a simulation: nothing is logged and no points move.</p>
      <button class="btn small-btn ghost" onclick="previewAdUse('${c.userId}')">Use in an ad</button> <span id="pv-aduse-note" class="saved"></span>
    </div>` : ""}
  </div>`;
}

async function previewAdUse(userId) {
  const note = document.getElementById("pv-aduse-note");
  try {
    const data = await api("POST", "/admin/preview/ad-use", { creatorId: userId, planId: state.preview ? state.preview.planId : "growth", visitKind: "paid" });
    if (note) note.textContent = (data.adUse && data.adUse.note) || "Simulated.";
  } catch (err) {
    if (note) note.textContent = err.message;
  }
}

function openCreatorProfile(userId) {
  // Build -81: Sig's result cards carry the same discover
  // objects, held in state.sigOpData: a card tap must open the
  // profile even when the business has not opened Discover yet
  // (state.discover still empty), so the Sig cohort is the
  // fallback source. Same objects, same detail render.
  const c = (state.discover || []).find((x) => x.userId === userId)
    || ((state.sigOpData && state.sigOpData.cards) || []).find((x) => x.userId === userId);
  const el = document.getElementById("tab-body");
  if (!c || !el) return;
  el.innerHTML = creatorProfileDetailHtml(c, false);
  window.scrollTo(0, 0);
}

function backToDiscover() {
  loadDiscover();
}

function creatorCard(c, viewer, opts) {
  opts = opts || {};
  const p = c.profile || {};
  const localTxt = p.localAudiencePct === null || p.localAudiencePct === undefined
    ? "Local audience not reported yet"
    : `${p.localAudiencePct}% local audience <span class="badge info">${esc(p.localAudienceSource || "Self-reported")}</span>`;
  const tr = c.trackRecord;
  const trackLine = tr
    ? (tr.isNew
      ? `<span class="badge info">New to SIGNL: no visits yet</span>`
      : `<span class="muted">${tr.visitsCompleted} visit${tr.visitsCompleted === 1 ? "" : "s"} completed &middot; ${tr.postsDelivered} post${tr.postsDelivered === 1 ? "" : "s"} delivered &middot; ${tr.onTimePct === null || tr.onTimePct === undefined ? "—" : tr.onTimePct + "% on time"}</span>`)
    : "";
  const ratingAvg = c.ratingAvg !== undefined && c.ratingAvg !== null ? c.ratingAvg : (c.reviewSummary ? c.reviewSummary.average : null);
  const ratingCount = c.ratingCount !== undefined ? c.ratingCount : (c.reviewSummary ? c.reviewSummary.count : 0);
  // Feed anatomy (UX redesign section 6): the rating joins the card
  // only once it rests on 3+ ratings; one or two ratings stay noise.
  const reviewLine = ratingCount >= 3 && ratingAvg !== null && ratingAvg !== undefined
    ? ` ${starsHtml(ratingAvg)} <strong>${esc(String(ratingAvg))}</strong> <span class="muted">(${ratingCount} rating${ratingCount === 1 ? "" : "s"})</span>`
    : "";
  // v2 .creator-card anatomy: one component for discovery, the public
  // profile hero, and the profile detail header (DESIGN-SYSTEM.md).
  // Same data, same words, same handlers; only the layout changed.
  const initial = esc((c.name || "?").trim().charAt(0).toUpperCase() || "?");
  return `
  <div class="creator-card${c.standing === "paused" ? " paused" : ""}">
    <div class="cc-photo${c.photoUrl ? "" : " no-photo"}">
      ${c.photoUrl ? `<img src="${esc(c.photoUrl)}" alt="">` : `<div class="cc-mono"><span>${initial}</span></div>`}
      ${p.tierBand ? `<span class="cc-tier">${esc(p.tierBand)}</span>` : ""}
      ${p.paidRate ? `<span class="cc-paid">Paid bookings: ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)}</span>` : ""}${p.licensingFee ? ` <span class="cc-paid">Licenses posts: ${currencySymbolForMarket(p.market)}${fmtPrice(p.licensingFee)}</span>` : ""}
    </div>
    <div class="cc-id">
      <div class="cc-name">${esc(c.name)}</div>
      ${p.primaryPlatform && p.primaryPlatform !== "instagram" ? ccHandleHtml(p) : `<div class="cc-handle">@${esc(p.handle || "")}</div>`}
      <div class="cc-chips">
        <span class="cc-chip market">${esc(marketDisplayName(c.market))}</span>
        ${c.marketContext ? `<span class="cc-chip">Listed in ${esc(c.marketContext.market)}</span>` : ""}
        ${c.city ? `<span class="cc-chip">${esc(c.city)}</span>` : ""}
        ${c.neighborhood ? `<span class="cc-chip">${esc(c.neighborhood)}</span>` : ""}
        ${c.distanceBand ? `<span class="cc-chip band">${esc(c.distanceBand)}</span>` : ""}
        ${campusBadgeHtml(c) ? `<span class="cc-chip">${esc(c.campusBadge || (c.profile && c.profile.campusBadge) || "")}</span>` : ""}
        ${c.foundingBand ? `<span class="cc-chip">First ${c.foundingBand} founding</span>` : ""}
      </div>
    </div>
    <div class="cc-local">
      ${p.localAudiencePct === null || p.localAudiencePct === undefined
        ? `<div class="lbl">Local audience not reported yet</div>`
        : `<div class="big">${p.localAudiencePct}%</div><div class="lbl">of their followers are local</div><div class="src">${esc(p.localAudienceSource || "Self-reported")}</div>`}
    </div>
    ${p.spanishAudiencePct !== null && p.spanishAudiencePct !== undefined ? `<p class="small muted" style="margin-top:6px">${p.spanishAudiencePct}% Spanish-speaking audience</p>` : ""}
    <div class="cc-meta">
      <div><div class="k">Stacked audience</div><div class="v">${fmtNum(totalAudienceOf(c))}</div></div>
      <div><div class="k">Typical views</div><div class="v">${fmtNum(p.avgViews)}</div></div>
    </div>
    ${stackList(c).length ? `<div class="cc-platforms">${stackList(c).map((x) => `<span class="cc-plat">${esc(x.label)} ${fmtNum(x.count)}</span>`).join("")}</div>` : ""}
    ${c.standing === "paused" ? `<p><span class="badge warn">Paused: a late post is outstanding</span> <span class="small muted">This creator is greyed out and cannot take new offers until the post is delivered.</span></p>` : ""}
    ${c.bookedUp ? `<p><span class="badge info">Booked up this week</span> <span class="small muted">At their weekly visit max. You can still send offers; they can accept next week.</span></p>` : ""}
    <p>${scoreBadge(c.localImpactScore)}${p.openToPaidCampaigns ? ` <span class="badge tier">Open to paid campaigns</span>` : ""}${p.spanishContent ? ` <span class="badge">Spanish content</span>` : ""}${p.musician ? ` <span class="badge">Musician</span>` : ""}${paidLaneBadgesHtml(p)}${c.momentum && c.momentum.points ? ` <span class="badge info">Momentum ${c.momentum.points} pts</span>` : ""}${badgesHtml(c.badges)}</p>
    ${p.categories && p.categories.length ? `<p class="small">${p.categories.map((x) => `<span class="badge">${esc(x)}</span>`).join(" ")}</p>` : ""}
    ${p.compCategories && p.compCategories.filter((x) => x !== PAID_COMP).length ? `<p class="small muted">Open to comps: ${p.compCategories.filter((x) => x !== PAID_COMP).map(esc).join(", ")}</p>` : ""}
    ${p.bio ? `<p class="small muted">${esc(p.bio)}</p>` : ""}
    <p class="small">${socialLinksHtml(p)}</p>
    ${bestWorkHtml(c.bestWork, true)}
    ${trackLine || reviewLine ? `<div class="cc-track">${trackLine}${reviewLine}</div>` : ""}
    ${c.fit && c.fit.reasons && c.fit.reasons.length ? `<p class="small cc-fit"><strong>Why they fit:</strong> ${c.fit.reasons.slice(0, 2).map(esc).join(" &middot; ")}</p>` : ""}
    <p class="small muted">Every SIGNL comped visit: 1 post or reel + 1 story that shares the post within 48 hours, tracked as proof. Paid bookings carry the deliverables set in the booking's terms. Content rights follow the visit: comp visits are native share only; paid visits add repost and ad rights for 90 days.</p>
    <div class="cc-actions">
      ${opts.preview
        ? `<button class="btn small-btn" onclick="previewViewCreator('${c.userId}')">View profile</button>
           <button class="btn small-btn ghost" onclick="previewStartOffer('${c.userId}')">Send preview offer</button>${p.paidRate ? `
           <button class="btn small-btn ghost" onclick="previewPaidBooking('${c.userId}')">Preview paid booking (${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)})</button>` : ""}`
        : `<button class="btn small-btn" onclick="startOffer('${c.userId}')">Send offer</button>${p.paidRate ? `
           <button class="btn small-btn" onclick="bookPaidVisit('${c.userId}')">Book paid visit (${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)})</button>` : ""}
           <button class="btn small-btn ghost" onclick="openCreatorProfile('${c.userId}')">View profile</button>
           <button class="btn small-btn ghost" onclick="openThread('${c.userId}')">Message</button>
           <button class="heart ${c.isFavorite ? "on" : ""}" title="Save to favorites" onclick="toggleFav('${c.userId}')">${c.isFavorite ? "&#10084;" : "&#9825;"}</button>`}
    </div>
  </div>`;
}

// ---------- creator ----------

const LIVE_CREATOR_TABS = ["Dashboard", "Profile", "Offers", "My Visits", "Messages", "Earnings", "More", "Momentum", "Numbers", "Settings", "Help", "Sig", "Bench"];
// V4.1: founding creators get the SAME tab set as live ones.
// The old founding whitelist hid Offers / My Visits / Earnings
// until the market launched — paired with the old 2-item tab
// bar, a founding creator (Jeff's own account) had no way to
// even see the explore door. The screens themselves carry the
// honest pre-launch states (completion gate, empty decks).
const FOUNDING_TABS = ["Dashboard", "Profile", "Status", "More", "Momentum", "Numbers", "Messages", "Settings", "Help", "Offers", "My Visits", "Earnings", "Sig", "Bench"];

function renderCreatorDash() {
  const u = state.user;
  const marketLive = !!(u.founding && u.founding.marketLive);
  if (!marketLive) { stopHomeCountdown(); return renderFoundingHome(); }
  let tab = state.tab || "Dashboard";
  if (!LIVE_CREATOR_TABS.includes(tab)) tab = "Dashboard";
  state.tab = tab;
  if (tab !== "Dashboard") stopHomeCountdown();
  let body = "";
  if (tab === "Dashboard") body = `<div id="creator-home" class="vx-stagger"><div class="sig-load-row">${sigAvatarHtml("think")}</div>${skelHtml("Loading your dashboard...", 2)}</div>`;
  if (tab === "Bench") body = `<div id="bench-body">${skelHtml("Loading the bench...", 1)}</div>`;
  if (tab === "Profile") body = wsHead("My profile", { chip: livePill("Live"), sub: "Your public creator profile. This is what businesses see when they find you.", subKey: "cr-profile" }) + creatorProfileHtml(u) + momentumHtml(u) + growRosterHtml(u);
  app.innerHTML = `<div class="wrap">
    ${standingBannerHtml(u)}
    <div id="tab-body">${body}</div></div>`;
  if (tab === "Dashboard") loadCreatorHome();
  if (tab === "Profile") { setTimeout(loadMyScore, 10); setTimeout(loadRateRange, 10); setTimeout(() => { setupUniversityAutocomplete("p-university", "p-university-results"); dragInit(); }, 10); }
  if (tab === "Offers") loadCreatorOffers();
  if (tab === "My Visits") loadMyVisits("creator");
  if (tab === "Messages") loadThreads();
  if (tab === "Earnings") renderEarningsTab();
  if (tab === "More") renderMoreScreen();
  if (tab === "Momentum") renderMomentumTab();
  if (tab === "Numbers") renderCreatorNumbers();
  if (tab === "Settings") renderSettingsTab();
  if (tab === "Help") renderHelpTab();
  if (tab === "Sig") renderSigTab();
  if (tab === "Bench") loadBench();
}

// The approved creator's home before their market activates. It is
// a real tabbed interface now (Jeff, 2026-10-20: Dashboard / Profile
// / Status, mirroring the bottom nav), because founding creators are
// the entire audience until markets open and the old single status
// page hid the Home blocks from every one of them. Dashboard leads
// with the home blocks; the full founding status detail lives under
// Status; Profile is the same profile form founding creators already
// use. Data comes from GET /me/founding (which also powers the score).
// Multi-market listing line (2026-11-01): where else this
// creator is listed, from the card's server-computed
// listedMarkets. With no extra markets yet, the line teaches
// the setting instead of rendering nothing.
function listedMarketsLineHtml(card) {
  const others = ((card && card.listedMarkets) || []).filter((m) => !m.home);
  if (others.length) {
    return `<p class="small" style="margin:6px 0 0">You are listed in ${others.map((m) => `<strong>${esc(m.market)}</strong> (${m.pct}% of your audience)`).join(" and ")} too: businesses there can find you, and their offers reach you.</p>`;
  }
  return `<p class="small muted" style="margin:6px 0 0">Audience in another city too? Add that market under Profile, in Your audience, and you are listed and ranked there as well.</p>`;
}

function renderFoundingHome() {
  const u = state.user;
  let tab = state.tab || "Dashboard";
  if (!FOUNDING_TABS.includes(tab)) tab = "Dashboard";
  state.tab = tab;
  const placeBadge = u.market === unlistedLabel() ? esc(u.city || u.market) : esc(marketDisplayName(u.market));
  let body = "";
  if (tab === "Dashboard") body = `<div id="founding-dash" class="vx-stagger"><div class="sig-load-row">${sigAvatarHtml("think")}</div>${skelHtml("Loading your dashboard...", 2)}</div>`;
  if (tab === "Bench") body = `<div id="bench-body">${skelHtml("Loading the bench...", 1)}</div>`;
  if (tab === "Status") body = `<h3 style="margin-top:0">Your founding status</h3><div id="founding-body">${skelHtml("Loading your founding profile...", 1)}</div><div id="founding-buzz"></div><div id="founding-depth"></div>`;
  if (tab === "Profile") body = wsHead("My profile", { sub: "Your public creator profile. Complete profiles get booked first.", subKey: "cr-profile" }) + creatorProfileHtml(u);
  if (tab === "Status") body = wsHead("Status", { sub: "Where your founding enrollment stands." }) + body;
  app.innerHTML = `<div class="wrap">
    ${standingBannerHtml(u)}
    <div id="tab-body">${body}</div></div>`;
  if (tab === "Dashboard") loadFoundingDashboard();
  if (tab === "Status") loadFoundingStatus();
  if (tab === "Profile") { setTimeout(loadMyScore, 10); setTimeout(loadRateRange, 10); setTimeout(() => { setupUniversityAutocomplete("p-university", "p-university-results"); dragInit(); }, 10); }
  if (tab === "More") renderMoreScreen();
  if (tab === "Momentum") renderMomentumTab();
  if (tab === "Numbers") renderCreatorNumbers();
  if (tab === "Messages") loadThreads();
  if (tab === "Settings") renderSettingsTab();
  if (tab === "Help") renderHelpTab();
  if (tab === "Offers") loadCreatorOffers();
  if (tab === "My Visits") loadMyVisits("creator");
  if (tab === "Earnings") renderEarningsTab();
  if (tab === "Sig") renderSigTab();
  if (tab === "Bench") loadBench();
}

// The founding Dashboard tab: greeting, a compact founding status
// card (the full detail is one tap away under Status), the metric
// band and paid lane panel, Momentum, and the roster block.
async function loadFoundingDashboard() {
  const el = document.getElementById("founding-dash");
  if (!el) return;
  try {
    const data = await api("GET", "/me/founding");
    if (!document.getElementById("founding-dash")) return; // navigated away mid-load
    const f = data.founding;
    const card = data.card;
    const p = card.profile || {};
    state.user.founding = f;
    const u = state.user;
    const isUnl = !!f.unlisted;
    const place = isUnl ? esc(unlistedPlace(f)) : esc(marketTalkNameClient(f.market));
    const hour = new Date().getHours();
    const greet = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
    const firstName = (u.name || "").trim().split(" ")[0] || u.name || "";
    const totalAud = totalAudienceOf(card);
    const pctSet = !(p.localAudiencePct === null || p.localAudiencePct === undefined);
    const localReach = pctSet ? Math.round((totalAud * Number(p.localAudiencePct)) / 100) : null;
    const momPts = (u.momentum || {}).points || 0;
    // Sig's queue (V3): the real waiting items on this home,
    // computed from the records on screen.
    const queueItems = [];
    if (u.profileCompletion && !u.profileCompletion.complete) {
      queueItems.push({ text: "Finish your profile. Businesses can only find finished profiles.", btn: "Open profile", act: () => goFinishProfile() });
    }
    if (!queueItems.length) {
      queueItems.push({ text: isUnl ? `You are on the founding roster. ${f.city} opens when sign-ups pile up; we email you the moment it opens.` : `You are on the founding roster for ${marketTalkNameClient(f.market)}. We email you the moment it opens.`, btn: "View status", act: () => go("dashboard", "Status") });
    }
    // Sig activation ideas (founding home): once the essentials
    // are done, Sig prompts the two build-up moves a founding
    // creator can actually take before the market opens — a
    // photo, and inviting the next founding creator. Same
    // dismissal + 14-day cooldown + 2-idea cap as the live home.
    if (u.profileCompletion && u.profileCompletion.complete) {
      const photoIt = (u.profileCompletion.items || []).find((i) => i.id === "photo");
      if (photoIt && !photoIt.done) {
        const it = sigIdeaItem(u.id, "cr_photo", `Add your profile photo.${photoIt.points ? ` It earns +${photoIt.points} Momentum.` : ""} Founding profiles with a face are the ones businesses meet first.`, "Add photo", () => go("dashboard", "Profile"), "Add a profile photo");
        if (it) queueItems.push(it);
      }
      const inv = sigIdeaItem(u.id, "cr_invite", "Know a creator who should be founding with you? Your invite earns +3 Momentum when they join, +10 when they are approved.", "Share invite", () => { const g = document.getElementById("grow-roster"); if (g) g.scrollIntoView({ behavior: "smooth", block: "start" }); }, "Invite a founding creator");
      if (inv) queueItems.push(inv);
      const capped = capSigIdeas(queueItems);
      queueItems.length = 0;
      queueItems.push(...capped);
    }
    // Build -42: Sig's introduction, when Sig has one, rides
    // the founding queue too. The Bench never blocks this home:
    // a failed read simply means no introduction today.
    try {
      const bench = await api("GET", "/me/bench");
      if (bench && bench.introduction && bench.introduction.creator) {
        state.bench = bench;
        const intro = bench.introduction;
        let introDismissed = false;
        try { introDismissed = !!localStorage.getItem(`benchintro:${intro.creator.userId}`); } catch (e) { /* storage unavailable: show it */ }
        if (!introDismissed) queueItems.push({ text: `${benchMeetLine(intro)} I think you two would make a strong +1 pair: visit together, and you each post your own post and story.`, btn: "Meet them", act: () => go("dashboard", "Bench"), dismissKey: `benchintro:${intro.creator.userId}`, onDismiss: () => benchDismissIntro(intro.creator.userId) });
      }
    } catch (e) { /* no introduction today */ }
    // V4.1: the Sig tab renders this same queue and badges its
    // count — one queue, two doors (see renderSigTab).
    state.sigQueue = queueItems;
    state.sigQueueLinks = [];
    state.sigQueueCount = queueItems.length;
    const fSteps = [
      { label: "Claim your profile", sub: "You are on the roster.", done: u.status === "approved" },
      { label: "Add the four basics", sub: "Home city, audience size, categories, local %.", done: !u.profileCompletion || u.profileCompletion.complete, btn: "Finish profile", act: () => goFinishProfile() },
      { label: "Set your paid rate", sub: "Comped visits work without it.", done: !!(u.creator && u.creator.paidRate), optional: true, btn: "Set my rate", act: () => go("dashboard", "Profile") },
      { label: "Apply to your first offer", sub: "Offers open when your market launches. The Offers tab shows how they work.", done: false, btn: "See Offers", act: () => go("dashboard", "Offers") },
    ];
    el.innerHTML = `
    ${wsHead("Home", { sub: "Start here. Sig shows you what needs you, in order.", subKey: "cr-home" })}
    <div class="home-greet"><div class="hg-hi">Hi, ${esc(firstName)}</div><div class="hg-line">${esc(greet)}. ${isUnl ? `${esc(f.city)} opens when sign-ups pile up. We email you the moment it opens.` : `${esc(marketTalkNameClient(f.market))} is a founding market. We email you the moment it opens.`}</div></div>
    ${sigQueueHtml(queueItems, { links: [], askBox: true })}
    ${checklistHtml(fSteps)}
    <div class="wcard">
      <div class="kpi-label">Your local reach</div>
      <div class="kpi-num" style="font-size:3.3rem">${localReach === null ? "Not set" : fmtNum(localReach)}</div>
      <div class="kpi-sub">${pctSet ? `${p.localAudiencePct}% of your ${fmtNum(totalAud)} audience is local. Businesses rank creators by this number, not by follower count.` : "Add your local audience % in your profile and this fills in."}</div>
      ${pctSet ? "" : `<p style="margin:12px 0 0"><button class="btn small-btn ws-primary" onclick="return go('dashboard','Profile')">Add your local %</button></p>`}
    </div>
    <p class="small" style="margin:10px 2px 0">${listedMarketsLineHtml(card)}</p>
    ${homePaidLaneSummaryHtml(u.creator)}
    ${growRosterHtml(u)}
    <p class="small muted" style="margin:14px 2px 0">Your Charter card, founding class, points, and full status live under <a class="tlink" href="#" onclick="return go('dashboard','Status')">Status</a> and <a class="tlink" href="#" onclick="return go('dashboard','Momentum')">Momentum</a>.</p>
    ${askSigRowHtml()}`;
    wireSigQueue(el, queueItems, []);
    wireChecklist(el, fSteps);
    renderBottomNav();
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}

// ---------- The Receipt + Proof Card (Build -34) ----------
// Every number on these surfaces is a counted floor with its
// method in plain words beside it. Nothing here projects,
// estimates silently, or says "caused": register events are
// counted, tallies are labeled as reported, Google's numbers
// stay under Google's name, and mentions ride their own line.
function receiptFoundingHtml() {
  return `<div id="biz-receipt"></div>`;
}
// The one-shot notice the Square OAuth return (?sq=) leaves
// behind, rendered once at the top of the receipt (Build -44).
function sqNoticeHtml() {
  const v = state.sqNotice;
  if (!v) return "";
  state.sqNotice = null;
  if (v === "connected") return `<div class="notice"><strong>Your register is connected.</strong> Code visits and come-backs now count themselves. The connection, its locations, and the disconnect live in Results, under your proof controls.</div>`;
  if (v === "error") return `<div class="notice"><strong>Square connect did not finish.</strong> Nothing changed, and your codes still count at the till. You can try again from the setup checklist on Home.</div>`;
  if (v === "unavailable") return `<div class="notice blue"><strong>The register plug-in opens on your setup call.</strong> We plug into your POS with you, one tap on your end. Until then your codes count on the register you already have.</div>`;
  return "";
}
async function loadReceipt() {
  const host = document.getElementById("biz-receipt");
  if (!host) return;
  let r = null;
  try { const data = await api("GET", "/me/receipt"); r = data.receipt; } catch (e) { r = null; }
  if (!document.getElementById("biz-receipt")) return;
  if (!r) { host.innerHTML = ""; return; }
  state._receiptTop = (r.topCreators || [])[0] || null;
  state._receiptMonth = r.month || null;
  host.innerHTML = receiptHtml(r);
  // Build -99: no setup card renders in Results anymore. The
  // proof kit's steps are items in the ONE setup checklist on
  // Home, and Proof Controls below points there for the
  // register connect.
  // Build -96: the forwardable export card fills its slot at
  // the foot of the Receipt.
  loadReceiptExport();
}
// Build -48: the Receipt's score blocks live under subtabs
// (Overview / Over time / Creators / Costs / How it counts).
// The selected tab is module state, so a loadReceipt re-render
// (a comp-cost save, the Sig capture-gap deep link) lands back
// on the tab the owner was reading. All five panels render in
// one pass; switching only toggles which one shows, so open
// details and half-filled forms survive a tab switch.
const RECEIPT_TABS = ["overview", "time", "creators", "costs", "counts"];
let receiptTab = "overview";
function receiptSetTab(name) {
  if (!RECEIPT_TABS.includes(name)) name = "overview";
  receiptTab = name;
  const host = document.getElementById("biz-receipt");
  if (host) {
    host.querySelectorAll(".rc-panel").forEach((p) => p.classList.toggle("on", p.getAttribute("data-rc") === name));
    const bar = host.querySelector(".rc-tabs");
    if (bar) bar.querySelectorAll(".ws-tab").forEach((b, i) => { const on = RECEIPT_TABS[i] === name; b.classList.toggle("on", on); b.setAttribute("aria-selected", on ? "true" : "false"); });
  }
  return false;
}
function receiptSettingsHtml(r) {
  const b = (state.user && state.user.business) || {};
  const base = r.baseline || null;
  const g = (r.google && r.google.current) || {};
  const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
  return `<details style="margin-top:14px"><summary class="small"><strong>Your receipt's starting lines and proof controls</strong> <span class="muted">(the settings that decide what counts: your usual night, your comp costs, your register connection)</span></summary>
    <div class="form-2col" style="margin-top:10px">
      <div class="field"><label>One of your usual open days</label><select id="rc-base-day">${days.map((d) => `<option ${base && base.dayLabel === d ? "selected" : ""}>${d}</option>`).join("")}</select></div>
      <div class="field"><label>About how many customers on that day?</label><input id="rc-base-count" type="number" min="0" value="${base ? base.usual : ""}" placeholder="For example: 40"></div>
    </div>
    <p class="small muted" style="margin:0 0 10px">Your receipt measures visit days against it, so you can see what a visit did in real dollars. One remembered number, set any time before your first visit. Skip it for now if you like.</p>
    <button class="btn small-btn ghost" type="button" onclick="receiptSaveBaseline()">Save</button> <span class="small muted" id="rc-base-note"></span>
    <div class="form-2col" style="margin-top:12px">
      <div class="field"><label>Google searches this month</label><input id="rc-g-searches" type="number" min="0" value="${g.searches !== undefined ? g.searches : ""}"></div>
      <div class="field"><label>Direction requests</label><input id="rc-g-directions" type="number" min="0" value="${g.directions !== undefined ? g.directions : ""}"></div>
      <div class="field"><label>Calls from Google</label><input id="rc-g-calls" type="number" min="0" value="${g.calls !== undefined ? g.calls : ""}"></div>
      <div class="field"><label>New reviews</label><input id="rc-g-reviews" type="number" min="0" value="${g.reviews !== undefined ? g.reviews : ""}"></div>
    </div>
    <button class="btn small-btn ghost" type="button" onclick="receiptSaveGoogle()">Save Google numbers</button> <span class="small muted" id="rc-g-note"></span>
    <p class="small" style="margin-top:12px"><label class="ckrow"><input type="checkbox" class="ckbox" id="rc-optin" ${r.proofNameOptIn ? "checked" : ""} onchange="receiptSaveOptIn()"><span>Let creators name my business on their proof cards. Until I check this, their proof shows my category and city only.</span></label></p>
    ${proofControlsHtml(r)}
  </details>`;
}
// Founding business onboarding setup (Build -64): the
// first-month moment + usual-night baseline that used to sit
// on the sign-up form. Both ride the existing /me/profile
// PATCH fields, the same ones the receipt settings use.
async function fbzSaveSetup() {
  const note = document.getElementById("fbz-setup-note");
  const moment = (document.getElementById("fbz-moment") || {}).value || "";
  const day = (document.getElementById("fbz-base-day") || {}).value || "";
  const countRaw = (document.getElementById("fbz-base-count") || {}).value;
  const patch = { moment: moment || null };
  if (day && countRaw !== "" && countRaw !== undefined && countRaw !== null) patch.baseline = { dayLabel: day, count: Number(countRaw) };
  try {
    const data = await api("PATCH", "/me/profile", patch);
    state.user = data.user;
    if (note) note.textContent = "Saved.";
  } catch (err) {
    if (note) note.textContent = err.message;
  }
  return false;
}

async function receiptSaveBaseline() {
  const day = (document.getElementById("rc-base-day") || {}).value;
  const count = (document.getElementById("rc-base-count") || {}).value;
  const note = document.getElementById("rc-base-note");
  // Build -68: the baseline is optional in fact. Saving it
  // blank is a skip, and a skip is a success state, never an
  // error and never a zero written over a real number.
  if (count === "" || count === undefined || count === null) {
    if (note) note.textContent = "Skipped for now. Set it any time before your first visit.";
    return;
  }
  try {
    const data = await api("PATCH", "/me/profile", { baseline: { dayLabel: day, count: Number(count) } });
    state.user = data.user;
    if (note) note.textContent = "Saved. Visit days now line up against your usual " + day + ".";
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
async function receiptSaveGoogle() {
  const val = (id) => { const el = document.getElementById(id); return el && el.value !== "" ? Number(el.value) : undefined; };
  const note = document.getElementById("rc-g-note");
  const gs = {};
  const map = { searches: "rc-g-searches", directions: "rc-g-directions", calls: "rc-g-calls", reviews: "rc-g-reviews" };
  for (const k of Object.keys(map)) { const v = val(map[k]); if (v !== undefined) gs[k] = v; }
  try {
    const data = await api("PATCH", "/me/profile", { googleStats: gs });
    state.user = data.user;
    if (note) note.textContent = "Saved under this month, labeled as Google's numbers.";
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
async function receiptSaveOptIn() {
  const el = document.getElementById("rc-optin");
  try { const data = await api("PATCH", "/me/profile", { proofNameOptIn: !!(el && el.checked) }); state.user = data.user; } catch (e) { /* the checkbox state stands */ }
}
// Proof Controls (Build -39): one panel, real knobs. The usual
// comp cost pre-fills every visit close-out; the code discount
// is the business's standing offer setting; the pass switch
// stops or starts pass issuance at the register; the sharing
// switch keeps this business's results off proof cards. Every
// control saves to the business record and bites immediately.
function proofControlsHtml(r) {
  const bz = (state.user && state.user.business) || {};
  const dflts = bz.compCostDefaults || {};
  const cats = new Set(Object.keys(dflts.byCategory || {}));
  for (const v of (r.scoreV2 && r.scoreV2.current && r.scoreV2.current.visits) || []) if (v.category) cats.add(v.category);
  const catRows = [...cats].map((cat) => `<div class="form-2col" style="margin-top:6px">
      <div class="field"><label>Usual comp cost for ${esc(cat)} visits ($)</label><input class="rc-comp-cat" data-cat="${esc(cat)}" type="number" min="0" step="0.01" placeholder="Uses your usual cost" value="${dflts.byCategory && typeof dflts.byCategory[cat] === "number" ? dflts.byCategory[cat] : ""}"></div>
      <div class="field"><label>&nbsp;</label><p class="small muted" style="margin:0">Only if ${esc(cat)} comps cost you something different.</p></div>
    </div>`).join("");
  return `<h4 style="margin:16px 0 4px">Proof controls</h4>
    <p class="small muted" style="margin:0 0 8px">Set these once. They run quietly under every visit after that.</p>
    <div class="form-2col">
      <div class="field"><label>Your usual comp cost ($)</label><input id="rc-comp-default" type="number" min="0" step="0.01" placeholder="For example: 30" value="${typeof dflts.default === "number" ? dflts.default : ""}"></div>
      <div class="field"><label>&nbsp;</label><p class="small muted" style="margin:0">What a comped visit usually costs you, at your cost. It pre-fills when a visit closes out, so closing is one tap unless that visit ran different.</p></div>
    </div>
    ${catRows}
    <div class="form-2col" style="margin-top:10px">
      <div class="field"><label>Code discount for customers (%)</label><input id="rc-disc-pct" type="number" min="0" max="100" step="0.5" placeholder="0" value="${bz.discountPct ? bz.discountPct : ""}"></div>
      <div class="field"><label>&nbsp;</label><label class="ckrow"><input type="checkbox" class="ckbox" id="rc-disc-on" ${bz.discountEnabled ? "checked" : ""}><span>Give code users this discount</span></label></div>
    </div>
    <p class="small muted" style="margin:4px 0 0">The discount stamps onto new bookings from here. Its cost counts in your score only when a customer actually uses it, figured on the full check.</p>
    <p class="small" style="margin-top:10px"><label class="ckrow"><input type="checkbox" class="ckbox" id="rc-pass-on" ${bz.comeBackPassEnabled === false ? "" : "checked"}><span>Hand a Came-Back Pass to each counted first customer, good for a return within 30 days.</span></label></p>
    <p class="small" style="margin-top:6px"><label class="ckrow"><input type="checkbox" class="ckbox" id="rc-share-on" ${bz.proofSharing === false ? "" : "checked"}><span>Let my counted results appear on creators' proof cards, as my category and city, or my name if I allow it above.</span></label></p>
    <button class="btn small-btn ghost" type="button" onclick="receiptSaveControls()">Save proof controls</button> <span class="small muted" id="rc-ctl-note"></span>
    ${squareControlsHtml(r)}`;
}
// Your register (Build -44, Square Connect): the register's
// status and management, living in Proof Controls. Build -99
// moved the CONNECT action to the setup checklist on Home:
// the not-connected state here states the status, explains
// what connecting does, and points to Home. The connected
// state (locations, read-back, disconnect) and the paused
// state (reconnect, disconnect) stay managed right here.
// The states are the server's (r.register, never a guess):
// not switched on yet (the approved concierge words), not
// connected, connected, or paused (the plain sentence, never
// an error code). Sandbox connections say sandbox.
function squareControlsHtml(r) {
  const reg = r.register || null;
  if (!reg) return "";
  const head = `<h4 style="margin:16px 0 4px">Your register</h4>`;
  if (!reg.configured) {
    return `${head}
    <p class="small" style="margin:0">On our setup call, we plug into your POS with you: it takes one tap on your end, and we stay on the line until your panel says connected. If your system isn't one we connect to yet, nothing waits on that: your codes start counting on the register you already have, the day your first creator posts.</p>`;
  }
  const sandboxTag = reg.env === "sandbox" ? ` <span class="badge">Square sandbox: a test register, not a live one</span>` : "";
  if (reg.state === "paused") {
    return `${head}
    <p class="small" style="margin:0 0 8px"><strong>Register paused.</strong> Square stopped sharing checks on ${esc(fmtDate(reg.pausedAt))}. Your codes still count at the till. Tap to reconnect.${sandboxTag}</p>
    <a class="btn small-btn" href="/api/me/square/start">Reconnect Square</a>
    <button class="btn small-btn ghost" type="button" onclick="squareDisconnect()">Disconnect register</button> <span class="small muted" id="rc-sq-note"></span>`;
  }
  if (!reg.connected) {
    // Build -99: the connect action's home is the setup
    // checklist on Home. Results keeps the register status
    // (not connected), what connecting does, and the counted
    // data; it hosts no Connect Square button anymore.
    return `${head}
    <p class="small" style="margin:0 0 6px"><strong>Register not connected.</strong> If your register is Square, connect it from your setup checklist on Home: tap Connect Square there and sign in once. After that, SIGNL counts code visits and come-backs from the register itself: nobody types anything. Not on Square? Skip it. The codes count your visits either way; your team just taps the amount at the till.</p>
    <p class="small muted" style="margin:0 0 8px">We read only the checks your codes touch: the orders they were rung on, whether a counted customer came back, and refunds, so a refunded check comes out of the count. Your other sales are yours.${sandboxTag}</p>
    <button class="btn small-btn" type="button" onclick="return go('dashboard','Home')">Open the setup checklist on Home</button>`;
  }
  const locs = (reg.locations || []).map((l) => `<label class="ckrow" style="display:block;margin-top:4px"><input type="checkbox" class="ckbox sq-loc" value="${esc(l.id)}" ${l.selected ? "checked" : ""}><span>${esc(l.name)}</span></label>`).join("");
  const sum = reg.lastSyncSummary || {};
  const counted = (sum.firsts || 0) + (sum.audience || 0) + (sum.returns || 0);
  return `${head}
    <p class="small" style="margin:0 0 6px"><strong>Register connected · ${esc(reg.businessName || "Square")} · counting from ${esc(fmtDate(reg.connectedAt))}</strong>${sandboxTag}</p>
    <p class="small muted" style="margin:0 0 6px">${reg.codesProvisioned || 0} of your codes sit on the register as discounts, named exactly the code, so staff pick the word the customer says.${reg.lastSyncAt ? ` Last read from your register ${esc(fmtDate(reg.lastSyncAt))}${counted ? `, ${counted} counted event${counted === 1 ? "" : "s"} on that read` : ""}.` : ""} Counting reads only the locations you pick:</p>
    ${locs}
    <div style="margin-top:8px">
      <button class="btn small-btn ghost" type="button" onclick="squareSaveLocations()">Save locations</button>
      <button class="btn small-btn ghost" type="button" onclick="squareSyncNow()">Read the register now</button>
      <button class="btn small-btn ghost" type="button" onclick="squareDisconnect()">Disconnect register</button> <span class="small muted" id="rc-sq-note"></span>
    </div>
    <p class="small muted" style="margin:6px 0 0">Disconnecting stops the reads and deletes the connection on our side at once. Everything already counted stays counted.</p>`;
}
async function squareSaveLocations() {
  const note = document.getElementById("rc-sq-note");
  const ids = [...document.querySelectorAll(".sq-loc")].filter((el) => el.checked).map((el) => el.value);
  try {
    await api("POST", "/me/square/locations", { locationIds: ids });
    if (note) note.textContent = "Saved. Counting reads the locations you picked, from here on.";
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
async function squareSyncNow() {
  const note = document.getElementById("rc-sq-note");
  if (note) note.textContent = "Reading your register...";
  try {
    const data = await api("POST", "/me/square/sync", {});
    if (note) note.textContent = data.ok ? "Read. Anything new is counted." : "Your register paused: reconnect above and the count carries on at the till meanwhile.";
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
async function squareDisconnect() {
  const note = document.getElementById("rc-sq-note");
  try {
    await api("POST", "/me/square/disconnect", {});
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
async function receiptSaveControls() {
  const note = document.getElementById("rc-ctl-note");
  const numOrNull = (id) => { const el = document.getElementById(id); if (!el || el.value === "") return null; const n = Number(el.value); return Number.isFinite(n) ? n : null; };
  const byCategory = {};
  document.querySelectorAll(".rc-comp-cat").forEach((el) => { if (el.value !== "" && Number.isFinite(Number(el.value))) byCategory[el.dataset.cat] = Number(el.value); });
  const compCostDefaults = {};
  const dflt = numOrNull("rc-comp-default");
  if (dflt !== null) compCostDefaults.default = dflt;
  if (Object.keys(byCategory).length) compCostDefaults.byCategory = byCategory;
  const discPct = numOrNull("rc-disc-pct");
  try {
    const data = await api("PATCH", "/me/profile", {
      compCostDefaults: Object.keys(compCostDefaults).length ? compCostDefaults : null,
      discountEnabled: !!((document.getElementById("rc-disc-on") || {}).checked),
      // Only a typed percentage travels: an empty field leaves
      // the stored choice alone (0 is not a settable percent).
      ...(discPct !== null ? { discountPct: discPct } : {}),
      comeBackPassEnabled: !!((document.getElementById("rc-pass-on") || {}).checked),
      proofSharing: !!((document.getElementById("rc-share-on") || {}).checked),
    });
    state.user = data.user;
    if (note) note.textContent = "Saved. These run under every visit from here.";
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
function receiptBookTop() {
  const top = state._receiptTop;
  if (top && typeof sigB1Start === "function") { sigB1Start({ creatorId: top.creatorId, creatorName: top.creatorName, creatorRate: null, creatorTier: null }); return false; }
  return go("dashboard", "Find Creators");
}
// ---------- Build -39: ROAS Score v2 on the Receipt ----------
// The headline block: the counted floor first, the score with
// its sentence, the came-back line, every cost itemized, media
// value on its own labeled line, tallies as facts. Forming is
// a normal first-month state and says exactly what is missing.
function compCostDefaultClient(category) {
  const d = (state.user && state.user.business && state.user.business.compCostDefaults) || null;
  if (!d) return null;
  if (category && d.byCategory && typeof d.byCategory[category] === "number") return d.byCategory[category];
  return typeof d.default === "number" ? d.default : null;
}
async function saveVisitCompCost(bookingId) {
  const amtEl = document.getElementById(`v2-cost-${bookingId}`);
  const zeroEl = document.getElementById(`v2-zero-${bookingId}`);
  const note = document.getElementById(`v2-cost-note-${bookingId}`);
  const body = zeroEl && zeroEl.checked ? { confirmedZero: true } : { amount: amtEl && amtEl.value !== "" ? Number(amtEl.value) : null };
  if (!zeroEl || !zeroEl.checked) { if (body.amount === null || !Number.isFinite(body.amount)) { if (note) note.textContent = "Enter the cost, or check the box if it genuinely cost you nothing."; return; } }
  try {
    await api("POST", `/bookings/${bookingId}/comp-cost`, body);
    if (note) note.textContent = "Saved. Your score updates with it.";
    loadReceipt();
  } catch (e) { if (note) note.textContent = e.message; }
}
function v2CostCaptureHtml(v) {
  const dflt = compCostDefaultClient(v.category);
  return `<div class="form-2col" style="margin-top:6px">
    <div class="field"><label>What did it cost you, at your cost? ($)</label><input type="number" id="v2-cost-${v.bookingId}" min="0" step="0.01" placeholder="At your cost" value="${dflt !== null ? dflt : ""}"></div>
    <div class="field"><label>&nbsp;</label><button class="btn small-btn" type="button" onclick="saveVisitCompCost('${v.bookingId}')">${dflt !== null ? `Confirm $${fmtMoney(dflt)}` : "Save its cost"}</button></div>
  </div>
  <label class="ckrow small"><input type="checkbox" class="ckbox" id="v2-zero-${v.bookingId}"><span>It genuinely cost us nothing</span></label> <span class="small" id="v2-cost-note-${v.bookingId}"></span>`;
}
// ---------- Build -43: ROAS presentation ----------
// The Score v2 math did not change. What changed is the
// presentation: visual numbers first, prose second, an info
// button on every figure, and tap-to-expand detail. The info
// text is one or two plain sentences per figure: what it is
// and how it is counted. The popover mirrors the offer form's
// info sheet.
const ROAS_INFO = {
  score: { title: "Your SIGNL ROAS Score", body: "For every $1 your month cost you, all in, this is how many dollars came back. It blends two labeled parts: dollars counted at your register, and Halo's estimate of the visits the posts likely brought in that no code caught. The counted part always prints on its own, with its own score, in the split right under the headline, so you can hold us to either number." },
  back: { title: "Counted back", body: "Check totals your team logged at the register with a creator's code: first visits and came-backs, every one time-stamped. Customers who came in without a code are not in this number, so the real figure is higher." },
  putin: { title: "All in", body: "Everything the month cost you: your plan at what you actually paid, comps at your cost, paid creators at their rate plus your fee share, and code discounts your customers used. Nothing else is in it, and no cost is ever estimated for you." },
  week: { title: "Counted by week", body: "Every check total your team logged, grouped by the week it was rung at your register. Your score groups the same dollars by the visits that earned them; this chart groups them by when they were rung." },
  cameback: { title: "Came-backs", body: "A counted first customer gets a pass, good for a return visit within 30 days. When they come back and spend, it counts here, at full price unless you chose a perk. The rate prints on first customers whose 30 days have closed, so it never rests on a window still running." },
  costs: { title: "What it cost, all in", body: "Every cost inside your score, itemized: your plan at what you actually paid, comps at your cost, paid creators, and code discounts as they were redeemed. A discount is figured on the full check, before the discount comes off." },
  media: { title: "The posts, priced as media", body: "What this month's posts would cost at our published rates. It is a model, not register money, so it rides on its own line and never enters your score." },
  tally: { title: "Your reported tally", body: "Numbers your team reported as one total instead of check by check. They print here as facts. Your score counts register events only, so a tally never enters the number." },
  months: { title: "Your months", body: "A score belongs to the month whose visits earned it, and the plan counts once, whole, in that month. Tap a month to see its counted events and its all-in cost." },
  visits: { title: "Visits, scored", body: "Each visit's counted register dollars against what that visit itself cost you, before your plan. Tap a visit for its counted customers, its cost, and how its number was counted." },
  creators: { title: "Who brought them", body: "Each creator's counted register dollars against their own visits' costs, before your plan. Tap a creator for their visits, customers, and came-backs. It is counted the same way for every creator." },
  forming: { title: "Why there is no score yet", body: "A score prints when a month has enough counted at the register to mean something: at least 3 visits counted at the register, at least 10 register events, every visit's cost on record, and your plan charge on record. Until then, you see the counted dollars themselves." },
};
function roasInfoBtn(topic) {
  return `<button type="button" class="info-btn" aria-label="About this number" onclick="return showRoasInfo('${topic}')">i</button>`;
}
function showRoasInfo(topic) {
  const info = ROAS_INFO[topic];
  const pop = document.getElementById("roas-info-pop");
  if (!info || !pop) return false;
  document.getElementById("roas-info-title").textContent = info.title;
  document.getElementById("roas-info-body").textContent = info.body;
  pop.style.display = "";
  return false;
}
function closeRoasInfo() {
  const pop = document.getElementById("roas-info-pop");
  if (pop) pop.style.display = "none";
  return false;
}
function roasInfoPopHtml() {
  return `<div id="roas-info-pop" class="sheet-overlay" style="display:none" onclick="if(event.target===this) closeRoasInfo()">
    <div class="sheet">
      <div class="flex-between"><strong id="roas-info-title"></strong><button type="button" class="linklike" onclick="return closeRoasInfo()">Close</button></div>
      <p class="small" id="roas-info-body"></p>
    </div>
  </div>`;
}
// The versus bars are segment stacks, not single fills: each
// row renders one or more { amount, cls } segments into one
// track, widths against the shared max, the row total being the
// segments' sum. A later component can stack into a row as one
// more segment with its own class, with no markup change here.
// Today the Back row carries exactly one segment (counted) and
// the All in row one (in).
function roasBarRow(label, topic, segments, max) {
  const segs = (segments || []).filter((sg) => sg && Number(sg.amount) > 0);
  const total = segs.reduce((a, sg) => a + Number(sg.amount), 0);
  const fills = segs.map((sg) => {
    const pct = max > 0 ? Math.max(2, Math.round((Number(sg.amount) / max) * 100)) : 0;
    return `<i class="${sg.cls || "counted"}" style="width:${pct}%"></i>`;
  }).join("");
  return `<div class="roas-vs-row"><div class="roas-vs-head"><span>${label} ${roasInfoBtn(topic)}</span><strong>$${fmtMoney(total)}</strong></div><div class="roas-bar stack">${fills}</div></div>`;
}
function roasWeekChart(weeks) {
  if (!weeks || !weeks.length) return "";
  const max = Math.max(...weeks.map((w) => w.total), 0);
  if (max <= 0) return "";
  const cols = weeks.map((w) => {
    const h = Math.max(3, Math.round((w.total / max) * 84));
    // Chart labels run compact (whole dollars when whole): at
    // phone width five full-cent labels collide with each other.
    const v = Number.isInteger(w.total) ? "$" + fmtNum(w.total) : "$" + fmtMoney(w.total);
    return `<div class="roas-wk"><span class="roas-wk-v">${w.total > 0 ? v : "&nbsp;"}</span><div class="roas-wk-bar" style="height:${h}px"></div><span class="roas-wk-l">${esc(w.label)}</span></div>`;
  }).join("");
  return `<div class="roas-wks">${cols}</div>`;
}
// How SIGNL gets credit (Build -43): the counting chain in
