// One-tap coaching fixes (the 48 hour nudge): raise the comp by
// $25, or widen the redemption window by 3 days. Both go through
// the same PATCH the composer uses, so the dignity floor and the
// window rules apply identically.
async function fixOffer(offerId, fix) {
  try {
    const data = await api("GET", "/offers");
    const o = (data.offers || []).find((x) => x.id === offerId);
    if (!o) { alert("That offer is no longer editable."); return; }
    if (fix === "raise") {
      await api("PATCH", `/offers/${offerId}`, o.kind === "paid" ? { cashRate: Number(o.cashRate) + 25 } : { dollarCap: Number(o.dollarCap) + 25 });
      alert("Comp raised by $25. Offers priced in the typical range for their tier fill first.");
    } else {
      const end = new Date(Date.parse(o.windowEndAt) + 3 * 24 * 3600 * 1000).toISOString();
      await api("PATCH", `/offers/${offerId}`, { windowEndAt: end });
      alert("Redemption window widened by 3 days.");
    }
    if (state.tab === "Home") loadBusinessHome(); else loadMyOffers();
  } catch (err) { alert(err.message); }
}

// One-tap rebook: the server prefills a direct offer from the
// last delivered visit with this creator; the composer opens on
// the new offer's list so the business can adjust before it is
// live... the offer is created open, matching "invite again"
// speed; the business can close it from My Offers any time.
async function rebookCreator(creatorId) {
  try {
    await api("POST", "/offers/rebook", { creatorId });
    state.tab = "My Offers";
    render();
    setTimeout(() => alert("Invite sent. It is prefilled from your last visit together and lives under Your campaigns."), 50);
  } catch (err) { alert(err.message); }
}

// Favorites view: the saved roster, favorites first-class. The
// heart on every discovery card toggles the same records.
async function loadFavorites() {
  const el = document.getElementById("tab-body");
  try {
    const data = await api("GET", "/favorites");
    const favHead = `${wsHead("Find creators", { sub: "Your saved creators. One tap invites them again, prefilled from your last visit together.", subKey: "biz-discover" })}${wsTabs([
      { label: "Discover", on: false, onclick: "return go('dashboard','Discover')" },
      { label: "Favorites", on: true, onclick: "return go('dashboard','Favorites')" },
    ])}`;
    if (!data.favorites.length) {
      el.innerHTML = `${favHead}<div class="empty-card"><div class="ec-t">No favorites yet</div><div class="ec-s">Tap the heart on any creator while browsing Find creators and they are saved here: your standing roster for repeat visits.</div></div><p class="center"><button class="btn ws-primary" onclick="return go('dashboard','Discover')">Browse creators</button></p>`;
      return;
    }
    el.innerHTML = `${favHead}
    <div class="creator-grid">${data.favorites.map((c) => `<div>${creatorCard(c, state.user)}<button class="btn small-btn mt" style="width:100%" onclick="rebookCreator('${c.userId}')">Invite again</button></div>`).join("")}</div>`;
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}

// Category selection lives in the chip row and nowhere else
// (Jeff, 2026-10-28): there is no Category control in the More
// filters fold anymore. The chips are MULTI-SELECT: a tap toggles
// the category in or out of state.discoverCats, results match ANY
// selected category (OR), and the "All" chip clears the set (it is
// the active chip exactly when the set is empty).
function discoverCatChip(cat, btn) {
  if (cat === "") {
    state.discoverCats = [];
  } else {
    const set = new Set(state.discoverCats || []);
    if (set.has(cat)) set.delete(cat); else set.add(cat);
    state.discoverCats = [...set];
  }
  syncDiscoverCatChips();
  runDiscover();
  return false;
}

// Re-paint chip states from state.discoverCats: "All" is on when
// the set is empty, each category chip is on when it is in the
// set. The Spanish-speaking toggle is not a category chip and is
// untouched here; it keeps its own independent state.
function syncDiscoverCatChips() {
  const set = new Set(state.discoverCats || []);
  document.querySelectorAll(".dcat-chip[data-cat]").forEach((b) => {
    const c = b.getAttribute("data-cat");
    b.classList.toggle("on", c === "" ? set.size === 0 : set.has(c));
  });
}

// Spanish-speaking creators toggle (Jeff, 2026-10-28): independent
// of the category chips; it narrows Discover to creators who make
// content in Spanish. The control spells that out in full ("Spanish-
// speaking creators only") because the earlier bare "Español" chip
// under a "Language" label read as a site-language switcher.
function discoverSpanishChip(btn) {
  state.discoverSpanish = !state.discoverSpanish;
  if (btn) {
    btn.classList.toggle("on", !!state.discoverSpanish);
    btn.setAttribute("aria-pressed", state.discoverSpanish ? "true" : "false");
  }
  runDiscover();
  return false;
}

// Musicians toggle (Sig activation, Jeff, 2026-10-28): the
// sibling of the Spanish toggle, same control, same grammar.
// The toggle itself rides the musician attribute (mode "1");
// Sig's idea prompts may set the "perform"/"create" modes,
// which this toggle reflects as on and a tap clears.
function discoverMusicianChip(btn) {
  state.discoverMusician = state.discoverMusician ? "" : "1";
  if (btn) {
    btn.classList.toggle("on", !!state.discoverMusician);
    btn.setAttribute("aria-pressed", state.discoverMusician ? "true" : "false");
  }
  runDiscover();
  return false;
}

// ---------- Build -91: wishlist, roster alerts, proof kit ----------
// Sig queue items from the wishlist / roster-digest notes the
// server writes (the email is the other half of each alert).
function sigAlertNotes(notes) {
  return (notes || []).filter((n) => n && !n.readAt && ["wishlist_ready", "wishlist_claimed", "roster_digest"].includes(n.kind));
}
function sigAlertAction(n) {
  const d = n.data || {};
  if (n.kind === "wishlist_ready" && d.creatorId) return { btn: "Invite to draft", act: () => startOffer(d.creatorId), short: "Wishlist creator ready" };
  if (n.kind === "wishlist_claimed") return { btn: "See wishlist", act: () => go("dashboard", "Discover"), short: "Wishlist creator joined" };
  return { btn: "Find creators", act: () => go("dashboard", "Discover"), short: "New creators this week" };
}

// The wishlist section inside Find creators (no new rail item):
// the business's own list, its private notes, and the match state
// of each row, straight from GET /me/wishlist.
async function loadWishlistSection() {
  const el = document.getElementById("biz-wishlist");
  if (!el) return;
  try {
    const d = await api("GET", "/me/wishlist");
    renderWishlistSection(d.wishlist || []);
  } catch (e) {
    el.innerHTML = "";
  }
}
function wishlistRowHtml(row) {
  const chip = row.state === "ready" ? `<span class="badge ok">Ready to invite</span>`
    : row.state === "claimed" ? `<span class="badge">On SIGNL, finishing their profile</span>`
    : `<span class="badge warn">Not on SIGNL yet</span>`;
  const hint = row.state === "waiting" ? `<p class="small muted" style="margin:2px 0 0">We email you when they claim their profile, and again when it is finished.</p>`
    : row.state === "claimed" ? `<p class="small muted" style="margin:2px 0 0">We email you when their profile is finished and they are ready to invite.</p>` : "";
  return `<div style="display:flex;gap:8px 10px;flex-wrap:wrap;align-items:flex-start;padding:10px 0;border-top:1px solid var(--line,#e6e6e6)">
    <div style="flex:1 1 230px;min-width:0">
      <div><strong>@${esc(row.handle)}</strong> ${chip}</div>
      ${row.note ? `<p class="small muted" style="margin:2px 0 0">Your note: ${esc(row.note)}</p>` : ""}
      ${hint}
    </div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end">
      ${row.state === "ready" ? `<button class="btn small-btn" type="button" onclick="return wishlistInvite('${row.creatorId}')">Invite to draft</button><button class="btn small-btn ghost" type="button" onclick="return wishlistSave('${row.creatorId}', this)">Save</button>` : ""}
      <button class="btn small-btn ghost" type="button" onclick="return wishlistRemove('${esc(row.handle)}')">Remove</button>
    </div>
  </div>`;
}
function renderWishlistSection(rows) {
  const el = document.getElementById("biz-wishlist");
  if (!el) return;
  el.innerHTML = `<section class="wcard" style="margin:14px 0">
    <h3 style="margin-top:0">Your wishlist</h3>
    <p class="small muted" style="margin-top:0">The creators you already want, from your own list. Paste their handles below, one per line, with your private note after a comma if you keep one. Your notes stay yours: creators never see them, and no other business can. We email you when someone on your list joins SIGNL, and again when their profile is finished.</p>
    ${rows.length ? rows.map(wishlistRowHtml).join("") : `<p class="small muted">No one on your wishlist yet.</p>`}
    <div class="field" style="margin-top:10px"><label>Add creators (one per line, note after a comma)</label><textarea id="wl-paste" rows="4" placeholder="@creatorone, loves our weekend brunch crowd&#10;@creatortwo"></textarea></div>
    <button class="btn small-btn" type="button" onclick="return wishlistImport()">Add to wishlist</button> <span class="small muted" id="wl-note"></span>
  </section>`;
}
async function wishlistImport() {
  const ta = document.getElementById("wl-paste");
  const note = document.getElementById("wl-note");
  if (!ta || !ta.value.trim()) { if (note) note.textContent = "Paste at least one handle first."; return false; }
  try {
    const d = await api("POST", "/me/wishlist", { text: ta.value });
    renderWishlistSection(d.wishlist || []);
    const n2 = document.getElementById("wl-note");
    if (n2) n2.textContent = "Saved. Matching runs right away, and we email you when someone joins or finishes.";
  } catch (e) { if (note) note.textContent = e.message; }
  return false;
}
async function wishlistRemove(handle) {
  try {
    const d = await api("DELETE", "/me/wishlist/" + encodeURIComponent(handle));
    renderWishlistSection(d.wishlist || []);
  } catch (e) { alert(e.message); }
  return false;
}
function wishlistInvite(creatorId) {
  startOffer(creatorId);
  return false;
}
async function wishlistSave(creatorId, btn) {
  try {
    const d = await api("POST", "/favorites", { creatorId });
    if (btn) btn.textContent = d.isFavorite ? "Saved" : "Save";
  } catch (e) { alert(e.message); }
  return false;
}

// ---------- Build -99: the ONE business setup checklist ----------
// Home used to carry three setup surfaces at once (the -74
// start-here cards, the launch checklist, and the -91 proof
// kit card), with the Square connect buried in Results. They
// are one surface now: this checklist, rendered from
// GET /me/setup-checklist (or the business-home payload),
// every item computed server-side from real stored state.
// The four proof-kit steps are items here. When all nine are
// done the server says allDone and this renders nothing: the
// surface retires. Each item's button runs the step or lands
// on the real surface where the step lives (SIG LINKING RULE).
function setupChecklistHtml(cl) {
  if (!cl || cl.allDone) return "";
  const reg = cl.register || {};
  const btnFor = (s) => {
    if (s.done) return s.id === "square" ? `<button class="btn small-btn ghost" type="button" onclick="return setupGoRegister()">Manage register</button>` : "";
    if (s.id === "square") {
      if (reg.state === "paused") return `<a class="btn small-btn" href="/api/me/square/start">Reconnect Square</a>`;
      if (!reg.configured) return `<button class="btn small-btn" type="button" onclick="return setupGoRegister()">See how it works</button>`;
      return `<a class="btn small-btn" href="/api/me/square/start">Connect Square</a>`;
    }
    if (s.id === "baseline") return `<button class="btn small-btn" type="button" onclick="return setupGoBaseline()">Set the usual day</button>`;
    if (s.id === "pin") return `<button class="btn small-btn" type="button" onclick="return go('dashboard','Settings')">Set the PIN</button>`;
    if (s.id === "counter_card") return `<button class="btn small-btn" type="button" onclick="return setupPrintCard()">Print the card</button>`;
    if (s.id === "test_redemption") return `<button class="btn small-btn" type="button" onclick="return setupTestRedeem(this)">Run the test</button>`;
    if (s.id === "till") return `<button class="btn small-btn ghost" type="button" onclick="return go('dashboard','Profile')">Change</button>`;
    if (s.id === "page") return `<button class="btn small-btn" type="button" onclick="return go('dashboard','Profile')">Finish my page</button>`;
    if (s.id === "hours") return `<button class="btn small-btn" type="button" onclick="return go('dashboard','Profile')">Set my hours</button>`;
    if (s.id === "creators") return `<button class="btn small-btn" type="button" onclick="return go('dashboard','Discover')">Find creators</button>`;
    if (s.id === "campaign") return `<button class="btn small-btn" type="button" onclick="return go('dashboard','Campaign Setup')">Set up a campaign</button>`;
    return "";
  };
  const squareNote = (s) => {
    if (s.id !== "square" || s.done) return "";
    if (reg.state === "paused") return `<p class="small" style="margin:4px 0 0"><strong>Register paused.</strong> Square stopped sharing checks. Your codes still count at the till.</p>`;
    if (!reg.configured) return `<p class="small muted" style="margin:4px 0 0">On our setup call, we plug into your register with you: one tap on your end. Until then your codes count on the register you already have.</p>`;
    if (reg.env === "sandbox") return `<p class="small" style="margin:4px 0 0"><span class="badge">Square sandbox: a test register, not a live one</span></p>`;
    return "";
  };
  return `<section class="wcard" id="setup-checklist" style="margin-top:14px">
    <p class="ui-kicker" style="margin:0">Finish setting up</p>
    <h3 style="margin:2px 0 0">Get the most from SIGNL</h3>
    <p class="wc-sub" style="margin-top:8px">${cl.doneCount} of ${cl.total} done. Each thing here is read from your real records, and this list goes away when all ${cl.total} are done.${cl.firstVisit ? ` Your first booking is confirmed${cl.firstVisit.creatorHandle ? ` with @${esc(cl.firstVisit.creatorHandle)}` : ""}: the register, usual day, PIN, card, and test steps are what make that visit count, and they only work if they are done before the visit.` : ""}</p>
    ${cl.items.map((s) => `<div style="display:flex;gap:10px;align-items:flex-start;margin-top:12px;flex-wrap:wrap">
      <div>${s.done ? `<span class="badge ok">Done</span>` : `<span class="badge warn">To do</span>`}</div>
      <div style="flex:1 1 210px;min-width:0"><strong>${esc(s.label)}</strong><p class="small muted" style="margin:2px 0 0">${esc(s.why)}</p>${squareNote(s)}${s.id === "till" && !s.done ? `<div class="chiprow" style="margin-top:8px">${["square", "clover", "toast", "lightspeed", "other", "none"].map((p) => `<button type="button" class="rchip" onclick="return setupSetPos('${p}')">${p === "other" ? "Another system" : p === "none" ? "No register system" : p[0].toUpperCase() + p.slice(1)}</button>`).join("")}</div><div id="setup-pos-other" style="display:none;margin-top:6px"><input id="setup-pos-other-name" placeholder="Which system?" style="max-width:220px"> <button type="button" class="btn small-btn" onclick="return setupSetPosOther()">Save</button></div>` : ""}</div>
      <div>${btnFor(s)}</div>
    </div>`).join("")}
  </section>`;
}
// Which till (Build -101): the checklist item answers in place.
// Picking a named system saves at once; "Another system" opens
// the name field first. The save is the ordinary profile PATCH,
// so the business page and Sig read the same record.
async function setupSetPos(provider) {
  if (provider === "other") {
    const box = document.getElementById("setup-pos-other");
    if (box) { box.style.display = ""; const inp = document.getElementById("setup-pos-other-name"); if (inp) inp.focus(); }
    return false;
  }
  try {
    const data = await api("PATCH", "/me/profile", { posProvider: provider });
    state.user = data.user;
    render();
  } catch (e) { alert(e.message); }
  return false;
}
async function setupSetPosOther() {
  const name = (document.getElementById("setup-pos-other-name") || {}).value || "";
  try {
    const data = await api("PATCH", "/me/profile", { posProvider: "other", posOther: name });
    state.user = data.user;
    render();
  } catch (e) { alert(e.message); }
  return false;
}
// The register's management (locations, read the register
// now, disconnect, reconnect when paused) lives in Results,
// inside the receipt's settings: go there and open them.
function setupGoRegister() {
  go("dashboard", "Analytics");
  setTimeout(() => {
    const host = document.getElementById("biz-receipt");
    const det = host ? host.querySelector("details") : null;
    if (det) {
      det.open = true;
      det.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }, 450);
  return false;
}
function setupGoBaseline() {
  go("dashboard", "Analytics");
  setTimeout(() => {
    const dayEl = document.getElementById("rc-base-day");
    if (dayEl) {
      const det = dayEl.closest("details");
      if (det) det.open = true;
      dayEl.scrollIntoView({ behavior: "smooth", block: "center" });
      const c = document.getElementById("rc-base-count");
      if (c) c.focus();
    }
  }, 450);
  return false;
}
// The printable counter card: the one question, plus how a
// creator's code gets redeemed at this business's register (the
// same instructions the staff settings carry today).
async function setupPrintCard() {
  try {
    await api("POST", "/me/proof-kit/printed", {});
    const d = await api("GET", "/me/staff");
    const w = window.open("", "_blank", "width=640,height=760");
    if (!w) { alert("Allow pop-ups to print the counter card."); return false; }
    const origin = location.origin;
    w.document.write(`<!DOCTYPE html><html><head><title>SIGNL counter card</title>
    <style>body{font-family:Arial,sans-serif;text-align:center;padding:36px;color:#0B0D0C}img.logo{height:54px}.biz{font-size:22px;font-weight:700;margin:10px 0 2px}.big{font-size:32px;font-weight:800;letter-spacing:0.01em;margin:22px 0 6px}.line{font-size:17px}.rule{border-top:2px solid #0B0D0C;margin:26px 0}.code{font-family:monospace;font-size:19px;font-weight:700;letter-spacing:0.12em}.muted{color:#666;font-size:13px}</style></head>
    <body>
      <img class="logo" src="${origin}/assets/logo.png" alt="SIGNL">
      <div class="biz">${esc(d.businessName || "")}</div>
      <div class="big">"First time in? How'd you hear about us?"</div>
      <p class="line">Ask it at the natural moment, ringing up or seating. When a creator or a post comes up, that answer counts.</p>
      <div class="rule"></div>
      <p class="line"><strong>Here with a SIGNL visit code?</strong><br>Show your code at the register.</p>
      <p class="muted">Staff: open <strong>${esc(d.staffLink || "")}</strong>, enter the staff PIN, then enter the creator's code. That tap is what counts the visit.<br>Business code: <span class="code">${esc(d.staffCode || "")}</span></p>
    </body></html>`);
    w.document.close();
    w.focus();
    setTimeout(() => { try { w.print(); } catch (e) { /* the card is on screen either way */ } }, 450);
    setTimeout(() => { try { render(); } catch (e) { /* stay put if render is unavailable */ } }, 700);
  } catch (e) { alert(e.message); }
  return false;
}
async function setupTestRedeem(btn) {
  if (btn) { btn.disabled = true; btn.textContent = "Running the test..."; }
  try {
    await api("POST", "/me/proof-kit/test-redeem", {});
    render();
  } catch (e) {
    alert(e.message);
    if (btn) { btn.disabled = false; btn.textContent = "Run the test"; }
  }
  return false;
}

async function loadDiscover() {
  const el = document.getElementById("tab-body");
  const u = state.user;
  // Build -68: a founding business got the ranking line and the
  // honest roster note up top. Build -74: EVERY business lands
  // on the card deck (Jeff: finding creators should feel fun,
  // not like scrolling); the grid stays one tap away behind
  // "See everyone". The mode is only defaulted, never forced.
  const foundingDisc = isFoundingBusiness(u);
  el.innerHTML = `
    ${wsHead("Find creators", { sub: "Flip through micro-influencers near you. Invite the ones who fit.", subKey: "biz-discover" })}
    ${wsTabs([
      { label: "Discover", on: true, onclick: "return go('dashboard','Discover')" },
      { label: "Favorites", on: false, onclick: "return go('dashboard','Favorites')" },
    ])}
    ${foundingDisc ? `<p class="small" style="margin:10px 0 0"><strong>Ranked by how local their audience is, not by follower count.</strong></p>
    <p class="small muted" style="margin:4px 0 0">${esc(foundingBizPlace(u))}'s founding roster is still joining. New creators show up here as they finish their pages.</p>` : ""}
    <div class="filters disc-top">
      <div><label>Market</label><select id="f-market">${marketOptions(u.market)}</select></div>
    </div>
    <div class="dspan-row"><button type="button" id="dchip-spanish" class="dspan-toggle${state.discoverSpanish ? " on" : ""}" aria-pressed="${state.discoverSpanish ? "true" : "false"}" onclick="return discoverSpanishChip(this)"><span class="dspan-check" aria-hidden="true">&#10003;</span><span class="dspan-main">Spanish-speaking creators only</span><span class="dspan-sub">Makes content in Spanish</span></button><button type="button" id="dchip-musician" class="dspan-toggle${state.discoverMusician ? " on" : ""}" style="margin-left:8px" aria-pressed="${state.discoverMusician ? "true" : "false"}" onclick="return discoverMusicianChip(this)"><span class="dspan-check" aria-hidden="true">&#10003;</span><span class="dspan-main">Musicians only</span><span class="dspan-sub">Creators who make music</span></button></div>
    <div class="dcat-row"><button type="button" data-cat="" class="dcat-chip${(state.discoverCats || []).length ? "" : " on"}" onclick="return discoverCatChip('', this)">All</button>${state.boot.creatorCategories.map((c) => `<button type="button" data-cat="${esc(c)}" class="dcat-chip${(state.discoverCats || []).includes(c) ? " on" : ""}" onclick="return discoverCatChip('${esc(c)}', this)">${esc(c)}</button>`).join("")}</div>
    <details class="filters-fold"><summary>More filters</summary>
    <div class="filters">
      <div><label>Neighborhood / area</label><input id="f-neighborhood" placeholder="For example: Oceanfront, Ghent"></div>
      <div><label>Tier</label><select id="f-tier"><option value="">All tiers</option>${state.boot.tiers.map((t) => `<option>${esc(t.id)}</option>`).join("")}</select></div>
      <div><label>Search</label><input id="f-q" placeholder="Name or handle"></div>
      <div><label>University (current students)</label><select id="f-university"><option value="">All universities</option>${state.discoverUniversity ? `<option selected>${esc(state.discoverUniversity)}</option>` : ""}</select></div>
    </div>
    <div class="filters">
      <div><label>Would accept (comp fit)</label><select id="f-comp"><option value="">Any comp</option>${state.boot.compCategories.map((c) => `<option>${esc(c)}</option>`).join("")}</select></div>
      <div><label>Total audience min</label><input type="number" id="f-fmin" min="0" placeholder="Any"></div>
      <div><label>Total audience max</label><input type="number" id="f-fmax" min="0" placeholder="Any"></div>
      <div><label>Min % followers in market</label><input type="number" id="f-minlocal" min="0" max="100" placeholder="Any"></div>
      <div><label>Sort by</label><select id="f-sort"><option value="">Founding order</option><option value="score">Local Impact Score</option><option value="momentum">Momentum (roster standing)</option><option value="fit">Best fit</option></select></div>
      <div><label>&nbsp;</label><label style="font-weight:500"><input type="checkbox" id="f-paid" style="width:auto"> Has a paid rate (paid bookings) only</label></div>
      <div><label>&nbsp;</label><button class="btn small-btn" style="width:100%" onclick="runDiscover()">Search</button></div>
    </div>
    </details>
    <div id="discover-toggle"></div>
    <div id="biz-wishlist"></div>
    <div id="discover-results">${skelHtml("Loading creators...", 2)}</div>`;
  runDiscover();
  loadWishlistSection();
}

// Campus filter options (U1): the server facet lists the
// universities with current-student roster creators in the
// selected market. Rebuild the select from each response; a
// selection that is not in the facet (the market changed, the
// school's students left the roster) resets to All universities
// instead of silently filtering to zero.
function syncUniversityOptions(facet) {
  const sel = document.getElementById("f-university");
  if (!sel) return;
  const names = (facet || []).map((f) => f.name);
  const keep = state.discoverUniversity && names.includes(state.discoverUniversity) ? state.discoverUniversity : "";
  state.discoverUniversity = keep;
  sel.innerHTML = `<option value="">All universities</option>` + (facet || []).map((f) => `<option value="${esc(f.name)}"${f.name === keep ? " selected" : ""}>${esc(f.name)} (${f.count})</option>`).join("");
}

async function runDiscover() {
  await ensureDeckState();
  const el = document.getElementById("discover-results");
  const params = new URLSearchParams();
  const market = document.getElementById("f-market").value;
  const tier = document.getElementById("f-tier").value;
  // Category comes from the chip row alone (multi-select set),
  // sent as one comma-separated list the server ORs.
  const cats = state.discoverCats || [];
  const q = document.getElementById("f-q").value;
  if (market) params.set("market", market);
  if (tier) params.set("tier", tier);
  if (cats.length) params.set("category", cats.join(","));
  if (q) params.set("q", q);
  const neighborhood = document.getElementById("f-neighborhood").value.trim();
  const comp = document.getElementById("f-comp").value;
  const fmin = document.getElementById("f-fmin").value;
  const fmax = document.getElementById("f-fmax").value;
  const minlocal = document.getElementById("f-minlocal").value;
  const sort = document.getElementById("f-sort").value;
  if (neighborhood) params.set("neighborhood", neighborhood);
  if (comp) params.set("compCategory", comp);
  if (fmin) params.set("followersMin", fmin);
  if (fmax) params.set("followersMax", fmax);
  if (minlocal) params.set("minLocalPct", minlocal);
  if (sort) params.set("sort", sort);
  if (document.getElementById("f-paid").checked) params.set("paid", "1");
  if (state.discoverSpanish) params.set("spanish", "1");
  if (state.discoverMusician) params.set("musician", state.discoverMusician);
  const uniSel = document.getElementById("f-university");
  state.discoverUniversity = uniSel ? uniSel.value : (state.discoverUniversity || "");
  if (state.discoverUniversity) params.set("university", state.discoverUniversity);
  try {
    const data = await api("GET", "/discover?" + params.toString());
    state.discover = data.creators;
    syncUniversityOptions(data.universities);
    if (!data.creators.length) {
      el.innerHTML = `<div class="empty-state"><span class="es-badge"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.4 7.2L22 12l-7.6 2.8L12 22l-2.4-7.2L2 12l7.6-2.8z"/></svg></span><h3>No approved creators match yet</h3><p>SIGNL is building the founding roster in this market now. Creators who sign up and get approved will appear here automatically.</p></div>`;
      return;
    }
    const tg = document.getElementById("discover-toggle");
    if (tg) tg.innerHTML = discoverModeToggleHtml();
    renderDiscoverResults();
  } catch (err) {
    el.innerHTML = `<div class="error-box">${esc(err.message)}</div>`;
  }
}

// ---------- V5: Discover as a card stack (Jeff, 2026-10-25) ----------
// Tinder-feel browsing over the SAME results, eligibility and
// actions: Invite is startOffer (the existing direct-offer flow),
// tap opens the existing profile view, a pass parks the creator
// in the business's Later pile. Cards is the default; List renders
// the exact card grid Discover has always rendered.
function discoverModeToggleHtml() {
  const mode = state.discoverMode || "cards";
  return `<div class="view-toggle"><div class="vt-group"><button type="button" class="rchip${mode === "cards" ? " on" : ""}" onclick="setDiscoverMode('cards')">Cards</button><button type="button" class="rchip${mode === "list" ? " on" : ""}" onclick="setDiscoverMode('list')">See everyone</button></div>${deckChromeHtml("discover")}<span class="stack-pos" data-stackpos="discover"></span></div>${deckTeachHtml("discover")}`;
}
// Build -74 deck save: the same favorites store the grid's
// heart writes (POST /favorites toggles server-side), so a
// creator saved in the deck shows in Favorites and on grid
// cards alike. Local state flips first; the deck stays put.
async function deckToggleFav(c) {
  const was = !!c.isFavorite;
  c.isFavorite = !was;
  try {
    const d = await api("POST", "/favorites", { creatorId: c.userId });
    if (d && typeof d.isFavorite === "boolean") c.isFavorite = d.isFavorite;
    showToast(c.isFavorite ? "Saved to your favorites" : "Removed from favorites");
  } catch (e) {
    c.isFavorite = was;
    alert(e.message);
  }
  const wrap = document.querySelector('[data-stack="discover"]');
  if (wrap) renderStack(wrap);
}
function setDiscoverMode(mode) {
  state.discoverMode = mode;
  const tg = document.getElementById("discover-toggle");
  if (tg) tg.innerHTML = discoverModeToggleHtml();
  renderDiscoverResults();
  return false;
}
function renderDiscoverResults() {
  const el = document.getElementById("discover-results");
  if (!el) return;
  const all = state.discover || [];
  if (!all.length) return; // runDiscover already rendered the empty state
  const q = deckQueue("discover", all);
  if (!q.visible.length) {
    const pos = document.querySelector('[data-stackpos="discover"]');
    if (pos) pos.textContent = "";
    el.innerHTML = `<div class="stk-end"><h3>Nothing new in this search</h3><p class="small muted">Everyone here is parked in your Later pile or hidden.</p><div class="stk-end-actions">${q.parked.length ? `<button type="button" class="btn ghost" onclick="openLaterPile('discover')">Review Later${q.parked.length >= 10 ? ` (${q.parked.length})` : ""}</button>` : ""}<button type="button" class="btn" onclick="discoverClearFilters()">Clear filters</button></div></div>`;
    syncDeckChrome("discover");
    return;
  }
  if ((state.discoverMode || "cards") === "list") {
    const pos = document.querySelector('[data-stackpos="discover"]');
    if (pos) pos.textContent = "";
    el.innerHTML = discoverListHtml(q.visible);
    syncDeckChrome("discover");
    return;
  }
  if (!stackState.discover || stackState.discover.src !== all) {
    // Build -74: the deck runs in canon rank order, highest
    // local % first (unreported local % last), whatever order
    // the server returned. The grid keeps its own order.
    const ranked = [...all].sort((a, b) => {
      const pa = (a.profile || {}).localAudiencePct;
      const pb = (b.profile || {}).localAudiencePct;
      return (pb === null || pb === undefined ? -1 : pb) - (pa === null || pa === undefined ? -1 : pa);
    });
    stackState.discover = startDeck("discover", ranked, {
      cardHtml: (c) => discoverStackCard(c),
      goLabel: "Invite",
      passLabel: "Next",
      onGo: (c) => { pileUnlater("discover", c.userId); startOffer(c.userId); },
      onPass: (c) => { pileLater("discover", c.userId); },
      onTap: (c) => { openCreatorProfile(c.userId); },
      onSave: (c) => { deckToggleFav(c); },
      saveOf: (c) => !!c.isFavorite,
      endHtml: (passed, total) => discoverEndHtml(passed, total),
    });
    // startDeck marks src as the array it was handed; the
    // re-render guard above compares against the raw result
    // set, so pin src back to it.
    stackState.discover.src = all;
  }
  el.innerHTML = `<div class="stk-wrap" data-stack="discover"></div>`;
  renderStack(el.firstElementChild);
  syncDeckChrome("discover");
}
// List mode grouping (Build -31): when the server banded any
// card for this business, the list groups by distance band in
// band order, with everyone unbanded after. Band headings carry
// no counts. Without bands (no ZIP on file, or nobody in range)
// the list renders exactly as before.
function discoverListHtml(list) {
  const bands = ["Same neighborhood", "Under 2 miles", "Under 5 miles"];
  if (!list.some((c) => c.distanceBand)) {
    return `<div class="creator-grid vx-stagger">${list.map((c) => creatorCard(c, state.user)).join("")}</div>`;
  }
  const groups = bands.map((b) => ({ band: b, items: list.filter((c) => c.distanceBand === b) })).filter((g) => g.items.length);
  const rest = list.filter((c) => !c.distanceBand);
  return groups.map((g) => `<div class="band-group"><h3 class="band-h">${esc(g.band)}</h3><div class="creator-grid vx-stagger">${g.items.map((c) => creatorCard(c, state.user)).join("")}</div></div>`).join("")
    + (rest.length ? `<div class="band-group"><h3 class="band-h">Everyone else in ${esc(marketTalkNameClient(state.user.market))}</h3><div class="creator-grid vx-stagger">${rest.map((c) => creatorCard(c, state.user)).join("")}</div></div>` : "");
}
function discoverStackCard(c) {
  const p = c.profile || {};
  const initial = esc((c.name || "?").trim().charAt(0).toUpperCase() || "?");
  const cats = (p.categories || []).slice(0, 3);
  const extra = (p.categories || []).length - cats.length;
  const place = [c.neighborhood, c.city].filter(Boolean).map(esc).join(" &middot; ");
  const rateLine = p.compOpen === false ? "Paid visits only" : (p.paidRate ? `Listed rate ${currencySymbolForMarket(p.market)}${fmtPrice(p.paidRate)}` : "Comp friendly");
  const thumbs = (Array.isArray(c.photos) && c.photos.length ? c.photos : (c.photoUrl ? [c.photoUrl] : [])).slice(0, 3);
  return `<div class="dcard deck2-card${c.standing === "paused" ? " paused" : ""}">
    <div class="dcard-photo${c.photoUrl ? "" : " no-photo"}">
      ${c.photoUrl ? `<img src="${esc(c.photoUrl)}" alt="">` : `<div class="dcard-mono"><span>${initial}</span></div>`}
      ${p.tierBand ? `<span class="dcard-tier">${esc(p.tierBand)}</span>` : ""}
      ${c.previewPhoto ? `<span class="dcard-sample">Sample photo · preview</span>` : ""}
      <div class="dcard-scrim">
        <div class="dcard-name">${esc(c.name)}</div>
        <div class="dcard-handle">@${esc(p.handle || "")}</div>
        <div class="dcard-local">${p.localAudiencePct === null || p.localAudiencePct === undefined
          ? `<span class="dcard-local-na">Local reach not reported yet</span>`
          : `<span class="dcard-pct">${p.localAudiencePct}%</span><span class="dcard-local-lbl">local reach</span>`}</div>
        <div class="dcard-rate">${rateLine}</div>
      </div>
    </div>
    <div class="dcard-body">
      ${cats.length || p.spanishContent || p.musician ? `<div class="dcard-chips">${cats.map((x) => `<span class="cc-chip">${esc(x)}</span>`).join("")}${extra > 0 ? `<span class="cc-chip">+${extra}</span>` : ""}${p.spanishContent ? `<span class="cc-chip">Spanish content</span>` : ""}${p.musician ? `<span class="cc-chip">Musician</span>` : ""}</div>` : ""}
      <div class="dcard-meta">${place ? `<span>${place}</span>` : ""}<span>${fmtNum(totalAudienceOf(c))} followers</span>${c.distanceBand ? `<span class="dcard-band">${esc(c.distanceBand)}</span>` : ""}</div>
      ${thumbs.length ? `<div class="deck2-thumbs">${thumbs.map((t) => `<img src="${esc(t)}" alt="" loading="lazy">`).join("")}</div>` : ""}
      ${p.spanishAudiencePct !== null && p.spanishAudiencePct !== undefined ? `<div class="dcard-meta"><span>${p.spanishAudiencePct}% Spanish-speaking audience</span></div>` : ""}
      ${c.bookedUp ? `<p class="small muted" style="margin:8px 0 0">Booked up this week — invites still land, accepting reopens next week.</p>` : ""}
      ${c.standing === "paused" ? `<p class="small muted" style="margin:8px 0 0">Paused: a late post is outstanding, so this creator cannot take new offers yet.</p>` : ""}
    </div>
  </div>`;
}
function discoverEndHtml(passed, total) {
  const q = deckQueue("discover", (stackState.discover && stackState.discover.src) || []);
  const n = q.parked.length;
  const seen = q.visible.length;
  return `<div class="stk-end"><h3>You have seen everyone near you for now</h3><p class="small muted">Your Later pile is below, and new creators in ${esc(marketTalkNameClient(state.user.market))} show up here first. You looked through ${seen} creator${seen === 1 ? "" : "s"} in this search.</p><div class="stk-end-actions">${n ? `<button type="button" class="btn ghost" onclick="openLaterPile('discover')">Review Later (${n})</button>` : ""}<button type="button" class="btn" onclick="discoverClearFilters()">Clear filters</button></div></div>`;
}
function discoverClearFilters() {
  ["f-neighborhood", "f-q", "f-fmin", "f-fmax", "f-minlocal"].forEach((id) => { const el = document.getElementById(id); if (el) el.value = ""; });
  ["f-tier", "f-comp", "f-sort"].forEach((id) => { const el = document.getElementById(id); if (el) el.value = ""; });
  const paid = document.getElementById("f-paid");
  if (paid) paid.checked = false;
  state.discoverUniversity = "";
  const uniSel = document.getElementById("f-university");
  if (uniSel) uniSel.value = "";
  state.discoverCats = [];
  syncDiscoverCatChips();
  state.discoverSpanish = false;
  const spChip = document.getElementById("dchip-spanish");
  if (spChip) { spChip.classList.remove("on"); spChip.setAttribute("aria-pressed", "false"); }
  state.discoverMusician = "";
  const muChip = document.getElementById("dchip-musician");
  if (muChip) { muChip.classList.remove("on"); muChip.setAttribute("aria-pressed", "false"); }
  const mkt = document.getElementById("f-market");
  if (mkt && state.user) mkt.value = state.user.market;
  runDiscover();
  return false;
}

async function toggleFav(creatorId) {
  try {
    await api("POST", "/favorites", { creatorId });
    if (state.tab === "Favorites") loadFavorites();
    else if (state.tab === "Discover" || !state.tab) runDiscover();
    else render();
  } catch (err) { alert(err.message); }
}

function goApplicants(offerId) {
  // V3: applicants live in the Offers screen's Applicants
  // segment, filtered to the offer when one is named.
  state.offersSeg = "applicants";
  if (offerId) {
    if (!reqState) reqState = reqFreshState();
    reqState.offerId = offerId;
    reqState.loaded = false;
  }
  state.tab = "My Offers";
  render();
  return false;
}

// Offers segments (spec §5.2): Live / Applicants / Past over
// one screen. Live carries the list, templates and composer;
// Applicants is the Requests workspace; Past is read-only
// except Duplicate.
function renderOffersSegTabs() {
  const host = document.getElementById("offers-segs");
  if (!host) return;
  const all = state.myOffers || [];
  const wc = state.waitCounts || {};
  host.innerHTML = wsTabs([
    { label: "Current", count: all.filter((o) => o.status === "open" || o.status === "filled").length || null, on: state.offersSeg === "live", onclick: "return offersSetSeg('live')" },
    { label: "Drafts", count: all.filter((o) => o.status === "draft").length || null, on: state.offersSeg === "drafts", onclick: "return offersSetSeg('drafts')" },
    { label: "Applicants", count: wc.bizApps || null, on: state.offersSeg === "applicants", onclick: "return offersSetSeg('applicants')" },
    { label: "Past", count: all.filter(offerIsArchived).length || null, on: state.offersSeg === "past", onclick: "return offersSetSeg('past')" },
  ]);
}
function offersSetSeg(seg) {
  state.offersSeg = seg;
  loadMyOffers();
  return false;
}
function offersNew() {
  // Build -97: the composer lives in Set up a campaign.
  if (state.tab === "Campaign Setup") {
    const c = document.getElementById("offer-composer");
    if (c) c.scrollIntoView({ behavior: "smooth" });
    return false;
  }
  return go("dashboard", "Campaign Setup");
}
// Duplicate: the one write allowed from Past — the composer
// opens pre-filled from the old offer.
function duplicateOffer(offerId) {
  const o = (state.myOffers || []).find((x) => x.id === offerId);
  if (!o) return false;
  state.offerTarget = null;
  state.composerLane = "open";
  state.offerDraft = {
    title: o.title || "", comped: o.whatComped || "", cap: o.dollarCap != null ? String(o.dollarCap) : "",
    rate: o.cashRate != null ? String(o.cashRate) : "", kind: o.kind || "comp", brief: o.paidBrief || "",
    includes: o.includes || "", experience: o.experience || "", tiers: o.targetTiers || [],
    spots: o.spots != null ? String(o.spots) : "", applydays: o.applyWindowDays != null ? String(o.applyWindowDays) : "",
    windowdays: o.windowDays != null ? String(o.windowDays) : "", window: o.visitWindow || "",
    covers: o.covers != null ? String(o.covers) : "",
    spanish: !!o.requiresSpanish,
    briefGoal: (o.brief && o.brief.goal) || "",
    briefHook: (o.brief && o.brief.hook) || "",
    briefMust: o.brief && o.brief.mustMention ? o.brief.mustMention.join("\n") : "",
    briefDont: o.brief && o.brief.doNotSay ? o.brief.doNotSay.join("\n") : "",
    briefTiming: (o.brief && o.brief.timing) || "",
    briefCta: (o.brief && o.brief.callToAction) || "",
    packetAttach: !!o.assetPacketAttached,
    packetManual: true,
    play: o.play || null,
    // Build -84: a duplicated coupon deal brings its coupon, and
    // every duplicated deal brings its deliverables.
    ctype: (o.coupon && o.coupon.type) || "store_credit",
    camount: o.coupon && o.coupon.amount != null ? String(o.coupon.amount) : "",
    cpercent: o.coupon && o.coupon.percent != null ? String(o.coupon.percent) : "",
    ccap: o.coupon && o.coupon.cap != null ? String(o.coupon.cap) : "",
    capplies: (o.coupon && o.coupon.appliesTo) || "",
    cexpires: o.coupon && o.coupon.expiresAt ? String(o.coupon.expiresAt).slice(0, 10) : "",
    dposts: o.deliverables ? String(deliverablesOfClient(o).posts) : "",
    dstory: o.deliverables ? deliverablesOfClient(o).story : undefined,
    dwindow: o.deliverables ? String(deliverablesOfClient(o).windowHours) : "",
    deliverablesTouched: !!o.deliverables,
  };
  state.offersSeg = "live";
  state.tab = "Campaign Setup";
  render();
  setTimeout(() => { const c = document.getElementById("offer-composer"); if (c) c.scrollIntoView({ behavior: "smooth" }); }, 60);
  return false;
}

// Two-tap invite (Jeff, 2026-10-26): the homepage promises a
// business can invite in two taps, so the DIRECT composer must
// open submittable: on a FRESH draft, prefill the title with the
// tier's lead comp suggestion and preselect that suggestion (its
// comped text + cap), on top of the lane defaults that already
// hold (kind comp, window 7 days, spots 1). Tap 1 = Invite on the
// card, tap 2 = Send. Everything stays editable before sending.
// A draft with anything typed in it is the business's own work
// and is NEVER overwritten: prefill only fires on an empty draft.
function offerDraftIsEmpty() {
  const d = state.offerDraft || {};
  return !["title", "comped", "cap", "rate", "brief", "includes", "experience", "spots", "window", "windowdays", "applydays"].some((k) => d[k] !== undefined && d[k] !== null && String(d[k]).trim() !== "");
}

function prefillDirectDraft(creator) {
  if (!creator || !offerDraftIsEmpty()) return false;
  const s = compSuggestions(creator.profile ? creator.profile.tierBand : null)[0];
  if (!s) return false;
  state.offerDraft.title = s.label;
  state.offerDraft.comped = s.comp;
  state.offerDraft.cap = String(s.cap);
  state.offerDraft.kind = "comp";
  return true;
}

function startOffer(creatorId) {
  pileUnlater("discover", creatorId);
  state.tab = "Campaign Setup";
  state.offerTarget = creatorId;
  prefillDirectDraft((state.discover || []).find((x) => x.userId === creatorId));
  render();
}

// Composer suggestion chips (Jeff, 2026-10-19): the Standard Visit
// package is pre-loaded and shown as a plain summary, comps are
// suggested by the creator's tier, dates are one tap. The underlying
// offer fields and API do not change.
function compSuggestions(tierBand) {
  const all = [
    { label: "Meal for one", comp: "Meal for one, on us", cap: 50 },
    { label: "Meal for two", comp: "Meal for two, on us", cap: 100 },
    { label: "Experience for two", comp: "Experience for two, on us", cap: 175 },
  ];
  if (tierBand === "Neighbors") return [all[0], { label: "Dessert + drinks", comp: "Dessert and drinks for one, on us", cap: 35 }];
  if (tierBand === "Locals") return [all[1], { label: "Brunch for two", comp: "Brunch for two, on us", cap: 80 }];
  if (tierBand === "Headliners") return [all[2], { label: "Meal for two + signature", comp: "Meal for two plus a signature item, on us", cap: 125 }];
  return all;
}

// Redemption windows (Jeff, 2026-10-19 r2): no appointments
// anywhere on SIGNL. An accepted offer is redeemed inside a
// window: 7 days from accepting (default) or this week, ending
// Sunday. The chips set the mode select; the free-text field is
// just an optional note for the creator.
function chipsRowHtml(kind, prefix, tierBand, current) {
  if (kind === "comp") {
    return `<div class="chip-row">${compSuggestions(tierBand).map((s) => `<button type="button" class="chip${current && current.comp === s.comp && Number(current.cap) === s.cap ? " on" : ""}" data-compchip="${prefix}" data-comp="${esc(s.comp)}" data-cap="${s.cap}" onclick="setCompChip('${prefix}', ${JSON.stringify(s.comp)}, ${s.cap})">${esc(s.label)} (~$${fmtPrice(s.cap)})</button>`).join("")}</div>`;
  }
  return `<div class="chip-row"><button type="button" class="chip" onclick="setWindowMode('${prefix}', '7days')">Use within 7 days</button><button type="button" class="chip" onclick="setWindowMode('${prefix}', 'thisweek')">This week (ends Sunday)</button></div>`;
}

function setCompChip(prefix, comp, cap) {
  const c = document.getElementById(prefix + "-comped");
  const k = document.getElementById(prefix + "-cap");
  if (c) c.value = comp;
  if (k) k.value = cap;
  document.querySelectorAll(`[data-compchip="${prefix}"]`).forEach((b) => b.classList.toggle("on", b.dataset.comp === comp && Number(b.dataset.cap) === Number(cap)));
  if (prefix === "o2") offerCoachUpdate();
}

function setWindowMode(prefix, mode) {
  const el = document.getElementById(prefix + "-windowmode");
  if (el) el.value = mode;
  // V4: the mode is a chip group over the hidden input — keep the
  // highlighted chip in step with the value.
  document.querySelectorAll(`[data-wm^="${prefix}:"]`).forEach((b) => b.classList.toggle("on", b.getAttribute("data-wm") === prefix + ":" + mode));
  if (prefix === "o2") offerDraftSync();
}

function windowModeFieldHtml(prefix, selected) {
  const sel = selected === "thisweek" ? "thisweek" : "7days";
  return `<div class="field"><label>Redemption window</label><div class="chiprow" data-wmrow="${prefix}"><button type="button" class="rchip${sel === "7days" ? " on" : ""}" data-wm="${prefix}:7days" onclick="setWindowMode('${prefix}', '7days')">Use within 7 days</button><button type="button" class="rchip${sel === "thisweek" ? " on" : ""}" data-wm="${prefix}:thisweek" onclick="setWindowMode('${prefix}', 'thisweek')">This week (ends Sunday)</button></div><input type="hidden" id="${prefix}-windowmode" value="${sel}"></div>`;
}

function packageSummaryHtml(planId, planName) {
  const comp = rightsForVisit("comp");
  return `<div class="pkg-mint"><h4>The Standard Visit — every comped offer</h4>
    ${standardVisitRowsHtml()}
    <details class="deal-details"><summary>The Standard Visit, in full</summary><div class="dd-body">
      <p class="small">${esc(standardVisit().summary)}</p>
      <p class="small"><strong>On a comp visit, you can:</strong> ${comp.can.map(esc).join("; ")}. They can't: ${comp.cannot.map(esc).join("; ")}. <strong>On a paid visit, you can also</strong> repost the post on your own feed and run it as an ad for 90 days from the post date. A comped post can be licensed for the same 90 days at the creator's listed licensing fee, with their approval. Rights follow the visit, not your plan${planName ? ` (${esc(planName)})` : ""}.</p>
      <p class="small"><strong>Coupon deals:</strong> you can also pay with a coupon (money off, a percent off, or store credit). The creator accepts the coupon as their payment for the post, and its rights are native share only, exactly like a comped post. Deliverables on every kind of deal start at the recommended standard and are yours to edit in the composer.</p>
    </div></details>
    <p class="small" style="margin:12px 0 0;font-weight:700">Meal-for-two comps outperform solo.</p>
  </div>`;
}

// ---------- offer composer v2 (Jeff, 2026-10-20) ----------
// Two lanes: the comp package is locked (the Standard Visit); paid
// bookings negotiate deliverables in their terms. DIRECT invites one creator (the
// target picked in Discover). OPEN posts terms to the market and
// creators apply with one tap. The composer coaches live: tier
// comp guidance, the dignity floor, a four-point strength
// checklist, and play templates. The server enforces the same
// numbers from bootstrap.offerGuidance, so the coaching here and
// the rules there can never drift apart.
function offerGuidance() { return (state.boot && state.boot.offerGuidance) || { compGuidance: {}, templates: [], paidFloor: 50, selectionSlaHours: 72, backfillAcceptHours: 24 }; }

function composerMode() {
  if (state.offerTarget) return "direct";
  return state.composerLane || "open";
}

function setComposerLane(lane) {
  offerDraftSync();
  state.composerLane = lane;
  state.offerTarget = null;
  loadCampaignSetup();
}

function applyTemplate(id) {
  const t = (offerGuidance().templates || []).find((x) => x.id === id);
  if (!t) return;
  const set = (elId, v) => { const el = document.getElementById(elId); if (el) el.value = v; };
  set("o2-title", t.title);
  set("o2-spots", t.spots);
  set("o2-windowdays", t.windowDays);
  set("o2-window", t.note);
  const hidden = document.getElementById("o2-template");
  if (hidden) hidden.value = id;
  offerCoachUpdate();
}

// The live coaching: strength checklist + dignity floor warning,
// recomputed on every keystroke from the same guidance the
// server enforces.
// ---------- offer composer support (UX redesign section 5) ----------
// The composer keeps its state in state.offerDraft: every input
// writes through on input/change, the render initializes FROM the
// draft, and loadMyOffers re-renders therefore never eat typed text.
function offerDraftSync() {
  if (!document.getElementById("o2-title")) return;
  const d = state.offerDraft;
  const set = (key, id) => { const el = document.getElementById(id); if (el) d[key] = el.value; };
  set("title", "o2-title"); set("comped", "o2-comped"); set("cap", "o2-cap"); set("rate", "o2-rate");
  set("brief", "o2-brief"); set("includes", "o2-includes"); set("experience", "o2-experience");
  set("spots", "o2-spots"); set("applydays", "o2-applydays"); set("windowdays", "o2-windowdays");
  set("window", "o2-window"); set("windowmode", "o2-windowmode"); set("template", "o2-template");
  // Brief Builder fields (Jeff, 2026-10-28): keys are prefixed
  // so they never collide with d.brief, the paid key-points text.
  set("briefHook", "o2-bhook"); set("briefMust", "o2-bmust"); set("briefDont", "o2-bdont");
  set("briefTiming", "o2-btiming"); set("briefCta", "o2-bcta");
  const kind = (document.querySelector("input[name='o2-kind']:checked") || {}).value;
  if (kind) d.kind = kind;
  const covers = (document.querySelector("input[name='o2-covers']:checked") || {}).value;
  if (covers) d.covers = covers;
  // Build -84: coupon fields + the deliverables editor ride the
  // same draft, so a re-render (kind switch, template pick)
  // never loses them.
  const ctype = (document.querySelector("input[name='o2-ctype']:checked") || {}).value;
  if (ctype) d.ctype = ctype;
  set("camount", "o2-camount"); set("cpercent", "o2-cpercent"); set("ccap", "o2-ccap");
  set("capplies", "o2-capplies"); set("cexpires", "o2-cexpires");
  set("dposts", "o2-dposts"); set("dwindow", "o2-dwindow");
  const dstory = document.getElementById("o2-dstory");
  if (dstory) d.dstory = !!dstory.checked;
  const bgoal = (document.querySelector("input[name='o2-bgoal']:checked") || {}).value;
  if (bgoal !== undefined) d.briefGoal = bgoal || "";
  const packet = document.getElementById("o2-packet");
  if (packet) d.packetAttach = !!packet.checked;
  if (document.querySelector("input[name='o2-tier']")) d.tiers = [...document.querySelectorAll("input[name='o2-tier']:checked")].map((x) => x.value);
  const spanish = document.getElementById("o2-spanish");
  if (spanish) d.spanish = !!spanish.checked;
}

// Packaged plays (Sig Operator refinement R1, Jeff, 2026-10-28):
// a play is a template over the existing brief object, never a
// new offer type: it presets the brief goal, drafts the brief
// fields, suggests the spots/window pattern, and names the
// creator mix that fits. Sig offers plays during B1 (matched to
// the business's category); the manual composer exposes the same
// plays and produces the identical offer+brief shape.
const SIG_PLAYS = [
  { id: "weekend_fill", name: "Weekend Fill", goal: "more_weekend_customers", spots: 3, applyDays: 3, windowDays: 7,
    hook: "{comped}, this weekend", mustExtra: [], timing: "Post by Friday noon so the weekend crowd sees it.",
    cta: "Tag us and tell them to book ahead.", mix: "Locals and strong Neighbors with 40%+ local reach fill weekends best." },
  { id: "grand_opening", name: "Grand Opening", goal: "launch_something_new", spots: 4, applyDays: 5, windowDays: 10,
    hook: "First look at {biz}: {comped}", mustExtra: ["Opening date"], timing: "Post on opening day, early.",
    cta: "Tell them opening week is the time to come.", mix: "A spread of tiers works here: one Headliner for reach, Locals for trust." },
  { id: "event_night", name: "Event Night", goal: "fill_an_event", spots: 3, applyDays: 4, windowDays: 7,
    hook: "One night only: {comped}", mustExtra: ["Event date"], timing: "Post two days before the event, and again in stories that day.",
    cta: "Tell them seats are limited and to reserve.", mix: "Creators who post fast and often in stories fill event nights best." },
  { id: "build_regulars", name: "Build Regulars", goal: "grow_regulars", spots: 2, applyDays: 3, windowDays: 14,
    hook: "My new regular spot: {comped}", mustExtra: [], timing: "Post midweek, when regulars plan their week.",
    cta: "Ask followers what their usual order is.", mix: "Small, local-heavy Neighbors and Locals read as real regulars, not ads." },
];
const SIG_PLAY_BY_CATEGORY = { "Restaurant": "weekend_fill", "Coffee & Bakery": "weekend_fill", "Bar": "event_night",
  "Attraction": "event_night", "Retail": "grand_opening", "Salon & Barbershop": "build_regulars",
  "Fitness Studio": "build_regulars", "Local Services": "build_regulars", "Other": "weekend_fill" };
function sigPlay(id) { return SIG_PLAYS.find((p) => p.id === id) || null; }
function playFill(tpl, bizName, comped) { return String(tpl || "").replaceAll("{biz}", bizName || "us").replaceAll("{comped}", comped || "the experience"); }
// Applying a play to the manual composer draft: presets only
// what the play owns (goal, brief fields, pattern numbers) and
// leaves the business's own title/comped/tiers untouched.
function applyPlayToDraft(playId) {
  const d = state.offerDraft || (state.offerDraft = {});
  const play = sigPlay(playId);
  d.play = playId || null;
  if (!play) { renderMyOffersPage(); return; }
  const bizName = (state.user && state.user.business && state.user.business.businessName) || "";
  d.briefGoal = play.goal;
  d.briefHook = playFill(play.hook, bizName, d.comped || "");
  d.briefMust = [bizName, ...play.mustExtra].filter(Boolean).join("\n");
  d.briefDont = "";
  d.briefTiming = play.timing;
  d.briefCta = play.cta;
  if (!d.spots) d.spots = String(play.spots);
  renderMyOffersPage();
  toast(`Play set: ${play.name}. The brief below is drafted from it; edit anything.`);
}
function composerPlaysHtml() {
  const d = state.offerDraft || {};
  const rec = SIG_PLAY_BY_CATEGORY[(state.user && state.user.business && state.user.business.category) || ""] || "weekend_fill";
  return `<div class="showcase-block"><h4>Start from a play</h4><p class="small muted" style="margin:0 0 8px">A play presets the goal, the brief and the timing pattern. ${esc(sigPlay(rec).mix)}</p><div class="chiprow">${SIG_PLAYS.map((p) => `<button type="button" class="rchip${d.play === p.id ? " on" : ""}" onclick="applyPlayToDraft('${p.id}')">${esc(p.name)}${p.id === rec ? " · fits you" : ""}</button>`).join("")}${d.play ? `<button type="button" class="rchip" onclick="applyPlayToDraft(null)">No play</button>` : ""}</div>${d.play ? `<p class="small" style="margin:8px 0 0"><strong>Play: ${esc(sigPlay(d.play).name)}.</strong> <span class="muted">${esc(sigPlay(d.play).mix)}</span></p>` : ""}</div>`;
}

// Brief Builder (Jeff, 2026-10-28): the structured brief every
// offer carries. The composer and Sig's B1 flow build the SAME
// object through briefFromParts; the server normalizes it
// (caps, dedupe, the locked deliverable line per kind) so both
// paths store byte-identical shapes.
const BRIEF_GOALS = [
  { id: "more_weekend_customers", label: "More weekend customers", labelEs: "Más clientes el fin de semana" },
  { id: "launch_something_new", label: "Launch something new", labelEs: "Lanzar algo nuevo" },
  { id: "fill_an_event", label: "Fill an event", labelEs: "Llenar un evento" },
  { id: "grow_regulars", label: "Grow regulars", labelEs: "Más clientes habituales" },
];
function briefGoalLabel(id) {
  const g = BRIEF_GOALS.find((x) => x.id === id);
  return g ? g.label : "";
}
function briefLines(text) {
  return String(text || "").split(/\n+/).map((x) => x.trim()).filter(Boolean).slice(0, 3);
}
function briefFromParts(parts) {
  const p = parts || {};
  return {
    goal: p.goal || null,
    hook: String(p.hook || "").trim().slice(0, 140),
    mustMention: Array.isArray(p.mustMention) ? p.mustMention.map((x) => String(x).trim()).filter(Boolean).slice(0, 3) : briefLines(p.mustMention),
    doNotSay: Array.isArray(p.doNotSay) ? p.doNotSay.map((x) => String(x).trim()).filter(Boolean).slice(0, 3) : briefLines(p.doNotSay),
    timing: String(p.timing || "").trim().slice(0, 140),
    callToAction: String(p.callToAction || "").trim().slice(0, 120),
  };
}
function briefFromDraft(d) {
  return briefFromParts({ goal: d.briefGoal || null, hook: d.briefHook, mustMention: d.briefMust, doNotSay: d.briefDont, timing: d.briefTiming, callToAction: d.briefCta });
}
// The creator-facing "Your brief" block: renders an offer's or a
// booking's stored brief (both carry .brief). Honest-posting line
// rides with it: key points, never a script.
function briefBlockHtml(x) {
  const b = x && x.brief;
  if (!b) return "";
  const rows = [];
  if (b.goal) rows.push(`<div class="ui-row"><span class="k">Goal</span><span class="v">${esc(briefGoalLabel(b.goal) || b.goal)}</span></div>`);
  if (b.hook) rows.push(`<div class="ui-row"><span class="k">The hook</span><span class="v">${esc(b.hook)}</span></div>`);
  if ((b.mustMention || []).length) rows.push(`<div class="ui-row"><span class="k">Must mention</span><span class="v">${b.mustMention.map(esc).join(" · ")}</span></div>`);
  if ((b.doNotSay || []).length) rows.push(`<div class="ui-row"><span class="k">Do not say</span><span class="v">${b.doNotSay.map(esc).join(" · ")}</span></div>`);
  if (b.deliverable) rows.push(`<div class="ui-row"><span class="k">Deliverable</span><span class="v">${esc(b.deliverable)}</span></div>`);
  if (b.timing) rows.push(`<div class="ui-row"><span class="k">Timing</span><span class="v">${esc(b.timing)}</span></div>`);
  if (b.callToAction) rows.push(`<div class="ui-row"><span class="k">Call to action</span><span class="v">${esc(b.callToAction)}</span></div>`);
  if (!rows.length) return "";
  return `<div class="showcase-block"><h4>Your brief</h4><div class="stack-list">${rows.join("")}</div><p class="small muted" style="margin:6px 0 0">Key points, never a script. Post honestly, in your own words.</p></div>`;
}
// The asset packet block (creator visit view): the business's
// logo link, key links, talking points, handle and hashtags,
// snapshotted onto the booking at booking time.
function assetPacketBlockHtml(packet) {
  const p = packet;
  if (!p || (!(p.links || []).length && !p.logoUrl && !p.talkingPoints && !p.handle && !(p.hashtags || []).length)) return "";
  const links = (p.links || []).map((l) => `<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label || l.url)}</a>`).join(" · ");
  return `<div class="showcase-block"><h4>From the business: links and assets</h4>
  ${p.logoUrl ? `<p class="small" style="margin:0 0 4px">Logo: <a href="${esc(p.logoUrl)}" target="_blank" rel="noopener">${esc(p.logoUrl)}</a></p>` : ""}
  ${links ? `<p class="small" style="margin:0 0 4px">${links}</p>` : ""}
  ${p.talkingPoints ? `<p class="small" style="margin:0 0 4px">${esc(p.talkingPoints)}</p>` : ""}
  ${p.handle || (p.hashtags || []).length ? `<p class="small muted" style="margin:0">Tag ${p.handle ? "@" + esc(p.handle) : "the business"}${(p.hashtags || []).length ? " · " + p.hashtags.map((h) => "#" + esc(h)).join(" ") : ""}</p>` : ""}
  </div>`;
}

// Per-field inline validation: the error lands in a
// <p class="field-err"> under the field; the top #form-error is
// reserved for server errors and the dedupe notice.
function offerFieldError(key, msg) {
  const el = document.getElementById("err-o2-" + key);
  if (el) el.textContent = msg || "";
  return !msg;
}

function offerValidateField(key) {
  offerDraftSync();
  const d = state.offerDraft;
  const kind = d.kind || "comp";
  if (key === "title") return offerFieldError("title", !String(d.title || "").trim() ? "Give the offer a title." : "");
  if (key === "comped") return kind === "coupon" ? offerFieldError("comped", "") : offerFieldError("comped", !String(d.comped || "").trim() ? "Say exactly what is comped." : "");
  if (key === "cap") return kind !== "comp" ? offerFieldError("cap", "") : offerFieldError("cap", !(Number(d.cap) > 0) ? "Enter the comp value in dollars." : "");
  if (key === "rate") return kind !== "paid" ? offerFieldError("rate", "") : offerFieldError("rate", !(Number(d.rate) >= ownPaidFloor()) ? `Enter the cash rate. Cash offers start at ${ownCurrencySymbol()}${ownPaidFloor()}.` : "");
  if (key === "spots") {
    const v = String(d.spots === undefined ? "" : d.spots).trim();
    if (v === "") return offerFieldError("spots", "");
    return offerFieldError("spots", !(parseInt(v, 10) > 0) ? "Spots must be at least 1." : "");
  }
  return true;
}

const OFFER_INFO = {
  lane: { title: "Open or direct", body: "An open offer posts your terms to your market and creators apply. A direct offer goes to one creator you pick in Discover, and only they see it." },
  templates: { title: "Templates", body: "Templates prefill a proven offer shape: title, spots, window, and a note. Edit anything after picking one, including the deliverables: every template starts from the recommended standard for its kind of deal." },
  title: { title: "Offer title", body: "Name the experience, not the deal. For example: Dinner for two on us. Creators scan titles first, so say what they get." },
  kind: { title: "How the creator is paid", body: "Comp means your product is the payment: the meal, service, or experience is on you. Cash means you pay the creator a rate for a booking. Coupon means a coupon is the payment: money off, a percent off, or store credit, and the creator accepts it as their pay for the post. Every kind starts from SIGNL's recommended deliverables, and you can edit them below. Pick one; an offer is never two kinds at once." },
  comped: { title: "What is comped", body: "Say exactly what the creator gets, in one line. For example: Two entrees and two drinks. This line prints on the offer, the visit card, and the staff screen." },
  covers: { title: "Who the comp covers", body: "One person is just the creator. Two people adds a guest. Creators post more when they can bring a guest, and meal for two comps outperform solo comps." },
  cap: { title: "Comp value / dollar cap", body: "The most the comp can ring up, at menu value. For example: a $100 cap on a dinner for two. Higher caps inside the typical range for a tier fill first." },
  rate: { title: "Cash rate", body: "What you pay the creator for one paid booking. The business pays the rate plus 3%. The creator keeps 97%. Minimum listed rate $50." },
  brief: { title: "Key points", body: "Short direction for a paid visit: what to feature, names, dates. Creators post honestly in their own words. No scripts, no required praise, no post pre-approval." },
  includes: { title: "What is included", body: "Any two entrees, two drinks each, dessert to share, tax and tip covered. Creators weigh this detail most: say exactly what they get." },
  experience: { title: "The experience", body: "What it feels like and what photographs well. For example: chef's counter seats, open kitchen, the tasting menu everyone photographs." },
  tiers: { title: "Who can apply", body: "Tiers are set automatically by audience size: Neighbors, Locals, Headliners. Ticking tiers only narrows who may apply. Leave all unticked and every tier your comp fits can apply." },
  spots: { title: "Spots", body: "How many creators you will pick from the applicants. Each picked creator books one visit." },
  applydays: { title: "Applications open for", body: "How many days creators can apply before you pick. Three days is the usual: long enough to build a stack, short enough to keep momentum." },
  windowdays: { title: "Redemption window", body: "How many days picked creators have to come in, starting when applications close. Seven days is the usual. Windows of 3 or more days fill best." },
  windownote: { title: "Window note", body: "Anything that helps the creator time the visit. For example: Evenings are best. The note prints on the offer and the visit card." },
};

function infoBtn(topic) {
  return `<button type="button" class="info-btn" aria-label="About this field" onclick="showOfferInfo('${topic}')">i</button>`;
}

function showOfferInfo(topic) {
  const info = OFFER_INFO[topic];
  const pop = document.getElementById("offer-info-pop");
  if (!info || !pop) return false;
  document.getElementById("offer-info-title").textContent = info.title;
  document.getElementById("offer-info-body").textContent = info.body;
  pop.style.display = "";
  return false;
}

function closeOfferInfo() {
  const pop = document.getElementById("offer-info-pop");
  if (pop) pop.style.display = "none";
  return false;
}

function jumpToOffer(offerId) {
  const card = document.getElementById("offer-card-" + offerId);
  if (!card) return false;
  card.scrollIntoView({ behavior: "smooth", block: "center" });
  card.classList.add("highlight");
  setTimeout(() => card.classList.remove("highlight"), 2400);
  return false;
}

// ---------- Build -84: the composer's deliverables editor ----------
// The draft's deliverables for a kind: the business's own values
// once they touch the editor, the kind's recommended standard
// until then.
function draftDeliverables(d, kind) {
  const std = deliverableStandardClient(kind);
  const dd = d || {};
  return {
    posts: dd.dposts !== undefined && dd.dposts !== "" ? Math.min(5, Math.max(1, parseInt(dd.dposts, 10) || std.posts)) : std.posts,
    story: dd.dstory !== undefined ? !!dd.dstory : std.story,
    windowHours: dd.dwindow !== undefined && dd.dwindow !== "" ? parseInt(dd.dwindow, 10) || std.windowHours : std.windowHours,
  };
}
function deliverablesEditorHtml(d, kind) {
  const std = deliverableStandardClient(kind);
  const cur = draftDeliverables(d, kind);
  const rec = (id, on) => `<span class="badge info" id="${id}"${on ? "" : ` style="display:none"`}>Recommended</span>`;
  return `<div class="field"><label>What the creator owes</label>
    <p class="small muted" style="margin:0 0 8px">These start at SIGNL's recommended standard for this kind of deal, marked Recommended. Change anything and the creator sees exactly what you set before they accept.</p>
    <div class="form-2col">
      <div class="field"><label>Posts ${rec("o2-drec-posts", cur.posts === std.posts)}</label><input type="number" id="o2-dposts" min="1" max="5" step="1" value="${cur.posts}" oninput="offerDeliverablesTouch()"></div>
      <div class="field"><label>Post within ${rec("o2-drec-window", cur.windowHours === std.windowHours)}</label>
        <select id="o2-dwindow" onchange="offerDeliverablesTouch()">
          ${[24, 48, 72, 168].map((h) => `<option value="${h}" ${cur.windowHours === h ? "selected" : ""}>${h === 24 ? "24 hours" : h === 48 ? "48 hours" : h === 72 ? "3 days" : "1 week"}</option>`).join("")}
        </select></div>
    </div>
    <label class="ckrow"><input type="checkbox" class="ckbox" id="o2-dstory" ${cur.story ? "checked" : ""} onchange="offerDeliverablesTouch()"><span>Include 1 story that shares the post ${rec("o2-drec-story", cur.story === std.story)}</span></label>
    ${kind === "paid" ? `<p class="small muted" style="margin:8px 0 0">A paid booking also includes the standard license: repost and ad use for 90 days from the post date. That part is set by SIGNL and cannot be changed.</p>` : ""}
    <p style="margin:8px 0 0"><button type="button" class="linklike" onclick="return offerDeliverablesReset()">Back to the recommended standard</button></p>
  </div>`;
}
function offerDeliverablesBadges() {
  const kind = (document.querySelector("input[name='o2-kind']:checked") || {}).value || "comp";
  const std = deliverableStandardClient(kind);
  const set = (id, on) => { const el = document.getElementById(id); if (el) el.style.display = on ? "" : "none"; };
  set("o2-drec-posts", parseInt((document.getElementById("o2-dposts") || {}).value, 10) === std.posts);
  set("o2-drec-window", parseInt((document.getElementById("o2-dwindow") || {}).value, 10) === std.windowHours);
  const storyEl = document.getElementById("o2-dstory");
  set("o2-drec-story", !!storyEl && storyEl.checked === std.story);
}
function offerDeliverablesTouch() {
  state.offerDraft = state.offerDraft || {};
  state.offerDraft.deliverablesTouched = true;
  offerDraftSync();
  offerDeliverablesBadges();
}
function offerDeliverablesReset() {
  const kind = (document.querySelector("input[name='o2-kind']:checked") || {}).value || (state.offerDraft && state.offerDraft.kind) || "comp";
  const std = deliverableStandardClient(kind);
  state.offerDraft = state.offerDraft || {};
  state.offerDraft.dposts = String(std.posts);
  state.offerDraft.dstory = std.story;
  state.offerDraft.dwindow = String(std.windowHours);
  state.offerDraft.deliverablesTouched = false;
  loadCampaignSetup();
  return false;
}
// Kind switch: until the business edits the deliverables
// themselves, the editor follows the newly picked kind's
// recommended standard. The composer re-renders from the draft,
// the same pattern as the lane switch.
function offerKindChanged() {
  offerDraftSync();
  const d = state.offerDraft || (state.offerDraft = {});
  if (!d.deliverablesTouched) {
    const std = deliverableStandardClient(d.kind || "comp");
    d.dposts = String(std.posts);
    d.dstory = std.story;
    d.dwindow = String(std.windowHours);
  }
  loadCampaignSetup();
}
function offerCouponTypeUpdate() {
  offerDraftSync();
  const t = (document.querySelector("input[name='o2-ctype']:checked") || {}).value || "store_credit";
  const amt = document.getElementById("o2-camount-wrap");
  const pct = document.getElementById("o2-cpercent-wrap");
  const cap = document.getElementById("o2-ccap-wrap");
  const lbl = document.getElementById("o2-camount-label");
  if (amt) amt.style.display = t === "percent_off" ? "none" : "";
  if (pct) pct.style.display = t === "percent_off" ? "" : "none";
  if (cap) cap.style.display = t === "percent_off" ? "" : "none";
  if (lbl) lbl.textContent = t === "store_credit" ? "Store credit ($)" : "Money off ($)";
}

function compNudgeUpdate() {
  const el = document.getElementById("o2-compnudge");
  if (!el) return;
  const kind = (document.querySelector("input[name='o2-kind']:checked") || {}).value || "comp";
  const cap = parseInt((document.getElementById("o2-cap") || {}).value, 10) || 0;
  if (kind !== "comp" || !cap) { el.textContent = ""; return; }
  el.textContent = cap < 50
    ? "That is a light comp for a post and a story that shares it. Creators weigh the value before they decide, and at this level a paid booking usually lands better."
    : cap < 100
      ? "A fair comp for many local spots. Bigger experiences pull stronger creators; a paid booking is the other lane."
      : "That value reads strong for a post and a story. It will get weighed seriously.";
}
function offerCoachUpdate() {
  offerDraftSync();
  compNudgeUpdate();
  const g = offerGuidance();
  const kind = (document.querySelector("input[name='o2-kind']:checked") || {}).value || "comp";
  const cap = parseInt((document.getElementById("o2-cap") || {}).value, 10) || 0;
  const rate = parseFloat((document.getElementById("o2-rate") || {}).value) || 0;
  const wdEl = document.getElementById("o2-windowdays");
  const windowDays = wdEl ? (wdEl.value === "" ? 7 : parseInt(wdEl.value, 10) || 0) : 7;
  const includes = ((document.getElementById("o2-includes") || {}).value || "").trim();
  const experience = ((document.getElementById("o2-experience") || {}).value || "").trim();
  const tiers = [...document.querySelectorAll("input[name='o2-tier']:checked")].map((x) => x.value);
  const couponOk = (() => {
    if (kind !== "coupon") return false;
    const t = (document.querySelector("input[name='o2-ctype']:checked") || {}).value || "store_credit";
    const v = t === "percent_off"
      ? Number((document.getElementById("o2-cpercent") || {}).value) >= 1
      : Number((document.getElementById("o2-camount") || {}).value) >= 1;
    return v && String((document.getElementById("o2-capplies") || {}).value || "").trim().length > 0;
  })();
  const checks = [
    { label: kind === "paid" ? `Cash rate stated (floor $${fmtPrice(g.paidFloor)})` : kind === "coupon" ? "Coupon value stated" : "Comp value stated", ok: kind === "paid" ? rate >= g.paidFloor : kind === "coupon" ? couponOk : cap > 0 },
    { label: "Redemption window is 3+ days", ok: windowDays >= 3 },
    { label: "What is included is written out", ok: includes.length >= 12 },
    { label: "The experience is described", ok: experience.length >= 12 },
  ];
  const el = document.getElementById("o2-strength");
  const doneCount = checks.filter((c) => c.ok).length;
  const nextCheck = checks.find((c) => !c.ok);
  if (el) el.innerHTML = `<strong>Offer checklist: ${doneCount} of ${checks.length}</strong>` + (nextCheck ? `<br>Next: ${esc(nextCheck.label)}` : `<br>Complete: ready to publish.`) + checks.map((c) => `<br>${c.ok ? "&#10003;" : "&#9675;"} ${esc(c.label)}`).join("");
  // Payment switch (UX redesign section 5): comp shows the cap
  // group, paid shows the rate group plus the brief. What is
  // comped and covers stay visible for both kinds.
  const briefWrap = document.getElementById("o2-brief-wrap");
  if (briefWrap) briefWrap.style.display = kind === "paid" ? "" : "none";
  const capWrap = document.getElementById("o2-cap-wrap");
  if (capWrap) capWrap.style.display = kind === "comp" ? "" : "none";
  const rateWrap = document.getElementById("o2-rate-wrap");
  if (rateWrap) rateWrap.style.display = kind === "paid" ? "" : "none";
  // Build -84: a coupon deal swaps the comp fields for the
  // coupon fields. Covers and "what is comped" are comp
  // concepts; the coupon block carries what the coupon is for.
  const couponWrap = document.getElementById("o2-coupon-wrap");
  if (couponWrap) couponWrap.style.display = kind === "coupon" ? "" : "none";
  const coversWrap = document.getElementById("o2-covers-wrap");
  if (coversWrap) coversWrap.style.display = kind === "coupon" ? "none" : "";
  const compedWrap = document.getElementById("o2-comped-wrap");
  if (compedWrap) compedWrap.style.display = kind === "coupon" ? "none" : "";
  const warn = document.getElementById("o2-dignity");
  if (warn) {
    let html = "";
    if (kind === "comp" && composerMode() === "open") {
      const blocked = tiers.filter((t) => g.compGuidance[t] && cap > 0 && cap < g.compGuidance[t].floor);
      if (blocked.length) {
        html = `<div class="error-box">A $${fmtMoney(cap)} comp is below the dignity floor for ${blocked.map(esc).join(", ")} (floors: ${blocked.map((t) => `${esc(t)} $${fmtPrice(g.compGuidance[t].floor)}`).join(", ")}). Raise the value or untick ${blocked.length === 1 ? "that tier" : "those tiers"}: token comps burn the roster's trust, so SIGNL will not publish this as is.</div>`;
      } else if (cap > 0 && tiers.length) {
        const fits = tiers.filter((t) => g.compGuidance[t] && cap >= g.compGuidance[t].typicalLow && cap <= g.compGuidance[t].typicalHigh);
        html = `<p class="small muted">$${fmtMoney(cap)} sits in the typical range for ${fits.length ? fits.map(esc).join(", ") : "none of the ticked tiers, which usually means slower applications"}.</p>`;
      } else if (cap > 0 && cap < 25) {
        html = `<div class="error-box">Comp offers start at $25 of value. Below that it is a token, and token comps burn the roster's trust.</div>`;
      }
    }
    if (kind === "paid") {
      const total = Math.round(rate * 1.03 * 100) / 100;
      const net = Math.round(rate * 0.97 * 100) / 100;
      html = rate > 0 ? `<p class="small muted">At $${fmtPrice(rate)}: you pay $${fmtMoney(total)} (rate + 3%), the creator keeps $${fmtMoney(net)} (97%), and SIGNL holds the payment until the post is live. Below $${fmtPrice(g.paidFloor)} a cash offer cannot run.</p>` : "";
    }
    warn.innerHTML = html;
  }
  // Build -84: the coupon type's sub-fields follow the picked
  // coupon type on first paint as well as on change.
  if (kind === "coupon") offerCouponTypeUpdate();
  // V5: keep the drag bars painted in step with the values
  // (template picks and chip fills write inputs directly).
  dragInit();
}

// ---------- Build -97: Sig-guided campaign setup ----------
// The guided entry at the top of Set up a campaign. This is
// the Sig campaign-draft machinery (the B1 flow's shape:
// ask one thing at a time, confirm on a plain-words summary,
// commit through POST /offers) brought into the setup view.
// It is NOT a second creation path: the commit below builds
// the same payload the Sig operator and the manual composer
// build, with the same deliverables helpers, and the draft
// lands in the same store, reviewed on the same cards in
// Your campaigns. Flow state lives in memory only until the
// summary confirmation, so no draft exists before the
// business taps Save this draft.
function campaignGuideKnown() {
  const u = state.user || {};
  const bz = u.business || {};
  const plan = foundingPlan() || (state.boot && state.boot.plans || []).find((p) => p.id === bz.plan) || null;
  return {
    businessName: bz.businessName || "",
    market: u.market || "",
    category: bz.category || "",
    visits: plan ? plan.visitsPerMonth : null,
    availability: availabilitySummaryClient(bz.standingAvailability),
  };
}
function campaignGuideParse(text) {
  const raw = String(text || "").trim();
  const t = " " + raw.toLowerCase() + " ";
  const out = {};
  if (/\b(paid|cash)\b/.test(t)) out.kind = "paid";
  else if (/\bcoupon\b/.test(t)) out.kind = "coupon";
  else if (/\b(comp|comped|on us|on the house|free meal)\b/.test(t)) out.kind = "comp";
  const spots = /(\d+)\s*(creators|spots|visits|people)/.exec(t);
  if (spots) out.spots = Math.min(30, Math.max(1, parseInt(spots[1], 10)));
  const money = /\$\s*(\d+)/.exec(t) || /(\d+)\s*dollars/.exec(t);
  if (money) out.amount = parseInt(money[1], 10);
  if (/store credit/.test(t)) out.ctype = "store_credit";
  if (/weekend/.test(t)) out.whenText = "This weekend";
  else if (/weekday/.test(t)) out.whenText = "Weekdays";
  else if (/evenings?/.test(t)) out.whenText = "Evenings";
  const tiers = [];
  if (/headliner/.test(t)) tiers.push("Headliners");
  if (/\blocals?\b/.test(t)) tiers.push("Locals");
  if (/neighbou?r/.test(t)) tiers.push("Neighbors");
  if (tiers.length) out.tiers = tiers;
  let s = raw.replace(/\s+/g, " ")
    .replace(/^(please\s+)?(i want|i need|we want|we need|let's|lets)\s+/i, "")
    .replace(/^(local\s+)?creators\s+(for|to)\s+/i, "")
    .replace(/^for\s+/i, "").replace(/^an?\s+/i, "");
  if (s.length >= 8 && s.length <= 70) out.title = s.charAt(0).toUpperCase() + s.slice(1);
  return out;
}
function campaignGuideHtml() {
  const known = campaignGuideKnown();
  const cg = state.campaignGuide;
  return `<section class="wcard" id="campaign-guide" style="border:2px solid #006AFC">
    <div style="display:flex;gap:12px;align-items:center">${sigAvatarHtml("greet")}<div><p class="ui-kicker" style="margin:0">Start with Sig</p><h3 style="margin:2px 0 0">Tell Sig what you want</h3></div></div>
    <p class="small muted" style="margin:10px 0 0">Type it in your own words. Sig fills in what it already knows about your business, asks only for what is missing, one question at a time, and shows you the full draft before anything is saved.</p>
    <p class="small" style="margin:8px 0 0"><strong>Already on file for you:</strong> ${esc(known.businessName || "Your business")}${known.market ? ` in ${esc(known.market)}` : ""}${known.category ? ` · ${esc(known.category)}` : ""}${known.visits ? ` · your plan includes ${known.visits} visits a month` : ""}${known.availability ? ` · your usual hours: ${esc(known.availability)}` : ""}. Sig will not ask you for any of that again.</p>
    <div id="cg-thread" class="sig-thread" style="margin-top:12px">${cg ? "" : `<div class="sig-turn sig"><span class="sig-turn-ava">${SIG_AVATAR_HTML}</span><div class="sig-bub">Tell me the campaign in one line. For example: I want creators for a weekend brunch push. I will build the draft from there.</div></div>`}</div>
    <form class="sig-ask-form" onsubmit="return campaignGuideSubmit(event)">
      <input id="cg-text" type="text" placeholder="I want creators for a weekend brunch push" autocomplete="off" aria-label="Tell Sig what you want">
      <button class="btn" type="submit">Tell Sig</button>
    </form>
    <p class="small muted" style="margin:8px 0 0">Rather build it yourself? The step by step form is right below. Both ways land in the same place: a draft in Your campaigns.</p>
  </section>`;
}
function campaignGuideRender() {
  const host = document.getElementById("cg-thread");
  if (!host) return;
  const cg = state.campaignGuide;
  if (!cg) return;
  host.innerHTML = cg.turns.map((t) => t.who === "user"
    ? `<div class="sig-turn user"><div class="sig-bub">${esc(t.text)}</div></div>`
    : `<div class="sig-turn sig"><span class="sig-turn-ava">${SIG_AVATAR_HTML}</span><div class="sig-bub">${esc(t.text)}</div></div>`).join("")
    + (cg.chips && cg.chips.length ? `<div class="sig-turn sig"><div class="sig-bub">${cg.chips.map((c) => `<button type="button" class="btn small-btn sig-turn-act${c.primary ? "" : " ghost"}" onclick="return campaignGuidePick('${c.field}','${c.value}')">${esc(c.label)}</button>`).join("")}</div></div>` : "")
    + (cg.step === "done" ? `<div class="sig-turn sig"><div class="sig-bub"><button type="button" class="btn small-btn sig-turn-act" onclick="return campaignGuideGoCampaigns()">See it in Your campaigns</button> <button type="button" class="btn small-btn sig-turn-act ghost" onclick="return campaignGuideRestart()">Start another</button></div></div>` : "");
  host.scrollTop = host.scrollHeight;
}
function campaignGuideSay(text, chips) {
  const cg = state.campaignGuide;
  cg.turns.push({ who: "sig", text });
  cg.chips = chips || [];
  campaignGuideRender();
}
function campaignGuideStart(requestText) {
  const known = campaignGuideKnown();
  const parsed = campaignGuideParse(requestText);
  const d = {
    request: requestText, lane: "open", title: parsed.title || "", kind: parsed.kind || "",
    comped: "", cap: null, rate: null, ctype: parsed.ctype || "amount_off", camount: null, cpercent: null, capplies: "",
    spots: parsed.spots || null, windowNote: parsed.whenText || known.availability || "",
    tiers: parsed.tiers || [], briefGoal: /weekend/.test(" " + requestText.toLowerCase() + " ") ? "more_weekend_customers" : null, dposts: undefined, dstory: undefined, dwindow: undefined, deliverablesTouched: false,
    deliverablesSeen: false, fitSeen: false,
  };
  if (parsed.amount) {
    if (d.kind === "paid") d.rate = parsed.amount;
    else if (d.kind === "coupon") d.camount = parsed.amount;
    else d.cap = parsed.amount;
  }
  state.campaignGuide = { step: "", data: d, turns: [{ who: "user", text: requestText }], chips: [] };
  const filled = [];
  if (d.title) filled.push(`the name "${d.title}"`);
  if (d.kind) filled.push(d.kind === "paid" ? "cash pay" : d.kind === "coupon" ? "a coupon as the payment" : "a comp, your product on you");
  if (d.spots) filled.push(`${d.spots} creator spot${d.spots === 1 ? "" : "s"}`);
  if (d.windowNote) filled.push(`timing: ${d.windowNote}`);
  campaignGuideSay(filled.length
    ? `Got it. From your words I have ${filled.join(", ")}. I already know your market (${known.market || "your market"}), your kind of business${known.category ? ` (${known.category})` : ""}${known.visits ? `, and that your plan includes ${known.visits} visits a month` : ""}, so I will not ask about those. A few things are still missing.`
    : `Got it. I already know your market (${known.market || "your market"}), your kind of business${known.category ? ` (${known.category})` : ""}${known.visits ? `, and that your plan includes ${known.visits} visits a month` : ""}, so I will not ask about those. A few things are still missing.`);
  campaignGuideNext();
  return false;
}
function campaignGuideNext() {
  const cg = state.campaignGuide;
  if (!cg) return;
  const d = cg.data;
  if (!d.title) { cg.step = "title"; campaignGuideSay("What should we call it? Name the experience, not the deal. For example: Dinner for two on us."); return; }
  if (!d.kind) {
    cg.step = "kind";
    campaignGuideSay("How will the creator be paid? Comp means your product is the payment. Cash means you pay a rate for a paid booking. A coupon can be the payment instead.", [
      { label: "Comp", field: "kind", value: "comp", primary: true },
      { label: "Cash", field: "kind", value: "paid" },
      { label: "Coupon", field: "kind", value: "coupon" },
    ]);
    return;
  }
  if (d.kind === "comp" && !d.comped) { cg.step = "comped"; campaignGuideSay("Exactly what does the creator get? One line is enough. For example: Brunch for two, on us."); return; }
  if (d.kind === "comp" && !d.cap) { cg.step = "value"; campaignGuideSay("What is that worth, in dollars? That number is the most it can cost you, and creators see it before they apply. For example: 100."); return; }
  if (d.kind === "paid" && !d.rate) { cg.step = "value"; campaignGuideSay(`What rate will you pay the creator? Paid bookings start at ${ownCurrencySymbol()}${ownPaidFloor()}. The creator keeps 97% of the rate.`); return; }
  if (d.kind === "coupon" && !d.camount && !d.cpercent) { cg.step = "couponamount"; campaignGuideSay("What is the coupon worth, in dollars? For example: 50 means $50 off."); return; }
  if (d.kind === "coupon" && !d.capplies) { cg.step = "couponapplies"; campaignGuideSay("What is the coupon good for? For example: Anything on the brunch menu."); return; }
  if (!d.spots) {
    cg.step = "spots";
    campaignGuideSay("How many creators do you want for this campaign? Each one you pick uses one visit from your plan.", [1, 2, 3, 5].map((n) => ({ label: String(n), field: "spots", value: String(n), primary: n === 1 })));
    return;
  }
  if (!d.windowNote) { cg.step = "dates"; campaignGuideSay("When should creators come in? For example: This weekend, or Saturday and Sunday mornings."); return; }
  if (!d.deliverablesSeen) {
    cg.step = "deliverables";
    const cur = draftDeliverables(d, d.kind);
    campaignGuideSay(`What the creator owes: ${deliverablePhraseClient({ kind: d.kind, deliverables: cur })}, post within ${windowPhraseClient(cur.windowHours)}. That is the recommended setup for this kind of campaign${d.kind === "paid" ? ". A paid booking also includes the standard licence: repost and ad use for 90 days. That part is set and cannot be changed" : ""}. Keep it, or change one part.`, [
      { label: "Keep as shown", field: "deliverables", value: "keep", primary: true },
      { label: `Story: ${cur.story ? "yes" : "no"}`, field: "deliverables", value: "story" },
      { label: `Posts: ${cur.posts}`, field: "deliverables", value: "posts" },
      { label: `Post within: ${windowPhraseClient(cur.windowHours)}`, field: "deliverables", value: "window" },
    ]);
    return;
  }
  if (!d.fitSeen) {
    cg.step = "fit";
    campaignGuideSay("Who fits this campaign? Tap any that fit, then tap Done. Leave all untapped and any creator who fits can apply.", [
      ...["Neighbors", "Locals", "Headliners"].map((t) => ({ label: `${d.tiers.includes(t) ? "✓ " : ""}${t}`, field: "tier", value: t, primary: d.tiers.includes(t) })),
      { label: "Done", field: "fitdone", value: "done", primary: !d.tiers.length },
    ]);
    return;
  }
  campaignGuideSummary();
}
function campaignGuideSummary() {
  const cg = state.campaignGuide;
  const d = cg.data;
  const known = campaignGuideKnown();
  const cur = draftDeliverables(d, d.kind);
  const payLine = d.kind === "paid"
    ? `Cash $${fmtPrice(d.rate)}. The creator keeps $${fmtMoney(Number(d.rate) * 0.97)} (97%).`
    : d.kind === "coupon"
      ? `A coupon: ${couponSummaryClient({ type: d.ctype, amount: d.camount, percent: d.cpercent, appliesTo: d.capplies }, known.businessName)}. The coupon is the payment. No cash changes hands.`
      : `Comp: ${d.comped} (worth up to $${fmtMoney(d.cap)}, on you). Your business can share the creator's post inside the app only.`;
  const lines = [
    "Here is your draft. Nothing is saved until you tap Save this draft:",
    `Campaign: "${d.title}"`,
    `Pay: ${payLine}`,
    `Creators: ${d.spots} spot${d.spots === 1 ? "" : "s"}, open to creators in ${known.market || "your market"}${known.category ? ` who fit a ${known.category}` : ""}.`,
    `Who fits: ${d.tiers.length ? d.tiers.join(", ") : "any creator who fits"}.`,
    `When: ${d.windowNote}.`,
    `What the creator owes: ${deliverablePhraseClient({ kind: d.kind, deliverables: cur })}, post within ${windowPhraseClient(cur.windowHours)}${d.kind === "paid" ? ". The standard licence is included: repost and ad use for 90 days" : ""}.`,
    `From: ${known.businessName || "your business"}${known.visits ? `. Your plan includes ${known.visits} visits a month` : ""}.`,
    ...(isFoundingBusiness(state.user) ? ["Your market has not opened yet, so this saves as a draft for opening day. Nothing sends to a creator until then."] : ["It saves as a draft. You can check it, change it, or send it from Your campaigns."]),
  ];
  cg.step = "summary";
  campaignGuideSay(lines.join("\n"), [
    { label: isFoundingBusiness(state.user) ? "Save this draft for opening day" : "Save this draft", field: "confirm", value: "yes", primary: true },
    { label: "Start over", field: "restart", value: "yes" },
  ]);
}
async function campaignGuideConfirm() {
  const cg = state.campaignGuide;
  const d = cg.data;
  const payload = {
    title: d.title || "", whatComped: d.comped || "", includes: "", experience: "",
    kind: d.kind, spots: d.spots || 1, visitWindow: d.windowNote || "", templateId: null,
    draft: true, creatorId: null, requiresSpanish: false, play: null, brief: briefFromParts({ goal: d.briefGoal || null, hook: "", mustMention: [], doNotSay: [], timing: d.windowNote || "", callToAction: "" }),
    assetPacketAttached: d.kind === "paid",
    deliverables: draftDeliverables(d, d.kind),
    targetTiers: d.tiers || [], applyWindowDays: 3, windowDays: 7,
  };
  if (d.kind === "paid") payload.cashRate = Number(d.rate);
  else if (d.kind === "coupon") {
    payload.coupon = { type: d.ctype || "amount_off", amount: d.camount != null ? Number(d.camount) : null, percent: d.cpercent != null ? Number(d.cpercent) : null, cap: null, appliesTo: String(d.capplies || "").trim(), expiresAt: null };
    payload.whatComped = "";
  } else { payload.dollarCap = Number(d.cap); payload.covers = 2; }
  try {
    const res = await api("POST", "/offers", payload);
    const created = res && res.offer ? res.offer : null;
    cg.step = "done";
    cg.chips = [];
    refreshBadges();
    campaignGuideSay(created && created.status === "draft"
      ? `Saved. "${d.title}" is a draft in Your campaigns. Nothing was sent to a creator.`
      : `Saved. "${d.title}" is in Your campaigns.`);
  } catch (err) {
    cg.step = "summary";
    campaignGuideSay(`${err.message || "That did not save."} Nothing was saved. Check the summary and try again, or start over.`, [
      { label: "Try again", field: "confirm", value: "yes", primary: true },
      { label: "Start over", field: "restart", value: "yes" },
    ]);
  }
}
function campaignGuidePick(field, value) {
  const cg = state.campaignGuide;
  if (!cg) return false;
  const d = cg.data;
  const labelOf = (c) => c.label;
  const chip = (cg.chips || []).find((c) => c.field === field && c.value === value);
  cg.turns.push({ who: "user", text: chip ? labelOf(chip) : value });
  if (field === "kind") { d.kind = value; campaignGuideNext(); }
  else if (field === "spots") { d.spots = parseInt(value, 10); campaignGuideNext(); }
  else if (field === "deliverables") {
    const cur = draftDeliverables(d, d.kind);
    if (value === "keep") { d.deliverablesSeen = true; campaignGuideNext(); }
    else {
      d.deliverablesTouched = true;
      if (value === "story") d.dstory = !cur.story;
      if (value === "posts") d.dposts = String(cur.posts >= 3 ? 1 : cur.posts + 1);
      if (value === "window") { const cyc = [24, 48, 72, 168]; d.dwindow = String(cyc[(cyc.indexOf(cur.windowHours) + 1) % cyc.length]); }
      campaignGuideNext();
    }
  }
  else if (field === "tier") { d.tiers = d.tiers.includes(value) ? d.tiers.filter((t) => t !== value) : [...d.tiers, value]; campaignGuideNext(); }
  else if (field === "fitdone") { d.fitSeen = true; campaignGuideNext(); }
  else if (field === "confirm") { cg.chips = []; campaignGuideRender(); campaignGuideConfirm(); }
  else if (field === "restart") { campaignGuideRestart(); }
  else campaignGuideRender();
  return false;
}
function campaignGuideAnswer(text) {
  const cg = state.campaignGuide;
  const d = cg.data;
  cg.turns.push({ who: "user", text });
  const num = (() => { const m = String(text).replace(/[$,]/g, "").match(/(\d+(?:\.\d+)?)/); return m ? Number(m[1]) : null; })();
  switch (cg.step) {
    case "title": d.title = text.slice(0, 120); break;
    case "comped": d.comped = text.slice(0, 200); break;
    case "value":
      if (!(num > 0)) { campaignGuideSay("I need a dollar amount. For example: 100."); return; }
      if (d.kind === "paid") d.rate = Math.round(num); else d.cap = Math.round(num);
      break;
    case "couponamount":
      if (!(num >= 1)) { campaignGuideSay("I need a dollar amount for the coupon. For example: 50."); return; }
      d.camount = Math.round(num); break;
    case "couponapplies": d.capplies = text.slice(0, 120); break;
    case "dates": d.windowNote = text.slice(0, 140); break;
    default: campaignGuideSay("Tap one of the choices above, or start over below the summary."); return;
  }
  campaignGuideNext();
}
function campaignGuideSubmit(ev) {
  if (ev) ev.preventDefault();
  const input = document.getElementById("cg-text");
  const text = input ? input.value.trim() : "";
  if (!text) return false;
  if (input) input.value = "";
  const cg = state.campaignGuide;
  if (!cg) { campaignGuideStart(text); return false; }
  if (["title", "comped", "value", "couponamount", "couponapplies", "dates"].includes(cg.step)) { campaignGuideAnswer(text); return false; }
  cg.turns.push({ who: "user", text });
  campaignGuideSay("Tap one of the choices above to answer this one. One question at a time keeps the draft right.");
  return false;
}
function campaignGuideRestart() {
  state.campaignGuide = null;
  if (state.tab === "Campaign Setup") loadCampaignSetup();
  return false;
}
function campaignGuideGoCampaigns() {
  state.offersSeg = "drafts";
  return go("dashboard", "My Offers");
}

// ---------- Build -97: the manual builder, one step at a time ----------
// The composer's own sections become the steps: one section
// on screen, a plain progress line, Back and Keep going. The
// draft syncs on every move, so leaving mid step loses
// nothing the fields had already captured.
function campaignStepsInit() {
  const comp = document.getElementById("offer-composer");
  if (!comp) return;
  const groups = [...comp.querySelectorAll(".fgroup")];
  if (!groups.length) return;
  const form = comp.querySelector("form");
  if (!form) return;
  let bar = document.getElementById("camp-stepbar");
  if (!bar) { bar = document.createElement("div"); bar.id = "camp-stepbar"; form.parentNode.insertBefore(bar, form); }
  const cta = form.querySelector(".cta-row");
  const show = (i) => {
    state.campaignStep = i;
    groups.forEach((g, j) => { g.style.display = j === i ? "" : "none"; });
    if (cta) cta.style.display = i === groups.length - 1 ? "" : "none";
    const kicker = (groups[i].querySelector(".fg-kicker") || {}).textContent || "";
    bar.innerHTML = `<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:0 0 12px"><strong style="color:#006AFC">Step ${i + 1} of ${groups.length}: ${esc(kicker)}</strong><span class="small muted">One part at a time. What you type is kept as you go.</span><span style="margin-left:auto;display:flex;gap:8px">${i > 0 ? `<button type="button" class="btn ghost small-btn" data-cstep="${i - 1}">Back</button>` : ""}${i < groups.length - 1 ? `<button type="button" class="btn small-btn" data-cstep="${i + 1}">Keep going</button>` : ""}</span></div>`;
    bar.querySelectorAll("[data-cstep]").forEach((btn) => { btn.onclick = () => { offerDraftSync(); show(Number(btn.getAttribute("data-cstep"))); comp.scrollIntoView({ behavior: "smooth" }); }; });
  };
  show(Math.min(state.campaignStep || 0, groups.length - 1));
}

// ---------- Build -97: Your campaigns prompts ----------
// Real records only: no campaigns at all, or drafts waiting.
// Anything else renders nothing.
function campaignPromptsHtml(offers) {
  const all = offers || [];
  const drafts = all.filter((o) => o.status === "draft");
  if (!all.length) {
    return `<div class="wcard" id="camp-prompt" style="text-align:center"><h3 style="margin-top:0">No campaigns yet</h3><p class="small muted">Your first campaign takes about a minute to set up. Sig can build the draft with you.</p><button type="button" class="btn ws-primary" onclick="return go('dashboard','Campaign Setup')">Set up your first campaign</button></div>`;
  }
  if (drafts.length) {
    return `<div class="notice blue" id="camp-prompt"><strong>${drafts.length} draft${drafts.length === 1 ? "" : "s"} waiting.</strong> A draft sends nothing until you publish it. Open the Drafts list below to finish one, or start a new one in Set up a campaign.</div>`;
  }
  return "";
}

// ---------- Build -97: Set up a campaign (its own view) ----------
// The builder half of the old single Campaigns view. The
// composer below is the same composer that always lived in
// loadMyOffers (same draft store, same POST /offers, same
// review cards in Your campaigns); Build -97 gave it its own
// tab so building and checking stop sharing one screen.
