// Asset packet form reader (Jeff, 2026-10-28): links are one
// per line, "Label | https://..." or a bare URL. The server
// validates (https only, 6 max) and its refusal is what the
// business sees; this reader only shapes the input.
function packetFromForm() {
  const val = (id) => { const el = document.getElementById(id); return el ? el.value.trim() : ""; };
  const links = val("bp-pk-links").split(/\n+/).map((line) => {
    const t = line.trim();
    if (!t) return null;
    const parts = t.split("|").map((x) => x.trim());
    return parts.length > 1 ? { label: parts[0], url: parts.slice(1).join("|") } : { label: "", url: parts[0] };
  }).filter(Boolean).slice(0, 6);
  return {
    logoUrl: val("bp-pk-logo"),
    links,
    talkingPoints: val("bp-pk-points"),
    handle: val("bp-pk-handle").replace(/^@/, ""),
    hashtags: val("bp-pk-tags").split(/[\s,]+/).map((x) => x.replace(/^#/, "")).filter(Boolean).slice(0, 6),
  };
}

// Build -68: per-card saves. The Basics card sends only its
// own fields, the Optional card only its own, so one card's
// save can never clobber the other's unsaved edits.
async function saveBusinessProfile(scope) {
  const val = (id) => { const el = document.getElementById(id); return el ? el.value : ""; };
  const chk = (id) => { const el = document.getElementById(id); return !!(el && el.checked); };
  if (scope === "pos") {
    // Which till (Build -101): an empty pick clears the saved
    // declaration through the same PATCH discipline as the rest
    // of this page (the server stores null for "").
    const patch = { posProvider: val("bp-pos-provider") || "", posOther: val("bp-pos-other") };
    try {
      const data = await api("PATCH", "/me/profile", patch);
      state.user = data.user;
      render();
      setTimeout(() => { const ok = document.getElementById("bp-ok-pos"); if (ok) ok.textContent = "Saved."; }, 30);
    } catch (err) { alert(err.message); }
    return;
  }
  if (scope === "availability") {
    // Build -96: an all-blank save clears the field (the server
    // stores null), so a business can retire the line cleanly.
    const days = AVAIL_DAYS_CLIENT.filter((d) => chk("bp-av-day-" + d));
    const hours = val("bp-av-hours").trim();
    const appointments = val("bp-av-appointments").trim();
    const patch = { standingAvailability: (!days.length && !hours && !appointments) ? null : { days, hours, appointments } };
    try {
      const data = await api("PATCH", "/me/profile", patch);
      state.user = data.user;
      render();
      setTimeout(() => { const ok = document.getElementById("bp-ok-avail"); if (ok) ok.textContent = "Saved."; }, 30);
    } catch (err) { alert(err.message); }
    return;
  }
  const patch = scope === "optional"
    ? {
      musicOpen: chk("bp-music-open"),
      musicLive: chk("bp-music-live"),
      musicCreated: chk("bp-music-created"),
      studentOpen: chk("bp-student-open"),
      preferredLanguage: val("bp-lang") || "en",
      assetPacket: packetFromForm(),
    }
    : {
      businessName: val("bp-name"),
      category: val("bp-category"),
      city: val("bp-city"),
      neighborhood: val("bp-neighborhood"),
      zip: val("bp-zip"),
      about: val("bp-about"),
    };
  try {
    const data = await api("PATCH", "/me/profile", patch);
    state.user = data.user;
    render();
    setTimeout(() => { const ok = document.getElementById(scope === "optional" ? "bp-ok-opt" : "bp-ok"); if (ok) ok.textContent = "Saved."; }, 30);
  } catch (err) { alert(err.message); }
}

